# tugma javoblari (answerCallbackQuery) — fire-and-forget: handler va lock ularni kutmaydi
_ack_q = queue.Queue(maxsize=3000)
_acked = {}
_acked_mu = threading.Lock()
_ack_started = [False]
_ack_start_mu = threading.Lock()


def _ack_mark(cid):
    now = time.time()
    with _acked_mu:
        _acked[cid] = now
        if len(_acked) > 6000:
            for k in [k for k, v in _acked.items() if now - v > 120]:
                _acked.pop(k, None)


def _ack_is_done(cid):
    with _acked_mu:
        return cid in _acked


def _ack_worker(real_answer):
    while True:
        a, kw = _ack_q.get()
        try:
            real_answer(*a, **kw)
        except Exception as e:
            _swallow(e)


def _ack_enqueue(real_answer, args, kwargs):
    if not _ack_started[0]:
        with _ack_start_mu:
            if not _ack_started[0]:
                for i in range(4):
                    threading.Thread(target=_ack_worker, args=(real_answer,),
                                     name=f"flow-ack{i}", daemon=True).start()
                _ack_started[0] = True
    try:
        _ack_q.put_nowait((args, kwargs))
    except queue.Full:
        pass


# ---------------------------------------------------------------------------
# 5) OUTBOX (notify): har chat uchun tartibli navbat
# ---------------------------------------------------------------------------
class _Outbox:
    def __init__(self, workers, limit):
        self.n_workers, self.limit = workers, limit
        self.cv = threading.Condition(threading.Lock())
        self.lanes = {}
        self.ready = collections.deque()
        self.count = 0
        self.dropped = 0
        self.started = False

    def put(self, chat, item):
        with self.cv:
            if not self.started:
                self.started = True
                for i in range(self.n_workers):
                    threading.Thread(target=self._worker, name=f"flow-out{i}", daemon=True).start()
            if self.count >= self.limit:
                self.dropped += 1
                return False
            lane = self.lanes.get(chat)
            if lane is None:
                lane = self.lanes[chat] = collections.deque()
                self.ready.append(chat)
            lane.append(item)
            self.count += 1
            self.cv.notify()
            return True

    def _worker(self):
        _flow_ctx.bulk = True
        while True:
            with self.cv:
                while not self.ready:
                    self.cv.wait()
                chat = self.ready.popleft()
                item = self.lanes[chat].popleft()
                self.count -= 1
            try:
                self._send(chat, item)
            except Exception as e:
                _swallow(e)
            with self.cv:
                if self.lanes[chat]:
                    self.ready.append(chat)
                    self.cv.notify()
                else:
                    del self.lanes[chat]

    @staticmethod
    def _send(chat, item):
        text, reply_markup, parse_mode = item
        for attempt in range(4):
            try:
                bot.send_message(chat, text, reply_markup=reply_markup, parse_mode=parse_mode)
                return
            except Exception as e:
                code = getattr(e, "error_code", None)
                if code == 429 and attempt < 3:
                    ra = 3
                    try:
                        ra = int(e.result_json["parameters"]["retry_after"])
                    except Exception:
                        pass
                    time.sleep(min(max(ra, 1), 10))
                    continue
                if _is_network_error(e) and attempt < 3:
                    time.sleep((0.5, 1.5, 4.0)[attempt])
                    continue
                _swallow(e)       # 403 (bloklagan), 400 va h.k. — qayta urinish befoyda
                return


_outbox = _Outbox(FLOW_OUTBOX_WORKERS, FLOW_OUTBOX_LIMIT)


def notify(owner_id, text, reply_markup=None, parse_mode="HTML"):
    """Xabarni outbox navbatiga qo'yadi — handler/lock Telegramni HECH QACHON kutmaydi."""
    if not owner_id:
        return
    if not _outbox.put(owner_id, (text, reply_markup, parse_mode)):
        logging.warning("outbox to'lgan — xabar tashlandi (%s)", owner_id)


_alert_seen = {}


def _flow_alert_once(key, text, ttl=60.0):
    """Adminlarga bir xil ogohlantirishni ttl ichida bir martagina yuboradi."""
    now = time.time()
    if now - _alert_seen.get(key, 0) < ttl:
        return
    _alert_seen[key] = now
    if len(_alert_seen) > 500:
        for k in [k for k, v in _alert_seen.items() if now - v > 600]:
            _alert_seen.pop(k, None)
    for aid in ADMIN_IDS:
        notify(aid, text)


# ---------------------------------------------------------------------------
# 1-3) KIRISH: dispatcher (yo'laklar, elastik ishchilar, yuk tashlash, osilganlarni ajratish)
# ---------------------------------------------------------------------------
class _Lane:
    __slots__ = ("key", "q", "running", "queued", "hi")

    def __init__(self, key, hi):
        self.key, self.q, self.running, self.queued, self.hi = key, collections.deque(), False, False, hi


class _Task:
    __slots__ = ("lane", "t0", "ident", "abandoned", "desc")

    def __init__(self, lane, ident, desc):
        self.lane, self.t0, self.ident, self.abandoned, self.desc = lane, time.time(), ident, False, desc


class _Dispatcher:
    def __init__(self):
        self.mu = threading.Lock()
        self.cv = threading.Condition(self.mu)
        self.lanes = {}
        self.ready = collections.deque()
        self.ready_hi = collections.deque()
        self.pending = 0
        self.alive = 0
        self.idle = 0
        self.cap = FLOW_MAX_WORKERS
        self.running = {}
        self.abandoned_alive = 0
        self.stat = collections.Counter()
        self._n = 0

    @staticmethod
    def classify(upd):
        cb = getattr(upd, "callback_query", None)
        if cb is not None and getattr(cb, "from_user", None):
            return cb.from_user.id, True
        msg = getattr(upd, "message", None)
        if msg is not None and getattr(msg, "from_user", None):
            return msg.from_user.id, False
        return None, False

    # -- qabul ------------------------------------------------------------
    def submit(self, upd):
        key, is_cb = self.classify(upd)
        if key is None:
            return
        try:
            hi = is_admin(key)
        except Exception:
            hi = False
        shed = False
        spawn = False
        with self.mu:
            lane = self.lanes.get(key)
            if self.pending >= FLOW_INTAKE_LIMIT or (lane is not None and len(lane.q) >= FLOW_LANE_BACKLOG):
                shed = True
                self.stat["shed"] += 1
            else:
                if lane is None:
                    lane = self.lanes[key] = _Lane(key, hi)
                lane.q.append((time.time(), upd, is_cb))
                self.pending += 1
                if not lane.running and not lane.queued:
                    lane.queued = True
                    (self.ready_hi if lane.hi else self.ready).append(lane)
                    self.cv.notify()
                if len(self.ready) + len(self.ready_hi) > self.idle and self.alive < self.cap:
                    self.alive += 1
                    spawn = True
        if shed:
            if is_cb:
                try:
                    bot.answer_callback_query(upd.callback_query.id,
                                              "⏳ Server band — bir necha soniyadan so'ng qayta bosing.")
                except Exception as e:
                    _swallow(e)
            return
        if spawn:
            self._spawn()

    def _spawn(self):
        self._n += 1
        try:
            threading.Thread(target=self._worker, name=f"flow-w{self._n}", daemon=True).start()
        except RuntimeError as e:
            # hosting thread limiti: mavjud ishchilar bilan davom etamiz
            with self.mu:
                self.alive -= 1
                self.cap = max(2, self.alive)
            logging.error("thread ochib bo'lmadi (%r) — ishchilar chegarasi %d", e, self.cap)

    # -- ishchi -----------------------------------------------------------
    def _worker(self):
        tid = threading.get_ident()
        _flow_ctx.bulk = False
        try:
            while True:
                with self.mu:
                    self.idle += 1
                    t_end = time.monotonic() + FLOW_IDLE_EXIT
                    while not (self.ready_hi or self.ready):
                        rem = t_end - time.monotonic()
                        if rem <= 0:
                            self.idle -= 1
                            self.alive -= 1
                            return
                        self.cv.wait(rem)
                    self.idle -= 1
                    lane = (self.ready_hi or self.ready).popleft()
                    lane.queued = False
                    lane.running = True
                    ts, upd, is_cb = lane.q.popleft()
                    self.pending -= 1
                    task = _Task(lane, tid, "callback" if is_cb else "message")
                    self.running[tid] = task
                stale = is_cb and (time.time() - ts) > FLOW_CALLBACK_TTL
                if stale:
                    self.stat["stale"] += 1
                else:
                    self._run(upd, is_cb, task)
                with self.mu:
                    self.running.pop(tid, None)
                    if task.abandoned:
                        self.abandoned_alive -= 1
                        return                      # reaper allaqachon hisobni yuritgan
                    lane.running = False
                    if lane.q:
                        lane.queued = True
                        (self.ready_hi if lane.hi else self.ready).append(lane)
                        self.cv.notify()
                    elif self.lanes.get(lane.key) is lane:
                        del self.lanes[lane.key]
        finally:
            try:
                _db_close_thread()
            except Exception:
                pass

    def _run(self, upd, is_cb, task):
        try:
            if is_cb:
                task.desc = "cb:" + str(getattr(upd.callback_query, "data", ""))[:40]
            else:
                task.desc = "msg:" + str(getattr(upd.message, "text", "") or "")[:40]
        except Exception:
            pass
        try:
            bot.process_new_updates([upd])
            self.stat["done"] += 1
        except Exception as e:
            self.stat["errors"] += 1
            logging.error("update xatosi: %r", e)
        finally:
            try:
                _db_rollback_safe()        # ochiq tranzaksiya hech qachon keyingi amalgacha qolmaydi
            except Exception:
                pass
            if is_cb:
                try:
                    cid = upd.callback_query.id
                    if cid and not _ack_is_done(cid):
                        bot.answer_callback_query(cid)   # tugma "yuklanmoqda"da osilib qolmasin
                except Exception as e:
                    _swallow(e)

    # -- osilganlarni ajratish (supervisor chaqiradi) ---------------------
    def reap(self, now):
        hung = []
        spawn = 0
        with self.mu:
            for tid, task in list(self.running.items()):
                if task.abandoned or now - task.t0 < FLOW_HANDLER_HANG:
                    continue
                task.abandoned = True
                lane = task.lane
                lane.running = False
                if lane.q and not lane.queued:
                    lane.queued = True
                    (self.ready_hi if lane.hi else self.ready).append(lane)
                    self.cv.notify()
                elif not lane.q and self.lanes.get(lane.key) is lane:
                    del self.lanes[lane.key]
                self.alive -= 1
                self.abandoned_alive += 1
                self.stat["abandoned"] += 1
                hung.append((tid, task.desc, now - task.t0, lane.key))
            while (self.ready or self.ready_hi) and self.alive < self.cap and \
                    len(self.ready) + len(self.ready_hi) > self.idle + spawn:
                self.alive += 1
                spawn += 1
        for _ in range(spawn):
            self._spawn()
        return hung

    def snapshot(self):
        with self.mu:
            return {"alive": self.alive, "idle": self.idle, "busy": len(self.running),
                    "pending": self.pending, "lanes": len(self.lanes),
                    "abandoned_alive": self.abandoned_alive, **dict(self.stat)}


_DISPATCH = _Dispatcher()


