_reply_nav_msgs = set()      # (chat_id, message_id) — reply tugma xabarlari (tahrirlab bo'lmaydi)


def _inline_to_reply(markup):
    if not isinstance(markup, types.InlineKeyboardMarkup):
        return markup
    try:
        rows = markup.to_dict().get("inline_keyboard") or []
    except Exception:
        return markup
    btns = [b for row in rows for b in row]
    if not btns or any(b.get("callback_data") not in _REPLY_NAV_CALLBACKS for b in btns):
        return markup
    kb = types.ReplyKeyboardMarkup(resize_keyboard=True, row_width=2)
    has_back = False
    for row in rows:
        texts = []
        for b in row:
            if b["callback_data"] == "m_back":
                has_back = True
                texts.append("⬅️ Bosh menyu")
                continue
            if b["text"] not in _REPLY_NAV_TEXT:
                _REPLY_NAV_TEXT[b["text"]] = b["callback_data"]
            texts.append(b["text"])
        kb.row(*[types.KeyboardButton(t) for t in texts])
    if not has_back:
        kb.row(types.KeyboardButton("⬅️ Bosh menyu"))
    return kb


_real_send_message = bot.send_message


def _is_network_error(e):
    """Internet uzilishi / Telegram javob bermasligi — kod xatosi emas."""
    import requests as _rq
    return isinstance(e, (_rq.exceptions.ConnectionError, _rq.exceptions.Timeout,
                          ConnectionError, TimeoutError))


def _net_call(fn, *args, **kwargs):
    """Tarmoq xatosida handler yiqilmasin: None qaytaradi. Qayta urinish va
    kutish egress qatlamida (_tg_sender) — bu yerda sleep YO'Q."""
    try:
        return fn(*args, **kwargs)
    except Exception as e:
        if not _is_network_error(e):
            raise
        logging.warning("Tarmoq xatosi (%s): %s", getattr(fn, "__name__", "api"), type(e).__name__)
        return None


def _send_message_reply_nav(chat_id, text, *args, **kwargs):
    if kwargs.get("reply_markup") is not None and str(chat_id) != str(globals().get("CHANNEL_ID")):
        kwargs["reply_markup"] = _inline_to_reply(kwargs["reply_markup"])
    return _net_call(_real_send_message, chat_id, text, *args, **kwargs)


bot.send_message = _send_message_reply_nav

