# ---------------------------------------------------------------------------
# YUTILGAN XATOLARNI LOGGA YOZISH (avval `except Exception: pass` hamma narsani
# jimgina yutardi). Telegramning oddiy/kutilgan xatolari (bloklagan foydalanuvchi,
# "message is not modified" va h.k.) esa e'tiborsiz qoldiriladi.
# ---------------------------------------------------------------------------
_SWALLOW_IGNORE = (
    "message is not modified", "query is too old", "bot was blocked",
    "chat not found", "message to edit not found", "message can't be edited",
    "user is deactivated", "message to delete not found", "message can't be deleted",
    "Forbidden", "have no rights", "query ID is invalid",
)


def _swallow(exc):
    try:
        s = str(exc)
        if any(x in s for x in _SWALLOW_IGNORE):
            return
        fr = sys._getframe(1)
        logging.warning("Yutilgan xato (%s:%s): %r", fr.f_code.co_name, fr.f_lineno, exc)
    except Exception:
        return


# ---------------------------------------------------------------------------
# TELEGRAM callback_data 64 BAYT CHEGARASI.
# Uzun nomlar (masalan foydalanuvchi qo'ygan 30 belgilik qal'a nomi, yoki ikkita
# uy + darvoza nomi) tugma ma'lumotini 64 baytdan oshirsa, Telegram xabarni
# umuman yubormaydi. Endi bunday uzun ma'lumot avtomatik qisqartiriladi:
# boshi (handler filtrlari uchun) saqlanadi, to'liq matn alohida kichik bazada
# ("<DB>.cb" fayli — asosiy baza bilan lock to'qnashuvi bo'lmasligi uchun) turadi,
# handler ishga tushishidan oldin esa asl holiga qaytariladi.
# ---------------------------------------------------------------------------
_CB_MARK = "~cbp~"
_CB_DB_PATH = DB_PATH + ".cb"
_cb_mem = {}
_cb_mem_lock = threading.Lock()
_cb_last_cleanup = [0.0]


def _cb_conn():
    c = sqlite3.connect(_CB_DB_PATH, timeout=10, check_same_thread=False, isolation_level=None)
    c.execute("CREATE TABLE IF NOT EXISTS cb_payloads (id INTEGER PRIMARY KEY AUTOINCREMENT, "
              "payload TEXT, created_at REAL)")
    return c


def _cb_shrink(data):
    head = data.encode("utf-8")[:30].decode("utf-8", "ignore")
    conn = _cb_conn()
    try:
        cur = conn.execute("INSERT INTO cb_payloads (payload, created_at) VALUES (?,?)",
                           (data, time.time()))
        pid = cur.lastrowid
    finally:
        conn.close()
    with _cb_mem_lock:
        if len(_cb_mem) > 2000:
            _cb_mem.clear()
        _cb_mem[pid] = data
    return f"{head}{_CB_MARK}{pid}"


def _cb_unpack(c):
    """True — davom etish mumkin; False — tugma muddati tugagan (foydalanuvchiga aytildi)."""
    d = getattr(c, "data", None) or ""
    i = d.rfind(_CB_MARK)
    if i < 0 or not d[i + len(_CB_MARK):].isdigit():
        return True
    pid = int(d[i + len(_CB_MARK):])
    full = _cb_mem.get(pid)
    if full is None:
        try:
            conn = _cb_conn()
            try:
                row = conn.execute("SELECT payload FROM cb_payloads WHERE id=?", (pid,)).fetchone()
            finally:
                conn.close()
            full = row[0] if row else None
        except Exception as e:
            logging.warning("cb_unpack xatosi: %r", e)
            full = None
    if full is None:
        try:
            bot.answer_callback_query(c.id, "Bu tugma muddati tugagan. Menyuni qaytadan oching.",
                                      show_alert=True)
        except Exception:
            return False
        return False
    c.data = full
    return True


def _cb_cleanup():
    now = time.time()
    if now - _cb_last_cleanup[0] < 3600:
        return
    _cb_last_cleanup[0] = now
    conn = _cb_conn()
    try:
        conn.execute("DELETE FROM cb_payloads WHERE created_at<?", (now - 7 * 86400,))
    finally:
        conn.close()


_OrigInlineKeyboardButton = types.InlineKeyboardButton


class _SafeInlineKeyboardButton(_OrigInlineKeyboardButton):
    def __init__(self, text, url=None, callback_data=None, *args, **kwargs):
        if isinstance(callback_data, str) and len(callback_data.encode("utf-8")) > 64:
            try:
                callback_data = _cb_shrink(callback_data)
            except Exception as e:
                logging.warning("callback_data qisqartirilmadi: %r", e)
        super().__init__(text, url, callback_data, *args, **kwargs)


types.InlineKeyboardButton = _SafeInlineKeyboardButton

_orig_callback_query_handler = bot.callback_query_handler


def _callback_query_handler_with_unpack(*dargs, **dkwargs):
    _deco = _orig_callback_query_handler(*dargs, **dkwargs)

    def _outer(fn):
        @functools.wraps(fn)
        def _wrapped(c, *a, **k):
            if not _cb_unpack(c):
                return None
            return fn(c, *a, **k)
        _deco(_wrapped)
        return fn
    return _outer


bot.callback_query_handler = _callback_query_handler_with_unpack

