# ---------------------------------------------------------------------------
# ESSOS SIYOSATI: "Essos qasosi", "Harbiy shahar" unvoni va "Essos qiroli"
# ---------------------------------------------------------------------------
# Bu funksiyalar module darajasida joylashgan boʻlsa-da, ular faqat pastda
# aniqlanadigan db()/notify()/post_to_channel() kabi funksiyalarga bot ISHGA
# TUSHGANDA (chaqirilganda) murojaat qiladi — shu sabab fayl tartibida
# muammo yoʻq (Python funksiya tanasini chaqiruv paytida baholaydi).


def is_essos_vengeance_active():
    """"Essos qasosi" kuchi hozir faolmi (biror Essos shahri talangandan
    keyingi 1 hafta ichida)."""
    conn = db()
    row = conn.execute("SELECT value FROM world WHERE key='essos_vengeance_until'").fetchone()
    conn.close()
    if not row or not row["value"]:
        return False
    try:
        return time.time() < float(row["value"])
    except Exception:
        return False


def trigger_essos_vengeance(raided_city, raider_name):
    """Essosning istalgan shahri talansa — BARCHA Essos shaharlari uchun
    "Essos qasosi" faollashadi: 1 hafta davomida ular bir-biriga yoki
    Westerosning istalgan uyiga (raider dushmanlariga) oʻz mulkini istalgan
    minimal narxda sota oladi (odatdagi savdo cheklovlaridan tashqarida)."""
    conn = db()
    until = time.time() + ESSOS_VENGEANCE_DAYS * 24 * 3600
    conn.execute("INSERT INTO world (key,value) VALUES ('essos_vengeance_until',?) "
                 "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (str(until),))
    conn.commit()
    essos_houses = conn.execute(
        "SELECT name, owner_id FROM houses WHERE is_essos=1").fetchall()
    conn.close()
    until_str = time.strftime("%Y-%m-%d %H:%M", time.localtime(until))
    text = (f"⚔️ <b>ESSOS QASOSI FAOLLASHDI!</b>\n\n"
            f"<b>{raider_name}</b> Essosning ozod shahri <b>{raided_city}</b> portini talon-taroj qildi!\n\n"
            f"Endi <b>{until_str}</b> gacha (1 hafta) BARCHA Essos shaharlari bir-biriga yoki "
            f"Westerosning istalgan uyiga oʻz mulkini istalgan minimal narxda sota oladi.")
    for hh in essos_houses:
        if hh["owner_id"]:
            try:
                bot.send_message(hh["owner_id"], text, parse_mode="HTML")
            except Exception as _e:
                _swallow(_e)
    post_to_channel(text)


def essos_military_status(house):
    """(ok: bool, atk: int, defn: int) — shaharning JORIY butun armiyasi
    asosida "harbiy shahar" boʻsagasiga yetgan-yetmaganini qaytaradi."""
    troops = row_troops(house)
    atk = land_attack_power(troops, house["valyria_polati"])
    defn = land_defense_power(troops, house["valyria_polati"])
    ok = atk >= ESSOS_MILITARY_ATK_THRESHOLD and defn >= ESSOS_MILITARY_DEF_THRESHOLD
    return ok, atk, defn


def get_essos_king():
    conn = db()
    row = conn.execute("SELECT value FROM world WHERE key='essos_king'").fetchone()
    conn.close()
    return row["value"] if row and row["value"] else None


def set_essos_king(name):
    conn = db()
    conn.execute("INSERT INTO world (key,value) VALUES ('essos_king',?) "
                 "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (name,))
    conn.commit()
    conn.close()


def essos_unification_check(new_ruler_name):
    """Bitta Essos shahri BUTUN Essosni (barcha boshqa 13 shaharni vassal
    qilib yoki bosib olib) birlashtira olsa — u "Essos qiroli" unvonini
    avtomatik qoʻlga kiritadi."""
    conn = db()
    others = conn.execute(
        "SELECT name, vassal_of FROM houses WHERE is_essos=1 AND name!=?",
        (new_ruler_name,)).fetchall()
    conn.close()
    if not others:
        return False
    if all(o["vassal_of"] == new_ruler_name for o in others):
        if get_essos_king() != new_ruler_name:
            set_essos_king(new_ruler_name)
            text = (f"👑🌊 <b>ESSOS BIRLASHDI!</b>\n\n<b>{new_ruler_name}</b> butun Essosni "
                    f"birlashtirib, ENDI ESSOS QIROLI! Faqat Essos qiroligina Westerosga "
                    f"mustaqil hujum qilish huquqiga ega.")
            post_to_channel(text)
            conn2 = db()
            essos_houses = conn2.execute(
                "SELECT owner_id FROM houses WHERE is_essos=1").fetchall()
            conn2.close()
            for hh in essos_houses:
                if hh["owner_id"]:
                    try:
                        bot.send_message(hh["owner_id"], text, parse_mode="HTML")
                    except Exception as _e:
                        _swallow(_e)
        return True
    return False


def _handle_essos_city_conquest(conn, attacker, defender):
    """Bitta Essos shahri boshqa Essos shahriga qarshi quruqlik urushida
    gʻalaba qozonganda ishga tushadi: gʻolib maglub shaharni vassal qiladi
    (kunlik ishlab chiqarishini oʻziga oladi), MUHIM shaharlar esa hech
    qachon toʻliq bosib olinmaydi — faqat oʻljaga uchraydi."""
    if defender["name"] in ESSOS_UNCONQUERABLE_CITIES:
        notify(attacker["owner_id"],
               f"🛡️ <b>{defender['name']}</b> — muhim shahar, uni butunlay bosib olib boʻlmaydi. "
               f"Faqat oʻljasini oldingiz.")
        return
    conn.execute("UPDATE houses SET vassal_of=? WHERE name=?", (attacker["name"], defender["name"]))
    conn.commit()
    notify(attacker["owner_id"],
           f"🏰 <b>{defender['name']}</b> ni bosib oldingiz! Uning kunlik ishlab chiqarishi "
           f"endi sizga oʻtadi.")
    if defender["owner_id"]:
        notify(defender["owner_id"],
               f"🏰 <b>{defender['name']}</b> shahri <b>{attacker['name']}</b> tomonidan bosib olindi "
               f"va endi uning vassali.")
    post_to_channel(f"⚔️ Essos ichki urushi: <b>{attacker['name']}</b> <b>{defender['name']}</b> ni "
                     f"bosib oldi va uning vassaliga aylantirdi.")
    essos_unification_check(attacker["name"])


# ---------------------------------------------------------------------------
# ESSOS QIROLLIGIGA DAVOGARLIK (ovoz berish tizimi)
# ---------------------------------------------------------------------------
ESSOS_CLAIM_TIMEOUT_SECONDS = 3600   # 1 soat — javob bermasa avtomatik "rozi"


def _essos_claim_get():
    conn = db()
    row = conn.execute("SELECT value FROM world WHERE key='essos_claim'").fetchone()
    conn.close()
    if not row or not row["value"]:
        return None
    try:
        return json.loads(row["value"])
    except Exception:
        return None


def _essos_claim_save(data):
    conn = db()
    conn.execute("INSERT INTO world (key,value) VALUES ('essos_claim',?) "
                 "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (json.dumps(data),))
    conn.commit()
    conn.close()


def _essos_claim_clear():
    conn = db()
    conn.execute("DELETE FROM world WHERE key='essos_claim'")
    conn.commit()
    conn.close()


def start_essos_king_claim(claimant_name):
    """Essos shahri qirollikka davogar boʻlganda: barcha BOSHQA Essos
    shaharlariga xabar boradi (roziman/rad etaman). Agar davogarning vassali
    boʻlsa — unga xabar bormaydi, u AVTOMATIK roziman deb hisoblanadi."""
    existing = _essos_claim_get()
    if existing and time.time() < existing.get("deadline", 0):
        return False, f"Hozir allaqachon <b>{existing['claimant']}</b> davogarligi koʻrib chiqilmoqda."
    conn = db()
    others = conn.execute(
        "SELECT name, owner_id, vassal_of FROM houses WHERE is_essos=1 AND name!=?",
        (claimant_name,)).fetchall()
    conn.close()
    if not others:
        set_essos_king(claimant_name)
        return True, f"👑 <b>{claimant_name}</b> — yagona Essos shahri sifatida ENDI ESSOS QIROLI!"

    votes = {}
    notify_list = []
    for o in others:
        if o["vassal_of"] == claimant_name or not o["owner_id"]:
            # Vassal — avtomatik rozi (xabar bormaydi). Egasiz shahar ham
            # avtomatik rozi hisoblanadi (e'tiroz bildiradigan hech kim yo'q).
            votes[o["name"]] = "yes"
        else:
            votes[o["name"]] = None
            notify_list.append(o)

    deadline = time.time() + ESSOS_CLAIM_TIMEOUT_SECONDS
    data = {"claimant": claimant_name, "deadline": deadline, "votes": votes}
    _essos_claim_save(data)

    for o in notify_list:
        if not o["owner_id"]:
            continue
        kb = types.InlineKeyboardMarkup()
        kb.add(
            types.InlineKeyboardButton("✅ Tasdiqlayman",
                                       callback_data=f"essos_claim_vote_yes_{claimant_name}"),
            types.InlineKeyboardButton("❌ Rad etaman",
                                       callback_data=f"essos_claim_vote_no_{claimant_name}"),
        )
        try:
            bot.send_message(o["owner_id"],
                f"👑🌊 <b>{claimant_name}</b> Essos qiroli boʻlishga davogar boʻldi. Nima qilasiz?\n\n"
                f"(1 soat ichida javob bermasangiz — avtomatik <b>ROZI</b> boʻlgan hisoblanasiz.)",
                parse_mode="HTML", reply_markup=kb)
        except Exception as _e:
            _swallow(_e)
    post_to_channel(f"👑🌊 <b>{claimant_name}</b> Essos qiroli boʻlishga davogar boʻldi. "
                     f"Barcha Essos shaharlari 1 soat ichida javob berishi kerak.")
    return True, "Davogarlik barcha Essos shaharlariga yuborildi."


def _essos_claim_finalize():
    data = _essos_claim_get()
    if not data:
        return
    claimant = data["claimant"]
    votes = data["votes"]
    if all(v == "yes" for v in votes.values()):
        _essos_claim_clear()
        set_essos_king(claimant)
        text = (f"👑🌊 <b>{claimant}</b> BARCHA Essos shaharlari roziligi bilan ENDI ESSOS QIROLI! "
                f"Faqat u Westerosga mustaqil hujum qila oladi.")
        post_to_channel(text)
        conn = db()
        all_essos = conn.execute("SELECT owner_id FROM houses WHERE is_essos=1").fetchall()
        conn.close()
        for hh in all_essos:
            if hh["owner_id"]:
                try:
                    bot.send_message(hh["owner_id"], text, parse_mode="HTML")
                except Exception as _e:
                    _swallow(_e)
    elif any(v == "no" for v in votes.values()):
        _essos_claim_clear()
        rejector = next(k for k, v in votes.items() if v == "no")
        text = (f"🚫 <b>{claimant}</b> ning Essos qiroli boʻlish davogarligi <b>{rejector}</b> "
                f"tomonidan rad etildi. Davogarlik bekor qilindi.")
        post_to_channel(text)
        claimant_h = get_house(claimant)
        if claimant_h and claimant_h["owner_id"]:
            notify(claimant_h["owner_id"], text)
    # aks holda hali ovoz berish davom etyapti — hech narsa qilinmaydi


def check_essos_claim_timeout():
    """1 soat oʻtgach javob bermagan shaharlar AVTOMATIK "roziman" deb
    hisoblanadi, keyin natija yakunlanadi."""
    data = _essos_claim_get()
    if not data:
        return
    if time.time() < data.get("deadline", 0):
        return
    votes = data["votes"]
    for k, v in votes.items():
        if v is None:
            votes[k] = "yes"
    data["votes"] = votes
    _essos_claim_save(data)
    _essos_claim_finalize()


@bot.callback_query_handler(func=lambda c: c.data.startswith("essos_claim_start_"))
def cb_essos_claim_start(c):
    name = c.data[len("essos_claim_start_"):]
    house = get_house_by_owner(c.from_user.id)
    if not house or house["name"] != name or not house["is_essos"]:
        bot.answer_callback_query(c.id, "Ruxsat yoʻq.", show_alert=True)
        return
    ok, msg = start_essos_king_claim(name)
    bot.answer_callback_query(c.id, "Yuborildi." if ok else "Amalga oshmadi.", show_alert=True)
    bot.send_message(c.message.chat.id, msg, parse_mode="HTML", reply_markup=back_button())


@bot.callback_query_handler(func=lambda c: c.data.startswith("essos_claim_vote_yes_") or
                                            c.data.startswith("essos_claim_vote_no_"))
def cb_essos_claim_vote(c):
    is_yes = c.data.startswith("essos_claim_vote_yes_")
    claimant = c.data[len("essos_claim_vote_yes_"):] if is_yes else c.data[len("essos_claim_vote_no_"):]
    voter_house = get_house_by_owner(c.from_user.id)
    if not voter_house or not voter_house["is_essos"]:
        bot.answer_callback_query(c.id, "Ruxsat yoʻq.", show_alert=True)
        return
    data = _essos_claim_get()
    if not data or data["claimant"] != claimant:
        bot.answer_callback_query(c.id, "Bu davogarlik allaqachon yakunlangan.", show_alert=True)
        return
    if voter_house["name"] not in data["votes"]:
        bot.answer_callback_query(c.id, "Siz ovoz bera olmaysiz.", show_alert=True)
        return
    data["votes"][voter_house["name"]] = "yes" if is_yes else "no"
    _essos_claim_save(data)
    bot.answer_callback_query(c.id, "Ovozingiz qabul qilindi.")
    bot.send_message(c.message.chat.id, "✅ Ovozingiz qabul qilindi." if is_yes else "❌ Rad etdingiz.",
                      reply_markup=back_button())
    _essos_claim_finalize()

