# ESSOS QIROLIDAN WESTEROSGA HUJUM QILISH RUXSATI
# Essos qiroli boʻlmagan biror Essos shahri Westerosga hujum qilmoqchi boʻlsa —
# u Essos qiroliga soʻrov yuboradi (ruxsat berasizmi?). Ruxsat berilsa —
# oʻsha aniq nishonga (target_house) 1 soat ichida hujum qilishi mumkin.
# ---------------------------------------------------------------------------
ESSOS_WAR_PERMIT_SECONDS = 3600  # 1 soat


def _essos_war_permit_key(attacker_name):
    return f"essos_war_permit_{attacker_name}"


def grant_essos_war_permission(attacker_name, target_name):
    conn = db()
    until = time.time() + ESSOS_WAR_PERMIT_SECONDS
    conn.execute("INSERT INTO world (key,value) VALUES (?,?) "
                 "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                 (_essos_war_permit_key(attacker_name), json.dumps({"target": target_name, "until": until})))
    conn.commit()
    conn.close()


def has_essos_war_permission(attacker_name, target_name):
    conn = db()
    row = conn.execute("SELECT value FROM world WHERE key=?",
                        (_essos_war_permit_key(attacker_name),)).fetchone()
    conn.close()
    if not row or not row["value"]:
        return False
    try:
        data = json.loads(row["value"])
    except Exception:
        return False
    return data.get("target") == target_name and time.time() < data.get("until", 0)


def clear_essos_war_permission(attacker_name):
    conn = db()
    conn.execute("DELETE FROM world WHERE key=?", (_essos_war_permit_key(attacker_name),))
    conn.commit()
    conn.close()


def request_essos_war_permission(attacker_name, target_name):
    """Essos qiroliga (agar u topilsa va Telegramda mavjud boʻlsa) soʻrov
    yuboradi. True/False — soʻrov yuborila oldimi."""
    king_name = get_essos_king()
    king_house = get_house(king_name) if king_name else None
    if not king_house or not king_house["owner_id"]:
        return False
    kb = types.InlineKeyboardMarkup(row_width=2)
    kb.add(
        types.InlineKeyboardButton("✅ Ruxsat berish",
                                   callback_data=f"essos_warpermit_yes|{attacker_name}|{target_name}"),
        types.InlineKeyboardButton("❌ Ruxsat bermaslik",
                                   callback_data=f"essos_warpermit_no|{attacker_name}|{target_name}"),
    )
    try:
        bot.send_message(king_house["owner_id"],
            f"⚔️ <b>{attacker_name}</b> Westerosdagi <b>{target_name}</b> uyiga urush qilmoqchi va "
            f"sizdan (Essos qiroli) ruxsat soʻramoqda. Urush qilishiga ruxsat berasizmi?",
            parse_mode="HTML", reply_markup=kb)
        return True
    except Exception:
        return False


@bot.callback_query_handler(func=lambda c: c.data.startswith("essos_warpermit_yes|") or
                                            c.data.startswith("essos_warpermit_no|"))
def cb_essos_warpermit(c):
    is_yes = c.data.startswith("essos_warpermit_yes|")
    parts = c.data.split("|")
    attacker_name, target_name = parts[1], parts[2]
    king_house = get_house_by_owner(c.from_user.id)
    if not king_house or king_house["name"] != get_essos_king():
        bot.answer_callback_query(c.id, "Ruxsat yoʻq.", show_alert=True)
        return
    attacker_h = get_house(attacker_name)
    if is_yes:
        grant_essos_war_permission(attacker_name, target_name)
        bot.answer_callback_query(c.id, "Ruxsat berildi.")
        bot.send_message(c.message.chat.id,
            f"✅ <b>{attacker_name}</b> uyiga <b>{target_name}</b>ga hujum qilishga ruxsat berdingiz.",
            parse_mode="HTML")
        if attacker_h and attacker_h["owner_id"]:
            try:
                bot.send_message(attacker_h["owner_id"],
                    f"✅ Essos qiroli <b>{king_house['name']}</b> sizga <b>{target_name}</b>ga "
                    f"urush qilishga ruxsat berdi! Endi hujum qilishingiz mumkin.",
                    parse_mode="HTML")
            except Exception as _e:
                _swallow(_e)
    else:
        bot.answer_callback_query(c.id, "Rad etildi.")
        bot.send_message(c.message.chat.id,
            f"❌ <b>{attacker_name}</b> ning <b>{target_name}</b>ga hujum qilish soʻrovini rad etdingiz.",
            parse_mode="HTML")
        if attacker_h and attacker_h["owner_id"]:
            try:
                bot.send_message(attacker_h["owner_id"],
                    f"❌ Essos qiroli <b>{king_house['name']}</b> sizga <b>{target_name}</b>ga "
                    f"urush qilishga ruxsat bermadi.",
                    parse_mode="HTML")
            except Exception as _e:
                _swallow(_e)


