def region_mission_key_for_house(house):
    """Uy qaysi REGION_MISSIONS kaliti ostida missiya olishini aniqlaydi."""
    if house["is_essos"]:
        return "Essos"
    region = house["region"] or _region_of_house(house["name"]) or "Shimol"
    if region not in REGION_MISSIONS:
        region = "Shimol"
    return region


def region_mission_daily_count(house_name):
    """Bugun (UTC) ushbu oila nechta hudud missiyasi qilganini qaytaradi."""
    today_start = time.time() - (time.time() % 86400)
    conn = db()
    row = conn.execute(
        "SELECT COUNT(*) AS n FROM region_missions WHERE house=? AND started_at>=?",
        (house_name, today_start)).fetchone()
    conn.close()
    return row["n"] if row else 0


def has_active_mission(house_name):
    """Oilaning hozir aktiv Valyria ekspeditsiyasi YOKI hudud missiyasi
    bor-yo'qligini tekshiradi — ikkalasidan bir vaqtning o'zida faqat
    BITTASI mumkin."""
    conn = db()
    exp = conn.execute(
        "SELECT id FROM expeditions WHERE house=? AND status='active'", (house_name,)).fetchone()
    if exp:
        conn.close()
        return True
    rm = conn.execute(
        "SELECT id FROM region_missions WHERE house=? AND status='active'", (house_name,)).fetchone()
    conn.close()
    return bool(rm)


region_mission_session = {}   # uid -> {"mission_id": str, "qoshin": int}


def check_region_mission_completions():
    """tick_loop'da har daqiqada chaqiriladi — vaqti tugagan aktiv hudud
    missiyalarini yakunlaydi."""
    now = time.time()
    conn = db()
    done = conn.execute(
        "SELECT * FROM region_missions WHERE status='active' AND started_at<=?",
        (now - REGION_MISSION_DURATION,)).fetchall()
    conn.close()
    for rm in done:
        try:
            _resolve_region_mission(rm["id"])
        except Exception as e:
            print(f"hudud missiyasi yakunlash xatosi (id={rm['id']}):", e)


def _resolve_region_mission(mission_row_id):
    """Bitta hudud missiyasini yakunlaydi: HAR DOIM muvaffaqiyatli, mukofot
    faqat 30-50 tanga oralig'ida, askarlar sog'-omon qaytadi."""
    conn = db()
    rm = conn.execute("SELECT * FROM region_missions WHERE id=?", (mission_row_id,)).fetchone()
    if not rm or rm["status"] != "active":
        conn.close()
        return

    house_name = rm["house"]
    house = conn.execute("SELECT * FROM houses WHERE name=?", (house_name,)).fetchone()
    if not house:
        conn.execute("UPDATE region_missions SET status='completed' WHERE id=?", (mission_row_id,))
        conn.commit()
        conn.close()
        return

    region_key = rm["region"] if rm["region"] in REGION_MISSIONS else "Shimol"
    mission = next((m for m in REGION_MISSIONS[region_key] if m["id"] == rm["mission_id"]), None)
    if not mission:
        mission = REGION_MISSIONS[region_key][0]

    sent_qoshin = rm["qoshin"]
    amount = random.randint(REGION_MISSION_MIN_REWARD, REGION_MISSION_MAX_REWARD)
    conn.execute("UPDATE houses SET tanga=MAX(tanga+?,0) WHERE name=?", (amount, house_name))
    if sent_qoshin > 0:
        conn.execute("UPDATE houses SET qoshin=qoshin+? WHERE name=?", (sent_qoshin, house_name))

    conn.execute("UPDATE region_missions SET status='completed', result='✅ muvaffaqiyat' WHERE id=?",
                 (mission_row_id,))
    conn.commit()
    conn.close()

    owner = get_house(house_name)
    if owner and owner["owner_id"]:
        troop_line = f"⚔️ {sent_qoshin} askar sog'-omon qaytdi\n" if sent_qoshin > 0 else ""
        msg = (
            f"🏞️ <b>Hudud topshirig'i yakunlandi!</b>\n\n"
            f"<b>Topshiriq:</b> {mission['emoji']} {mission['title']}\n\n"
            f"{mission['success_text']}\n\n"
            f"{troop_line}"
            f"<b>Mukofot:</b> +{amount} tanga"
        )
        notify(owner["owner_id"], msg)


@bot.callback_query_handler(func=lambda c: c.data == "m_hudud_missiya")
def cb_hudud_missiya_menu(c):
    """Hudud topshiriqlari bosh menyusi."""
    uid = c.from_user.id
    house = get_house_by_owner(uid)
    bot.answer_callback_query(c.id)
    if not house:
        bot.send_message(c.message.chat.id, "Sizda uy yo'q.", reply_markup=main_menu(uid))
        return

    done_today = region_mission_daily_count(house["name"])
    if done_today >= REGION_MISSION_DAILY_MAX:
        bot.send_message(c.message.chat.id,
            f"🏞️ <b>Hudud topshiriqlari</b>\n\n"
            f"Bugun allaqachon {REGION_MISSION_DAILY_MAX} ta topshiriq bajardingiz. "
            f"Ertaga qaytib keling!",
            reply_markup=main_menu(uid), parse_mode="HTML")
        return

    conn = db()
    active = conn.execute(
        "SELECT * FROM region_missions WHERE house=? AND status='active'",
        (house["name"],)).fetchone()
    conn.close()
    if active or has_active_mission(house["name"]):
        remaining = None
        if active:
            remaining = int((active["started_at"] + REGION_MISSION_DURATION - time.time()) / 60)
        text = (f"🏞️ <b>Hudud topshiriqlari</b>\n\n"
                f"Sizning askarlaringiz hozir band (topshiriq yoki ekspeditsiyada)! "
                f"Qaytishini kuting.")
        if remaining is not None:
            text += f"\n\n⏱ Taxminan <b>{max(1,remaining)} daqiqa</b> qoldi."
        bot.send_message(c.message.chat.id, text, reply_markup=main_menu(uid), parse_mode="HTML")
        return

    region_key = region_mission_key_for_house(house)
    missions = REGION_MISSIONS.get(region_key, REGION_MISSIONS["Shimol"])
    remaining_today = REGION_MISSION_DAILY_MAX - done_today

    text = (
        f"🏞️ <b>Hudud topshiriqlari — {region_key}</b>\n\n"
        f"Hududingizga mos topshiriqlardan birini tanlang. Topshiriq HAR DOIM "
        f"muvaffaqiyatli yakunlanadi va {REGION_MISSION_MIN_REWARD}-{REGION_MISSION_MAX_REWARD} "
        f"tanga mukofot beradi.\n\n"
        f"⏱ Davomiyligi: <b>40 daqiqa</b>\n"
        f"📅 Bugun qolgan topshiriqlar: <b>{remaining_today}</b>\n"
        f"⚔️ Mavjud askarlar: <b>{house['qoshin']}</b>\n\n"
        f"Qaysi topshiriqni bajarasiz?"
    )
    kb = types.InlineKeyboardMarkup(row_width=1)
    for m in missions:
        kb.add(types.InlineKeyboardButton(
            f"{m['emoji']} {m['title']}", callback_data=f"region_pick_{m['id']}"))
    kb.add(types.InlineKeyboardButton("⬅️ Bekor qilish", callback_data="m_back"))
    region_mission_session[uid] = {}
    bot.send_message(c.message.chat.id, text, reply_markup=kb, parse_mode="HTML")


