@bot.callback_query_handler(func=lambda c: c.data == "region_confirm")
def cb_region_confirm(c):
    uid = c.from_user.id
    sess = region_mission_session.get(uid)
    if not sess or "mission_id" not in sess:
        bot.answer_callback_query(c.id, "Sessiya tugagan. Qaytadan boshlang.", show_alert=True)
        return
    bot.answer_callback_query(c.id)
    house = get_house_by_owner(uid)
    if not house:
        bot.send_message(c.message.chat.id, "Sizda uy yo'q.", reply_markup=main_menu(uid))
        return

    done_today = region_mission_daily_count(house["name"])
    if done_today >= REGION_MISSION_DAILY_MAX:
        bot.send_message(c.message.chat.id,
            f"⛔ Bugun topshiriq limiti to'lgan (kuniga {REGION_MISSION_DAILY_MAX} ta).",
            reply_markup=main_menu(uid))
        region_mission_session.pop(uid, None)
        return

    if has_active_mission(house["name"]):
        bot.send_message(c.message.chat.id,
            "⛔ Sizning askarlaringiz hozir band (topshiriq yoki ekspeditsiyada)! Qaytishini kuting.",
            reply_markup=main_menu(uid))
        region_mission_session.pop(uid, None)
        return

    mission_id = sess.get("mission_id")
    qoshin = sess.get("qoshin", 0)
    region_key = region_mission_key_for_house(house)

    conn = db()
    fresh = conn.execute("SELECT qoshin FROM houses WHERE name=?", (house["name"],)).fetchone()
    if qoshin > 0 and (not fresh or fresh["qoshin"] < qoshin):
        qoshin = fresh["qoshin"] if fresh else 0

    now = time.time()
    conn.execute(
        "INSERT INTO region_missions (house, region, mission_id, qoshin, started_at, status) "
        "VALUES (?,?,?,?,?,'active')",
        (house["name"], region_key, mission_id, qoshin, now))
    if qoshin > 0:
        conn.execute("UPDATE houses SET qoshin=MAX(qoshin-?,0) WHERE name=?",
                     (qoshin, house["name"]))
    conn.commit()
    conn.close()
    region_mission_session.pop(uid, None)

    finish_time = now + REGION_MISSION_DURATION
    finish_str = time.strftime("%H:%M", time.localtime(finish_time))
    bot.send_message(c.message.chat.id,
        f"🏞️ <b>Topshiriq boshlandi!</b>\n\n"
        f"⚔️ {qoshin} askar topshiriqqa yo'l oldi.\n"
        f"⏱ Natija taxminan <b>{finish_str}</b> da tayyor bo'ladi.\n\n"
        f"Bot sizga xabar beradi — sabr qiling!",
        reply_markup=main_menu(uid), parse_mode="HTML")


def tournament_open_text(t, houses_list_str, prize_text):
    """Turnir boshlanganda kanalga yuboriladigan e'lon matnini turnir turiga
    (qirollik / hududiy / uy tashkil qilgan) qarab tanlaydi."""
    if t["organizer_house"]:
        tpl = random.choice(TOURNAMENT_START_HOUSE_TEMPLATES)
        return tpl.format(organizer=lord_full_name(t["organizer_house"]),
                           seat=house_seat(t["organizer_house"]),
                           prize=prize_text, houses=houses_list_str)
    if t["kind"] == "regional":
        tpl = random.choice(TOURNAMENT_START_REGIONAL_TEMPLATES)
        seat_house = get_region_lord(t["region"]) or t["region"]
        return tpl.format(region=t["region"], seat=house_seat(seat_house),
                           prize=prize_text, houses=houses_list_str)
    tpl = random.choice(TOURNAMENT_START_TEMPLATES)
    return tpl.format(prize=prize_text, houses=houses_list_str)

# Har bir uy oxirgi marta qachon urushni tugatgani (in-memory, faqat
# "ketma-ket urush" hazili uchun ishlatiladi — bot qayta ishga tushsa reset bo'ladi).
_last_war_end_time = {}
WAR_REPEAT_JOKE_WINDOW = 3 * 3600   # 3 soat ichida yana urush boshlasa — hazil variant


def announce_war_declared(attacker_name, defender_name, units):
    """Urush e'lon qilinganda kanalga qiziqarli/yumoristik xabar yuboradi.
    Agar hujumchi yaqinda (WAR_REPEAT_JOKE_WINDOW ichida) boshqa urushni
    tugatgan bo'lsa — maxsus "dam olmadi" hazili ishlatiladi.
    Askar soni va turi kanalda ko'rsatilmaydi — faqat hikoya."""
    last_end = _last_war_end_time.get(attacker_name, 0)
    is_repeat = (time.time() - last_end) < WAR_REPEAT_JOKE_WINDOW
    templates = WAR_DECLARE_REPEAT_TEMPLATES if is_repeat else WAR_DECLARE_TEMPLATES
    text = random.choice(templates).format(
        attacker=lord_full_name(attacker_name),
        defender=lord_full_name(defender_name))
    post_to_channel(text)


def announce_war_concluded(attacker_name, defender_name, outcome,
                           personal_side=None, guard_power=0):
    """Urush hal bo'lganda (attacker yoki defender g'olib) kanalga qisqa
    hikoya uslubidagi xabar yuboradi. outcome — 'attacker' yoki 'defender'."""
    now = time.time()
    _last_war_end_time[attacker_name] = now
    _last_war_end_time[defender_name] = now
    attacker_full = lord_full_name(attacker_name)
    defender_full = lord_full_name(defender_name)
    templates = WAR_ATTACKER_WIN_STORY if outcome == "attacker" else WAR_DEFENDER_WIN_STORY
    text = random.choice(templates).format(
        attacker=attacker_full, defender=defender_full,
        attacker_h=attacker_name, defender_h=defender_name)
    if personal_side == "attacker":
        text += (f"\n\n⚔️ Qoʻshinlar tugagach, {attacker_full} jang maydoniga "
                 "shaxsan o‘zi kirdi va lashkariga bosh bo‘ldi.")
    elif personal_side == "defender":
        text += (f"\n\n⚔️ Qoʻshinlar tor-mor bo‘lgach, {defender_full} "
                 "jang maydoniga shaxsan o‘zi kirdi.")
    if guard_power:
        text += (f"\n🛡️ Qirol qoʻshini ogʻir ahvolga tushganida qirol gvardiyasi "
                 f"jangga chiqdi — himoya kuchi {guard_power} ball.")
    post_to_channel(text)


def _house_cache_invalidate(name=None, uid=None):
    """Ma'lumot o'zgarganda keshni tozalash uchun chaqiriladi."""
    if name:
        _house_cache.pop(name, None)
    if uid:
        _owner_cache.pop(uid, None)


def get_house(name):
    now = time.time()
    cached = _house_cache.get(name)
    if cached and now < cached[1]:
        return cached[0]
    conn = db()
    row = conn.execute("SELECT * FROM houses WHERE name=?", (name,)).fetchone()
    conn.close()
    _house_cache[name] = (row, now + _HOUSE_CACHE_TTL)
    return row


def get_house_by_owner(uid):
    now = time.time()
    cached = _owner_cache.get(uid)
    if cached and now < cached[1]:
        return cached[0]
    conn = db()
    # is_essos ASC: avval Westeros uyi (0), keyin Essos shahar (1)
    row = conn.execute(
        "SELECT * FROM houses WHERE owner_id=? ORDER BY is_essos ASC LIMIT 1", (uid,)).fetchone()
    conn.close()
    _owner_cache[uid] = (row, now + _HOUSE_CACHE_TTL)
    return row


def get_king():
    conn = db()
    row = conn.execute("SELECT value FROM world WHERE key='king'").fetchone()
    conn.close()
    return row["value"] if row else None


def get_region_lord(region):
    conn = db()
    row = conn.execute("SELECT lord_house FROM regions WHERE region=?", (region,)).fetchone()
    conn.close()
    return row["lord_house"] if row else None


def get_bannermen(lord_name):
    """Hudud lordining BAYROQDORLARI — bu hudud lordining oʻz HUDUDIDAGI
    barcha boshqa uylar (masalan Stark uchun — Bolton, Karstark, Umber va
    hokazo, chunki ularning barchasi 'Shimol' hududida). Bu roʻyxat
    'vassal_of' ustuniga bogʻliq EMAS — 'vassal_of' faqat urushda
    magʻlub etib rasman vassal qilingan (odatda BOSHQA hududdagi) uylar
    uchun ishlatiladi va ular bayroqdor chaqiruviga KIRMAYDI (foydalanuvchi
    talabiga koʻra: "hudud lordi faqat oʻz hududidagilarni chaqiradi,
    vassal qilganlarni chaqirmaydi")."""
    lord = get_house(lord_name)
    if not lord:
        return []
    conn = db()
    rows = conn.execute(
        "SELECT name, owner_id FROM houses WHERE region=? AND name!=? AND is_essos=0",
        (lord["region"], lord_name)).fetchall()
    conn.close()
    return rows


def is_gate_captured(castle_name):
    """Chegara qasri "egallangan" hisoblanadi, agar u oʻzining ONA qirolligidan
    BOSHQA qirollikka mansub bir uyga vassal boʻlib qolgan boʻlsa."""
    h = get_house(castle_name)
    if not h or not h["vassal_of"]:
        return False
    overlord = get_house(h["vassal_of"])
    return bool(overlord) and overlord["region"] != h["region"]


# ---------------------------------------------------------------------------
# V9: YANGI RUXSAT TIZIMI
#  - land_permits: bitta ruxsat = bitta ANIQ nishonga (target_house) FAQAT
#    BIR MARTA hujum qilish huquqi. Urush e'lon qilinganda "used" boʻlib
#    qoladi (gʻalaba/magʻlubiyatidan qatʼiy nazar) — qayta hujum qilish
#    uchun yana ruxsat soʻralishi kerak.
#  - port_leases: portdan dengizga chiqish ruxsati "ijara" — 1 soat davomida
#    istalgancha ishlatish mumkin, muddat tugagach yana soʻralishi kerak.
#  - Agar hujumchining nishon hududda (target["region"]) allaqachon vassali
#    boʻlsa — u yerga kirish uchun boshqa ruxsat SHART EMAS (chunki u yerda
#    poydevori/vassali bor).
# ---------------------------------------------------------------------------

def has_land_permit(gate_name, house_name, target_house):
    conn = db()
    row = conn.execute(
        "SELECT 1 FROM land_permits WHERE gate=? AND house=? AND target_house=? AND used=0",
        (gate_name, house_name, target_house)).fetchone()
    conn.close()
    return bool(row)


def grant_land_permit(gate_name, house_name, target_house):
    conn = db()
    conn.execute(
        "INSERT INTO land_permits (gate, house, target_house, used, created_at) VALUES (?,?,?,0,?)",
        (gate_name, house_name, target_house, time.time()))
    conn.commit()
    conn.close()


def consume_land_permits_for_target(house_name, target_house):
    """Urush e'lon qilingach, shu (hujumchi, nishon) juftligi uchun berilgan
    BARCHA quruqlik ruxsatlarini 'ishlatilgan' deb belgilaydi — endi shu
    nishonga qayta hujum qilish uchun yangi ruxsat kerak boʻladi."""
    conn = db()
    conn.execute(
        "UPDATE land_permits SET used=1 WHERE house=? AND target_house=? AND used=0",
        (house_name, target_house))
    conn.commit()
    conn.close()


def has_port_lease(gate_name, house_name):
    conn = db()
    row = conn.execute(
        "SELECT 1 FROM port_leases WHERE gate=? AND house=? AND expires_at>?",
        (gate_name, house_name, time.time())).fetchone()
    conn.close()
    return bool(row)


def grant_port_lease(gate_name, house_name):
    conn = db()
    conn.execute(
        "INSERT INTO port_leases (gate, house, expires_at, created_at) VALUES (?,?,?,?)",
        (gate_name, house_name, time.time() + PORT_LEASE_SECONDS, time.time()))
    conn.commit()
    conn.close()


def attacker_has_beachhead(attacker_name, region):
    """Hujumchining shu hudud (region) ichida allaqachon vassali bormi —
    bo'lsa, chegara qasrlaridan o'tish ruxsati talab qilinmaydi (chunki u
    yerda allaqachon poydevori bor)."""
    conn = db()
    row = conn.execute("SELECT 1 FROM houses WHERE vassal_of=? AND region=?",
                        (attacker_name, region)).fetchone()
    conn.close()
    return bool(row)


def _build_land_graph():
    """LAND_GATES asosida yoʻnalish grafini quradi: graph[A] ichida A dan qaysi
    qirollik(lar)ga qanday qasr(lar) orqali oʻtib kirish mumkinligi saqlanadi.
    Bu koʻp bosqichli (masalan Shimol -> Daryo yerlari -> Qirollik yerlari kabi
    "oradagi hududlar" orqali oʻtadigan) yoʻllarni topish uchun ishlatiladi."""
    graph = {}
    for dest, routes in LAND_GATES.items():
        for r in routes:
            for src in r["from"]:
                graph.setdefault(src, []).append(
                    {"to": dest, "gates": r["gates"], "bypass": r.get("bypass", [])})
    return graph


_LAND_GRAPH = _build_land_graph()


def _find_land_paths(start, end, max_hops=6):
    """start hududidan end hududigacha barcha oddiy (qirollik takrorlanmaydigan)
    yoʻllarni topadi. Har bir yoʻl — bosqichlar roʻyxati: [{"to","gates","bypass"}, ...].
    Natija eng qisqa yoʻldan boshlab saralanadi (kamroq bosqich — kamroq ruxsat kerak)."""
    paths = []

    def dfs(current, visited, path):
        if len(path) > max_hops:
            return
        for edge in _LAND_GRAPH.get(current, []):
            nxt = edge["to"]
            if nxt in visited:
                continue
            path.append(edge)
            if nxt == end:
                paths.append(list(path))
            else:
                visited.add(nxt)
                dfs(nxt, visited, path)
                visited.discard(nxt)
            path.pop()

    dfs(start, {start}, [])
    paths.sort(key=len)
    return paths


def check_land_route(attacker, defender):
    """Quruqlik jangi uchun geografik tekshiruv — endi bevosita qoʻshni boʻlmagan
    hududlarga ham ORADAGI HUDUDLAR orqali (koʻp bosqichli yoʻl) hujum qilish
    mumkinligini hisobga oladi. Har bir bosqichdagi chegara qasri(lari) egallangan
    yoki lordidan oʻtish ruxsati olingan boʻlishi kerak. Qaytaradi:
    (ruxsat_bormi, xabar_yoki_None, yetishmayotgan_qasrlar_royxati)."""
    # Essos shaharlari — Westerosdan quruqlikdan yetib borib boʻlmaydi (dengiz
    # ortida). LEKIN boshqa Essos shahri hujum qilsa — ular bitta qit'ada
    # joylashgani uchun quruqlikdan ham hujum qila oladi.
    if defender.get("is_essos"):
        if attacker.get("is_essos"):
            return True, None, []
        return False, (f"⛔ <b>{defender['name']}</b> — Essos dengiz shahri. "
                       f"Quruqlik qoʻshini u yerga yetib bora olmaydi. "
                       f"Dengiz urushini tanlang va kema bilan hujum qiling."), []
    # Devor ("Devor" hududi) xaritada Shimol bilan tutashgan — quruqlik yo'li
    # hisobida Shimol hududidan hujum qilayotgandek qaraladi.
    if attacker["name"] == WALL_HOUSE:
        attacker = dict(attacker)
        attacker["region"] = "Shimol"
    # Orol hujumchi: ISLAND_ONLY_HOUSES yoki ISLAND_KINGDOMS dagi uy
    # qit'adagi nishonga quruqlikdan hujum qila olmaydi — avval port egallashi kerak.
    attacker_is_island = (
        attacker["name"] in ISLAND_ONLY_HOUSES or
        attacker["region"] in ISLAND_KINGDOMS
    )
    defender_is_island = (
        defender["name"] in ISLAND_ONLY_HOUSES or
        defender["region"] in ISLAND_KINGDOMS
    )
    if attacker_is_island and not defender_is_island and not defender.get("is_essos"):
        # Bir xil regiondagi (masalan Targaryen → Blackfyre, ikkalasi Qirollik yerlari)
        # uyga quruqlikdan hujum qilish mumkin — cheklov faqat boshqa regionlarga.
        same_region = (attacker["region"] == defender["region"])
        if not same_region and not attacker_has_beachhead(attacker["name"], defender["region"]):
            return False, (
                f"⛔ <b>{attacker['name']}</b> — orolda joylashgan. "
                f"Qit'adagi <b>{defender['name']}</b> ga quruqlikdan hujum qilish uchun avval "
                f"<b>{defender['region']}</b> hududidagi port shahrini (dengiz orqali) egallashingiz kerak."
            ), []
    # Orol uylariga quruqlikdan hujum qilib boʻlmaydi — faqat dengizdan.
    # V19: Targaryen (Qizil qasr) bundan mustasno — u ham dengiz orqali,
    # ham quruqlikdan (Qirollik yerlari geografiyasidagi "Targaryen" qasr
    # darvozasi orqali) hujum qilinishi mumkin boʻlgan yagona uy.
    if defender["name"] in ISLAND_ONLY_HOUSES and defender["name"] != "Targaryen":
        return False, (f"⛔ <b>{defender['name']}</b> — orolda yoki dengiz boʻyida joylashgan. "
                       f"Bu yerga faqat dengiz orqali hujum qilish mumkin, "
                       f"quruqlikdan hujum qilib boʻlmaydi."), []
    # Temir orollar — quruqlik yoʻli yoʻq, faqat dengizdan.
    if defender["region"] in ISLAND_KINGDOMS:
        return False, (f"⛔ <b>{defender['region']}</b> — orolda joylashgan. "
                       f"Bu yerga faqat dengiz orqali hujum qilish mumkin."), []
    if attacker["region"] == defender["region"]:
        return True, None, []

    # V9: agar hujumchining nishon hududda allaqachon vassali bo'lsa (masalan
    # G'arbiy yerlarda Lannister vassal qilingan bo'lsa), o'sha hududdagi
    # BOSHQA uylarga hujum qilish uchun chegaradan o'tish ruxsati shart emas.
    if attacker_has_beachhead(attacker["name"], defender["region"]):
        return True, None, []

    paths = _find_land_paths(attacker["region"], defender["region"])
    if not paths:
        return False, (f"⛔ <b>{defender['region']}</b> hududiga <b>{attacker['region']}</b> "
                        f"tomonidan quruqlikdan hujum qilib boʻlmaydi — bu ikki hudud orasida "
                        f"(hatto oradagi hududlar orqali ham) hech qanday quruqlik yoʻli mavjud emas."), []

    best_missing = None
    for path in paths:
        missing_all = []
        for i, edge in enumerate(path):
            is_last = (i == len(path) - 1)
            if is_last and defender["name"] in edge["gates"]:
                continue  # chegaraviy qasrning oʻzi — toʻgʻridan-toʻgʻri hujum mumkin
            if any(is_gate_captured(g) for g in edge["bypass"]):
                continue
            missing = [g for g in edge["gates"]
                       if not (is_gate_captured(g) or has_land_permit(g, attacker["name"], defender["name"]))]
            for g in missing:
                if g not in missing_all:
                    missing_all.append(g)
        if not missing_all:
            return True, None, []
        if best_missing is None or len(missing_all) < len(best_missing):
            best_missing = missing_all

    needed = ", ".join(best_missing)
    return False, (f"⛔ Avval <b>{needed}</b> qasri(lari)ni egallashingiz yoki lordi(lari)dan "
                    f"oʻtish ruxsatini olishingiz kerak (oradagi hududlar orqali oʻtish uchun) — "
                    f"shundan keyingina <b>{defender['region']}</b> hududiga quruqlikdan "
                    f"kirishingiz mumkin."), best_missing


def check_naval_route(attacker, defender):
    """Dengiz jangi uchun geografik tekshiruv. Qaytaradi: (ruxsat_bormi, xabar_yoki_None)."""
    kingdom = defender["region"]
    # Barcha Essos shaharlari dengiz boʻyida joylashgan — toʻgʻridan-toʻgʻri
    # dengizdan hujum qilinishi mumkin (savdo ham, urush ham).
    if defender.get("is_essos"):
        return True, None
    # Alohida orol/dengiz porti uylariga toʻgʻridan-toʻgʻri dengizdan hujum mumkin
    if defender["name"] in ISLAND_ONLY_HOUSES:
        return True, None
    if kingdom in ISLAND_KINGDOMS:
        return True, None
    if kingdom in NO_SEA_ACCESS_KINGDOMS:
        return False, f"⛔ <b>{kingdom}</b> hududiga dengiz orqali hujum qilib boʻlmaydi (dengizga chiqishi yoʻq)."
    if defender["name"] == "Targaryen":
        if all(is_gate_captured(g) for g in CROWNLANDS_NAVAL_GUARDS):
            return True, None
        missing = [g for g in CROWNLANDS_NAVAL_GUARDS if not is_gate_captured(g)]
        return False, (f"⛔ Avval <b>{', '.join(missing)}</b> yakson etilishi (egallanishi) kerak, "
                        f"shundan keyingina Qizil qasrga dengizdan hujum qilish mumkin.")
    chains = NAVAL_GATES.get(kingdom, [])
    for chain in chains:
        if defender["name"] in chain:
            idx = chain.index(defender["name"])
            prev = chain[:idx]
            if all(is_gate_captured(g) for g in prev):
                return True, None
            missing = [g for g in prev if not is_gate_captured(g)]
            return False, (f"⛔ Avval <b>{', '.join(missing)}</b> egallanishi kerak, "
                            f"shundan keyingina bu qasrga dengizdan hujum qilish mumkin.")
    return False, "⛔ Bu qasr port shahar yoki orol emas — dengizdan toʻgʻridan-toʻgʻri hujum qilib boʻlmaydi."


def _naval_ports_for_region(region):
    """Berilgan qirollik uchun barcha "port shahar" (dengizga chiqish nuqtasi)
    qasrlari roʻyxatini qaytaradi (NAVAL_GATES + Qirollik yerlari uchun
    CROWNLANDS_NAVAL_GUARDS)."""
    ports = set()
    for chain in NAVAL_GATES.get(region, []):
        ports.update(chain)
    if region == "Qirollik yerlari":
        ports.update(CROWNLANDS_NAVAL_GUARDS)
    return ports


def _all_westeros_ports():
    """V13: Westerosdagi BARCHA port shahar qasrlari roʻyxatini qaytaradi
    (barcha qirolliklar boʻyicha, faqat hujumchining oʻz hududidagi emas).
    Dengiz jangi yoki Valyria ekspeditsiyasi uchun dengizga chiqish ruxsati
    soʻralganda — endi istalgan lordlikdagi port shahardan ruxsat soʻrash
    mumkin boʻlishi uchun ishlatiladi."""
    ports = set()
    for region in NAVAL_GATES:
        ports.update(_naval_ports_for_region(region))
    ports.update(CROWNLANDS_NAVAL_GUARDS)
    return ports


def attacker_has_naval_vassal_beachhead(attacker_name):
    """Agar hujumchining istalgan qirollikda PORT SHAHAR boʻlgan vassali boʻlsa
    (masalan dengiz boʻyidagi lordlikni bosib olib vassal qilgan boʻlsa), u holda
    hujumchi oʻz vassali orqali dengizga chiqa oladi — hech qanday qoʻshimcha
    ruxsat kerak emas."""
    conn = db()
    vassals = conn.execute("SELECT name, region FROM houses WHERE vassal_of=?",
                            (attacker_name,)).fetchall()
    conn.close()
    for v in vassals:
        ports = _naval_ports_for_region(v["region"])
        if v["name"] in ports:
            return True
    return False


def check_naval_departure(attacker):
    """Hujumchining oʻzi dengizga CHIQA OLADIMI, tekshiradi: faqat orol
    qirolliklari (masalan Temir orollar) yoki oʻz qirolligining port shahri
    boʻlgan uylar toʻgʻridan-toʻgʻri dengiz jangi boshlay oladi. Boshqa (dengizga
    toʻgʻridan-toʻgʻri chiqmaydigan, masalan Shimol ichidagi Stark kabi) uylar
    avval biror port shahar lordidan oʻtish ruxsati olishlari kerak — YOKI,
    agar oʻzining port shahar boʻlgan vassali boʻlsa (uni urushda bosib olib
    vassal qilgan boʻlsa), qoʻshimcha ruxsatsiz dengizga chiqa oladi.
    V13: endi ruxsat FAQAT oʻz qirolligidagi port shahardan emas — Westerosdagi
    ISTALGAN lordlikdagi port shahardan soʻralishi mumkin (Daryo yerlari kabi
    dengizga bevosita chiqishi boʻlmagan hududlar ham shu yoʻl bilan boshqa
    qirollikdagi portdan ruxsat soʻrab dengizga chiqa oladi). Qaytaradi:
    (ruxsat_bormi, xabar_yoki_None, ruxsat_soʻralishi_mumkin_boʻlgan_port_qasrlari_royxati)."""
    region = attacker["region"]
    # Bravos oʻzi port shahar — dengizga chiqish uchun hech qanday
    # ruxsat kerak emas.
    if attacker["name"] == IRON_BANK_HOUSE:
        return True, None, []
    if region in ISLAND_KINGDOMS:
        return True, None, []
    # ISLAND_ONLY_HOUSES — orol uylar dengizga bevosita chiqadi
    if attacker["name"] in ISLAND_ONLY_HOUSES:
        return True, None, []
    if attacker_has_naval_vassal_beachhead(attacker["name"]):
        return True, None, []
    own_ports = _naval_ports_for_region(region)
    if attacker["name"] in own_ports:
        return True, None, []
    all_ports = _all_westeros_ports()
    if not all_ports:
        return False, "⛔ Westerosda hech qanday port shahar aniqlanmagan — dengiz jangi boshlay olmaysiz.", []
    if any(has_port_lease(p, attacker["name"]) for p in all_ports):
        return True, None, []
    return False, (f"⛔ <b>{attacker['name']}</b> port shahar yoki orol emas — dengizga chiqish uchun "
                    f"avval Westerosdagi istalgan port shahar lordidan oʻtish ruxsatini (1 soatlik ijara) "
                    f"olishingiz kerak, shundan keyingina dengizdan hujum qila olasiz."), sorted(all_ports)


def _kingdom_owning_gate(gate_name):
    """Berilgan chegara qasri (yoki port shahar) qaysi qirollikning chegarasini
    himoya qilishini aniqlaydi — ruxsat soʻralganda kimga murojaat qilishni
    bilish uchun kerak."""
    for dest, routes in LAND_GATES.items():
        for r in routes:
            if gate_name in r["gates"] or gate_name in r.get("bypass", []):
                return dest
    for region, chains in NAVAL_GATES.items():
        for chain in chains:
            if gate_name in chain:
                return region
    if gate_name in CROWNLANDS_NAVAL_GUARDS:
        return "Qirollik yerlari"
    return None


def _passage_responder(gate_name):
    """Oʻtish ruxsati soʻralganda kimga murojaat qilinishi kerakligini aniqlaydi:
    1) Agar qasrning oʻzi (uy sifatida) real egasi boʻlsa — oʻsha lord javob beradi.
    2) Aks holda (qasr hozircha NPC boshqaruvida / egasiz) — shu qasr himoya
       qiladigan qirollikning hudud lordi javob beradi (agar uning real egasi boʻlsa).
    3) Ikkalasi ham NPC boʻlsa — QIROL (agar real oʻyinchi boʻlsa) soʻrovga javob
       beradi, chunki u butun qirollikning oliy hukmdori.
    4) Uchalasi ham topilmasa — javob beradigan hech kim yoʻq (None, None).
       MUHIM: bu holatda ruxsat AVTOMATIK berilmaydi — chaqiruvchi tomon
       soʻrovni rad etishi kerak (aks holda "hamma dengizga/chegaradan
       toʻsiqsiz oʻtadi" xatosi qaytadi).
    Qaytaradi: (javobgar_uy_nomi_yoki_None, javobgar_owner_id_yoki_None)."""
    gate_house = get_house(gate_name)
    if gate_house and gate_house["owner_id"]:
        return gate_name, gate_house["owner_id"]
    kingdom = _kingdom_owning_gate(gate_name)
    if kingdom:
        region_lord_name = get_region_lord(kingdom)
        if region_lord_name and region_lord_name != gate_name:
            region_lord_house = get_house(region_lord_name)
            if region_lord_house and region_lord_house["owner_id"]:
                return region_lord_name, region_lord_house["owner_id"]
    king_name = get_king()
    if king_name and king_name != gate_name:
        king_house = get_house(king_name)
        if king_house and king_house["owner_id"]:
            return king_name, king_house["owner_id"]
    return None, None


def valyria_bonus_power(troops, valyria_stock, power_key):
    """Har bir valyria po'lati bloki (100 ta askar) shu turdagi 100 ta askarning
    kuchini 2x qiladi — ya'ni +100*kuch qo'shimcha ball beradi. Zaxira eng kuchli
    turlarga birinchi navbatda taqsimlanadi."""
    if not valyria_stock:
        return 0
    blocks_left = valyria_stock
    bonus = 0
    for u in sorted(COMBAT_UNITS, key=lambda x: -UNIT_POWER[x][power_key]):
        if blocks_left <= 0:
            break
        available_blocks = troops.get(u, 0) // VALYRIA_BLOCK
        used = min(available_blocks, blocks_left)
        if used:
            bonus += used * VALYRIA_BLOCK * UNIT_POWER[u][power_key]
            blocks_left -= used
    return bonus


def land_attack_power(troops, valyria_stock=0):
    """troops: dict {unit_name: count} — faqat COMBAT_UNITS kalitlari kerak."""
    base = sum(troops.get(u, 0) * UNIT_POWER[u]["atk"] for u in COMBAT_UNITS)
    return base + valyria_bonus_power(troops, valyria_stock, "atk")


def land_defense_power(troops, valyria_stock=0):
    base = sum(troops.get(u, 0) * UNIT_POWER[u]["def"] for u in COMBAT_UNITS)
    return base + valyria_bonus_power(troops, valyria_stock, "def")


def land_power_with_valyria_map(troops, power_key, valyria_map=None):
    """Endi lord BIR NECHTA qoʻshin turiga alohida-alohida valyria berishi
    mumkin (masalan ham otliqqa, ham benuqsonga). valyria_map: {unit: dona}.
    Har bir dona valyria shu turdan VALYRIA_BLOCK (100) tagacha askarni 2x
    kuchaytiradi."""
    base = sum(troops.get(u, 0) * UNIT_POWER[u][power_key] for u in COMBAT_UNITS)
    if valyria_map:
        for unit, count in valyria_map.items():
            if not count or unit not in troops:
                continue
            boosted_count = min(troops.get(unit, 0), VALYRIA_BLOCK * count)
            base += boosted_count * UNIT_POWER[unit][power_key]
    return base


def row_troops(row):
    return {u: row[u] for u in COMBAT_UNITS}


def naval_capacity(kema_count):
    return kema_count * SHIP_CAPACITY


def naval_ratio_ok(kema, troops):
    """V4 qoidasi: 1 kema = AYNAN 10 askar. troops — {unit: n} lug'ati yoki son."""
    total = troops if isinstance(troops, int) else sum(
        int(v) for k, v in troops.items() if k in COMBAT_UNITS)
    if kema <= 0 or total <= 0:
        return False
    return total == kema * SHIP_CAPACITY


_click_guard_data: dict = {}
_click_guard_lock = threading.Lock()


def click_guard(uid, key, ttl=3.0):
    """Debounce: bir foydalanuvchi bir xil kritik harakatni `ttl` soniya ichida
    qayta bossa False qaytaradi (spam-click). Haqiqiy himoya — DB dagi atomik
    UPDATE ... WHERE resurs>0; bu esa qo'shimcha qatlam."""
    now = time.time()
    k = (uid, key)
    with _click_guard_lock:
        last = _click_guard_data.get(k, 0)
        if now - last < ttl:
            return False
        _click_guard_data[k] = now
        if len(_click_guard_data) > 5000:
            for kk in [kk for kk, v in _click_guard_data.items() if now - v > 60]:
                _click_guard_data.pop(kk, None)
    return True


def sea_power(troops, valyria_stock=0):
    """Dengizda barcha qo'shin turlari teng kuchga ega — faqat kemaga chiqqan
    askar sonining o'zi hisoblanadi (qo'shin turi ahamiyatsiz)."""
    # 1 askar = 1 ball. Valyria po'lati dengizda bonus bermaydi (avval zaxiradagi
    # valyria avtomatik qo'shilib, 10 kema/100 askar 200 ball bo'lib qolardi).
    return sum(max(0, int(v or 0)) for v in troops.values()) * SEA_UNIT_POWER


def fmt_resources(row):
    lines = []
    for res in RESOURCE_NAMES:
        lines.append(f"{RESOURCE_EMOJI.get(res,'')} {RESOURCE_LABEL.get(res,res)}: {row[res]}")
    lines.append(f"🏆 Ritsarlik balli: {row['ritsarlik']} (= {ritsarlik_war_power(row['ritsarlik'])} askar kuchi)")
    lines.append(f"🏛️ Siyosiy balli: {row['siyosat']}")
    return "\n".join(lines)


