# KUNLIK DAROMAD + AVTOMATIK SOLIQ ("tick" tsikli)
# ---------------------------------------------------------------------------

def _daily_tick_should_fire(conn, now_struct):
    """Kunlik tick FAQAT DAILY_TICK_HOUR da (masalan soat 8:00) va shu kun uchun
    hali ishlamagan bo'lsa ishga tushadi — barcha uylar bir vaqtda daromad oladi."""
    today_key = time.strftime("%Y-%m-%d", now_struct)
    if now_struct.tm_hour < DAILY_TICK_HOUR:
        return False, today_key
    row = conn.execute("SELECT value FROM world WHERE key='last_tick_date'").fetchone()
    last_date = row["value"] if row else ""
    return (last_date != today_key), today_key


def _collect_tax(conn, payer_name, amount, recipient_name):
    """Soliqni avval tangadan, agar tanga yetmasa BUY_PRICES asosidagi
    ekvivalent qiymatda resurslardan (arzonidan boshlab) to'laydi va real
    resursni recipientga o'tkazadi. Valyria po'lati soliqqa hisoblanmaydi.
    Qaytaradi: (jami to'langan tanga ekvivalenti, to'lov tafsiloti matni)."""
    payer = conn.execute("SELECT * FROM houses WHERE name=?", (payer_name,)).fetchone()
    if not payer or amount <= 0:
        return 0, ""
    remaining = amount
    paid_lines = []

    pay_tanga = min(remaining, payer["tanga"])
    if pay_tanga > 0:
        conn.execute("UPDATE houses SET tanga=tanga-? WHERE name=?", (pay_tanga, payer_name))
        conn.execute("UPDATE houses SET tanga=tanga+? WHERE name=?", (pay_tanga, recipient_name))
        remaining -= pay_tanga
        paid_lines.append(f"{pay_tanga} 💰tanga")

    if remaining > 0:
        for res, price in sorted(BUY_PRICES.items(), key=lambda kv: kv[1]):
            if remaining <= 0:
                break
            if res == "valyria_polati":
                continue
            stock = payer[res]
            units_needed = remaining // price
            if units_needed <= 0 or stock <= 0:
                continue
            take = min(units_needed, stock)
            if take <= 0:
                continue
            conn.execute(f"UPDATE houses SET {res} = MAX({res}-?,0) WHERE name=?", (take, payer_name))
            conn.execute(f"UPDATE houses SET {res} = {res}+? WHERE name=?", (take, recipient_name))
            remaining -= take * price
            paid_lines.append(f"{take} {RESOURCE_EMOJI.get(res,'')}{RESOURCE_LABEL.get(res,res)}")

    paid_total = amount - remaining
    desc = ", ".join(paid_lines) if paid_lines else "hech narsa (resurs yetmadi)"
    return paid_total, desc


def apply_daily_income_for_house(conn, h, king, now=None):
    """Bitta uyga kunlik ishlab chiqarish + vassallik ulushi + avtomatik soliqni
    qo'llaydi. Umumiy kunlik tsiklda (process_tick) HAM, admin panelidan bitta
    oilaga qo'lda kunlik daromad berishda HAM shu funksiya ishlatiladi —
    ikkalasida ham xuddi bir xil qoida ishlaydi."""
    now = now or time.time()
    prod = PRODUCTION.get(h["name"])
    if not prod:
        # V18: ritser qurgan vassal qal'a PRODUCTION lug'atida yo'q — lekin
        # castle_daily_income ustunida saqlangan flat kunlik daromadi bor.
        custom_income = h.get("castle_daily_income", 0) or 0
        if custom_income > 0:
            prod = (h["region"], h["tier"], custom_income, 0, 0, 0, 0, 0, 0)
        else:
            return False
    _, _, tanga, qoshin, kamonchi, otliq, kema, benuqson, kenja_ogil = prod
    # Kengash bonusi: xazinachi +20% tanga daromad
    if is_council_member(h["name"], "xazinachi"):
        tanga = int(tanga * 1.20)
    # Qasr yuksaltirish bonusi: har bir yuksaltirilgan daraja kunlik daromadga
    # qoʻshimcha tanga beradi (C→B: +30, B→A: +35)
    tanga += h.get("income_bonus", 0) or 0
    conn.execute("""UPDATE houses SET tanga=tanga+?, qoshin=qoshin+?, kamonchi=kamonchi+?,
        otliq=otliq+?, kema=kema+?, benuqson=benuqson+?, kenja_ogil=kenja_ogil+?, last_income=?
        WHERE name=?""",
        (tanga, qoshin, kamonchi, otliq, kema, benuqson, kenja_ogil, now, h["name"]))

    # --- VASSALLIK: agar bu uy kimningdir vassali bo'lsa, kunlik
    #     ishlab chiqarishining YARMI ustidagi lordga o'tadi ---
    # Egasiz (owner_id IS NULL) vassal ham o'z lordiga ulush to'laydi; faqat o'ziga
    # vassal bo'lib qolgan buzuq havola o'tkazib yuboriladi.
    if h["vassal_of"] and h["vassal_of"] != h["name"]:
        overlord = conn.execute("SELECT name FROM houses WHERE name=?", (h["vassal_of"],)).fetchone()
        if overlord:
            half_tanga = tanga // 2
            half_qoshin = qoshin // 2
            half_kamonchi = kamonchi // 2
            half_otliq = otliq // 2
            half_kema = kema // 2
            half_benuqson = benuqson // 2
            half_kenja = kenja_ogil // 2
            if any([half_tanga, half_qoshin, half_kamonchi, half_otliq, half_kema, half_benuqson, half_kenja]):
                conn.execute("""UPDATE houses SET tanga=MAX(tanga-?,0), qoshin=MAX(qoshin-?,0),
                    kamonchi=MAX(kamonchi-?,0), otliq=MAX(otliq-?,0), kema=MAX(kema-?,0),
                    benuqson=MAX(benuqson-?,0), kenja_ogil=MAX(kenja_ogil-?,0) WHERE name=?""",
                    (half_tanga, half_qoshin, half_kamonchi, half_otliq, half_kema,
                     half_benuqson, half_kenja, h["name"]))
                conn.execute("""UPDATE houses SET tanga=tanga+?, qoshin=qoshin+?, kamonchi=kamonchi+?,
                    otliq=otliq+?, kema=kema+?, benuqson=benuqson+?, kenja_ogil=kenja_ogil+?
                    WHERE name=?""",
                    (half_tanga, half_qoshin, half_kamonchi, half_otliq, half_kema,
                     half_benuqson, half_kenja, h["vassal_of"]))
                try:
                    vassal_amounts = [
                        ("tanga", half_tanga), ("qoshin", half_qoshin), ("kamonchi", half_kamonchi),
                        ("otliq", half_otliq), ("kema", half_kema), ("benuqson", half_benuqson),
                        ("kenja_ogil", half_kenja),
                    ]
                    detail = ", ".join(
                        f"{n} {RESOURCE_EMOJI.get(res,'')}{RESOURCE_LABEL.get(res,res)}"
                        for res, n in vassal_amounts if n > 0
                    ) or "hech narsa"
                    if h["owner_id"]:
                        notify(h["owner_id"],
                            f"🏰 Vassal sifatida kunlik daromadingizdan {detail} <b>{h['vassal_of']}</b> ga o'tdi.")
                    ov = conn.execute("SELECT owner_id FROM houses WHERE name=?", (h["vassal_of"],)).fetchone()
                    if ov and ov["owner_id"]:
                        notify(ov["owner_id"],
                            f"🏰 Vassalingiz <b>{h['name']}</b> dan {detail} keldi.")
                except Exception as _e:
                    _swallow(_e)

    # --- AVTOMATIK SOLIQ ---
    # (agar uy admin tomonidan "soliqdan ozod" qilingan bo'lsa — bekor qilingan
    # ittifoq/qo'zg'olon/qirol inʼomi kabi sabablarga ko'ra — soliq olinmaydi)
    # YANGI QOIDA (V13):
    #   - QIROLGA faqat HUDUD LORDI soliq toʻlaydi (20 tanga).
    #   - Qolgan barcha uylar (shu jumladan lord boʻlmagan A toifa uylar ham)
    #     oʻz hudud lordiga toifa boʻyicha toʻlaydi: A — 15, B — 9, C — 5 tanga.
    # BUG FIX: vassal bo'lgan uy allaqachon yuqorida daromadining YARMINI
    # o'z lordiga (vassal_of) berdi. Shu sababli vassal uydan hudud lordiga
    # ALOHIDA soliq olinmaydi — ikki marta ayirishning oldini olish uchun.
    region_lord_row = conn.execute("SELECT lord_house FROM regions WHERE region=?", (h["region"],)).fetchone()
    region_lord = region_lord_row["lord_house"] if region_lord_row else None
    if not h["tax_exempt"] and not h["vassal_of"]:
        if region_lord and h["name"] == region_lord:
            tax = KING_TAX
            recipient = king
            recipient_label = f"qirolga (<b>{king}</b>)" if king else ""
        else:
            tax = TAX_RATE.get(h["tier"], 0)
            recipient = region_lord
            recipient_label = f"hudud lordi <b>{region_lord}</b> ga" if region_lord else ""
        if tax > 0 and recipient and h["name"] != recipient:
            paid, desc = _collect_tax(conn, h["name"], tax, recipient)
            if paid > 0:
                try:
                    owner = conn.execute("SELECT owner_id FROM houses WHERE name=?", (h["name"],)).fetchone()
                    if owner and owner["owner_id"]:
                        note = "" if paid >= tax else f" (jami {tax} tangadan faqat {paid} tasi qoplandi, resurs yetmadi)"
                        bot.send_message(owner["owner_id"],
                            f"📜 Kunlik daromad qoʻshildi va soliq sifatida {desc} "
                            f"{recipient_label} toʻlandi{note}.")
                except Exception as _e:
                    _swallow(_e)
    return True


def _apply_essos_city_daily_production(conn, city_name, now_struct=None, force=False):
    """Bitta Essos shahri uchun kunlik ishlab chiqarishni beradi (ESSOS_CITIES
    lugʻatidan). Agar shahar boshqa Essos shahri tomonidan bosib olingan
    (vassal_of boshqa Essos shahri) boʻlsa — "Boshqa Essos Shaharlarini bosib
    olish u shaharning ham kunlik ishlab chiqarishini oʻziga olishni
    anglatadi" qoidasiga koʻra, TOʻLIQ ishlab chiqarish egallovchi shaharga
    oʻtadi (oʻziga emas)."""
    now_struct = now_struct or time.localtime()
    res = ESSOS_CITIES.get(city_name)
    if not res:
        return False
    today_key = time.strftime("%Y-%m-%d", now_struct)
    tick_key = f"essos_last_tick_{city_name}"
    row = conn.execute("SELECT value FROM world WHERE key=?", (tick_key,)).fetchone()
    if not force and row and row["value"] == today_key:
        return False  # bugun allaqachon berilgan

    house_row = conn.execute("SELECT vassal_of FROM houses WHERE name=?", (city_name,)).fetchone()
    recipient = city_name
    if house_row and house_row["vassal_of"]:
        overlord = conn.execute(
            "SELECT is_essos FROM houses WHERE name=?", (house_row["vassal_of"],)).fetchone()
        if overlord and overlord["is_essos"]:
            recipient = house_row["vassal_of"]

    for resource, amount in res.items():
        if amount:
            conn.execute(f"UPDATE houses SET {resource} = {resource} + ? WHERE name=?",
                         (amount, recipient))
    conn.execute("INSERT INTO world (key,value) VALUES (?,?) "
                 "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (tick_key, today_key))
    conn.commit()
    return True


def _apply_essos_daily_production(conn, now_struct=None, force=False):
    """Barcha Essos shaharlari (hozir faqat Bravos) uchun kunlik ishlab
    chiqarishni birma-bir beradi."""
    now_struct = now_struct or time.localtime()
    for city_name in ESSOS_CITIES:
        _apply_essos_city_daily_production(conn, city_name, now_struct, force=force)


