@bot.callback_query_handler(func=lambda c: c.data.startswith("ww_pct_"))
def cb_ww_pct(c):
    uid = c.from_user.id
    sess = white_walker_session.get(uid)
    if not sess:
        bot.answer_callback_query(c.id, "Tanlash sessiyasi topilmadi.", show_alert=True)
        return
    _, _, unit, pct_text = c.data.split("_")
    house = get_house_by_owner(uid)
    if not house or unit not in COMBAT_UNITS:
        return
    amount = round(house[unit] * max(0, min(int(pct_text), 100)) / 100)
    sess["units"][unit] = amount
    if sess["queue"] and sess["queue"][0] == unit:
        sess["queue"].pop(0)
    bot.answer_callback_query(c.id, f"{amount} ta tanlandi.")
    _ww_selection_prompt(c.message.chat.id, uid)


@bot.callback_query_handler(func=lambda c: c.data == "ww_confirm")
def cb_ww_confirm(c):
    uid = c.from_user.id
    sess = white_walker_session.pop(uid, None)
    event = _ww_event()
    house = get_house_by_owner(uid)
    if not sess or not event or not house or event["id"] != sess["event_id"]:
        bot.answer_callback_query(c.id, "Event yopilgan.", show_alert=True)
        return
    units = {u: n for u, n in sess["units"].items() if n > 0}
    if not units:
        bot.answer_callback_query(c.id, "Kamida bitta qoʻshin tanlang.", show_alert=True)
        return
    conn = db()
    current = conn.execute(
        "SELECT defense_units,helper_units,nk_units FROM white_walker_events WHERE id=?",
        (event["id"],)).fetchone()
    existing_helpers = json.loads(current["helper_units"] or "{}")
    if sess["mode"] == "wall" and current["defense_units"]:
        conn.close()
        bot.answer_callback_query(c.id, "Devor qoʻshini allaqachon tanlangan.", show_alert=True)
        return
    if sess["mode"] == "helper" and house["name"] in existing_helpers:
        conn.close()
        bot.answer_callback_query(c.id, "Siz allaqachon yordam qoʻshdingiz.", show_alert=True)
        return
    _vused, _vbonus = _ww_auto_valyria(house, units)
    if _vused:
        units["_vbonus"] = _vbonus
        conn.execute("UPDATE houses SET valyria_polati=MAX(valyria_polati-?,0) WHERE name=?",
                     (_vused, house["name"]))
    _ww_commit_units(house["name"], units)
    if sess["mode"] == "wall":
        conn.execute(
            "UPDATE white_walker_events SET defense_units=? WHERE id=?",
            (json.dumps(units), event["id"]))
    else:
        existing_helpers[house["name"]] = units
        conn.execute(
            "UPDATE white_walker_events SET helper_units=? WHERE id=?",
            (json.dumps(existing_helpers), event["id"]))
    conn.commit()
    conn.close()
    bot.answer_callback_query(c.id, "Qoʻshin eventga yuborildi.")
    bot.send_message(c.message.chat.id,
                     "✅ Qoʻshin Oq piyodalarga qarshi jangga yuborildi.",
                     reply_markup=main_menu(uid))


# ===========================================================================
# V9: TUN QIROLI — ALOHIDA ROL (uy lordi EMAS)
# ---------------------------------------------------------------------------
# * Tun qiroli — uy lordi bilan bir vaqtda bo'la olmaydi: uyi, xazinasi yo'q.
# * Temir bankdan askar sotib ola olmaydi, savdo qila olmaydi.
# * Alohida (o'z) menyusi bor — asosiy o'yin bo'limlariga kira olmaydi.
# * Qo'shini 3 turdan iborat (ball = hujum VA himoya kuchi, ikkalasi bir xil):
#       💀 Oddiy o'liklar            — 2 ball
#       🐴 O'lik otliqlar            — 3 ball
#       ❄️ Oq o'lik chavandozlari    — 4 ball
# * Har kuni (kunlik tick vaqtida) har bir turdan 100 tadan oladi.
# * Qo'shin Oq piyodalar hujumi paytida Devorga qarshi yuboriladi.
# ===========================================================================
NIGHT_KING_KEY = "night_king_uid"
NK_ARMY_KEY = "nk_army"
NK_DAILY_PER_UNIT = 100         # har bir turdan kuniga shuncha dona

NK_UNITS = {
    "olik":         {"label": "Oddiy oʻliklar",         "emoji": "💀", "power": 2},
    "olik_otliq":   {"label": "Oʻlik otliqlar",         "emoji": "🐴", "power": 3},
    "oq_chavandoz": {"label": "Oq oʻlik chavandozlari", "emoji": "❄️", "power": 4},
}
NK_UNIT_KEYS = list(NK_UNITS.keys())

NK_BTN_ARMY = "💀 Armiyam"
NK_BTN_ATTACK = "🌑 Oq piyodalar hujumi"
NK_BTN_RULES = "📜 Tun qiroli qoidalari"
NK_MENU_TEXTS = {NK_BTN_ARMY, NK_BTN_ATTACK, NK_BTN_RULES, "⬅️ Bosh menyu",
                 "👤 Profilim", "⚔️ Janglar", "🏰 Uylar", "📊 Reyting"}
NK_ALLOWED_CALLBACKS = {"m_uylar", "m_reyting"}
NK_ALLOWED_CALLBACK_PREFIXES = ("nkp_", "hview_")

_nk_lock = threading.Lock()                 # armiya o'qish-yozish poygasidan himoya
_nk_uid_cache = [None, 0.0, False]          # [uid, muddati, yaroqli]


def get_night_king_uid():
    now = time.time()
    if _nk_uid_cache[2] and now < _nk_uid_cache[1]:
        return _nk_uid_cache[0]
    conn = db()
    row = conn.execute("SELECT value FROM world WHERE key=?", (NIGHT_KING_KEY,)).fetchone()
    conn.close()
    uid = int(row["value"]) if row and str(row["value"]).lstrip("-").isdigit() else None
    _nk_uid_cache[0] = uid
    _nk_uid_cache[1] = now + 2.0
    _nk_uid_cache[2] = True
    return uid


def _set_night_king(uid):
    conn = db()
    if uid is None:
        conn.execute("DELETE FROM world WHERE key=?", (NIGHT_KING_KEY,))
    else:
        conn.execute("INSERT INTO world (key,value) VALUES (?,?) "
                     "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                     (NIGHT_KING_KEY, str(uid)))
    conn.commit()
    conn.close()
    _nk_uid_cache[2] = False


def is_night_king(uid):
    return bool(uid) and get_night_king_uid() == uid


def _nk_label():
    uid = get_night_king_uid()
    if not uid:
        return "🤖 NPC (avtomatik, tajovuzkor)"
    nm = get_user_name(uid) or "—"
    return f"{nm} (ID {uid})"


# ---- Armiya (rolga tegishli: o'yinchi almashsa ham saqlanadi) -------------
def get_nk_army(conn=None):
    own = conn is None
    conn = conn or db()
    row = conn.execute("SELECT value FROM world WHERE key=?", (NK_ARMY_KEY,)).fetchone()
    if own:
        conn.close()
    try:
        raw = json.loads(row["value"]) if row and row["value"] else {}
    except Exception:
        raw = {}
    if not isinstance(raw, dict):
        raw = {}
    out = {}
    for k in NK_UNIT_KEYS:
        try:
            out[k] = max(0, int(raw.get(k, 0) or 0))
        except (TypeError, ValueError):
            out[k] = 0
    return out


def _save_nk_army(conn, army):
    conn.execute("INSERT INTO world (key,value) VALUES (?,?) "
                 "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                 (NK_ARMY_KEY, json.dumps({k: int(army.get(k, 0)) for k in NK_UNIT_KEYS})))


def nk_power(units, mode="atk"):
    """Tun qiroli qo'shinining kuchi. mode ('atk' / 'def') hozircha farq
    qilmaydi — ball hujum ham, himoya ham uchun bir xil amal qiladi."""
    total = 0
    for k in NK_UNIT_KEYS:
        try:
            total += int(units.get(k, 0) or 0) * NK_UNITS[k]["power"]
        except (TypeError, ValueError):
            pass
    return total


def _ww_atk_power(units):
    return nk_power(units, "atk")


def _nk_units_lines(units):
    return "\n".join(
        f"{NK_UNITS[k]['emoji']} {NK_UNITS[k]['label']}: <b>{int(units.get(k, 0))}</b> ta "
        f"({NK_UNITS[k]['power']} ball)" for k in NK_UNIT_KEYS)


def _nk_army_text():
    army = get_nk_army()
    return (
        "☠️ <b>Tun qiroli armiyasi</b>\n\n"
        f"{_nk_units_lines(army)}\n\n"
        f"⚔️🛡️ Umumiy kuch: <b>{nk_power(army)}</b> ball (hujum va himoya uchun)\n"
        f"📅 Har kuni har turdan <b>+{NK_DAILY_PER_UNIT}</b> ta qo'shiladi.")


def _nk_rules_text():
    return (
        "📜 <b>Tun qiroli qoidalari</b>\n\n"
        "• Siz uy lordi emassiz — uyingiz va xazinangiz yo'q, lord bo'lib ham olmaysiz.\n"
        "• Savdo, Temir bank, ittifoq va chat bo'limlari sizga yopiq.\n"
        "• Urush va Oq piyodalarni siz boshqarasiz: ⚔️ Janglar → 🧱 Devorga hujum qilish.\n"
        "• Devor qulamaguncha Shimol va boshqa lordliklarga hujum qila olmaysiz. "
        "Devor yiqilgach, ⚔️ Janglar bo'limidan istalgan Westeros lordligiga hujum qilasiz.\n\n"
        "<b>Qo'shin turlari</b> (ball hujum va himoya uchun bir xil):\n"
        f"{_nk_units_lines({})}\n\n"
        f"📅 Har kuni har bir turdan <b>{NK_DAILY_PER_UNIT}</b> tadan olasiz.\n"
        "🌑 Oq piyodalar hujumi boshlanganda qo'shiningizni Devorga qarshi "
        "yuborishingiz mumkin. Devor yutsa 50%, Oq piyodalar yutsa 10% yo'qotasiz; "
        "tirik qolganlar armiyangizga qaytadi.\n"
        "💀 Jangda o'ldirilgan BARCHA dushman askarlari va o'zingiz yo'qotgan askarlarning "
        "YARMI oddiy o'lik bo'lib armiyangizga qo'shiladi.\n"
        "⏰ Hujum faqat urush vaqtida, kunlik limit yo'q.\n"
        "🗺️ Yurish tartibi: Umber → Shimol → Frey → Daryo yerlari va Vodiy → "
        "G'arbiy yerlar va Qirollik bandargohi → Kengliklar va To'fonli yerlar → Dorne.\n"
        "🤖 Admin Tun qirolini tayinlamasa, NPC Tun qiroli o'zi hujum qiladi.")


def nk_main_menu(uid):
    kb = types.ReplyKeyboardMarkup(resize_keyboard=True, row_width=2)
    kb.add(types.KeyboardButton("/start"), types.KeyboardButton("/help"))
    kb.add(types.KeyboardButton("👤 Profilim"), types.KeyboardButton("⚔️ Janglar"))
    kb.add(types.KeyboardButton("🏰 Uylar"), types.KeyboardButton("📊 Reyting"))
    kb.add(types.KeyboardButton(NK_BTN_RULES))
    return kb


def show_nk_home(chat_id, uid):
    bot.send_message(chat_id, "☠️ <b>Siz Tun qirolisiz.</b>\n\n" + _nk_army_text(),
                     reply_markup=nk_main_menu(uid), parse_mode="HTML")


def _nk_daily_tick(conn):
    """Har kuni har bir turdan NK_DAILY_PER_UNIT tadan qo'shadi (o'yinchi yoki NPC Tun qiroli)."""
    uid = get_night_king_uid()
    with _nk_lock:
        army = get_nk_army(conn)
        for k in NK_UNIT_KEYS:
            army[k] += NK_DAILY_PER_UNIT
        _save_nk_army(conn, army)
        conn.commit()
    if not uid:
        return
    notify(uid,
           "☠️ <b>Kunlik qo'shin keldi!</b>\n\n" + _nk_army_text(),
           nk_main_menu(uid))


def _nk_add_units(add):
    with _nk_lock:
        conn = db()
        army = get_nk_army(conn)
        for k, n in add.items():
            if k in army:
                army[k] += int(n)
        _save_nk_army(conn, army)
        conn.commit()
        conn.close()


def _nk_return_survivors(units, loss_ratio):
    """Jangdan keyin tirik qolganlarni Tun qiroli armiyasiga qaytaradi."""
    survivors = {}
    with _nk_lock:
        conn = db()
        army = get_nk_army(conn)
        for k in NK_UNIT_KEYS:
            n = int(units.get(k, 0) or 0)
            if n <= 0:
                continue
            lost = min(n, int(n * loss_ratio))
            alive = n - lost
            if alive:
                survivors[k] = alive
                army[k] += alive
        _save_nk_army(conn, army)
        conn.commit()
        conn.close()
    return survivors


# ---- Himoya: Tun qiroli bo'lmagan hech kim NK bo'limlariga kira olmaydi ----
def _nk_removed_notice(old_uid):
    nk_session.pop(old_uid, None)
    notify(old_uid,
           "☠️ Siz endi Tun qiroli emassiz.\n/start bosing — sizga oddiy o'yinchi sifatida "
           "uy biriktiriladi.",
           main_menu(old_uid))


class _NightKingMiddleware(telebot.handler_backends.BaseMiddleware):
    """Tun qiroli faqat o'z menyusidan (nk_main_menu va 'nkp_' tugmalari)
    foydalana oladi. Uy/savdo/Temir bank/jang va boshqa barcha bo'limlar unga yopiq."""

    def __init__(self):
        super().__init__()
        self.update_types = ["message", "callback_query"]

    def pre_process(self, update_obj, data):
        uid = update_obj.from_user.id if update_obj.from_user else None
        if not uid or is_admin(uid) or not is_night_king(uid):
            return None
        data_ = getattr(update_obj, "data", None) or ""
        if _ai_companion_for(uid) and (data_.startswith(("edw_", "katie_"))
                                       or _ai_companion_for(uid, getattr(update_obj, "text", None))
                                       or (not isinstance(update_obj, types.CallbackQuery)
                                           and _ai_in_chat_mode(uid))):
            return None
        if isinstance(update_obj, types.CallbackQuery):
            cdata = update_obj.data or ""
            if cdata.startswith(NK_ALLOWED_CALLBACK_PREFIXES) or cdata in NK_ALLOWED_CALLBACKS:
                return None
            if cdata == "m_back":
                try:
                    bot.answer_callback_query(update_obj.id)
                    show_nk_home(update_obj.message.chat.id, uid)
                except Exception as _e:
                    _swallow(_e)
                return telebot.handler_backends.CancelUpdate()
            try:
                bot.answer_callback_query(
                    update_obj.id, "☠️ Tun qiroli bu amalni bajara olmaydi.", show_alert=True)
            except Exception as _e:
                _swallow(_e)
            return telebot.handler_backends.CancelUpdate()
        text = update_obj.text or ""
        first = text.split()[0].split("@")[0] if text.split() else ""
        if first in ("/start", "/help") or text in NK_MENU_TEXTS or text in _REPLY_NAV_TEXT:
            return None
        try:
            bot.send_message(
                update_obj.chat.id,
                "☠️ Tun qiroli uchun savdo, Temir bank, ittifoq va chat bo'limlari yopiq. "
                "Quyidagi menyudan foydalaning 👇",
                reply_markup=nk_main_menu(uid))
        except Exception as _e:
            _swallow(_e)
        return telebot.handler_backends.CancelUpdate()

    def post_process(self, update_obj, data, exception=None):
        pass


bot.setup_middleware(_NightKingMiddleware())


# ---- Tun qiroli menyusi (doimiy panel tugmalari) ---------------------------
nk_session = {}   # uid -> {"event_id", "units": {}, "queue": [...]}


def _nk_only(c):
    """Tun qiroli bo'lmasa False (va tushuntirish yuboradi)."""
    if is_night_king(c.from_user.id):
        return True
    bot.answer_callback_query(c.id, "Bu bo'lim faqat Tun qiroli uchun.", show_alert=True)
    return False


def cb_nk_army(c):
    if not _nk_only(c):
        return
    bot.send_message(c.message.chat.id,
                     f"☠️ <b>Tun qiroli</b> — {_nk_label()}\n\n{_nk_army_text()}\n\n{_nk_status_text()}",
                     reply_markup=nk_main_menu(c.from_user.id), parse_mode="HTML")
    bot.answer_callback_query(c.id)


def cb_nk_rules(c):
    if not _nk_only(c):
        return
    bot.send_message(c.message.chat.id, _nk_rules_text(),
                     reply_markup=nk_main_menu(c.from_user.id), parse_mode="HTML")
    bot.answer_callback_query(c.id)


def cb_nk_attack_menu(c):
    """Tun qiroli 'Janglar' bo'limi: Devorga hujum, Devor yiqilgach — lordliklarga hujum."""
    if not _nk_only(c):
        return
    now = time.time()
    event = _ww_event()
    kb = types.InlineKeyboardMarkup(row_width=1)
    if event and event["deadline"] > now:
        sent = json.loads(event["nk_units"] or "{}")
        remaining = max(0, int(event["deadline"] - now))
        if sent:
            text = (f"🌑 <b>Devorga hujum davom etyapti.</b>\n"
                    f"☠️ Qo'shiningiz yuborilgan (kuch: <b>{nk_power(sent, 'atk')}</b> ball).\n"
                    f"{_nk_units_lines(sent)}\n\nJang tugashiga ~{remaining // 60} daqiqa.")
        else:
            kb.add(types.InlineKeyboardButton("☠️ Qo'shin yuborish", callback_data="nkp_join"),
                   types.InlineKeyboardButton("🚫 Qatnashmayman", callback_data="nkp_skip"))
            text = (f"🌑 <b>Oq piyodalar {WALL_HOUSE}ga hujum qilyapti!</b>\n"
                    f"Muddat: ~{remaining // 60} daqiqa qoldi.")
    elif not _wall_destroyed():
        kb.add(types.InlineKeyboardButton("🧱 Devorga hujum qilish", callback_data="nkp_wall"))
        text = ("⚔️ <b>Tun qiroli urushlari</b>\n\n"
                "🧱 Devor hali turibdi. Devor qulamaguncha Shimol va boshqa lordliklarga "
                "hujum qila olmaysiz.")
    else:
        kb.add(types.InlineKeyboardButton("🗡️ Lordlikka hujum qilish", callback_data="nkp_htarget"))
        text = ("⚔️ <b>Tun qiroli urushlari</b>\n\n"
                "☠️ Devor yiqilgan! Endi Shimol va boshqa Westeros lordliklariga hujum qila olasiz.")
    text += f"\n\n{_nk_status_text()}\n\n{_nk_army_text()}"
    _nk_say(c, text, kb if json.loads(kb.to_json()).get("inline_keyboard") else None)


@bot.callback_query_handler(func=lambda c: c.data == "nkp_skip")
def cb_nkp_skip(c):
    if not is_night_king(c.from_user.id):
        bot.answer_callback_query(c.id)
        return
    nk_session.pop(c.from_user.id, None)
    bot.answer_callback_query(c.id, "Qatnashmadingiz.")


def _nk_selection_prompt(chat_id, uid):
    sess = nk_session.get(uid)
    if not sess:
        return
    army = get_nk_army()
    if not sess["queue"]:
        chosen = sess["units"]
        kb = types.InlineKeyboardMarkup(row_width=1)
        kb.add(types.InlineKeyboardButton("✅ Tasdiqlash", callback_data="nkp_confirm"),
               types.InlineKeyboardButton("🚫 Bekor qilish", callback_data="nkp_skip"))
        bot.send_message(
            chat_id,
            "☠️ <b>Yuboriladigan qo'shin:</b>\n\n"
            f"{_nk_units_lines(chosen)}\n\n"
            f"⚔️ Jami kuch: <b>{nk_power(chosen, 'atk')}</b> ball",
            reply_markup=kb, parse_mode="HTML")
        return
    unit = sess["queue"][0]
    info = NK_UNITS[unit]
    kb = types.InlineKeyboardMarkup(row_width=5)
    kb.add(*[types.InlineKeyboardButton(f"{p}%", callback_data=f"nkp_pct_{unit}_{p}")
             for p in (0, 25, 50, 75, 100)])
    bot.send_message(
        chat_id,
        f"{info['emoji']} <b>{info['label']}</b> ({info['power']} ball): qanchasini yuborasiz? "
        f"(sizda {army[unit]} ta bor)",
        reply_markup=kb, parse_mode="HTML")


@bot.callback_query_handler(func=lambda c: c.data == "nkp_join")
def cb_nkp_join(c):
    uid = c.from_user.id
    if not is_night_king(uid):
        bot.answer_callback_query(c.id)
        return
    event = _ww_event()
    if not event or event["deadline"] <= time.time():
        bot.answer_callback_query(c.id, "Hujum yopilgan.", show_alert=True)
        return
    if (event["nk_units"] or "{}") not in ("", "{}"):
        bot.answer_callback_query(c.id, "Qo'shin allaqachon yuborilgan.", show_alert=True)
        return
    army = get_nk_army()
    queue = [k for k in NK_UNIT_KEYS if army[k] > 0]
    if not queue:
        bot.answer_callback_query(c.id, "Armiyangiz bo'sh.", show_alert=True)
        return
    nk_session[uid] = {"mode": "help", "event_id": event["id"], "units": {}, "queue": queue}
    bot.answer_callback_query(c.id)
    _nk_selection_prompt(c.message.chat.id, uid)


@bot.callback_query_handler(func=lambda c: c.data.startswith("nkp_pct_"))
def cb_nkp_pct(c):
    uid = c.from_user.id
    sess = nk_session.get(uid)
    if not is_night_king(uid) or not sess:
        bot.answer_callback_query(c.id, "Tanlash sessiyasi topilmadi.", show_alert=True)
        return
    unit, pct_text = c.data[len("nkp_pct_"):].rsplit("_", 1)
    if unit not in NK_UNITS or not pct_text.isdigit() or not sess["queue"] \
            or sess["queue"][0] != unit:
        bot.answer_callback_query(c.id)
        return
    pct = max(0, min(int(pct_text), 100))
    amount = get_nk_army()[unit] * pct // 100
    sess["units"][unit] = amount
    sess["queue"].pop(0)
    bot.answer_callback_query(c.id, f"{amount} ta tanlandi.")
    _nk_selection_prompt(c.message.chat.id, uid)


@bot.callback_query_handler(func=lambda c: c.data == "nkp_confirm")
def cb_nkp_confirm(c):
    uid = c.from_user.id
    if not is_night_king(uid):
        bot.answer_callback_query(c.id)
        return
    if not click_guard(uid, "nkp_confirm", 3.0):
        bot.answer_callback_query(c.id)
        return
    sess = nk_session.pop(uid, None)
    mode = (sess or {}).get("mode", "help")
    if mode == "wall":
        _nk_launch_wall(c, sess)
        return
    if mode == "house":
        _nk_launch_house(c, sess)
        return
    event = _ww_event()
    if (not sess or not event or event["id"] != sess["event_id"]
            or event["deadline"] <= time.time()):
        bot.answer_callback_query(c.id, "Hujum yopilgan yoki muddat tugagan.", show_alert=True)
        return
    with _nk_lock:
        conn = db()
        cur_ev = conn.execute(
            "SELECT status, nk_units FROM white_walker_events WHERE id=?",
            (event["id"],)).fetchone()
        if (not cur_ev or cur_ev["status"] != "pending"
                or (cur_ev["nk_units"] or "{}") not in ("", "{}")):
            conn.close()
            bot.answer_callback_query(c.id, "Qo'shin allaqachon yuborilgan yoki hujum yopilgan.",
                                      show_alert=True)
            return
        army = get_nk_army(conn)
        sent = {}
        for k in NK_UNIT_KEYS:
            n = min(int(sess["units"].get(k, 0)), army[k])
            if n > 0:
                sent[k] = n
                army[k] -= n
        if not sent:
            conn.close()
            bot.answer_callback_query(c.id, "Kamida bitta qo'shin tanlang.", show_alert=True)
            return
        _save_nk_army(conn, army)
        conn.execute("UPDATE white_walker_events SET nk_units=? WHERE id=? AND status='pending'",
                     (json.dumps(sent), event["id"]))
        conn.commit()
        conn.close()
    bot.answer_callback_query(c.id, "Qo'shin yuborildi.")
    bot.send_message(
        c.message.chat.id,
        "☠️ Qo'shiningiz Oq piyodalar safiga qo'shildi.\n\n"
        f"{_nk_units_lines(sent)}\n\n⚔️ Kuch: <b>{nk_power(sent, 'atk')}</b> ball",
        reply_markup=nk_main_menu(uid), parse_mode="HTML")


