def _process_nk_admin(m):
    uid = m.from_user.id
    mode = _nk_admin_session.pop(uid, None)
    if not is_admin(uid) or not mode:
        return
    text = (m.text or "").strip()
    if text.lower() == "/cancel":
        bot.send_message(m.chat.id, "❌ Bekor qilindi.", reply_markup=main_menu(uid))
        return
    if not re.fullmatch(r"\d+", text):
        bot.send_message(m.chat.id, "❌ Butun son kiriting.", reply_markup=main_menu(uid))
        return
    val = int(text)
    if mode == "power":
        conn = db()
        conn.execute("INSERT INTO world (key,value) VALUES ('ww_admin_power',?) "
                     "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (str(val),))
        conn.commit()
        conn.close()
        bot.send_message(m.chat.id,
            f"✅ Oq piyodalar bazaviy kuchi: {val if val else 'tasodifiy rejim'}.",
            reply_markup=main_menu(uid))
        return
    if is_admin(val):
        bot.send_message(m.chat.id, "❌ Adminni Tun qiroli qilib bo'lmaydi.",
                         reply_markup=main_menu(uid))
        return
    _c = db()
    _u = _c.execute("SELECT 1 FROM users WHERE user_id=?", (val,)).fetchone()
    _c.close()
    if not _u:
        bot.send_message(m.chat.id,
            "❌ Bu foydalanuvchi topilmadi (u avval botda /start bosishi kerak).",
            reply_markup=main_menu(uid))
        return
    _h = get_house_by_owner(val)
    if _h:
        bot.send_message(m.chat.id,
            f"❌ Bu foydalanuvchi hozir <b>{_h['name']}</b> uyining egasi. Uy lordi bir vaqtda "
            "Tun qiroli bo'la olmaydi — avval \"🗡️ Xonadon lordini olib tashlash\" orqali "
            "uni uydan bo'shating, so'ng qayta tayinlang.",
            reply_markup=main_menu(uid), parse_mode="HTML")
        return
    old = get_night_king_uid()
    _set_night_king(val)
    nk_session.pop(val, None)
    notify(val,
           "☠️ <b>Siz Tun qirolisiz!</b>\n\n" + _nk_army_text() + "\n\n"
           "Sizning alohida menyungiz bor. Savdo va Temir bankdan foydalana olmaysiz — "
           "qo'shiningiz har kuni o'zi to'ldirib boriladi.",
           nk_main_menu(val))
    if old and old != val:
        _nk_removed_notice(old)
    bot.send_message(m.chat.id,
        f"✅ Tun qiroli tayinlandi: {_nk_label()}", reply_markup=main_menu(uid))


