NK_HOUSE_ATTACK_WINDOW = 15 * 60      # lordlik himoyaga tayyorlanishi uchun vaqt


def _nk_say(c, text, kb=None):
    try:
        bot.answer_callback_query(c.id)
    except Exception as _e:
        _swallow(_e)
    bot.send_message(c.message.chat.id, text,
                     reply_markup=kb or nk_main_menu(c.from_user.id), parse_mode="HTML")


def _nk_world_float(key):
    conn = db()
    row = conn.execute("SELECT value FROM world WHERE key=?", (key,)).fetchone()
    conn.close()
    try:
        return float(row["value"]) if row and row["value"] else 0.0
    except (TypeError, ValueError):
        return 0.0


def _nk_pending_house_attack():
    conn = db()
    row = conn.execute(
        "SELECT * FROM nk_attacks WHERE status='pending' ORDER BY id DESC LIMIT 1").fetchone()
    conn.close()
    return row


def _nk_wall_block_reason(now=None):
    if _ww_banned():
        return "⛔ Admin Oq piyodalar hujumini vaqtincha taqiqlagan."
    if not get_house(WALL_HOUSE):
        return "Devor uyi topilmadi."
    if _wall_destroyed():
        return "Devor allaqachon yiqilgan — endi lordliklarga hujum qiling."
    if _ww_event():
        return "Devorga hujum allaqachon davom etyapti."
    if not is_war_time():
        return "Devorga hujum faqat urush vaqtida boshlanadi."
    return None


def _nk_house_block_reason():
    if _ww_banned():
        return "⛔ Admin Oq piyodalar hujumini vaqtincha taqiqlagan."
    if not _wall_destroyed():
        return ("🧱 Devor qulamaguncha Shimol va boshqa lordliklarga hujum qila olmaysiz. "
                "Avval Devorni yiqiting!")
    if not is_war_time():
        return "Lordliklarga hujum faqat urush vaqtida mumkin."
    return None


def _nk_status_text():
    now = time.time()
    lines = ["🧱 Devor: <b>yiqilgan</b> — lordliklarga hujum ochiq." if _wall_destroyed()
             else "🧱 Devor: <b>turibdi</b> — avval Devorga hujum qilish kerak."]
    ev = _ww_event()
    if ev:
        lines.append(f"🌑 Devorga hujum davom etyapti (~{max(0, int(ev['deadline'] - now)) // 60} daqiqa).")
    conn = db()
    pending = conn.execute("SELECT * FROM nk_attacks WHERE status='pending' ORDER BY id").fetchall()
    conn.close()
    for pa in pending:
        lines.append(f"🗡️ {pa['target']}ga hujum (~{max(0, int(pa['deadline'] - now)) // 60} daqiqa).")
    if _ww_banned():
        lines.append("⛔ Admin hujumlarni vaqtincha taqiqlagan.")
    return "\n".join(lines)


def _nk_start_selection(c, sess):
    army = get_nk_army()
    queue = [k for k in NK_UNIT_KEYS if army[k] > 0]
    if not queue:
        _nk_say(c, "Armiyangiz bo'sh.")
        return
    sess.update({"units": {}, "queue": queue})
    nk_session[c.from_user.id] = sess
    bot.answer_callback_query(c.id)
    _nk_selection_prompt(c.message.chat.id, c.from_user.id)


def _nk_take_units(sess):
    with _nk_lock:
        conn = db()
        army = get_nk_army(conn)
        sent = {}
        for k in NK_UNIT_KEYS:
            n = min(int((sess or {}).get("units", {}).get(k, 0) or 0), army[k])
            if n > 0:
                sent[k] = n
                army[k] -= n
        if sent:
            _save_nk_army(conn, army)
            conn.commit()
        conn.close()
    return sent


@bot.callback_query_handler(func=lambda c: c.data == "nkp_wall")
def cb_nkp_wall(c):
    if not _nk_only(c):
        return
    reason = _nk_wall_block_reason()
    if reason:
        _nk_say(c, "❌ " + reason)
        return
    _nk_start_selection(c, {"mode": "wall", "event_id": None})


def _nk_launch_wall(c, sess):
    reason = _nk_wall_block_reason()
    if reason:
        _nk_say(c, "❌ " + reason)
        return
    sent = _nk_take_units(sess)
    if not sent:
        _nk_say(c, "Kamida bitta qo'shin tanlang.")
        return
    if not _ww_start_event(by_nk=True, nk_units=sent):
        _nk_add_units(sent)
        _nk_say(c, "❌ Hujumni boshlab bo'lmadi.")
        return
    _nk_say(c, f"☠️ <b>Devorga hujum boshlandi!</b>\n\n{_nk_units_lines(sent)}\n\n"
               f"⚔️ Kuch: <b>{nk_power(sent)}</b> ball\n"
               f"⏰ Natija {WHITE_WALKER_WINDOW_SECONDS // 60} daqiqadan keyin.")


def _nk_conquered():
    conn = db()
    row = conn.execute("SELECT value FROM world WHERE key='nk_conquered'").fetchone()
    conn.close()
    try:
        return set(json.loads(row["value"])) if row else set()
    except Exception:
        return set()


def _nk_mark_conquered(name):
    done = _nk_conquered()
    done.add(name)
    conn = db()
    conn.execute("INSERT INTO world (key,value) VALUES ('nk_conquered',?) "
                 "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                 (json.dumps(sorted(done), ensure_ascii=False),))
    conn.commit()
    conn.close()


def _nk_allowed_targets():
    """Tun qiroli geografik tartibda yuradi:
    Umber → Shimol → Frey → Daryo yerlari + Vodiy (Tully, Arryn) →
    G'arbiy yerlar + Qirollik yerlari (+ Temir orollar) → Kenglik + To'fonli
    yerlar → (To'fonli yerlar taslim bo'lgach) Dorne.
    Qaytaradi: (hujum qilish mumkin bo'lgan uylar, bosqich nomi)."""
    reg = {lord: region for region, lord in REGION_LORDS_INIT.items()}
    conq = _nk_conquered()
    left = [r for r in _nk_target_houses() if r["name"] not in conq]
    by_reg = {}
    for r in left:
        by_reg.setdefault(r.get("region") or "", []).append(r)

    def rows(*lords):
        return [r for lord in lords for r in by_reg.get(reg[lord], [])]

    umber = [r for r in left if r["name"] == "Umber"]
    if umber:
        return umber, "Shimol — Umber yerlari (Devordan chiqish joyi)"
    if rows("Stark"):
        return rows("Stark"), "Shimol"
    frey = [r for r in left if r["name"] == "Frey"]
    if frey:
        return frey, "Daryo yerlari — Frey (Shimoldan chiqish yo'li)"
    if rows("Tully", "Arryn"):
        return rows("Tully", "Arryn"), "Daryo yerlari va Vodiy (Tully, Arryn)"
    if rows("Lannister", "Targaryen", "Greyjoy"):
        return rows("Lannister", "Targaryen", "Greyjoy"), "G'arbiy yerlar va Qirollik bandargohi"
    stage = rows("Tyrell", "Barateon")
    name = "Kengliklar va To'fonli yerlar (Tyrell, Barateon)"
    if not rows("Barateon"):
        stage = stage + rows("Martell")
        name = "Dorne" if not rows("Tyrell") else name + " + Dorne"
    if stage:
        return stage, name
    known = set(REGION_LORDS_INIT)
    rest = [r for r in left if (r.get("region") or "") not in known]
    return rest, "Qolgan yerlar"


def _nk_target_houses():
    conn = db()
    rows = conn.execute("SELECT * FROM houses WHERE is_essos=0 ORDER BY name").fetchall()
    conn.close()
    return [r for r in (dict(x) for x in rows)
            if r["name"] not in (WALL_HOUSE, IRON_BANK_HOUSE) and not r.get("is_free_knight")
            and r["owner_id"]]


@bot.callback_query_handler(func=lambda c: c.data == "nkp_htarget")
def cb_nkp_htarget(c):
    if not _nk_only(c):
        return
    reason = _nk_house_block_reason()
    if reason:
        _nk_say(c, "❌ " + reason)
        return
    kb = types.InlineKeyboardMarkup(row_width=2)
    targets, stage = _nk_allowed_targets()
