def _nk_launch_house(c, sess):
    reason = _nk_house_block_reason()
    if reason:
        _nk_say(c, "❌ " + reason)
        return
    target = get_house((sess or {}).get("target") or "")
    if not target or target["name"] not in {r["name"] for r in _nk_allowed_targets()[0]}:
        _nk_say(c, "Nishon topilmadi yoki hali unga yo'l ochilmagan.")
        return
    sent = _nk_take_units(sess)
    if not sent:
        _nk_say(c, "Kamida bitta qo'shin tanlang.")
        return
    attack_id, mins = _nk_create_house_attack(target, sent)
    _nk_say(c, f"🗡️ <b>{target['name']}ga hujum boshlandi!</b>\n\n{_nk_units_lines(sent)}\n\n"
               f"⚔️ Kuch: <b>{nk_power(sent)}</b> ball\n⏰ Jang {mins} daqiqadan keyin.")
    if not target["owner_id"]:
        _nk_resolve_house_attack(attack_id)


def _nk_create_house_attack(target, sent):
    now = time.time()
    conn = db()
    cur = conn.execute(
        "INSERT INTO nk_attacks(target,units,status,created_at,deadline) VALUES(?,?,'pending',?,?)",
        (target["name"], json.dumps(sent), now, now + NK_HOUSE_ATTACK_WINDOW))
    attack_id = cur.lastrowid
    conn.commit()
    conn.close()
    mins = NK_HOUSE_ATTACK_WINDOW // 60
    if target["owner_id"]:
        kb = types.InlineKeyboardMarkup(row_width=1)
        kb.add(types.InlineKeyboardButton("🛡️ Hoziroq jangga kirish",
                                          callback_data=f"nkd_fight_{attack_id}"))
        notify(target["owner_id"],
               f"☠️ <b>TUN QIROLI SIZGA HUJUM QILDI!</b>\n\n"
               f"Oq piyodalar armiyasi <b>{target['name']}</b> tomon yurdi. Dushman kuchi nomaʼlum.\n"
               f"⏰ {mins} daqiqadan keyin butun qo'shiningiz avtomatik himoyaga chiqadi "
               "(Valyria po'lati ham avtomatik ishlatiladi). Bu vaqtda qo'shin yollashingiz mumkin.",
               kb)
    post_to_channel(f"☠️ <b>Tun qiroli {lord_full_name(target['name'])}ga hujum boshladi!</b>\n"
                    f"Jang {mins} daqiqadan keyin.")
    for _aid in ADMIN_IDS:
        notify(_aid, f"☠️ [ADMIN] Tun qiroli ({_nk_label()}) {target['name']}ga hujum qildi. "
                     f"Kuch: <b>{nk_power(sent)}</b>.")
    _ai_on_attack(target["name"], "Tun qiroli")
    return attack_id, mins


@bot.callback_query_handler(func=lambda c: c.data.startswith("nkd_fight_"))
def cb_nkd_fight(c):
    raw = c.data[len("nkd_fight_"):]
    if not raw.isdigit():
        bot.answer_callback_query(c.id)
        return
    conn = db()
    row = conn.execute("SELECT * FROM nk_attacks WHERE id=? AND status='pending'",
                       (int(raw),)).fetchone()
    conn.close()
    house = get_house_by_owner(c.from_user.id)
    if not row or not house or house["name"] != row["target"]:
        bot.answer_callback_query(c.id, "Bu jang allaqachon yakunlangan.", show_alert=True)
        return
    bot.answer_callback_query(c.id, "Jang boshlandi!")
    _nk_resolve_house_attack(int(raw))


def _nk_resolve_house_attack(attack_id):
    """Tun qiroli va Westeros lordligi jangi. Himoyachi butun qo'shini bilan
    (avtomatik Valyria po'lati bilan) himoyalanadi."""
    with _lock:
        conn = db()
        row = conn.execute("SELECT * FROM nk_attacks WHERE id=?", (attack_id,)).fetchone()
        if not row or row["status"] != "pending":
            conn.close()
            return
        cur = conn.execute("UPDATE nk_attacks SET status='resolving' WHERE id=? AND status='pending'",
                           (attack_id,))
        if cur.rowcount != 1:
            conn.close()
            return
        units = json.loads(row["units"] or "{}")
        ap = nk_power(units)
        d = conn.execute("SELECT * FROM houses WHERE name=?", (row["target"],)).fetchone()
        d = dict(d) if d else None
        d_units = {u: max(0, int((d or {}).get(u, 0) or 0)) for u in COMBAT_UNITS}
        dp = sum(n * UNIT_POWER[u]["def"] for u, n in d_units.items())
        v_used, v_bonus = _ww_auto_valyria(d, d_units) if d else (0, 0)
        dp += v_bonus
        nk_won = ap > dp
        if nk_won:
            d_lost = dict(d_units)
            nk_loss_ratio = min(dp / ap, 1.0) if ap else 1.0
        else:
            ratio = min(ap / dp, 1.0) if dp else 0.0
            d_lost = {u: min(n, int(n * ratio)) for u, n in d_units.items()}
            nk_loss_ratio = 1.0
        if d:
            for u, n in d_lost.items():
                if n:
                    conn.execute(f"UPDATE houses SET {u}=MAX({u}-?,0) WHERE name=?", (n, d["name"]))
            if v_used:
                conn.execute("UPDATE houses SET valyria_polati=MAX(valyria_polati-?,0) WHERE name=?",
                             (v_used, d["name"]))
            col = "wars_lost" if nk_won else "wars_won"
            try:
                conn.execute(f"UPDATE houses SET {col}=COALESCE({col},0)+1 WHERE name=?", (d["name"],))
            except Exception as _e:
                _swallow(_e)
        conn.execute("UPDATE nk_attacks SET status='resolved',result=?,resolved_at=? WHERE id=?",
                     ("nk" if nk_won else "defender", time.time(), attack_id))
        conn.commit()
        conn.close()
    target = row["target"]
    if d:
        _house_cache_invalidate(name=target, uid=d.get("owner_id"))
    survivors = _nk_return_survivors(units, nk_loss_ratio) if nk_won else {}
    raised_own = (sum(int(v) for v in units.values()) - sum(survivors.values())) // 2
    raised_enemy = sum(d_lost.values())
    if raised_own + raised_enemy:
        _nk_add_units({"olik": raised_own + raised_enemy})
    revive_line = (f"\n💀 Tiriltirildi: {raised_enemy} ta dushman askari + "
                   f"{raised_own} ta Tun qirolining o'z askari = "
                   f"<b>{raised_own + raised_enemy}</b> oddiy o'lik.")
    score = f"☠️ Tun qiroli: <b>{ap}</b> ball | 🛡️ {target}: <b>{dp}</b> ball"
    if nk_won:
        _nk_mark_conquered(target)
        _next, _stage = _nk_allowed_targets()
        revive_line += f"\n🗺️ {target} bosib olindi. Keyingi bosqich: <b>{_stage}</b>."
    if nk_won:
        text = f"☠️ <b>TUN QIROLI {target.upper()}NI YENGDI!</b>\n{score}" + revive_line
    else:
        text = f"🛡️ <b>{target} Tun qirolini qaytardi!</b>\n{score}" + revive_line
    post_to_channel(text)
    nk_uid = get_night_king_uid()
    if nk_uid:
        extra = (f"\n\nTirik qaytganlar:\n{_nk_units_lines(survivors)}" if survivors
                 else "\n\nYuborilgan qo'shin to'liq yo'q qilindi." if not nk_won else "")
        notify(nk_uid, text + extra, nk_main_menu(nk_uid))
    if d and d.get("owner_id"):
        lost_total = sum(d_lost.values())
        notify(d["owner_id"], f"{text}\n\nYo'qotishingiz: {lost_total} askar"
                              + (f", {v_used} Valyria po'lati" if v_used else "") + ".")


def check_nk_attack_timeouts(now=None):
    now = now or time.time()
    conn = db()
    rows = conn.execute("SELECT id FROM nk_attacks WHERE status='pending' AND deadline<=?",
                        (now,)).fetchall()
    conn.close()
    for r in rows:
        _nk_resolve_house_attack(r["id"])


def check_white_walker_event(now=None):
    now = now or time.time()
    local = time.localtime(now)
    # Tun qiroli bo'lsa, Devorga hujumni u o'zi boshqaradi — haftalik avtomatik hujum yo'q.
    # Admin Tun qirolini tayinlamagan bo'lsa — NPC Tun qiroli o'zi hujum qiladi.
    event = _ww_event()
    if event and event["deadline"] <= now:
        _ww_resolve()
    check_nk_attack_timeouts(now)
    try:
        _npc_nk_tick(now)
    except Exception as _e:
        _db_rollback_safe()
        _swallow(_e)


NPC_NK_ATTACK_INTERVAL = 2 * 3600   # NPC Tun qiroli urush vaqtida har 2 soatda hujum qiladi
NPC_NK_SEND_RATIO = 0.8             # armiyasining 80% ini yuboradi


def _nk_take_exact(units):
    with _nk_lock:
        conn = db()
        army = get_nk_army(conn)
        taken = {}
        for k, n in units.items():
            t = min(int(n), int(army.get(k, 0)))
            if t > 0:
                army[k] -= t
                taken[k] = t
        _save_nk_army(conn, army)
        conn.commit()
        conn.close()
    return taken


def _npc_nk_tick(now=None):
    """NPC Tun qiroli: mustaqil va tajovuzkor. Avval Devorga, Devor qulagach
    geografik tartibda lordliklarga hujum qiladi."""
    now = now or time.time()
    if get_night_king_uid() or _ww_banned() or not is_war_time():
        return
    if now - _nk_world_float("npc_nk_last") < NPC_NK_ATTACK_INTERVAL:
        return
    if _ww_event():
        return
    conn = db()
    busy = conn.execute("SELECT 1 FROM nk_attacks WHERE status='pending' LIMIT 1").fetchone()
    conn.close()
    if busy:
        return
    army = get_nk_army()
    want = {k: int(int(army.get(k, 0)) * NPC_NK_SEND_RATIO) for k in NK_UNIT_KEYS}
    if sum(want.values()) <= 0:
        return
    if not _wall_destroyed():
        if _nk_wall_block_reason(now):
            return
        sent = _nk_take_exact(want)
        if not sent:
            return
        _ww_start_event(now, by_nk=True, nk_units=sent)
    else:
        targets, _stage = _nk_allowed_targets()
        if not targets:
            return
        target = get_house(random.choice(targets)["name"])
        if not target:
            return
        sent = _nk_take_exact(want)
        if not sent:
            return
        attack_id, _m = _nk_create_house_attack(target, sent)
        if not target["owner_id"]:
            _nk_resolve_house_attack(attack_id)
    conn = db()
    conn.execute("INSERT INTO world (key,value) VALUES ('npc_nk_last',?) "
                 "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (str(now),))
    conn.commit()
    conn.close()


def process_tick(force=False):
    """Kunlik daromad+soliq siklini ishga tushiradi. force=True bo'lsa —
    soat/kunlik cheklovlarni (DAILY_TICK_HOUR, "bugun allaqachon ishladi")
    e'tiborga olmay, BARCHA uylarga darhol bir vaqtda daromad beradi
    (admin panelidagi "Kunlik siklni ishga tushirish" tugmasi uchun)."""
    # Kunlik tick oldidan keshni tozalaymiz — eski ma'lumot qolmasin
    _house_cache.clear()
    _owner_cache.clear()
    with _lock:
        conn = db()
        now = time.time()
        now_struct = time.localtime(now)
        if force:
            today_key = time.strftime("%Y-%m-%d", now_struct)
            should_fire = True
        else:
            should_fire, today_key = _daily_tick_should_fire(conn, now_struct)
        if not should_fire:
            conn.close()
            return
        king_row = conn.execute("SELECT value FROM world WHERE key='king'").fetchone()
        king = king_row["value"] if king_row else None
        _run_westeros_daily_tick(conn, king, now)

        # ESLATMA: endi hudud lordlari alohida qirolga soliq toʻlamaydi — A toifali
        # uylar (asosiy lordlar) qirolga soliqni apply_daily_income_for_house ichida
        # toʻgʻridan-toʻgʻri toʻlaydi (TAX_RATE["A"] orqali).

        conn.execute("INSERT INTO world (key, value) VALUES ('last_tick_date', ?) "
                     "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (today_key,))
        conn.commit()

        # Essos shahri (Bravos) — kunlik ishlab chiqarish
        # (alohida, Westeros siklidan mustaqil — admin panelda ham alohida
        # tugma orqali ishga tushirilishi mumkin).
        _apply_essos_daily_production(conn, now_struct, force=force)

        conn.close()


def _run_westeros_daily_tick(conn, king, now):
    """Faqat Westeros uylari (is_essos=0) uchun kunlik daromad+soliq sikli.
    Admin panelidagi "Faqat Westeros" tugmasi ham shu funksiyani chaqiradi."""
    houses = conn.execute("SELECT * FROM houses WHERE is_essos=0").fetchall()
    for h in houses:
        # Bitta uydagi xato (masalan egasiz/NPC uy yoki buzuq vassal havolasi)
        # butun kunlik siklni to'xtatib qo'ymasin.
        try:
            apply_daily_income_for_house(conn, h, king, now)
        except Exception as _e:
            logging.warning("kunlik daromad xatosi (%s): %r", h.get("name"), _e)
    if king:
        guards = conn.execute(
            "SELECT g.slot, g.guard_house FROM king_guard_slots g "
            "JOIN houses h ON h.name=g.guard_house WHERE g.king_house=?",
            (king,)).fetchall()
        for guard in guards:
            wage = 25 if guard["slot"] == 1 else 20
            conn.execute("UPDATE houses SET tanga=tanga+? WHERE name=?",
                         (wage, guard["guard_house"]))
            owner = conn.execute("SELECT owner_id FROM houses WHERE name=?",
                                 (guard["guard_house"],)).fetchone()
            if owner and owner["owner_id"]:
                notify(owner["owner_id"],
                       f"👑 Qirol gvardiyasi daromadi: <b>{wage} tanga</b> qo'shildi.")
    sea_ruler = get_sea_ruler()
    if sea_ruler:
        coastal_names = {r["name"] for r in _coastal_westeros_houses()}
        for name in coastal_names:
            if name != sea_ruler:
                paid, _ = _collect_tax(conn, name, SEA_BLOCKADE_TAX, sea_ruler)
                owner = conn.execute("SELECT owner_id FROM houses WHERE name=?", (name,)).fetchone()
                if paid and owner and owner["owner_id"]:
                    notify(owner["owner_id"],
                           f"🌊 Dengiz hukmdori <b>{sea_ruler}</b> ga {paid} tanga soliq to'landi.")
        total_paid = SEA_BLOCKADE_TAX * max(0, len(coastal_names) - 1)
        ruler_owner = conn.execute("SELECT owner_id FROM houses WHERE name=?", (sea_ruler,)).fetchone()
        if ruler_owner and ruler_owner["owner_id"]:
            notify(ruler_owner["owner_id"],
                   f"🌊 Orol va sohil oilalaridan kunlik soliq yig'ildi: <b>{total_paid} tanga</b>.")
    conn.commit()
    try:
        _nk_daily_tick(conn)      # Tun qirolining kunlik qo'shini
    except Exception as _e:
        logging.warning("Tun qiroli kunlik xatosi: %r", _e)


def _deliver_blockade_event(conn, event, toll=0):
    buyer = event["buyer_house"]
    ruler = get_sea_ruler()
    if toll and ruler:
        _collect_tax(conn, buyer, toll, ruler)
    conn.execute("UPDATE houses SET {} = {} + ? WHERE name=?".format(
        event["resource"], event["resource"]), (event["amount"], buyer))
    buyer_row = conn.execute("SELECT is_essos FROM houses WHERE name=?", (buyer,)).fetchone()
    if buyer_row and not buyer_row["is_essos"] and ESSOS_TRADE_REQUIRES_SHIP:
        conn.execute("UPDATE houses SET kema=kema+? WHERE name=?", (event["ship_count"], buyer))
    conn.execute("UPDATE sea_blockade_events SET status='passed' WHERE id=?", (event["id"],))
    conn.execute("UPDATE essos_deliveries SET status='delivered' WHERE id=?", (event["delivery_id"],))


@bot.callback_query_handler(func=lambda c: c.data.startswith("sea_pass_") or
                            c.data.startswith("sea_sink_") or
                            c.data.startswith("sea_toll_"))
def cb_sea_blockade_decision(c):
    parts = c.data.split("_")
    action = parts[1]
    event_id = int(parts[2])
    toll_choice = parts[3] if action == "toll" and len(parts) > 3 else ""
    ruler_house = get_house_by_owner(c.from_user.id)
    if not ruler_house or ruler_house["name"] != get_sea_ruler():
        bot.answer_callback_query(c.id, "Bu qarorni faqat dengiz hukmdori beradi.", show_alert=True)
        return
    if action == "toll" and toll_choice == "choose":
        conn = db()
        event = conn.execute(
            "SELECT ship_count FROM sea_blockade_events WHERE id=? AND status='pending'",
            (event_id,)).fetchone()
        conn.close()
        if not event:
            bot.answer_callback_query(c.id, "Bu kema bo'yicha qaror berilgan.", show_alert=True)
            return
        cap = sea_toll_cap(event["ship_count"])
        amounts = sorted({min(cap, amount) for amount in (5, 10, 15, 20, 30, 50)})
        kb = types.InlineKeyboardMarkup(row_width=3)
        kb.add(*[
            types.InlineKeyboardButton(
                f"{amount} tanga",
                callback_data=f"sea_toll_{event_id}_{amount}")
            for amount in amounts
        ])
        bot.send_message(
            c.message.chat.id,
            f"🌊 Necha tanga tovon so'raysiz? Maksimal: <b>{cap} tanga</b>.",
            parse_mode="HTML",
            reply_markup=kb)
        bot.answer_callback_query(c.id)
        return
    toll = int(toll_choice) if action == "toll" and toll_choice else 0
    conn = db()
    event = conn.execute("SELECT * FROM sea_blockade_events WHERE id=? AND status='pending'",
                         (event_id,)).fetchone()
    if not event:
        conn.close()
        bot.answer_callback_query(c.id, "Bu kema bo'yicha qaror berilgan.", show_alert=True)
        return
    if action == "sink":
        conn.execute("UPDATE sea_blockade_events SET status='sunk' WHERE id=?", (event_id,))
        conn.execute("UPDATE essos_deliveries SET status='sunk' WHERE id=?", (event["delivery_id"],))
        conn.execute("UPDATE houses SET kema=MAX(kema-?,0) WHERE name=?",
                     (event["ship_count"], event["buyer_house"]))
        conn.execute("UPDATE houses SET kema=MAX(kema-?,0) WHERE name=?",
                     (event["ship_count"], ruler_house["name"]))
        conn.commit()
        conn.close()
        notify(get_house(event["buyer_house"])["owner_id"],
               f"🌊 Dengiz hukmdori kemangizni cho'ktirdi.")
        bot.answer_callback_query(c.id, "Kema cho'ktirildi.")
    else:
        cap = sea_toll_cap(event["ship_count"])
        toll = min(max(0, toll), cap)
        _deliver_blockade_event(conn, event, toll=toll)
        conn.commit()
        conn.close()
        if toll:
            notify(get_house(event["buyer_house"])["owner_id"],
                   f"🌊 Kema o'tkazildi, dengiz hukmdoriga {toll} tanga boj to'landi.")
        bot.answer_callback_query(c.id, "Kema o'tkazildi.")
    try:
        bot.edit_message_reply_markup(c.message.chat.id, c.message.message_id, reply_markup=None)
    except Exception as _e:
        _swallow(_e)


def check_essos_deliveries():
    """Essos savdo yetkazib berishlarini tekshiradi: muddati yetgan
    (1 soatdan o'tgan) buyurtmalarni xaridorga yetkazadi va kema qaytariladi."""
    now = time.time()
    conn = db()
    try:
        rows = conn.execute(
            "SELECT * FROM essos_deliveries WHERE status='transit' AND deliver_at<=?",
            (now,)).fetchall()
        for row in rows:
            buyer_house = row["buyer_house"]
            seller_house = row["seller_house"]
            resource = row["resource"]
            amount = row["amount"]
            res_label = RESOURCE_LABEL.get(resource, resource)
            res_emoji = RESOURCE_EMOJI.get(resource, "")
            # Xaridorga resurs qo'shish
            if _sea_blockade_enabled():
                ruler = get_house(get_sea_ruler())
                if ruler and ruler["owner_id"]:
                    cur = conn.execute(
                        "INSERT INTO sea_blockade_events(delivery_id,buyer_house,seller_house,resource,amount,cost,ship_count,created_at) "
                        "VALUES(?,?,?,?,?,?,?,?)",
                        (row["id"], buyer_house, seller_house, resource, amount, row["cost"],
                         ESSOS_TRADE_SHIP_COUNT, time.time()))
                    event_id = cur.lastrowid
                    conn.execute("UPDATE essos_deliveries SET status='blockade_pending' WHERE id=?",
                                 (row["id"],))
                    conn.commit()
                    cap = sea_toll_cap(ESSOS_TRADE_SHIP_COUNT)
                    kb = types.InlineKeyboardMarkup(row_width=2)
                    kb.add(
                        types.InlineKeyboardButton("💰 Tovon so'rash",
                            callback_data=f"sea_toll_{event_id}_choose"),
                        types.InlineKeyboardButton("✅ O'tkazib yuborish",
                            callback_data=f"sea_pass_{event_id}"),
                        types.InlineKeyboardButton("💥 Cho'ktirish",
                            callback_data=f"sea_sink_{event_id}"))
                    notify(ruler["owner_id"],
                           f"🌊 <b>{seller_house}</b>dan <b>{buyer_house}</b>ga bayroq ko'targan "
                           f"kema kelyapti: {amount} {res_label}. Maksimal boj: {cap} tanga.",
                           kb)
                    continue
            conn.execute(f"UPDATE houses SET {resource} = {resource} + ? WHERE name=?",
                         (amount, buyer_house))
            # Agar Westeros uyi bo'lsa — kema qaytariladi
            buyer_row = conn.execute("SELECT is_essos FROM houses WHERE name=?", (buyer_house,)).fetchone()
            if buyer_row and not buyer_row["is_essos"] and ESSOS_TRADE_REQUIRES_SHIP:
                conn.execute("UPDATE houses SET kema = kema + ? WHERE name=?",
                             (ESSOS_TRADE_SHIP_COUNT, buyer_house))
            conn.execute("UPDATE essos_deliveries SET status='delivered' WHERE id=?", (row["id"],))
            conn.commit()
            # Xaridorga xabar yuborish
            owner_row = conn.execute("SELECT owner_id FROM houses WHERE name=?", (buyer_house,)).fetchone()
            if owner_row and owner_row["owner_id"]:
                try:
                    ship_note = " (kema ham qaytib keldi ⛵)" if (ESSOS_TRADE_REQUIRES_SHIP and
                                buyer_row and not buyer_row["is_essos"]) else ""
                    bot.send_message(
                        owner_row["owner_id"],
                        f"⛵ <b>Kema qaytdi!</b> {seller_house} dan {amount} {res_emoji} {res_label} "
                        f"xazinangizga yetib keldi!{ship_note}",
                        parse_mode="HTML")
                except Exception as _e:
                    _swallow(_e)
    finally:
        conn.close()


def check_sea_blockade_timeouts():
    conn = db()
    rows = conn.execute(
        "SELECT * FROM sea_blockade_events WHERE status='pending' AND created_at<=?",
        (time.time() - 15 * 60,)).fetchall()
    for row in rows:
        _deliver_blockade_event(conn, row)
    conn.commit()
    conn.close()


