trade_session = {}   # uid -> {"target": str, "resource": str}
war_session = {}      # uid -> {"type": "quruqlik"/"dengiz", "target": str, "units": {...}, "queue": [...]}
def_session = {}      # uid -> {"attack_id": int, "type": ..., "units": {...}, "queue": [...]}
admin_session = {}    # uid -> {"action": str, "house": str, "field": str}
help_session = {}     # uid -> {"attack_id": int, "units": {...}, "queue": [...]}
ally_gift_session = {}   # uid -> {"resource": str}


def clear_sessions(uid):
    trade_session.pop(uid, None)
    war_session.pop(uid, None)
    def_session.pop(uid, None)
    admin_session.pop(uid, None)
    help_session.pop(uid, None)
    expedition_session.pop(uid, None)
    ally_gift_session.pop(uid, None)


# ---------------------------------------------------------------------------
# ESKIRGAN XABAR HIMOYASI
# Callback xabari 10 daqiqadan eski bo'lsa — sotib olish/sotish bekor qilinadi.
# ---------------------------------------------------------------------------
CALLBACK_STALE_SECONDS = 600  # 10 daqiqa

def _is_stale_callback(c):
    """Callback xabari eskirgan bo'lsa True qaytaradi va foydalanuvchiga
    ogoh xabar yuboradi.  Bank sotib olish/sotish/savdo qabul qilish
    handler'larida MAJBURIY chaqiriladi."""
    if c.message and c.message.date:
        if time.time() - c.message.date > CALLBACK_STALE_SECONDS:
            try:
                bot.answer_callback_query(
                    c.id,
                    "⚠️ Bu xabar eskirgan (10+ daqiqa). /start bosib yangi menyu oching.",
                    show_alert=True)
            except Exception as _e:
                _swallow(_e)
            return True
    return False


# ---------------------------------------------------------------------------
# HUJUM E'LON QILISH / HIMOYA KUTISH TIZIMI
# ---------------------------------------------------------------------------

def create_pending_attack(war_type, attacker_name, defender_name, units, kema_count=0,
                           isyon=0, isyon_type=''):
    conn = db()
    now = time.time()
    conn.execute("""INSERT INTO pending_attacks (war_type, attacker, defender, attack_units, kema_count,
        status, defense_units, created_at, deadline, isyon, isyon_type)
        VALUES (?,?,?,?,?,'pending','',?,?,?,?)""",
        (war_type, attacker_name, defender_name, json.dumps(units), kema_count, now,
         now + DEFENSE_WINDOW_SECONDS, 1 if isyon else 0, isyon_type or ''))
    attack_id = conn.execute("SELECT last_insert_rowid() AS id").fetchone()["id"]
    conn.commit()
    conn.close()
    # V9: quruqlik urushi eʼlon qilingach, shu nishonga berilgan bir martalik
    # oʻtish ruxsati "ishlatilgan" deb belgilanadi — gʻalaba/magʻlubiyatidan
    # qatʼiy nazar, shu nishonga qayta hujum qilish uchun yangi ruxsat kerak.
    if war_type != "dengiz":
        consume_land_permits_for_target(attacker_name, defender_name)
    _ai_on_attack(defender_name, attacker_name)
    return attack_id


def get_pending_attack(attack_id):
    conn = db()
    row = conn.execute("SELECT * FROM pending_attacks WHERE id=?", (attack_id,)).fetchone()
    conn.close()
    return row


def get_active_war_for_house(house_name):
    """Shu uy hozir biror urushda (hujumchi yoki himoyachi sifatida) ishtirok
    etayotgan bo'lsa, o'sha pending_attacks yozuvini qaytaradi. Aks holda None.
    Bir oila bir vaqtning o'zida faqat BITTA urushda bo'la oladi — yangi
    urush boshlashdan oldin shu tekshiriladi."""
    conn = db()
    row = conn.execute(
        "SELECT * FROM pending_attacks WHERE status='pending' AND (attacker=? OR defender=?) "
        "ORDER BY created_at DESC LIMIT 1",
        (house_name, house_name)).fetchone()
    conn.close()
    return row


def auto_fill_land_defense(defender_row):
    """Himoyachi javob bermasa, butun mavjud armiya avtomatik himoyaga kiradi
    (tartib faqat rivoyat uchun: kamonchi -> qoshin -> benuqson -> otliq -> kenja o'g'il)."""
    return {u: defender_row[u] for u in AUTO_DEFENSE_ORDER if defender_row[u] > 0}


def auto_fill_naval_defense(defender_row):
    """V4: faqat TO'LIQ to'ldirilgan kemalar (1 kema = aniq 10 askar) himoyaga
    chiqadi. Askar yetmasa, kema soni kamaytiriladi (ortiqcha kema safarbar
    bo'lmaydi). Qaytaradi: (kema_soni, {unit: n})."""
    avail = sum(int(defender_row[u] or 0) for u in AUTO_DEFENSE_ORDER)
    ships = min(int(defender_row["kema"] or 0), avail // SHIP_CAPACITY)
    troops = {}
    remaining = ships * SHIP_CAPACITY
    for u in AUTO_DEFENSE_ORDER:
        if remaining <= 0:
            break
        take = min(int(defender_row[u] or 0), remaining)
        if take:
            troops[u] = take
            remaining -= take
    return ships, troops


# (notify — FLOW v2 blokidagi _Outbox orqali ishlaydi)


def ritsarlik_war_power(score):
    """Ritsarlik ballini oddiy askar kuchiga aylantiradi: har 20 ball = 1 askar kuchi."""
    score = max(0, int(score or 0))
    return score // 20


def get_king_guard_slots(king_house=None):
    king_house = king_house or get_king()
    if not king_house:
        return []
    conn = db()
    rows = conn.execute(
        "SELECT * FROM king_guard_slots WHERE king_house=? ORDER BY slot",
        (king_house,)).fetchall()
    conn.close()
    return rows


def king_guard_power(king_house=None, conn=None):
    own_conn = conn is None
    conn = conn or db()
    if not king_house:
        king_row = conn.execute("SELECT value FROM world WHERE key='king'").fetchone()
        king_house = king_row["value"] if king_row else None
    if not king_house:
        if own_conn:
            conn.close()
        return 0
    rows = conn.execute("""
        SELECT h.ritsarlik
        FROM king_guard_slots g JOIN houses h ON h.name=g.guard_house
        WHERE g.king_house=?
    """, (king_house,)).fetchall()
    power = sum(ritsarlik_war_power(row["ritsarlik"]) for row in rows)
    if own_conn:
        conn.close()
    return power


def _guard_candidate_rows():
    conn = db()
    rows = conn.execute(
        "SELECT name, owner_id, ritsarlik FROM houses "
        "WHERE is_essos=0 AND is_free_knight=0 AND owner_id IS NOT NULL "
        "ORDER BY name").fetchall()
    conn.close()
    return rows


def _send_guard_offer(offer_id):
    conn = db()
    offer = conn.execute("SELECT * FROM king_guard_offers WHERE id=?", (offer_id,)).fetchone()
    candidate = conn.execute(
        "SELECT * FROM houses WHERE name=?",
        (offer["candidate_house"],)).fetchone() if offer else None
    conn.close()
    if not offer or not candidate or not candidate["owner_id"]:
        return
    role = "bosh gvardiyachi" if offer["slot"] == 1 else f"{offer['slot']}-gvardiyachi"
    kb = types.InlineKeyboardMarkup(row_width=2)
    kb.add(
        types.InlineKeyboardButton("✅ Roziman", callback_data=f"kg_offer_yes_{offer_id}"),
        types.InlineKeyboardButton("❌ Rad etaman", callback_data=f"kg_offer_no_{offer_id}"))
    notify(candidate["owner_id"],
           f"👑 Qirol sizni <b>{role}</b> etib tayinlamoqchi.\n"
           f"Uy: <b>{candidate['name']}</b>\n"
           f"Ritsarlik: <b>{candidate['ritsarlik']}</b> → "
           f"<b>{ritsarlik_war_power(candidate['ritsarlik'])}</b> urush balli.\n"
           "Taklif 2 soat amal qiladi.", kb)


def _king_guard_menu_text(king_house):
    slots = {row["slot"]: row for row in get_king_guard_slots(king_house)}
    lines = ["👑 <b>Qirol gvardiyasi</b>", "7 ta joy: 1 bosh gvardiyachi + 6 gvardiyachi."]
    for slot in range(1, 8):
        row = slots.get(slot)
        if row:
            house = get_house(row["guard_house"])
            score = house["ritsarlik"] if house else 0
            lines.append(f"{slot}. <b>{row['guard_house']}</b> — "
                         f"{ritsarlik_war_power(score)} ball")
        else:
            lines.append(f"{slot}. — bo'sh")
    lines.append(f"\nJami himoya kuchi: <b>{king_guard_power(king_house)}</b> ball")
    return "\n".join(lines)


