@bot.callback_query_handler(func=lambda c: c.data.startswith("kg_candidate_"))
def cb_kg_candidate(c):
    king = get_house_by_owner(c.from_user.id)
    if not king or get_king() != king["name"]:
        bot.answer_callback_query(c.id, "Faqat qirol tayinlaydi.", show_alert=True)
        return
    _, _, slot_text, candidate = c.data.split("_", 3)
    slot = int(slot_text)
    candidate_row = get_house(candidate)
    if not candidate_row or candidate_row["is_essos"] or not candidate_row["owner_id"]:
        bot.answer_callback_query(c.id, "Bu uyga taklif yuborib bo'lmaydi.", show_alert=True)
        return
    conn = db()
    try:
        cur = conn.execute(
            "INSERT INTO king_guard_offers(king_house,slot,candidate_house,created_at,deadline) "
            "VALUES(?,?,?,?,?)",
            (king["name"], slot, candidate, time.time(), time.time() + 2 * 3600))
        offer_id = cur.lastrowid
        conn.commit()
    except sqlite3.IntegrityError:
        offer_id = None
    conn.close()
    if offer_id:
        _send_guard_offer(offer_id)
        bot.answer_callback_query(c.id, "Taklif yuborildi.")
        bot.edit_message_text("Taklif yuborildi. Javob 2 soat ichida kutiladi.",
                              c.message.chat.id, c.message.message_id)
    else:
        bot.answer_callback_query(c.id, "Bu taklif allaqachon yuborilgan.", show_alert=True)


@bot.callback_query_handler(func=lambda c: c.data.startswith("kg_offer_"))
def cb_kg_offer(c):
    try:
        action, offer_id = c.data.rsplit("_", 1)
        offer_id = int(offer_id)
    except (ValueError, TypeError):
        bot.answer_callback_query(c.id, "Noto'g'ri taklif.", show_alert=True)
        return
    conn = db()
    offer = conn.execute("SELECT * FROM king_guard_offers WHERE id=?", (offer_id,)).fetchone()
    house = get_house_by_owner(c.from_user.id)
    if not offer or not house or offer["candidate_house"] != house["name"] or offer["status"] != "pending":
        conn.close()
        bot.answer_callback_query(c.id, "Taklif faol emas.", show_alert=True)
        return
    if offer["deadline"] <= time.time():
        conn.execute("UPDATE king_guard_offers SET status='expired' WHERE id=?", (offer_id,))
        conn.commit()
        conn.close()
        bot.answer_callback_query(c.id, "Taklif muddati tugagan.", show_alert=True)
        return
    if action == "kg_offer_yes":
        conn.execute("INSERT OR REPLACE INTO king_guard_slots(king_house,slot,guard_house,appointed_at) "
                     "VALUES(?,?,?,?)", (offer["king_house"], offer["slot"], house["name"], time.time()))
        conn.execute("UPDATE king_guard_offers SET status='accepted' WHERE id=?", (offer_id,))
        conn.commit()
        king = get_house(offer["king_house"])
        notify(king["owner_id"] if king else None,
               f"✅ <b>{house['name']}</b> taklifni qabul qildi va "
               f"{offer['slot']}-gvardiyachi bo'ldi.")
        bot.answer_callback_query(c.id, "Siz qirol gvardiyasiga kirdingiz.")
        bot.edit_message_text("✅ Taklif qabul qilindi. Siz qirol gvardiyachisisiz.",
                              c.message.chat.id, c.message.message_id)
    else:
        conn.execute("UPDATE king_guard_offers SET status='rejected' WHERE id=?", (offer_id,))
        conn.commit()
        king = get_house(offer["king_house"])
        notify(king["owner_id"] if king else None,
               f"❌ <b>{house['name']}</b> qirol gvardiyasi taklifini rad etdi.")
        bot.answer_callback_query(c.id, "Taklif rad etildi.")
        bot.edit_message_text("❌ Taklif rad etildi.", c.message.chat.id, c.message.message_id)
    conn.close()


