@bot.callback_query_handler(func=lambda c: c.data.startswith("kg_release_"))
def cb_kg_release(c):
    king = get_house_by_owner(c.from_user.id)
    if not king or get_king() != king["name"]:
        bot.answer_callback_query(c.id, "Faqat qirol ozod qiladi.", show_alert=True)
        return
    slot = int(c.data.rsplit("_", 1)[1])
    conn = db()
    row = conn.execute("SELECT guard_house FROM king_guard_slots WHERE king_house=? AND slot=?",
                       (king["name"], slot)).fetchone()
    conn.execute("DELETE FROM king_guard_slots WHERE king_house=? AND slot=?",
                 (king["name"], slot))
    conn.commit()
    conn.close()
    if row:
        guard = get_house(row["guard_house"])
        notify(guard["owner_id"] if guard else None,
               f"👑 Qirol sizni qirol gvardiyasidan ozod qildi.")
        bot.answer_callback_query(c.id, "Gvardiyachi ozod qilindi.")
    else:
        bot.answer_callback_query(c.id, "Joy bo'sh.", show_alert=True)
    cb_king_guard(c)


SEA_CLAIM_MIN_SHIPS = 70
SEA_SHIP_CREW = SHIP_CAPACITY
SEA_BLOCKADE_TAX = 5


def _fleet_troop_total(house):
    return sum(max(0, house[u]) for u in COMBAT_UNITS)


def can_claim_sea_rule(house):
    return bool(
        house and not house["is_essos"] and house["kema"] >= SEA_CLAIM_MIN_SHIPS
        and _fleet_troop_total(house) >= house["kema"] * SEA_SHIP_CREW)


def get_sea_ruler():
    conn = db()
    row = conn.execute("SELECT value FROM world WHERE key='sea_ruler'").fetchone()
    conn.close()
    return row["value"] if row and row["value"] else None


def _coastal_westeros_houses():
    ports = _all_westeros_ports()
    coastal_regions = set(NAVAL_GATES) | ISLAND_KINGDOMS
    conn = db()
    rows = conn.execute(
        "SELECT name, owner_id FROM houses WHERE is_essos=0 AND owner_id IS NOT NULL "
        "AND (name IN ({}) OR region IN ({}))".format(
            ",".join("?" * len(ports)) or "NULL",
            ",".join("?" * len(coastal_regions)) or "NULL"),
        tuple(sorted(ports)) + tuple(sorted(coastal_regions))).fetchall()
    conn.close()
    return rows


def sea_toll_cap(ship_count):
    if ship_count >= 100:
        return 50
    if ship_count >= 30:
        return 15
    if ship_count >= 10:
        return 20
    return 5


def _sea_claim_message(claimant, recipient, claim_id):
    kb = types.InlineKeyboardMarkup(row_width=2)
    kb.add(
        types.InlineKeyboardButton("✅ Dengiz hukmdori deb tan olish",
                                   callback_data=f"sea_recognize_{claim_id}"),
        types.InlineKeyboardButton("⚔️ Urush qilish",
                                   callback_data=f"sea_challenge_{claim_id}"))
    notify(recipient["owner_id"],
           f"🌊 <b>{claimant['name']}</b> o'zini Westeros dengiz hukmdori deb e'lon qildi.\n"
           "Siz uni tan olasizmi yoki flot bilan urushasizmi?\n"
           "Javob berilmasa, 1 soatdan keyin avtomatik tan olingan hisoblanadi.", kb)


def _sea_claim_candidates(claimant_name):
    return [row for row in _coastal_westeros_houses() if row["name"] != claimant_name]


def _announce_sea_ruler(name, challenged=False):
    ruler = get_house(name)
    if not ruler:
        return
    prefix = "⚔️ Dengiz urushidan so'ng" if challenged else "⏰ Bir soatlik sukutdan so'ng"
    post_to_channel(
        f"🌊 <b>{prefix}</b> <b>{lord_full_name(name)}</b> Westerosning DENGIZ HUKMDORI deb e'lon qilindi! "
        "Orol va dengiz bo'yi oilalaridan kunlik 5 tanga soliq oladi.")
    if ruler["owner_id"]:
        notify(ruler["owner_id"],
               "🌊 Siz Westerosning dengiz hukmdori bo'ldingiz. Orol va sohil oilalaridan kunlik 5 tanga soliq yig'iladi.")


SEA_CHALLENGE_SECONDS = 3600


def _sea_strength(house):
    """Dengiz hukmdorligi bellashuvi: avval kema soni, teng bo'lsa askar soni."""
    if not house:
        return (0, 0)
    return (max(0, int(house["kema"] or 0)), _fleet_troop_total(house))


def _sea_say(c, text, kb=None):
    bot.answer_callback_query(c.id)
    bot.send_message(c.message.chat.id, text, reply_markup=kb or back_button(),
                     parse_mode="HTML")


@bot.callback_query_handler(func=lambda c: c.data == "m_sea_rule")
def cb_sea_rule(c):
    house = get_house_by_owner(c.from_user.id)
    if not house:
        _sea_say(c, "Sizda uy yo'q.")
        return
    if house["is_essos"] or house["name"] == WALL_HOUSE:
        _sea_say(c, "🌊 Dengiz hukmdorligiga faqat Westeros oilalari da'vo qila oladi.")
        return
    ruler = get_sea_ruler()
    now = time.time()
    conn = db()
    active = conn.execute(
        "SELECT * FROM sea_claims WHERE status='pending' AND deadline>? ORDER BY id DESC LIMIT 1",
        (now,)).fetchone()
    conn.close()
    if ruler == house["name"]:
        ships, troops = _sea_strength(house)
        lines = ["🌊 <b>Siz Westeros dengiz hukmdorisiz.</b>",
                 f"⛵ Kemalar: <b>{ships}</b> | ⚔️ Askarlar: <b>{troops}</b>",
                 "Orol va dengiz bo'yi oilalaridan kunlik 5 tanga soliq olinadi."]
        if active and active["claimant_house"] != house["name"]:
            cs, ct = _sea_strength(get_house(active["claimant_house"]))
            left = max(0, int(active["deadline"] - now)) // 60
            lines.append(
                f"\n⚠️ <b>{active['claimant_house']}</b> hukmdorlikka talabgor: {cs} kema, {ct} askar.\n"
                f"~{left} daqiqadan keyin kimda ko'proq kema (teng bo'lsa — askar) bo'lsa, "
                "o'sha dengiz hukmdori bo'ladi.")
        kb = types.InlineKeyboardMarkup(row_width=1)
        kb.add(types.InlineKeyboardButton("📊 Dengiz hukmdorligi holati", callback_data="sea_status"))
        kb.add(types.InlineKeyboardButton("⬅️ Bosh menyu", callback_data="m_back"))
        _sea_say(c, "\n".join(lines), kb)
        return
    if active:
        _sea_say(c, f"⏳ Hozir <b>{active['claimant_house']}</b>ning dengiz da'vosi ko'rib "
                    "chiqilmoqda. U tugashini kuting.")
        return
    if not can_claim_sea_rule(house):
        need = max(0, SEA_CLAIM_MIN_SHIPS - house["kema"])
        crew_need = max(0, house["kema"] * SEA_SHIP_CREW - _fleet_troop_total(house))
        _sea_say(c, f"Kamida {SEA_CLAIM_MIN_SHIPS} ta to'liq ekipajli kema kerak "
                    f"(har kemaga {SEA_SHIP_CREW} askar).\n"
                    f"Yetishmayapti: {need} kema, {crew_need} askar.")
        return
    conn = db()
    if conn.execute("SELECT 1 FROM sea_claims WHERE status='pending' AND deadline>?",
                    (now,)).fetchone():
        conn.close()
        _sea_say(c, "Hozir boshqa dengiz da'vosi ko'rib chiqilmoqda.")
        return
    cur = conn.execute(
        "INSERT INTO sea_claims(claimant_house,created_at,deadline,target_ruler) VALUES(?,?,?,?)",
        (house["name"], now, now + SEA_CHALLENGE_SECONDS, ruler or ""))
    claim_id = cur.lastrowid
    candidates = [] if ruler else _sea_claim_candidates(house["name"])
    for row in candidates:
        conn.execute("INSERT OR IGNORE INTO sea_claim_responses(claim_id,responder_house) VALUES(?,?)",
                     (claim_id, row["name"]))
    conn.commit()
    conn.close()
    mins = SEA_CHALLENGE_SECONDS // 60
    if ruler:
        rh = get_house(ruler)
        rs, rt = _sea_strength(rh)
        cs, ct = _sea_strength(house)
        if rh and rh["owner_id"]:
            notify(rh["owner_id"],
                   f"🌊⚠️ <b>{house['name']}</b> dengiz hukmdori bo'lishga talab ochdi!\n\n"
                   f"Uning floti: <b>{cs}</b> kema, <b>{ct}</b> askar.\n"
                   f"Sizning flotingiz: <b>{rs}</b> kema, <b>{rt}</b> askar.\n\n"
                   f"⏰ {mins} daqiqadan keyin kimda ko'proq kema (teng bo'lsa — ko'proq askar) "
                   "bo'lsa, o'sha dengiz hukmdori bo'ladi. Flotingizni kuchaytirishga ulguring!")
        post_to_channel(
            f"🌊⚔️ <b>{lord_full_name(house['name'])}</b> dengiz hukmdori "
            f"<b>{lord_full_name(ruler)}</b>ga qarshi talab ochdi! {mins} daqiqadan keyin "
            "kimning kemasi va askari ko'proq bo'lsa, o'sha dengiz hukmdori bo'ladi.")
        _sea_say(c, f"⚔️ Talabingiz yuborildi, hozirgi hukmdor <b>{ruler}</b>ga xabar berildi.\n"
                    f"{mins} daqiqadan keyin solishtiriladi:\n"
                    f"• Siz: {cs} kema, {ct} askar\n• {ruler}: {rs} kema, {rt} askar")
        return
    for row in candidates:
        _sea_claim_message(house, row, claim_id)
    post_to_channel(
        f"🌊 <b>{lord_full_name(house['name'])}</b> kamida {SEA_CLAIM_MIN_SHIPS} ta to'liq ekipajli "
        "kema bilan o'zini Westeros dengiz hukmdori deb e'lon qildi. Sohil oilalariga tanlov yuborildi.")
    _sea_say(c, "Sohil oilalariga tan olish yoki urush qilish tanlovi yuborildi.")


