def _fleet_from_house(house, ships):
    remaining = ships * SEA_SHIP_CREW
    troops = {}
    for unit in AUTO_DEFENSE_ORDER:
        take = min(max(0, house[unit]), remaining)
        if take:
            troops[unit] = take
            remaining -= take
        if remaining <= 0:
            break
    return troops


@bot.callback_query_handler(func=lambda c: c.data.startswith("sea_fleet_"))
def cb_sea_fleet(c):
    _, _, claim_text, pct_text = c.data.split("_")
    claim_id, pct = int(claim_text), int(pct_text)
    challenger = get_house_by_owner(c.from_user.id)
    conn = db()
    claim = conn.execute("SELECT * FROM sea_claims WHERE id=? AND status='pending'",
                         (claim_id,)).fetchone()
    conn.close()
    if not claim or not challenger:
        bot.answer_callback_query(c.id, "Da'vo topilmadi.", show_alert=True)
        return
    if challenger["name"] == claim["claimant_house"]:
        bot.answer_callback_query(c.id, "O'z da'voingizga qarshi chiqa olmaysiz.", show_alert=True)
        return
    claimant = get_house(claim["claimant_house"])
    ships = min(challenger["kema"], max(1, round(challenger["kema"] * pct / 100)))
    if _fleet_troop_total(challenger) < ships * SEA_SHIP_CREW:
        bot.answer_callback_query(c.id, "Tanlangan flotni to'ldirishga askar yetmaydi.", show_alert=True)
        return
    challenger_troops = _fleet_from_house(challenger, ships)
    claimant_ships = claimant["kema"]
    claimant_troops = _fleet_from_house(claimant, claimant_ships)
    if ships == claimant_ships:
        bot.answer_callback_query(c.id, "Teng flot bilan da'vo hal bo'lmadi.", show_alert=True)
        return
    winner = challenger if ships > claimant_ships else claimant
    loser = claimant if winner["name"] == challenger["name"] else challenger
    winner_ships = abs(ships - claimant_ships)
    winner_troops = {u: abs(challenger_troops.get(u, 0) - claimant_troops.get(u, 0))
                     for u in COMBAT_UNITS}
    conn = db()
    for u, n in claimant_troops.items():
        conn.execute(f"UPDATE houses SET {u}=MAX({u}-?,0) WHERE name=?", (n, claimant["name"]))
    conn.execute("UPDATE houses SET kema=MAX(kema-?,0) WHERE name=?", (claimant_ships, claimant["name"]))
    for u, n in challenger_troops.items():
        conn.execute(f"UPDATE houses SET {u}=MAX({u}-?,0) WHERE name=?", (n, challenger["name"]))
    conn.execute("UPDATE houses SET kema=MAX(kema-?,0) WHERE name=?", (ships, challenger["name"]))
    conn.execute("UPDATE houses SET kema=kema+? WHERE name=?", (winner_ships, winner["name"]))
    for u, n in winner_troops.items():
        if n:
            conn.execute(f"UPDATE houses SET {u}={u}+? WHERE name=?", (n, winner["name"]))
    conn.execute("UPDATE sea_claims SET status='resolved', winner_house=? WHERE id=?",
                 (winner["name"], claim_id))
    conn.execute("DELETE FROM sea_claim_responses WHERE claim_id=?", (claim_id,))
    conn.execute("INSERT INTO world(key,value) VALUES('sea_ruler',?) "
                 "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (winner["name"],))
    conn.commit()
    conn.close()
    _announce_sea_ruler(winner["name"], challenged=True)
    post_to_channel(
        f"🌊⚔️ {lord_full_name(winner['name'])} dengiz jangida g'alaba qozondi. "
        f"{lord_full_name(loser['name'])} floti yo'q qilindi; g'olibda {winner_ships} ta kema qoldi.")
    bot.answer_callback_query(c.id, f"{winner['name']} dengiz hukmdori bo'ldi.")
    bot.edit_message_text("⚔️ Dengiz jangi yakunlandi.", c.message.chat.id, c.message.message_id)


def _resolve_sea_challenge(claim):
    """Mavjud hukmdorga qarshi talab: kimda ko'proq kema (teng bo'lsa askar) — o'sha yutadi."""
    ruler_now = get_sea_ruler()
    claimant = get_house(claim["claimant_house"])
    incumbent = get_house(ruler_now) if ruler_now else None
    c_str = _sea_strength(claimant) if can_claim_sea_rule(claimant) else (0, 0)
    i_str = _sea_strength(incumbent)
    if claimant and c_str > i_str:
        winner = claimant["name"]
    else:
        winner = ruler_now or ""
    conn = db()
    conn.execute("UPDATE sea_claims SET status='resolved',winner_house=? WHERE id=?",
                 (winner, claim["id"]))
    if winner and winner != ruler_now:
        conn.execute("INSERT INTO world(key,value) VALUES('sea_ruler',?) "
                     "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (winner,))
    conn.commit()
    conn.close()
    detail = (f"{claim['claimant_house']}: {c_str[0]} kema, {c_str[1]} askar | "
              f"{ruler_now or '—'}: {i_str[0]} kema, {i_str[1]} askar")
    if winner and winner != ruler_now:
        post_to_channel(f"🌊👑 <b>{lord_full_name(winner)}</b> kattaroq flot bilan yangi DENGIZ "
                        f"HUKMDORI bo'ldi!\n{detail}")
        msg_c = f"🌊 Talabingiz g'alaba qildi — siz endi dengiz hukmdorisiz!\n{detail}"
        msg_i = f"🌊 Dengiz hukmdorligini {winner}ga boy berdingiz.\n{detail}"
    else:
        post_to_channel(f"🌊🛡️ <b>{lord_full_name(ruler_now) if ruler_now else '—'}</b> dengiz "
                        f"hukmdorligini saqlab qoldi.\n{detail}")
        msg_c = f"🌊 Talabingiz rad etildi — flotingiz yetarli emas.\n{detail}"
        msg_i = f"🌊 Dengiz hukmdorligini saqlab qoldingiz.\n{detail}"
    if claimant and claimant["owner_id"]:
        notify(claimant["owner_id"], msg_c)
    if incumbent and incumbent["owner_id"]:
        notify(incumbent["owner_id"], msg_i)


def check_sea_claim_timeouts():
    conn = db()
    rows = conn.execute("SELECT * FROM sea_claims WHERE status='pending' AND deadline<=?",
                        (time.time(),)).fetchall()
    conn.close()
    for claim in rows:
        target = claim["target_ruler"] if "target_ruler" in claim.keys() else ""
        if target:
            _resolve_sea_challenge(claim)
            continue
        conn = db()
        conn.execute("UPDATE sea_claims SET status='resolved',winner_house=? WHERE id=?",
                     (claim["claimant_house"], claim["id"]))
        conn.execute("INSERT INTO world(key,value) VALUES('sea_ruler',?) "
                     "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                     (claim["claimant_house"],))
        conn.execute("DELETE FROM sea_claim_responses WHERE claim_id=?", (claim["id"],))
        conn.commit()
        conn.close()
        _announce_sea_ruler(claim["claimant_house"])


