def resolve_pending_attack(attack_id, defense_units):
    """Belgilangan hujumni (qo'lda yoki avtomatik) himoya bilan yakunlaydi."""
    with _lock:
        conn = db()
        atk_row = conn.execute("SELECT * FROM pending_attacks WHERE id=?", (attack_id,)).fetchone()
        if not atk_row or atk_row["status"] not in ("pending", "guard_pending"):
            conn.close()
            return
        attacker = conn.execute("SELECT * FROM houses WHERE name=?", (atk_row["attacker"],)).fetchone()
        defender = conn.execute("SELECT * FROM houses WHERE name=?", (atk_row["defender"],)).fetchone()
        sent_units = json.loads(atk_row["attack_units"])
        guard_stage = atk_row["status"] == "guard_pending"
        if not guard_stage and atk_row["war_type"] != "dengiz" and defender:
            king_name = conn.execute("SELECT value FROM world WHERE key='king'").fetchone()
            is_king = king_name and king_name["value"] == defender["name"]
            army_empty = not any(defender[u] > 0 for u in COMBAT_UNITS)
            defense_empty = not any(defense_units.get(u, 0) > 0 for u in COMBAT_UNITS)
            guard_rows = conn.execute(
                "SELECT * FROM king_guard_slots WHERE king_house=? ORDER BY slot",
                (defender["name"],)).fetchall()
            if is_king and army_empty and defense_empty and guard_rows:
                now = time.time()
                for row in guard_rows:
                    conn.execute(
                        "INSERT OR REPLACE INTO king_guard_battle_responses"
                        "(attack_id,guard_house,response,created_at) VALUES(?,?,?,?)",
                        (attack_id, row["guard_house"], "pending", now))
                conn.execute(
                    "UPDATE pending_attacks SET status='guard_pending', deadline=? WHERE id=?",
                    (now + 10 * 60, attack_id))
                conn.commit()
                conn.close()
                _notify_guard_battle(attack_id, defender["name"], guard_rows)
                return
        guard_power = 0
        if guard_stage:
            responses = conn.execute(
                "SELECT * FROM king_guard_battle_responses WHERE attack_id=?",
                (attack_id,)).fetchall()
            if any(row["response"] == "pending" for row in responses):
                conn.close()
                return
            guard_power = 0
            for row in responses:
                if row["response"] != "protect":
                    continue
                guard = get_house(row["guard_house"])
                guard_power += ritsarlik_war_power(guard["ritsarlik"] if guard else 0)
        if defender and not any(defender[u] > 0 for u in COMBAT_UNITS):
            defense_units["_lord_power"] = ritsarlik_war_power(defender["ritsarlik"])
        if guard_power:
            defense_units["_guard_power"] = guard_power
        personal_side = None
        if attacker and defender:
            if not any(attacker[u] > 0 for u in COMBAT_UNITS):
                personal_side = "attacker"
            elif not any(defender[u] > 0 for u in COMBAT_UNITS):
                personal_side = "defender"
        conn.execute("UPDATE pending_attacks SET status='resolved', defense_units=?, resolved_at=? WHERE id=?",
                     (json.dumps(defense_units), time.time(), attack_id))
        conn.commit()
        if not attacker or not defender:
            conn.close()
            return
        # Ittifoqchi hujumchi qo'shini
        ally_atk_raw = ""  # eski versiya uchun
        ally_atk_units = {}
        ally_atk_house = atk_row["ally_attack_house"] if "ally_attack_house" in atk_row.keys() else ""

        # Ittifoqchi himoyachi qo'shini
        ally_def_raw = atk_row["ally_defense_units"] if "ally_defense_units" in atk_row.keys() else ""
        ally_def_units = json.loads(ally_def_raw) if ally_def_raw else {}
        ally_def_house = atk_row["ally_defense_house"] if "ally_defense_house" in atk_row.keys() else ""

        # Bayroqdor (hudud lordi) qo'shini
        bannerlord_raw = atk_row["bannerlord_units"] if "bannerlord_units" in atk_row.keys() else ""
        bannerlord_units_data = json.loads(bannerlord_raw) if bannerlord_raw else {}
        bannerlord_house = ""
        if bannerlord_units_data:
            # bannerlord_units ichida "_lord_house" kaliti saqlanadi
            bannerlord_house = bannerlord_units_data.pop("_lord_house", "")

        if atk_row["war_type"] == "dengiz":
            # V4: hujumchining kema/askar nisbati va zaxirasi qayta tekshiriladi
            _ak = int(sent_units.get("kema", atk_row["kema_count"]) or atk_row["kema_count"] or 0)
            _at = {u: int(sent_units.get(u, 0) or 0) for u in COMBAT_UNITS}
            if (SHIPS_REQUIRE_FULL and not naval_ratio_ok(_ak, _at)) or attacker["kema"] < _ak \
                    or any(attacker[u] < _at[u] for u in COMBAT_UNITS):
                _txt = (f"🚫 <b>{attacker['name']}</b> ning dengiz hujumi bekor qilindi: kema/askar "
                        f"nisbati (1 kema = {SHIP_CAPACITY} askar) buzilgan yoki zaxira yetmaydi.")
                notify(attacker["owner_id"], _txt)
                notify(defender["owner_id"], _txt)
                conn.close()
                return
            # Himoyachi: nisbat buzilgan bo'lsa — himoyasiz hisoblanadi
            _dk = int(defense_units.get("kema", 0) or 0)
            if _dk > 0 and SHIPS_REQUIRE_FULL and not naval_ratio_ok(_dk, defense_units):
                defense_units = {}
            elif _dk > defender["kema"]:
                defense_units = {}
            # Dengizda ittifoqchi qo'shinlari birlashtirilib beriladi
            merged_def = dict(defense_units)
            for u, n in ally_def_units.items():
                merged_def[u] = merged_def.get(u, 0) + n
            for u, n in bannerlord_units_data.items():
                merged_def[u] = merged_def.get(u, 0) + n
            _resolve_naval(conn, attacker, defender, sent_units, merged_def, atk_row["kema_count"])
        else:
            isyon_type = atk_row["isyon_type"] if "isyon_type" in atk_row.keys() else ""
            _resolve_land(conn, attacker, defender, sent_units, defense_units,
                          ally_atk_units=ally_atk_units, ally_atk_house=ally_atk_house or None,
                          ally_def_units=ally_def_units, ally_def_house=ally_def_house or None,
                          bannerlord_units=bannerlord_units_data, bannerlord_house=bannerlord_house or None,
                          isyon_type=isyon_type or None, personal_side=personal_side)
        conn.close()


def _deduct_income_penalty(conn, house_name, penalty):
    """Toifa tushganda kunlik daromad jazosi: avval qasr yuksaltirish bonusi
    (income_bonus) kamaytiriladi, yetmagan qismi bir martalik tanga yoki
    BUY_PRICES boʻyicha teng qiymatdagi resurslardan ayriladi.
    Qaytaradi: jazo tafsiloti matni."""
    row = conn.execute("SELECT * FROM houses WHERE name=?", (house_name,)).fetchone()
    if not row or penalty <= 0:
        return ""
    lines = []
    bonus = row.get("income_bonus", 0) or 0
    from_bonus = min(bonus, penalty)
    if from_bonus > 0:
        conn.execute("UPDATE houses SET income_bonus=MAX(income_bonus-?,0) WHERE name=?",
                     (from_bonus, house_name))
        lines.append(f"kunlik daromaddan -{from_bonus} 💰tanga")
    remaining = penalty - from_bonus
    if remaining > 0:
        pay_tanga = min(remaining, row.get("tanga", 0) or 0)
        if pay_tanga > 0:
            conn.execute("UPDATE houses SET tanga=MAX(tanga-?,0) WHERE name=?",
                         (pay_tanga, house_name))
            remaining -= pay_tanga
            lines.append(f"{pay_tanga} 💰tanga")
        for res, price in sorted(BUY_PRICES.items(), key=lambda kv: kv[1]):
            if remaining <= 0:
                break
            if res == "valyria_polati":
                continue
            stock = row.get(res, 0) or 0
            take = min(remaining // price, stock)
            if take <= 0:
                continue
            conn.execute(f"UPDATE houses SET {res}=MAX({res}-?,0) WHERE name=?",
                         (take, house_name))
            remaining -= take * price
            lines.append(f"{take} {RESOURCE_EMOJI.get(res,'')}{RESOURCE_LABEL.get(res,res)}")
    return ", ".join(lines) if lines else ""


def _downgrade_tier_on_war_loss(conn, house_name):
    """Urush magʻlubiyatini hisobga oladi: har DEMOTION_LOSS_COUNT (5) ta
    magʻlubiyatda uyning toifasi bir pogʻona pasayadi: A -> B, B -> C.
    Toifa tushganda kunlik daromad jazosi qoʻllanadi (A dan tushsa 35,
    B dan tushsa 30 tanga — avval yuksaltirish bonusidan, yetmasa tanga/
    resursdan ayriladi). C toifadagi uylar uchun toifa oʻzgarmaydi
    (bu — eng past toifa, va oʻyindan chiqarish faqat qizil toʻy orqali sodir
    boʻladi, oddiy urush magʻlubiyati bilan emas)."""
    row = conn.execute("SELECT tier, owner_id, loss_streak FROM houses WHERE name=?",
                       (house_name,)).fetchone()
    if not row:
        return
    old_tier = row["tier"]
    new_tier = {"A": "B", "B": "C"}.get(old_tier)
    streak = (row.get("loss_streak", 0) or 0) + 1
    if not new_tier or streak < DEMOTION_LOSS_COUNT:
        conn.execute("UPDATE houses SET loss_streak=? WHERE name=?", (streak, house_name))
        conn.commit()
        if new_tier and row["owner_id"]:
            notify(row["owner_id"],
                   f"⚠️ Urush magʻlubiyati hisobga olindi ({streak}/{DEMOTION_LOSS_COUNT}). "
                   f"Yana {DEMOTION_LOSS_COUNT - streak} ta magʻlubiyatda toifangiz "
                   f"<b>{old_tier}</b> dan <b>{new_tier}</b> ga tushadi.")
        return
    conn.execute("UPDATE houses SET tier=?, loss_streak=0 WHERE name=?", (new_tier, house_name))
    penalty = DOWNGRADE_INCOME_PENALTY.get(old_tier, 0)
    detail = _deduct_income_penalty(conn, house_name, penalty)
    conn.commit()
    if row["owner_id"]:
        msg = (f"📉 {DEMOTION_LOSS_COUNT} ta urush magʻlubiyati tufayli toifangiz "
               f"<b>{old_tier}</b> dan <b>{new_tier}</b> ga pasaytirildi.")
        if detail:
            msg += f"\n💸 Jazo: {detail} ayrildi."
        notify(row["owner_id"], msg)
    log_history("tier_down", house_name,
                f"{DEMOTION_LOSS_COUNT} ta mag'lubiyat tufayli toifasi {old_tier} dan {new_tier} ga tushdi")


def _resolve_land(conn, attacker, defender, sent_troops, defense_troops, from_naval=False,
                  ally_atk_units=None, ally_atk_house=None,
                  ally_def_units=None, ally_def_house=None,
                  bannerlord_units=None, bannerlord_house=None,
                  isyon_type=None, personal_side=None):
    """
    ally_atk_units  — ittifoqchi hujumchi yuborgan qo'shin {unit: count}
    ally_atk_house  — shu ittifoqchining nomi
    ally_def_units  — ittifoqchi himoyachi yuborgan qo'shin
    ally_def_house  — shu ittifoqchining nomi
    bannerlord_units — hudud lordi bayroqdor sifatida yuborgan qo'shin (himoya)
    bannerlord_house — hudud lordining nomi

    YOQOTISH NISBATI:
      Asosiy taraf 75%, ittifoqchi 25% yoqotadi.
    Tirik qolgan ittifoqchi/bayroqdor qo'shini uyiga qaytariladi.
    """
    ally_atk_units = ally_atk_units or {}
    ally_def_units = ally_def_units or {}
    bannerlord_units = bannerlord_units or {}

    valyria_a_map = sent_troops.pop("_valyria_map", None) or {}
    valyria_d_map = defense_troops.pop("_valyria_map", None) or {}
    lord_power = defense_troops.pop("_lord_power", 0) or 0
    guard_power = defense_troops.pop("_guard_power", 0) or 0
    valyria_a_total = sum(valyria_a_map.values())
    valyria_d_total = sum(valyria_d_map.values())
    # Valyria poʻlati faqat YUTQAZGAN tomon yo'qotadi — g'olib o'z po'latini saqlab qoladi.

    # Jami hujum kuchi = asosiy + ittifoqchi hujumchi
    combined_atk = dict(sent_troops)
    for u, n in ally_atk_units.items():
        combined_atk[u] = combined_atk.get(u, 0) + n
    ap = land_power_with_valyria_map(combined_atk, "atk", valyria_a_map)
    # Kengash bonusi: qo'shin boshi hujum kuchini +20% oshiradi
    if is_council_member(attacker["name"], "qoshin_boshi"):
        ap = int(ap * 1.20)

    # Jami himoya kuchi = asosiy + ittifoqchi himoyachi + bayroqdor
    combined_def = dict(defense_troops)
    for u, n in ally_def_units.items():
        combined_def[u] = combined_def.get(u, 0) + n
    for u, n in bannerlord_units.items():
        combined_def[u] = combined_def.get(u, 0) + n
    dp = land_power_with_valyria_map(combined_def, "def", valyria_d_map)
    dp += lord_power + guard_power
    # Kengash bonusi: qo'shin boshi himoya kuchini +20% oshiradi
    if is_council_member(defender["name"], "qoshin_boshi"):
        dp = int(dp * 1.20)
    companion_power = _ai_defense_bonus(conn, defender, dp)
    dp += companion_power

    escalated_note = ""
    # Agar himoyachi armiyaning faqat bir qismini himoyaga qo'ygan bo'lsa va shu
    # qism yutqazayotgan bo'lsa — qolgan zaxiradagi barcha askarlari ham avtomatik
    # jangga kiradi.
    if ap > dp:
        reserve = {u: max(defender[u] - combined_def.get(u, 0), 0) for u in COMBAT_UNITS}
        if any(reserve.values()):
            for u in COMBAT_UNITS:
                combined_def[u] = combined_def.get(u, 0) + reserve[u]
                defense_troops[u] = defense_troops.get(u, 0) + reserve[u]
            dp = land_power_with_valyria_map(combined_def, "def", valyria_d_map) + companion_power
            escalated_note = "\n♻️ Himoyachining zaxiradagi qolgan barcha askarlari ham jangga qoʻshildi!"

    def_lines = "\n".join(f"{RESOURCE_EMOJI.get(u,'')} {RESOURCE_LABEL.get(u,u)}: {combined_def.get(u,0)}"
                           for u in COMBAT_UNITS if combined_def.get(u, 0) > 0) or "— (hech kim himoyalanmadi)"
    if lord_power:
        def_lines += f"\n👑 Lord kuchi: {lord_power}"
    if guard_power:
        def_lines += f"\n🛡️ Qirol gvardiyasi: {guard_power}"
    outcome = "draw"

    # --- Yordamchi: ittifoqchi/bayroqdor tirik qolganlarini uyiga qaytarish ---
    def _return_ally_survivors(ally_house_name, ally_units_sent, total_loss_ratio, side_share=0.25):
        """side_share — ittifoqchi ulushi (0.25 = 25%).
        MUHIM: askarlar help_advance/bannerlord_advance da allaqachon uydan yechilgan.
        Bu yerda: yoqotilganlarni o'chiramiz, tirik qolganlarni qaytaramiz (uyga qo'shamiz)."""
        if not ally_house_name or not ally_units_sent:
            return []
        lines = []
        for u, sent in ally_units_sent.items():
            if sent <= 0:
                continue
            # Ittifoqchi 25% yoqotadi (asosiy 75% nisbatiga moslashtirib)
            loss = int(sent * total_loss_ratio * side_share / 0.75)
            loss = min(loss, sent)
            survived = sent - loss
            # Yoqotilganlar allaqachon bazadan yechilgan (help_advance da) edi —
            # lekin biz ularni help_advance da BASEdan olib, PENDING_ATTACKS ga qo'ydik.
            # Jang tugaganda: faqat tirik qolganlarni uyiga qaytaramiz.
            # Yoqotilganlar esa qaytarilmaydi (yo'q qilingan).
            if survived > 0:
                conn.execute(f"UPDATE houses SET {u}={u}+? WHERE name=?", (survived, ally_house_name))
                lines.append(f"{RESOURCE_EMOJI.get(u,'')} {RESOURCE_LABEL.get(u,u)}: {survived} ta qaytdi")
        return lines

    if ap == dp:
        text = (f"⚔️ <b>{attacker['name']}</b> → <b>{defender['name']}</b> quruqlik jangi durrang yakunlandi "
                f"({ap} vs {dp}). Hech kim yutmadi, yuborilgan qoʻshinlar uyga qaytadi.\nHimoya:\n{def_lines}")
        # Durrangda ittifoqchi/bayroqdor qo'shinlari HECH NIMA yoʻqotmasdan uyiga qaytadi.
        # (Oldin ular help_advance/bannerlord_advance da uydan yechilgan boʻlib, durrangda
        # qaytarilmasdan yoʻqolib qolar edi — tuzatildi.)
        _return_ally_survivors(ally_atk_house, ally_atk_units, 0)
        _return_ally_survivors(ally_def_house, ally_def_units, 0)
        _return_ally_survivors(bannerlord_house, bannerlord_units, 0)
        conn.commit()
    elif ap > dp:
        outcome = "attacker"
        if guard_power:
            fallen_guards = conn.execute(
                "SELECT guard_house FROM king_guard_slots WHERE king_house=?",
                (defender["name"],)).fetchall()
            conn.execute("DELETE FROM king_guard_slots WHERE king_house=?", (defender["name"],))
            for fallen in fallen_guards:
                guard = conn.execute("SELECT owner_id FROM houses WHERE name=?",
                                     (fallen["guard_house"],)).fetchone()
                if guard and guard["owner_id"]:
                    notify(guard["owner_id"],
                           f"⚔️ Qirol gvardiyasi jangda halok bo'ldi: <b>{defender['name']}</b> mag'lub bo'ldi.")
        # Yoqotish nisbati: ratio = dp/ap (himoyachi kuchiga nisbatan)
        ratio = min(dp / ap, 1.0) if ap else 0

        # Himoyachining jangga chiqqan qo'shini (asosiy) to'liq yo'q bo'ladi
        for u in COMBAT_UNITS:
            used = combined_def.get(u, 0)
            if used:
                # Avval faqat asosiy himoyachidan olamiz
                main_used = defense_troops.get(u, 0)
                if main_used:
                    conn.execute(f"UPDATE houses SET {u} = MAX({u}-?,0) WHERE name=?", (main_used, defender["name"]))

        # Hujumchi yoqotishi: 75% hissasi
        atk_loss_lines = []
        for u in COMBAT_UNITS:
            sent = sent_troops.get(u, 0)
            if sent:
                loss = int(sent * ratio)  # asosiy hujumchi ulushi
                if loss:
                    conn.execute(f"UPDATE houses SET {u} = MAX({u}-?,0) WHERE name=?", (loss, attacker["name"]))

        # Ittifoqchi hujumchi yoqotishi (25% ulush) + tirik qolganlarini qaytarish
        ally_atk_return_lines = _return_ally_survivors(ally_atk_house, ally_atk_units, ratio)

        # Ittifoqchi/bayroqdor himoyachi yutqazdi — ularning qo'shini allaqachon
        # help_advance/bannerlord_advance da bazadan yechilgan edi, shu sababli
        # bu yerda qayta yechish SHART EMAS — ular shunchaki qaytmaydi (yo'q bo'ladi).
        # (Agar bu yerda ham yechsak — ikki marta yechiladi, bu xato edi)

        # Himoyachi yutqazdi — uning valyria poʻlati yoʻqoladi
        if valyria_d_total:
            conn.execute("UPDATE houses SET valyria_polati=MAX(valyria_polati-?,0) WHERE name=?",
                         (valyria_d_total, defender["name"]))
        conn.commit()

        # --- Gʻ'ALABA OʻLJASI ---
        # Qizil jodugar bonusi: agar hujumchi (g'olib)da qizil jodugar bo'lsa,
        # tanga va oddiy askar (qoshin)dan 50% o'rniga 60% oladi
        atk_jodugar = (attacker.get("qizil_jodugar", 0) or 0)
        loot_lines = []
        tanga_loot_amount = 0
        loot_resources = ["tanga", "valyria_polati", "kema"] + COMBAT_UNITS
        if defender.get("is_essos"):
            # Essos porti talanganda "mulkning yarmi" BARCHA resurs turlarini
            # (jumladan maxsus resurslarni ham) qamrab oladi.
            loot_resources = list(dict.fromkeys(
                loot_resources + ["yuzsiz_qotil", "qizil_jodugar", "zahar", "ziddizahar"]))
        for res in loot_resources:
            cur_row = conn.execute(f"SELECT {res} FROM houses WHERE name=?", (defender["name"],)).fetchone()
            cur = cur_row[res] if cur_row else 0
            if atk_jodugar >= 1 and res in ("tanga", "qoshin"):
                half = int(cur * 0.60)  # 60% — qizil jodugar bonusi
            else:
                half = cur // 2
            if half > 0:
                conn.execute(f"UPDATE houses SET {res}=MAX({res}-?,0) WHERE name=?", (half, defender["name"]))
                conn.execute(f"UPDATE houses SET {res}={res}+? WHERE name=?", (half, attacker["name"]))
                loot_lines.append(f"{RESOURCE_EMOJI.get(res,'')} {RESOURCE_LABEL.get(res,res)}: {half}")
                if res == "tanga":
                    tanga_loot_amount = half
        conn.commit()
        loot_note = ("\n\n🏆 <b>Gʻalaba oʻljasi</b>: " + ", ".join(loot_lines)) if loot_lines else ""

        # --- BAYROQDORLAR OʻLJASI: agar hujumchi bayroqdor chaqirgan boʻlsa,
        #     tanga oʻljasi bayroqdorlar oʻz vaqtida qoʻshgan qoʻshin ulushiga
        #     (yaʼni ular chekkan taxminiy yoqotish ulushiga) proporsional
        #     taqsimlanadi — qancha askar qoʻshgan/yoqotgan boʻlsa, shuncha % oladi. ---
        banner_loot_lines = []
        if tanga_loot_amount > 0:
            campaign = conn.execute(
                "SELECT * FROM muster_campaigns WHERE lord_house=? AND status='active'",
                (attacker["name"],)).fetchone()
            if campaign:
                contribs = conn.execute(
                    "SELECT * FROM muster_contributions WHERE campaign_id=? AND status='active'",
                    (campaign["id"],)).fetchall()
                total_contrib = sum(
                    (c["qoshin"] or 0) + (c["kamonchi"] or 0) + (c["otliq"] or 0)
                    + (c["kema"] or 0) + (c["benuqson"] or 0) + (c["kenja_ogil"] or 0)
                    for c in contribs)
                if total_contrib > 0:
                    # V15: o'ljaning BANNER_LORD_LOOT_SHARE qismi chaqiruvchi lordda
                    # qoladi; qolgani bayroqdorlar o'rtasida proporsional bo'linadi.
                    banner_pool = tanga_loot_amount - int(tanga_loot_amount * BANNER_LORD_LOOT_SHARE)
                    lord_kept = tanga_loot_amount - banner_pool
                    banner_loot_lines.append(
                        f"👑 {attacker['name']} (chaqiruvchi lord): {lord_kept} 💰 tanga")
                    for c in contribs:
                        c_total = ((c["qoshin"] or 0) + (c["kamonchi"] or 0) + (c["otliq"] or 0)
                                   + (c["kema"] or 0) + (c["benuqson"] or 0) + (c["kenja_ogil"] or 0))
                        if c_total <= 0:
                            continue
                        share_pct = c_total / total_contrib
                        share_tanga = int(banner_pool * share_pct)
                        if share_tanga <= 0:
                            continue
                        conn.execute("UPDATE houses SET tanga=MAX(tanga-?,0) WHERE name=?",
                                     (share_tanga, attacker["name"]))
                        conn.execute("UPDATE houses SET tanga=tanga+? WHERE name=?",
                                     (share_tanga, c["vassal_house"]))
                        banner_loot_lines.append(
                            f"🏴 {c['vassal_house']}: {share_tanga} 💰 tanga ({share_pct*100:.0f}%)")
                    conn.commit()
        banner_loot_note = ("\n\n🏴 <b>Bayroqdorlar ulushi</b> (qoʻshgan qoʻshiniga proporsional):\n"
                             + "\n".join(banner_loot_lines)) if banner_loot_lines else ""

        ally_note = ""
        if ally_atk_return_lines:
            ally_note += f"\n\n🤝 <b>{ally_atk_house}</b> ittifoqchi askarlari uyiga qaytdi:\n" + "\n".join(ally_atk_return_lines)

        text = (f"⚔️ <b>{attacker['name']}</b> quruqlik jangida gʻalaba qozondi ({ap} vs {dp})!\n"
                f"<b>{defender['name']}</b> ning jangga chiqqan himoyasi tor-mor etildi.\nHimoya:\n{def_lines}"
                f"{escalated_note}\n\n🏰 <b>{defender['name']}</b> qasri egallandi!{loot_note}{banner_loot_note}{ally_note}")
    else:
        outcome = "defender"
        ratio = min(ap / dp, 1.0) if dp else 0

        # Hujumchi yuborgan qo'shin: 75% asosiy, 25% ittifoqchi
        for u in COMBAT_UNITS:
            sent = sent_troops.get(u, 0)
            if sent:
                conn.execute(f"UPDATE houses SET {u} = MAX({u}-?,0) WHERE name=?", (sent, attacker["name"]))

        # Ittifoqchi hujumchi: 25% ulushi yoqotadi + tirik qolganlar qaytadi
        ally_atk_return_lines = _return_ally_survivors(ally_atk_house, ally_atk_units, ratio)

        # Himoyachi yoqotishi (asosiy): 75% ulush
        for u in COMBAT_UNITS:
            used = combined_def.get(u, 0)
            # Asosiy himoyachidan
            main_used = defense_troops.get(u, 0)
            if main_used:
                loss = int(main_used * ratio)
                if loss:
                    conn.execute(f"UPDATE houses SET {u} = MAX({u}-?,0) WHERE name=?", (loss, defender["name"]))

        # Ittifoqchi himoyachi (tirik qolganlarni qaytarish, 25% ulush yo'qotadi)
        ally_def_return_lines = _return_ally_survivors(ally_def_house, ally_def_units, ratio)
        bannerlord_return_lines = _return_ally_survivors(bannerlord_house, bannerlord_units, ratio)

        # Hujumchi yutqazdi — uning valyria poʻlati yoʻqoladi
        if valyria_a_total:
            conn.execute("UPDATE houses SET valyria_polati=MAX(valyria_polati-?,0) WHERE name=?",
                         (valyria_a_total, attacker["name"]))
        conn.commit()

        ally_note = ""
        if ally_atk_return_lines:
            ally_note += f"\n\n🤝 <b>{ally_atk_house}</b> ittifoqchi askarlari uyiga qaytdi:\n" + "\n".join(ally_atk_return_lines)
        if ally_def_return_lines:
            ally_note += f"\n\n🛡️ <b>{ally_def_house}</b> himoya ittifoqchi askarlari uyiga qaytdi:\n" + "\n".join(ally_def_return_lines)
        if bannerlord_return_lines:
            ally_note += f"\n\n🏴 <b>{bannerlord_house}</b> bayroqdor askarlari uyiga qaytdi:\n" + "\n".join(bannerlord_return_lines)

        text = (f"⚔️ <b>{defender['name']}</b> himoyani ushlab qoldi ({dp} vs {ap})!\n"
                f"<b>{attacker['name']}</b> yuborgan qoʻshinning barchasini yoʻqotdi.\nHimoya:\n{def_lines}"
                f"{ally_note}")
    if from_naval:
        text = "🌊➡️🗡️ Dengizdagi gʻalabadan soʻng qoʻshin qirgʻoqqa tushib, jang quruqlikda davom etdi!\n\n" + text
    notify(attacker["owner_id"], text)
    notify(defender["owner_id"], text)
    announce_war_concluded(attacker["name"], defender["name"], outcome,
                           personal_side=personal_side, guard_power=guard_power)

    # --- VASSAL OZODLIGI: agar gʻolib tomon magʻlub boʻlgan tomonning vassali
    #     boʻlsa (yaʼni oʻz hukmdoriga qarshi urushda gʻalaba qozongan boʻlsa),
    #     u ENDI OZOD boʻladi — hujumchi sifatida ham, himoyachi sifatida ham. ---
    if outcome == "attacker" and attacker["vassal_of"] == defender["name"]:
        conn.execute("UPDATE houses SET vassal_of='' WHERE name=?", (attacker["name"],))
        conn.commit()
        notify(attacker["owner_id"], f"🏰 Siz oʻz hukmdoringiz <b>{defender['name']}</b> ni urushda magʻlub etib, ENDI OZODSIZ!")
    elif outcome == "defender" and defender["vassal_of"] == attacker["name"]:
        conn.execute("UPDATE houses SET vassal_of='' WHERE name=?", (defender["name"],))
        conn.commit()
        notify(defender["owner_id"], f"🏰 Siz oʻz hukmdoringiz <b>{attacker['name']}</b> ning hujumini qaytarib, ENDI OZODSIZ!")

    # Urush statistikasi va tarix
    if outcome == "attacker":
        conn.execute("UPDATE houses SET wars_won=wars_won+1 WHERE name=?", (attacker["name"],))
        conn.execute("UPDATE houses SET wars_lost=wars_lost+1 WHERE name=?", (defender["name"],))
        conn.commit()
        log_history("war_win", attacker["name"], f"{defender['name']} ustidan g'alaba qozondi")
        log_history("war_loss", defender["name"], f"{attacker['name']} ga mag'lubiyatga uchradi")
    elif outcome == "defender":
        conn.execute("UPDATE houses SET wars_won=wars_won+1 WHERE name=?", (defender["name"],))
        conn.execute("UPDATE houses SET wars_lost=wars_lost+1 WHERE name=?", (attacker["name"],))
        conn.commit()
        log_history("war_win", defender["name"], f"{attacker['name']} hujumini qaytardi")
        log_history("war_loss", attacker["name"], f"{defender['name']} ga hujum muvaffaqiyatsiz")

    if outcome == "attacker":
        # Magʻlubiyat hisobga olinadi — har 5 ta magʻlubiyatda toifa pasayadi.
        _downgrade_tier_on_war_loss(conn, defender["name"])
        # --- ISYON GʻALABASI: hudud lordiga yoki qirolga qarshi isyon
        #     gʻalaba bilan tugasa, isyonchi DARHOL yangi hudud lordi yoki
        #     yangi qirol boʻladi (vassal qilish-qilmasligidan qatʼiy nazar). ---
        if isyon_type == "king":
            _isyon_promote_king(attacker["name"], defender["name"])
        elif isyon_type == "lord":
            _isyon_promote_region_lord(attacker["name"], defender["name"])
        # Temir bank maxsus qoidasi: barcha resurs tortib olindi + vassal
        if attacker["name"] == IRON_BANK_HOUSE:
            apply_iron_bank_war_result(conn, attacker["name"], defender["name"])
        elif defender.get("is_essos") and attacker.get("is_essos"):
            # Essos shahri boshqa Essos shahriga qarshi urushda gʻalaba
            # qozondi — "harbiy shahar" bosib olish qoidasi ishlaydi.
            _handle_essos_city_conquest(conn, attacker, defender)
        elif defender.get("is_essos") and not attacker.get("is_essos"):
            # Westeros Essos shahrini HECH QACHON bosib ololmaydi (faqat
            # portini talaydi — oʻlja yuqorida allaqachon olindi). Bu esa
            # BARCHA Essos shaharlari uchun "Essos qasosi"ni faollashtiradi.
            trigger_essos_vengeance(defender["name"], attacker["name"])
        elif attacker.get("is_essos") and not defender.get("is_essos"):
            # Essos shahri Westeros uyini VASSAL QILA OLMAYDI —
            # faqat portini talaydi (oʻlja yuqorida olindi).
            notify(attacker["owner_id"] if attacker.get("owner_id") else None,
                   f"⚔️ <b>{defender['name']}</b> portini muvaffaqiyatli taladingiz! "
                   f"Essos shahrlari Westeros uylarini vassal qila olmaydi.")
        else:
            # Westeros → Westeros: vassal taklifi
            offer_vassal_choice(attacker["name"], defender["name"])
    elif outcome == "defender":
        # Hujumi muvaffaqiyatsiz tugagan uy uchun ham magʻlubiyat hisoblanadi.
        _downgrade_tier_on_war_loss(conn, attacker["name"])
        # Himoyachi gʻalaba qozondi (hujum muvaffaqiyatsiz): hujumchi VASSAL
        # QILINMAYDI. Vassallik faqat hujumchi gʻalaba qozonib, himoyachi
        # himoyani ushlab qololmaganda boʻladi (yuqoridagi outcome == "attacker").


def _isyon_promote_king(rebel_name, old_king_name):
    """ISYON GʻALABASI (qirolga qarshi): isyonchi urushda gʻalaba qozonsa,
    vassal qilish-qilmasligidan qatʼiy nazar DARHOL yangi qirol boʻladi.
    Barcha uylarga xabar boradi va kanalga eʼlon qilinadi."""
    conn = db()
    king_row = conn.execute("SELECT value FROM world WHERE key='king'").fetchone()
    if not king_row or king_row["value"] != old_king_name:
        # Bu orada qirol allaqachon boshqa birov bo'lib ulgurgan bo'lishi mumkin — o'tkazib yuboramiz.
        conn.close()
        return
    conn.execute(
        "INSERT INTO world (key,value) VALUES ('king',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",
        (rebel_name,))
    conn.commit()
    all_h = conn.execute("SELECT name, owner_id FROM houses WHERE is_essos=0").fetchall()
    conn.close()
    rebel = get_house(rebel_name)
    post_to_channel(f"👑 <b>ISYON GʻALABA QILDI!</b> {lord_full_name(rebel_name)} qirol "
                    f"<b>{old_king_name}</b> ga qarshi isyon koʻtarib gʻalaba qozondi va ENDI YANGI "
                    f"TEMIR TAXT QIROLI!")
    for hh in all_h:
        if not hh["owner_id"]:
            continue
        try:
            bot.send_message(hh["owner_id"],
                f"👑 <b>ISYON GʻALABA QOZONDI!</b>\n\n<b>{rebel_name}</b> qirol <b>{old_king_name}</b> ga "
                f"qarshi isyon koʻtarib gʻalaba qozondi. Endi <b>{rebel_name}</b> — YANGI TEMIR TAXT QIROLI! "
                f"Barcha A toifali hudud lordlari endi unga soliq toʻlaydi.")
        except Exception as _e:
            _swallow(_e)


def _isyon_promote_region_lord(rebel_name, old_lord_name):
    """ISYON GʻALABASI (hudud lordiga qarshi): isyonchi gʻalaba qozonsa,
    DARHOL shu hududning yangi lordi boʻladi."""
    rebel = get_house(rebel_name)
    if not rebel:
        return
    region = rebel["region"]
    conn = db()
    lord_row = conn.execute("SELECT lord_house FROM regions WHERE region=?", (region,)).fetchone()
    if not lord_row or lord_row["lord_house"] != old_lord_name:
        # Bu orada hudud lordligi allaqachon boshqa birovga o'tgan bo'lishi mumkin.
        conn.close()
        return
    conn.execute("UPDATE regions SET lord_house=? WHERE region=?", (rebel_name, region))
    conn.commit()
    region_h = conn.execute(
        "SELECT name, owner_id FROM houses WHERE region=? AND is_essos=0", (region,)).fetchall()
    conn.close()
    log_history("region_lord_change", rebel_name,
                f"{region} hududi lordligi isyon orqali {old_lord_name} dan {rebel_name} ga o'tdi")
    post_to_channel(f"🏛️ <b>ISYON GʻALABA QILDI!</b> {lord_full_name(rebel_name)} hudud lordi "
                    f"<b>{old_lord_name}</b> ga qarshi isyon koʻtarib gʻalaba qozondi va ENDI "
                    f"<b>{region}</b> HUDUDINING YANGI LORDI!")
    for hh in region_h:
        if not hh["owner_id"]:
            continue
        try:
            bot.send_message(hh["owner_id"],
                f"🏛️ <b>ISYON GʻALABA QOZONDI!</b>\n\n<b>{rebel_name}</b> hudud lordi "
                f"<b>{old_lord_name}</b> ga qarshi isyon koʻtarib gʻalaba qozondi. Endi <b>{rebel_name}</b> — "
                f"<b>{region}</b> hududining YANGI LORDI!")
        except Exception as _e:
            _swallow(_e)


def _transfer_region_lordship_if_vassal(loser_name):
    """Agar hudud hukmdori (lordi) biror oilaga vassal boʻlib qolsa — hudud
    boshqaruvi hududdagi 2-eng kuchli va VASSAL BOʻLMAGAN oilaga oʻtadi.
    Agar hududda mustaqil oila qolmasa, amaldagi lord hudud lordligicha
    qolaveradi."""
    conn = db()
    loser = conn.execute("SELECT * FROM houses WHERE name=?", (loser_name,)).fetchone()
    if not loser:
        conn.close()
        return
    region = loser["region"]
    lord_row = conn.execute("SELECT lord_house FROM regions WHERE region=?", (region,)).fetchone()
    if not lord_row or lord_row["lord_house"] != loser_name:
        conn.close()
        return
    candidates = conn.execute(
        "SELECT * FROM houses WHERE region=? AND name!=? AND is_essos=0 "
        "AND (vassal_of IS NULL OR vassal_of='')", (region, loser_name)).fetchall()
    if not candidates:
        # Hududda mustaqil oila qolmadi — amaldagi lord lordligicha qoladi.
        conn.close()
        return
    best = max(candidates,
               key=lambda h: (land_defense_power(row_troops(h)), h.get("tanga", 0) or 0, h["name"]))
    conn.execute("UPDATE regions SET lord_house=? WHERE region=?", (best["name"], region))
    conn.commit()
    conn.close()
    log_history("region_lord_change", best["name"],
                f"{region} hududi boshqaruvi {loser_name} dan {best['name']} ga o'tdi (lord vassal bo'ldi)")
    if loser.get("owner_id"):
        notify(loser["owner_id"],
               f"🏛️ Vassal boʻlganingiz uchun <b>{region}</b> hududi boshqaruvi "
               f"<b>{best['name']}</b> ga oʻtdi.")
    if best.get("owner_id"):
        notify(best["owner_id"],
               f"🏛️ <b>{loser_name}</b> vassal boʻlib qolgani sababli endi SIZ "
               f"<b>{region}</b> hududining yangi lordisiz!")
    post_to_channel(f"🏛️ {lord_full_name(loser_name)} vassal boʻlib qolgani uchun {region} "
                    f"hududi boshqaruvi {lord_full_name(best['name'])} ga oʻtdi.")


def _same_continent(house_a, house_b):
    """Ikkala uy ham bitta qit'ada (Westeros yoki Essos) joylashganmi.
    Vassallik FAQAT bir qit'a ichida mumkin: Westeros uyi Essos shahrini ham,
    Essos shahri Westeros uyini ham vassal qila olmaydi (masalan Bravos Starkni
    yoki Stark Bravosni vassal qila olmaydi)."""
    if not house_a or not house_b:
        return False
    return bool(house_a.get("is_essos")) == bool(house_b.get("is_essos"))


def offer_vassal_choice(winner_name, loser_name):
    winner = get_house(winner_name)
    loser = get_house(loser_name)
    if not winner or not winner["owner_id"]:
        return
    if not loser:
        return
    if not _same_continent(winner, loser):
        # Qit'alararo urush: vassallik yo'q — faqat o'lja (port talash) qoidalari amal qiladi.
        notify(winner["owner_id"],
               f"⛔ <b>{loser_name}</b> boshqa qit'ada joylashgan — qit'alararo urushda "
               f"gʻalaba qozonsangiz ham vassal qilib boʻlmaydi.")
        return
    if (loser.get("vassal_of") or "") == winner_name:
        return  # allaqachon sizning vassalingiz
    kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton(f"🏰 Ha, {loser_name} ni vassal qilaman",
                                       callback_data=f"vassal_yes_{loser_name}"))
    kb.add(types.InlineKeyboardButton("🚫 Yoʻq, vassal qilmayman", callback_data=f"vassal_no_{loser_name}"))
    try:
        bot.send_message(winner["owner_id"],
            f"🏰 <b>{loser_name}</b> ni vassal qilasizmi? Vassal qilsangiz, uning kunlik "
            f"resursining yarmi har kuni sizga oʻtib turadi.", reply_markup=kb)
    except Exception as _e:
        _swallow(_e)


@bot.callback_query_handler(func=lambda c: c.data.startswith("vassal_yes_"))
def cb_vassal_yes(c):
    loser_name = c.data[len("vassal_yes_"):]
    winner = get_house_by_owner(c.from_user.id)
    if not winner:
        bot.answer_callback_query(c.id, "Sizda uy yoʻq.", show_alert=True)
        return
    # Vassallik faqat bir qit'a ichida: Westeros <-> Essos vassallik yo'q (ikki tomonga ham)
    loser = get_house(loser_name)
    if not loser:
        bot.answer_callback_query(c.id, "Bu uy topilmadi.", show_alert=True)
        return
    if not _same_continent(winner, loser):
        bot.answer_callback_query(c.id, "Boshqa qit'adagi oilani vassal qilib boʻlmaydi.", show_alert=True)
        return
    if loser_name == winner["name"] or (loser.get("vassal_of") or "") == winner["name"]:
        bot.answer_callback_query(c.id, "Bu uy allaqachon sizning vassalingiz.", show_alert=True)
        return
    conn = db()
    conn.execute("UPDATE houses SET vassal_of=? WHERE name=?", (winner["name"], loser_name))
    # --- KASKAD OZODLIK: agar magʻlub boʻlgan uy (loser) oʻzining vassallariga ega
    #     boʻlsa, ular endi ozod boʻladi — chunki loser oʻzi endi boshqa birovning
    #     vassaliga aylandi va oʻz vassalini boshqara olmaydi. ---
    freed = conn.execute("SELECT name, owner_id FROM houses WHERE vassal_of=?", (loser_name,)).fetchall()
    if freed:
        conn.execute("UPDATE houses SET vassal_of='' WHERE vassal_of=?", (loser_name,))
    # --- YANGI QIROL: agar magʻlub boʻlgan uy HOZIRGI QIROL boʻlsa, gʻolib
    #     ENDI YANGI QIROL boʻladi — barcha A toifali hudud lordlari endi
    #     unga soliq toʻlay boshlaydi (kunlik siklda avtomatik). ---
    became_king = False
    king_row = conn.execute("SELECT value FROM world WHERE key='king'").fetchone()
    if king_row and king_row["value"] == loser_name:
        conn.execute("UPDATE world SET value=? WHERE key='king'", (winner["name"],))
        became_king = True
    conn.commit()
    conn.close()
    bot.answer_callback_query(c.id, "Vassal qilindi.")
    bot.send_message(c.message.chat.id, f"🏰 <b>{loser_name}</b> endi sizning vassalingiz.", reply_markup=main_menu(c.from_user.id))
    if became_king:
        bot.send_message(c.message.chat.id,
            f"👑 <b>{loser_name}</b> avvalgi qirol edi — uni magʻlub etib vassal qilganingiz uchun "
            f"ENDI SIZ TEMIR TAXT QIROLISIZ! Barcha A toifali hudud lordlari endi sizga soliq toʻlaydi.")
        conn2 = db()
        all_h = conn2.execute("SELECT owner_id FROM houses WHERE is_essos=0").fetchall()
        conn2.close()
        for hh in all_h:
            if hh["owner_id"] and hh["owner_id"] != winner["owner_id"]:
                try:
                    bot.send_message(hh["owner_id"],
                        f"👑 <b>{winner['name']}</b> <b>{loser_name}</b> ni magʻlub etib TEMIR TAXTNI "
                        f"EGALLADI! Yangi qirol — <b>{winner['name']}</b>.")
                except Exception as _e:
                    _swallow(_e)
    loser = get_house(loser_name)
    if loser and loser["owner_id"]:
        notify(loser["owner_id"], f"🏰 Siz endi <b>{winner['name']}</b> ning vassalisiz. Kunlik resursingizning yarmi ularga oʻtadi.")
    # Agar vassal bo'lgan uy hudud lordi bo'lsa — hudud boshqaruvi hududdagi
    # eng kuchli mustaqil oilaga o'tadi.
    _transfer_region_lordship_if_vassal(loser_name)
    for f in freed:
        if f["owner_id"]:
            notify(f["owner_id"],
                   f"🏰 Sizning sobiq hukmdoringiz <b>{loser_name}</b> endi <b>{winner['name']}</b> ning vassaliga "
                   f"aylandi, shu sabab siz ENDI OZODSIZ va hech kimning vassali emassiz.")


