def help_advance(chat_id, uid):
    sess = help_session.get(uid)
    if not sess:
        return
    ally_house = get_house_by_owner(uid)
    if sess["queue"]:
        nxt = sess["queue"][0]
        send_pct_prompt(chat_id, "helppct_", "helpmanual_", nxt, ally_house[nxt])
        return
    attack = get_pending_attack(sess["attack_id"])
    if not attack or attack["status"] != "pending":
        bot.send_message(chat_id, "🚫 Hujum endi yordamga ochiq emas.", reply_markup=main_menu(uid))
        help_session.pop(uid, None)
        return
    mode = sess.get("mode", "attack")
    conn = db()
    added_lines = []

    if mode == "defense":
        current_units = json.loads(attack["ally_defense_units"]) if attack["ally_defense_units"] else {}
        for u, n in sess["units"].items():
            if n > 0:
                current_units[u] = current_units.get(u, 0) + n
                conn.execute(f"UPDATE houses SET {u} = MAX({u}-?,0) WHERE name=?", (n, ally_house["name"]))
                added_lines.append(f"{RESOURCE_EMOJI.get(u,'')} {RESOURCE_LABEL.get(u,u)}: {n}")
        conn.execute("UPDATE pending_attacks SET ally_defense_units=?, ally_defense_house=? WHERE id=?",
                     (json.dumps(current_units), ally_house["name"], attack["id"]))
        conn.commit()
        conn.close()
        help_session.pop(uid, None)
        text = "🤝 Ittifoqdoshingiz himoyangizga qoʻshin yubordi:\n" + ("\n".join(added_lines) if added_lines else "—")
        bot.send_message(chat_id, "✅ Yordam himoyaga qoʻshildi!", reply_markup=main_menu(uid))
        defender = get_house(attack["defender"])
        if defender and defender["owner_id"]:
            notify(defender["owner_id"], text)
        return

    current_units = json.loads(attack["attack_units"])
    reserved_map = current_units.pop("_valyria_map", None)
    ally_atk_units = json.loads(attack["ally_attack_units"]) if "ally_attack_units" in attack.keys() and attack["ally_attack_units"] else {}
    for u, n in sess["units"].items():
        if n > 0:
            current_units[u] = current_units.get(u, 0) + n
            ally_atk_units[u] = ally_atk_units.get(u, 0) + n
            conn.execute(f"UPDATE houses SET {u} = MAX({u}-?,0) WHERE name=?", (n, ally_house["name"]))
            added_lines.append(f"{RESOURCE_EMOJI.get(u,'')} {RESOURCE_LABEL.get(u,u)}: {n}")
    if reserved_map:
        current_units["_valyria_map"] = reserved_map
    conn.execute("UPDATE pending_attacks SET attack_units=?, ally_attack_house=?, ally_attack_units=? WHERE id=?",
                 (json.dumps(current_units), ally_house["name"], json.dumps(ally_atk_units), attack["id"]))
    conn.commit()
    conn.close()
    help_session.pop(uid, None)
    text = "🤝 Ittifoqdoshingiz jangga qoʻshin yubordi:\n" + ("\n".join(added_lines) if added_lines else "—")
    bot.send_message(chat_id, "✅ Yordam qoʻshinga qoʻshildi!", reply_markup=main_menu(uid))
    attacker = get_house(attack["attacker"])
    if attacker and attacker["owner_id"]:
        notify(attacker["owner_id"], text)


@bot.callback_query_handler(func=lambda c: c.data.startswith("helppct_"))
def cb_helppct(c):
    uid = c.from_user.id
    sess = help_session.get(uid)
    if not sess:
        bot.answer_callback_query(c.id, "Yordam jarayoni topilmadi.", show_alert=True)
        return
    _, unit, pct = c.data.split("_")
    pct = int(pct)
    ally_house = get_house_by_owner(uid)
    amount = round(ally_house[unit] * pct / 100)
    sess["units"][unit] = amount
    if sess["queue"]:
        sess["queue"].pop(0)
    bot.answer_callback_query(c.id, f"{amount} ta {RESOURCE_LABEL.get(unit,unit)} tanlandi.")
    help_advance(c.message.chat.id, uid)


