def process_help_manual(m, unit):
    uid = m.from_user.id
    sess = help_session.get(uid)
    if not sess:
        bot.reply_to(m, "Yordam jarayoni topilmadi.", reply_markup=main_menu(uid))
        return
    ally_house = get_house_by_owner(uid)
    max_amount = ally_house[unit]
    try:
        amount = int(m.text.strip())
    except ValueError:
        bot.reply_to(m, "Butun son kiriting.")
        return
    if amount < 0 or amount > max_amount:
        bot.reply_to(m, f"0 dan {max_amount} gacha son kiriting.")
        return
    sess["units"][unit] = amount
    if sess["queue"]:
        sess["queue"].pop(0)
    help_advance(m.chat.id, uid)


def _resolve_naval(conn, attacker, defender, sent_units, defense_units, kema_count):
    a_kema = sent_units.get("kema", kema_count) or kema_count
    d_kema = defense_units.get("kema", 0)
    a_troops = {u: sent_units.get(u, 0) for u in COMBAT_UNITS}
    d_troops = {u: defense_units.get(u, 0) for u in COMBAT_UNITS}
    a_total = sum(a_troops.values())
    d_total = sum(d_troops.values())

    if a_total == 0:
        text = f"🌊 <b>{attacker['name']}</b> kemalarga askar chiqarmagani uchun hujum bekor qilindi."
        notify(attacker["owner_id"], text)
        notify(defender["owner_id"], text)
        return

    if d_kema == 0 or d_total == 0:
        text = (f"🌊 <b>{defender['name']}</b> dengizda himoyalanmadi — <b>{attacker['name']}</b> floti "
                f"bemalol qirg'oqqa chiqdi. Qoʻshin qirgʻoqqa tushib, jang quruqlikda darhol davom etadi!")
        notify(attacker["owner_id"], text)
        notify(defender["owner_id"], text)
        fresh_attacker = conn.execute("SELECT * FROM houses WHERE name=?", (attacker["name"],)).fetchone()
        fresh_defender = conn.execute("SELECT * FROM houses WHERE name=?", (defender["name"],)).fetchone()
        land_defense = auto_fill_land_defense(fresh_defender)
        # Quruqda ham askar yo'q bo'lsa — hujumchi yo'qotmasdan g'alaba qozonadi
        if not land_defense or all(v == 0 for v in land_defense.values()):
            # Himoyachida hech kim yo'q — lootni to'g'ridan-to'g'ri olamiz
            _resolve_land(conn, fresh_attacker, fresh_defender, dict(a_troops), {}, from_naval=True)
        else:
            _resolve_land(conn, fresh_attacker, fresh_defender, dict(a_troops), land_defense, from_naval=True)
        return

    valyria_a = attacker["valyria_polati"]
    valyria_d = defender["valyria_polati"]
    ap = sea_power(a_troops, valyria_a)
    dp = sea_power(d_troops, valyria_d)
    def_lines = "\n".join(f"{RESOURCE_EMOJI.get(u,'')} {RESOURCE_LABEL.get(u,u)}: {d_troops.get(u,0)}"
                           for u in COMBAT_UNITS if d_troops.get(u, 0) > 0) or "—"

    if ap == dp:
        text = f"🌊 <b>{attacker['name']}</b> → <b>{defender['name']}</b> dengiz jangi durrang yakunlandi ({ap} vs {dp})."
        notify(attacker["owner_id"], text)
        notify(defender["owner_id"], text)
        post_to_channel(f"🤝 {lord_full_name(attacker['name'])} va {lord_full_name(defender['name'])} o'rtasidagi "
                         f"dengiz jangi durrang yakunlandi — ikkala tomon ham uyiga qaytdi.")
        now = time.time()
        _last_war_end_time[attacker["name"]] = now
        _last_war_end_time[defender["name"]] = now
        return
    elif ap > dp:
        for u in COMBAT_UNITS:
            used = d_troops.get(u, 0)
            if used:
                conn.execute(f"UPDATE houses SET {u} = MAX({u}-?,0) WHERE name=?", (used, defender["name"]))
        if d_kema:
            conn.execute("UPDATE houses SET kema = MAX(kema-?,0) WHERE name=?", (d_kema, defender["name"]))
        ratio = min(dp / ap, 1.0) if ap else 0
        for u in COMBAT_UNITS:
            sent = a_troops.get(u, 0)
            loss = int(sent * ratio)
            if loss:
                conn.execute(f"UPDATE houses SET {u} = MAX({u}-?,0) WHERE name=?", (loss, attacker["name"]))
        lost_ships = int(a_kema * ratio)
        if lost_ships:
            conn.execute("UPDATE houses SET kema = MAX(kema-?,0) WHERE name=?", (lost_ships, attacker["name"]))
        conn.commit()
        # Qirg'oqqa tushgan (omon qolgan) askarlar bilan quruqlik jangi DARHOL davom etadi.
        surviving = {u: max(a_troops.get(u, 0) - int(a_troops.get(u, 0) * ratio), 0) for u in COMBAT_UNITS}
        text = (f"🌊 <b>{attacker['name']}</b> dengiz jangida gʻalaba qozondi ({ap} vs {dp})!\n"
                f"<b>{defender['name']}</b> ning dengizdagi himoyasi va {d_kema} kemasi yoʻq qilindi.\n"
                f"Himoya:\n{def_lines}")
        notify(attacker["owner_id"], text)
        notify(defender["owner_id"], text)
        if sum(surviving.values()) > 0:
            fresh_attacker = conn.execute("SELECT * FROM houses WHERE name=?", (attacker["name"],)).fetchone()
            fresh_defender = conn.execute("SELECT * FROM houses WHERE name=?", (defender["name"],)).fetchone()
            land_defense = auto_fill_land_defense(fresh_defender)
            _resolve_land(conn, fresh_attacker, fresh_defender, surviving, land_defense, from_naval=True)
        else:
            announce_war_concluded(attacker["name"], defender["name"], "attacker")
        return
    else:
        for u in COMBAT_UNITS:
            sent = a_troops.get(u, 0)
            if sent:
                conn.execute(f"UPDATE houses SET {u} = MAX({u}-?,0) WHERE name=?", (sent, attacker["name"]))
        if a_kema:
            conn.execute("UPDATE houses SET kema = MAX(kema-?,0) WHERE name=?", (a_kema, attacker["name"]))
        ratio = min(ap / dp, 1.0) if dp else 0
        for u in COMBAT_UNITS:
            used = d_troops.get(u, 0)
            loss = int(used * ratio)
            if loss:
                conn.execute(f"UPDATE houses SET {u} = MAX({u}-?,0) WHERE name=?", (loss, defender["name"]))
        lost_ships = int(d_kema * ratio)
        if lost_ships:
            conn.execute("UPDATE houses SET kema = MAX(kema-?,0) WHERE name=?", (lost_ships, defender["name"]))
        conn.commit()
        text = (f"🌊 <b>{defender['name']}</b> dengizda himoyani ushlab qoldi ({dp} vs {ap})!\n"
                f"<b>{attacker['name']}</b> yuborgan {a_kema} kema va askarlarning barchasi yoʻq boʻldi.\n"
                f"Himoya:\n{def_lines}")
    notify(attacker["owner_id"], text)
    notify(defender["owner_id"], text)
    announce_war_concluded(attacker["name"], defender["name"], "defender")


def check_expired_attacks():
    conn = db()
    now = time.time()
    rows = conn.execute(
        "SELECT * FROM pending_attacks WHERE status IN ('pending','guard_pending') AND deadline<=?",
        (now,)).fetchall()
    conn.close()
    for r in rows:
        if r["status"] == "guard_pending":
            conn2 = db()
            conn2.execute(
                "UPDATE king_guard_battle_responses SET response='treason' "
                "WHERE attack_id=? AND response='pending'", (r["id"],))
            conn2.commit()
            conn2.close()
            resolve_pending_attack(r["id"], {})
            notify(get_house(r["defender"])["owner_id"] if get_house(r["defender"]) else None,
                   "⏰ Qirol gvardiyasi javob vaqti tugadi — javob bermaganlar xiyonat qilgan hisoblandi.")
            continue
        defender = get_house(r["defender"])
        if not defender:
            continue
        try:
            if r["war_type"] == "dengiz":
                d_kema, d_troops = auto_fill_naval_defense(defender)
                defense = dict(d_troops)
                defense["kema"] = d_kema
            else:
                defense = auto_fill_land_defense(defender)
            resolve_pending_attack(r["id"], defense)
            notify(defender["owner_id"], "⏰ Himoya vaqti tugadi — avtomatik himoya ishga tushdi.")
        except Exception as e:
            print("auto-himoya xatosi:", e)


