# ===========================================================================
# MUSTAQIL RITSER TIZIMI
# Barcha lordliklar band bo'lganda yangi o'yinchilar mustaqil ritser bo'ladi.
# Ritser: kunlik tanga, ritserlik turniri, lordga isyon orqali uy egallay olish.
# ===========================================================================

KNIGHT_DAILY_TANGA = 15       # Ritserlarga kunlik beriladigan tanga
KNIGHT_REBEL_COST  = 100      # Lordga isyon uchun kerakli minimal tanga
KNIGHT_TAX_RATE    = 0.10     # Vassal qal'asi bo'lmagan ritser kunlik resursining 10%ini soliq to'laydi
KNIGHT_CASTLE_COST = 500      # Vassal qal'a qurish narxi (tanga)
KNIGHT_CASTLE_DAILY_INCOME = 60   # Qal'a qurilgach kunlik daromad (C darajali lord kabi)
# Kunlik soliqda ushbu resurs turlari hisoblanadi (tanga + asosiy qo'shinlar)
KNIGHT_TAX_FIELDS = ["tanga", "qoshin", "kamonchi", "otliq", "kema", "benuqson", "kenja_ogil"]


def _knight_house_name(uid):
    """Yersiz mustaqil ritserning 'houses' jadvalidagi ichki (texnik) nomi."""
    return f"Ritser#{uid}"


def get_knight(uid):
    """Foydalanuvchi yersiz mustaqil ritser bo'lsa — 'houses' jadvalidagi
    qatorini qaytaradi, aks holda None.
    ESLATMA (V18): endi mustaqil ritserlar alohida 'knights' jadvalida EMAS,
    balki 'houses' jadvalida (is_free_knight=1) saqlanadi — shu bois savdo,
    hayvon, hudud topshirig'i, temir bank kabi BARCHA bo'limlar oddiy
    lordlardagidek avtomatik ishlaydi (chunki hammasi get_house_by_owner()
    ga tayanadi). Qulaylik uchun natijada 'house' kaliti ham qo'shiladi —
    bu ritserning xizmat qiladigan lordligi (vassal_of) nomi.
    """
    conn = db()
    row = conn.execute(
        "SELECT * FROM houses WHERE owner_id=? AND is_free_knight=1", (uid,)).fetchone()
    conn.close()
    if row:
        row = dict(row)
        row["house"] = row.get("vassal_of", "")
    return row


def assign_as_knight(uid, house_name):
    """Foydalanuvchini berilgan lordlikdagi mustaqil ritser qilib belgilaydi
    (V18: 'houses' jadvalida is_free_knight=1 qator sifatida)."""
    liege = get_house(house_name)
    region = liege["region"] if liege else ""
    kname = _knight_house_name(uid)
    conn = db()
    # Foydalanuvchida avvaldan boshqa uy yoki eski ritser yozuvi bo'lsa tozalash
    conn.execute("UPDATE houses SET owner_id=NULL WHERE owner_id=? AND name!=?", (uid, kname))
    conn.execute("DELETE FROM knights WHERE user_id=?", (uid,))
    conn.execute("""
        INSERT INTO houses (name, region, tier, owner_id, tanga, vassal_of, is_essos,
                             last_income, is_free_knight)
        VALUES (?,?,?,?,50,?,0,?,1)
        ON CONFLICT(name) DO UPDATE SET
            region=excluded.region, tier='RITSER', owner_id=excluded.owner_id,
            vassal_of=excluded.vassal_of, is_free_knight=1
    """, (kname, region, "RITSER", uid, house_name, time.time()))
    conn.commit()
    conn.close()


def make_independent_knight(uid, house_name):
    """Admin panelidan: foydalanuvchini berilgan lordlik hududida mustaqil
    ritser qilib belgilaydi. (ism, xabar) qaytaradi."""
    liege = get_house(house_name)
    if not liege:
        return False, "❌ Bunday lordlik topilmadi."
    assign_as_knight(uid, house_name)
    ism = get_user_name(uid) or f"user_id={uid}"
    return True, (
        f"✅ <b>{ism}</b> endi <b>{house_name}</b> lordligining mustaqil ritseri "
        f"qilib tayinlandi.")


def _knight_daily_tick(conn, now_struct):
    """Kunlik tickda har bir yersiz mustaqil ritserga (is_free_knight=1):
      1) KNIGHT_DAILY_TANGA (15 tanga) qo'shiladi,
      2) shundan so'ng resurslarining (tanga, qoshin, kamonchi, otliq, kema,
         benuqson, kenja_ogil) KNIGHT_TAX_RATE (10%) qismi xizmat qilgan
         lordlikka (vassal_of) soliq sifatida o'tkaziladi. Vassal qal'a
         qurgan (endi is_free_knight=0, tier='C') ritserlar bu soliqdan
         AVTOMATIK ozod — chunki ular endi bu tsiklga kirmaydi.
    """
    today_key = time.strftime("%Y-%m-%d", now_struct)
    last_row = conn.execute(
        "SELECT value FROM world WHERE key='knight_last_tick'").fetchone()
    last_date = last_row["value"] if last_row else ""
    if last_date == today_key:
        return
    # 1) Kunlik stipendiya
    conn.execute("UPDATE houses SET tanga = tanga + ? WHERE is_free_knight=1",
                 (KNIGHT_DAILY_TANGA,))
    conn.commit()

    # 2) Xizmat solig'i (10%, kamayib boruvchi — har kuni QOLGAN miqdordan hisoblanadi)
    knights = conn.execute(
        "SELECT * FROM houses WHERE is_free_knight=1 AND vassal_of IS NOT NULL "
        "AND vassal_of!=''").fetchall()
    for kn in knights:
        liege_name = kn["vassal_of"]
        liege = conn.execute("SELECT name, owner_id FROM houses WHERE name=?",
                              (liege_name,)).fetchone()
        if not liege:
            continue
        amounts = {}
        for field in KNIGHT_TAX_FIELDS:
            cur_val = kn[field] or 0
            amt = int(cur_val * KNIGHT_TAX_RATE)
            if amt > 0:
                amounts[field] = amt
        if not amounts:
            continue
        for field, amt in amounts.items():
            conn.execute(f"UPDATE houses SET {field} = MAX({field}-?,0) WHERE name=?",
                         (amt, kn["name"]))
            conn.execute(f"UPDATE houses SET {field} = {field}+? WHERE name=?",
                         (amt, liege_name))
        conn.commit()
        try:
            detail = ", ".join(
                f"{n} {RESOURCE_EMOJI.get(f,'')}{RESOURCE_LABEL.get(f,f)}"
                for f, n in amounts.items())
            if kn["owner_id"]:
                bot.send_message(kn["owner_id"],
                    f"📜 Mustaqil ritser sifatida kunlik xizmat solig'i: {detail} "
                    f"<b>{liege_name}</b> ga to'landi. (Qal'a qursangiz bu soliqdan "
                    f"ozod bo'lasiz!)", parse_mode="HTML")
            if liege["owner_id"]:
                bot.send_message(liege["owner_id"],
                    f"📜 Mustaqil ritseringizdan xizmat solig'i sifatida {detail} keldi.",
                    parse_mode="HTML")
        except Exception as _e:
            _swallow(_e)

    conn.execute(
        "INSERT INTO world (key,value) VALUES ('knight_last_tick',?) "
        "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
        (today_key,))
    conn.commit()


