@bot.callback_query_handler(func=lambda c: c.data == "kn_rebel")
def cb_kn_rebel(c):
    uid = c.from_user.id
    if _is_stale_callback(c):
        return
    knight = get_knight(uid)
    if not knight:
        bot.answer_callback_query(c.id, "Siz ritser emassiz.", show_alert=True)
        return
    if not is_war_time():
        bot.answer_callback_query(c.id,
            "⛔ Isyon faqat Chorshanba/Juma/Yakshanba 19:00-21:30 da bo'ladi!",
            show_alert=True)
        return
    if knight["tanga"] < KNIGHT_REBEL_COST:
        bot.answer_callback_query(c.id,
            f"⛔ Isyon uchun {KNIGHT_REBEL_COST} tanga kerak (sizda: {knight['tanga']}).",
            show_alert=True)
        return
    target_house = get_house(knight["house"])
    if not target_house:
        bot.answer_callback_query(c.id, "Lordlik topilmadi.", show_alert=True)
        return
    if not target_house["owner_id"]:
        # Egasiz uy — to'g'ridan-to'g'ri lord qilamiz
        conn = db()
        conn.execute(
            "UPDATE houses SET owner_id=? WHERE name=? AND owner_id IS NULL",
            (uid, knight["house"]))
        conn.execute("DELETE FROM knights WHERE user_id=?", (uid,))
        conn.execute("DELETE FROM houses WHERE name=? AND is_free_knight=1", (knight["name"],))
        conn.commit()
        conn.close()
        bot.answer_callback_query(c.id, "🎉 Lordlik egasiz edi — siz lord bo'ldingiz!", show_alert=True)
        bot.send_message(c.message.chat.id,
            f"🎉 <b>{knight['house']}</b> lordligi egasiz ekan — siz endi <b>lord</b> bo'ldingiz!",
            reply_markup=main_menu(uid), parse_mode="HTML")
        return
    # Egali uy — isyon tasdiqlash so'raladi
    kb = types.InlineKeyboardMarkup(row_width=1)
    kb.add(
        types.InlineKeyboardButton(
            f"⚔️ Ha, isyon ko'taraman ({KNIGHT_REBEL_COST} tanga sarflanadi)",
            callback_data=f"kn_rebel_confirm_{knight['house']}"),
        types.InlineKeyboardButton("❌ Bekor", callback_data="m_back")
    )
    text = (
        f"⚔️ <b>Lordga isyon</b>\n\n"
        f"<b>{knight['house']}</b> lordiga qarshi isyon ko'taryapsiz.\n"
        f"Bu {KNIGHT_REBEL_COST} tanga sarflaydi.\n\n"
        f"G'alaba qozonilsa — siz yangi lord bo'lasiz!\n"
        f"Mag'lub bo'lsangiz — tanga yo'qoladi."
    )
    bot.send_message(c.message.chat.id, text, reply_markup=kb, parse_mode="HTML")
    bot.answer_callback_query(c.id)


@bot.callback_query_handler(func=lambda c: c.data.startswith("kn_rebel_confirm_"))
def cb_kn_rebel_confirm(c):
    import random as _r
    uid = c.from_user.id
    if _is_stale_callback(c):
        return
    target_name = c.data[len("kn_rebel_confirm_"):]
    knight = get_knight(uid)
    if not knight or knight["house"] != target_name:
        bot.answer_callback_query(c.id, "Xatolik.", show_alert=True)
        return
    if not is_war_time():
        bot.answer_callback_query(c.id, "⛔ Isyon vaqti tugadi.", show_alert=True)
        return
    # Atomic tanga yechish
    conn = db()
    cur = conn.execute(
        "UPDATE houses SET tanga = tanga - ? WHERE name=? AND is_free_knight=1 AND tanga >= ?",
        (KNIGHT_REBEL_COST, knight["name"], KNIGHT_REBEL_COST))
    conn.commit()
    if cur.rowcount == 0:
        conn.close()
        bot.answer_callback_query(c.id, "❌ Tanga yetarli emas.", show_alert=True)
        return
    conn.close()

    target_house = get_house(target_name)
    if not target_house:
        bot.answer_callback_query(c.id, "Lordlik topilmadi.", show_alert=True)
        return

    # Jang kuchi: ritser ritsarlik balli vs lord quruqlik himoyasi
    knight_power = max(10, knight["ritsarlik"] * 3 + 20)
    lord_troops  = row_troops(target_house)
    lord_power   = max(5, land_defense_power(lord_troops, target_house.get("valyria_polati", 0)))
    knight_wins  = _r.random() < (knight_power / (knight_power + lord_power))
    ism = get_user_name(uid) or "Ritser"

    if knight_wins:
        old_owner = target_house["owner_id"]
        conn2 = db()
        conn2.execute("UPDATE houses SET owner_id=? WHERE name=?", (uid, target_name))
        conn2.execute("DELETE FROM knights WHERE user_id=?", (uid,))
        # Ritsarlik balli va tanga bonusi — yersiz ritser qatori endi kerak emas
        conn2.execute(
            "UPDATE houses SET wars_won = wars_won + 1 WHERE name=?", (target_name,))
        conn2.execute("DELETE FROM houses WHERE name=? AND is_free_knight=1", (knight["name"],))
        conn2.commit()
        conn2.close()
        bot.answer_callback_query(c.id, "🎉 G'alaba!", show_alert=True)
        bot.send_message(c.message.chat.id,
            f"🎉 <b>ISYON G'ALABA QILDI!</b>\n\n"
            f"<b>{ism}</b> <b>{target_name}</b> lordiga isyon ko'tarib g'alaba qozondi!\n"
            f"Endi siz yangi lord sifatida o'yinni davom ettiring! 👑",
            reply_markup=main_menu(uid), parse_mode="HTML")
        if old_owner:
            try:
                bot.send_message(old_owner,
                    f"⚠️ <b>{target_name}</b> lordligingizga ritser <b>{ism}</b> isyon ko'tarib "
                    f"g'alaba qozondi. Endi u yangi lord!")
            except Exception as _e:
                _swallow(_e)
    else:
        conn2 = db()
        conn2.execute(
            "UPDATE houses SET wars_lost = wars_lost + 1 WHERE name=?", (knight["name"],))
        conn2.commit()
        conn2.close()
        bot.answer_callback_query(c.id, "❌ Isyon bostirila olindi.", show_alert=True)
        bot.send_message(c.message.chat.id,
            f"❌ <b>Isyon mag'lub bo'ldi.</b>\n\n"
            f"<b>{target_name}</b> lordining qo'shinlari isyoningizni bostirib tashladi.\n"
            f"{KNIGHT_REBEL_COST} tanga sarflandi. Kuchini to'plab qayta urining!",
            reply_markup=main_menu(uid), parse_mode="HTML")
        if target_house["owner_id"]:
            try:
                bot.send_message(target_house["owner_id"],
                    f"⚔️ <b>{ism}</b> siz bilan isyon orqali jang qildi va mag'lub bo'ldi. "
                    f"Lordligingiz himoyalandi!")
            except Exception as _e:
                _swallow(_e)


