# ---------------------------------------------------------------------------
# TEMIR BANK — istalgan resursni sotib olish YOKI sotish mumkin bo'lgan
# umumiy bozor. Valyria poʻlati endi shu yerdan sotib olinadi (avvalgi
# "Maxsus boʻlim" bekor qilindi).
# ---------------------------------------------------------------------------

BANK_BUY_OPTIONS = [1, 5, 10, 50]
# QAT'IY QOIDA: bank resursni AYNAN qanday narxga sotgan boʻlsa, xuddi shu
# narxga qaytarib sotib oladi ham (chegirma/marja YOʻQ). Masalan kamonchi
# 3 tangaga sotib olingan boʻlsa, sotilganda ham 3 tanga beriladi.
SELL_PRICES = dict(BUY_PRICES)


@bot.callback_query_handler(func=lambda c: c.data == "m_temirbank")
def cb_temirbank(c):
    house = get_house_by_owner(c.from_user.id)
    if not house:
        bot.answer_callback_query(c.id, "Sizda uy yoʻq.", show_alert=True)
        return
    # Temir bank balansi
    conn_tb = db()
    tb_bal_row = conn_tb.execute("SELECT value FROM world WHERE key='iron_bank_balance'").fetchone()
    tb_balance = int(tb_bal_row["value"]) if tb_bal_row else IRON_BANK_INITIAL_BALANCE
    # Faol qarz bormi?
    active_loan = conn_tb.execute(
        "SELECT * FROM loans WHERE house=? AND status='active'", (house["name"],)).fetchone()
    pending_loan = conn_tb.execute(
        "SELECT * FROM loans WHERE house=? AND status='pending'", (house["name"],)).fetchone()
    conn_tb.close()

    kb = types.InlineKeyboardMarkup(row_width=2)
    for res in BUY_PRICES.keys():
        if res in BANK_EXCLUDED_RESOURCES:
            continue  # benuqson, yuzsiz_qotil, qizil_jodugar, zahar, ziddizahar temir bankda sotilmaydi
        kb.add(types.InlineKeyboardButton(f"{RESOURCE_EMOJI.get(res,'')} {RESOURCE_LABEL.get(res,res)}",
                                           callback_data=f"tb_res_{res}"))
    if active_loan:
        owed = active_loan["given_amount"]  # foizsiz avtomatik qarz
        due = time.strftime("%d.%m.%Y %H:%M", time.localtime(active_loan["due_at"]))
        kb.add(types.InlineKeyboardButton(
            f"💸 Qarz qaytarish ({owed} tanga, muddat: {due})", callback_data="tb_repay_loan"))
    elif pending_loan:
        kb.add(types.InlineKeyboardButton("⏳ Qarz so'rovi ko'rib chiqilmoqda...", callback_data="tb_loan_pending"))
    elif house["tier"] in LOAN_TIER_AMOUNTS:
        loan_amt = LOAN_TIER_AMOUNTS[house["tier"]]
        kb.add(types.InlineKeyboardButton(
            f"💵 Qarz olish ({loan_amt} tanga, {LOAN_TERM_DAYS} kunga)", callback_data="tb_loan_request"))
    kb.add(types.InlineKeyboardButton("⬅️ Bosh menyu", callback_data="m_back"))

    loan_info = ""
    if active_loan:
        owed = active_loan["given_amount"]
        due = time.strftime("%d.%m.%Y %H:%M", time.localtime(active_loan["due_at"]))
        loan_info = (f"\n\n⚠️ <b>Faol qarz:</b> {active_loan['given_amount']} tanga olgan "
                     f"(qaytarish: {owed} tanga, muddat: {due}). Muddat tugasa Temir bank "
                     f"AVTOMATIK undirib oladi. Yangi qarz olish uchun avval shu qarzni yoping.")
    # Braavos admini uchun ikki xil byudjet ko'rsatiladi
    if house["name"] == IRON_BANK_HOUSE:
        bravos_city_tanga = house["tanga"]
        text = (f"🏦 <b>Temir bank</b>\n\n"
                f"🏦 <b>Temir bank byudjeti:</b> <b>{tb_balance} tanga</b>\n"
                f"   (qarz berish, savdo tushumlari)\n\n"
                f"🌊 <b>Braavos shahri xazinasi:</b> <b>{bravos_city_tanga} tanga</b>\n"
                f"   (shahar o'z resurslari uchun)\n\n"
                f"Resurs sotib olish yoki sotish uchun tanlang:")
    else:
        text = (f"🏦 <b>Temir bank</b>\n"
                f"Bank balansi: <b>{tb_balance} tanga</b>\n"
                f"Sizda hozir: <b>{house['tanga']} tanga</b>{loan_info}\n\n"
                f"Resurs sotib olish yoki sotish uchun tanlang:")
    bot.send_message(c.message.chat.id, text, reply_markup=kb, parse_mode="HTML")
    bot.answer_callback_query(c.id)


