@bot.callback_query_handler(func=lambda c: c.data == "m_qasr_upgrade")
def cb_qasr_yuksaltirish(c):
    uid = c.from_user.id
    house = get_house_by_owner(uid)
    if not house or house.get("is_essos"):
        bot.answer_callback_query(c.id, "Sizda Westerosda uy yoʻq.", show_alert=True)
        return
    if house.get("is_free_knight"):
        # Mustaqil ritser hali yer/qal'aga ega emas — "yuksaltirish" o'rniga
        # o'ziga birinchi (vassal) qal'a qurish taklif etiladi (bu funksiya
        # callback'ni o'zi javoblaydi).
        cb_kn_build_castle(c)
        return
    bot.answer_callback_query(c.id)
    if _freeze_guard(uid, c.message.chat.id):
        return
    tier = house["tier"]
    next_tier = {"C": "B", "B": "A"}.get(tier)
    bonus_now = house.get("income_bonus", 0) or 0
    if not next_tier:
        bot.send_message(c.message.chat.id,
            f"🏗 <b>Qasrni yuksaltirish</b>\n\nQasringiz allaqachon eng yuqori — <b>A</b> toifada. "
            f"Undan yuqoriga yuksaltirib boʻlmaydi.\n"
            f"💰 Yuksaltirish bonusi: kuniga +{bonus_now} tanga.",
            reply_markup=back_button())
        return
    cost = UPGRADE_COST[tier]
    bonus = UPGRADE_INCOME_BONUS[tier]
    kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton(f"🏗 Yuksaltirish ({cost} tanga)", callback_data="qasr_up_go"))
    kb.add(types.InlineKeyboardButton("⬅️ Orqaga", callback_data="m_back"))
    bot.send_message(c.message.chat.id,
        f"🏗 <b>Qasrni yuksaltirish</b>\n\n"
        f"Hozirgi daraja: <b>{tier}</b>\n"
        f"Keyingi daraja: <b>{next_tier}</b>\n"
        f"Narx: <b>{cost}</b> 💰tanga\n"
        f"Kunlik daromadga qoʻshiladi: <b>+{bonus}</b> 💰tanga\n\n"
        f"Xazinangizda: <b>{house['tanga']}</b> 💰tanga\n"
        f"Hozirgi yuksaltirish bonusi: kuniga +{bonus_now} tanga\n\n"
        f"⚠️ Eslatma: 5 ta urush magʻlubiyatida daraja bir pogʻona tushadi va "
        f"kunlik daromaddan (A dan tushsa 35, B dan tushsa 30 tanga) ayriladi.",
        reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data == "qasr_up_go")
def cb_qasr_up_go(c):
    uid = c.from_user.id
    house = get_house_by_owner(uid)
    if not house or house.get("is_essos"):
        bot.answer_callback_query(c.id, "Sizda Westerosda uy yoʻq.", show_alert=True)
        return
    if _freeze_guard(uid, c.message.chat.id):
        bot.answer_callback_query(c.id)
        return
    tier = house["tier"]
    next_tier = {"C": "B", "B": "A"}.get(tier)
    if not next_tier:
        bot.answer_callback_query(c.id, "Qasringiz allaqachon eng yuqori toifada.", show_alert=True)
        return
    cost = UPGRADE_COST[tier]
    bonus = UPGRADE_INCOME_BONUS[tier]
    if house["tanga"] < cost:
        bot.answer_callback_query(c.id,
            f"Tanga yetarli emas: kerak {cost}, sizda {house['tanga']}.", show_alert=True)
        return
    conn = db()
    conn.execute("UPDATE houses SET tanga=MAX(tanga-?,0), tier=?, "
                 "income_bonus=income_bonus+? WHERE name=?",
                 (cost, next_tier, bonus, house["name"]))
    conn.commit()
    conn.close()
    bot.answer_callback_query(c.id, "Qasr yuksaltirildi!")
    bot.send_message(c.message.chat.id,
        f"🏗 <b>Qasr yuksaltirildi!</b>\n\n"
        f"<b>{house['name']}</b> endi <b>{next_tier}</b> toifada.\n"
        f"💰 {cost} tanga toʻlandi.\n"
        f"📈 Kunlik daromadingizga +{bonus} tanga qoʻshildi.",
        reply_markup=main_menu(uid))
    log_history("tier_up", house["name"],
                f"qasrini yuksaltirib {tier} dan {next_tier} toifaga chiqdi ({cost} tanga)")
    post_to_channel(f"🏗 {lord_full_name(house['name'])} qasrini yuksaltirdi — "
                    f"<b>{house['name']}</b> endi <b>{next_tier}</b> toifada!")


@bot.callback_query_handler(func=lambda c: c.data == "m_vassals")
def cb_vassals(c):
    house = get_house_by_owner(c.from_user.id)
    if not house:
        bot.answer_callback_query(c.id, "Sizda uy yoʻq.", show_alert=True)
        return
    conn = db()
    rows = conn.execute("SELECT * FROM houses WHERE vassal_of=? ORDER BY name",
                         (house["name"],)).fetchall()
    # Aktiv muster (bayroqdor safarbarlik) hissalarini ham ko'rsatamiz
    campaign_row = conn.execute("SELECT * FROM muster_campaigns WHERE lord_house=? AND status='active'",
                                 (house["name"],)).fetchone()
    muster_contribs = []
    if campaign_row:
        muster_contribs = conn.execute(
            "SELECT * FROM muster_contributions WHERE campaign_id=? AND status='active'",
            (campaign_row["id"],)).fetchall()
    conn.close()
    kb = types.InlineKeyboardMarkup(row_width=1)

    if not rows:
        txt = "🏰 Sizning hozircha vassalingiz yoʻq."
    else:
        lines = [f"🏰 <b>{house['name']}</b> ning vassallari:\n"]
        for r in rows:
            egasi = "(egasiz)" if not r["owner_id"] else "👤"
            # Har bir vassaldan kunlik nima kelishi haqida ma'lumot
            prod = PRODUCTION.get(r["name"])
            has_income = False
            if prod:
                _, _, tanga, qoshin, kamonchi, otliq, kema, benuqson, kenja_ogil = prod
                has_income = True
            elif r["castle_daily_income"]:
                # V18: ritser qurgan vassal qal'a — PRODUCTION lug'atida yo'q,
                # lekin castle_daily_income ustunida oʻz kunlik daromadi bor.
                tanga = r["castle_daily_income"]
                qoshin = kamonchi = otliq = kema = benuqson = kenja_ogil = 0
                has_income = True
            if has_income:
                half_parts = []
                if tanga // 2: half_parts.append(f"💰{tanga // 2} tanga")
                if qoshin // 2: half_parts.append(f"⚔️{qoshin // 2} qoshin")
                if kamonchi // 2: half_parts.append(f"🏹{kamonchi // 2} kamonchi")
                if otliq // 2: half_parts.append(f"🐎{otliq // 2} otliq")
                if kema // 2: half_parts.append(f"⛵{kema // 2} kema")
                if benuqson // 2: half_parts.append(f"🛡️{benuqson // 2} benuqson")
                if kenja_ogil // 2: half_parts.append(f"🗡️{kenja_ogil // 2} kenja oʻgʻil")
                kunlik_info = " | ".join(half_parts) if half_parts else "—"
            else:
                kunlik_info = "—"
            # Agar shu vassal aktiv musterda hissasi bo'lsa — ko'rsatamiz
            contrib_info = ""
            for mc in muster_contribs:
                if mc["vassal_house"] == r["name"]:
                    contrib_parts = []
                    for u in ["qoshin", "kamonchi", "otliq", "kema", "benuqson", "kenja_ogil"]:
                        if mc[u] > 0:
                            contrib_parts.append(f"{RESOURCE_EMOJI.get(u,'')}{mc[u]}")
                    if contrib_parts:
                        contrib_info = f"\n  🏴 Safarbarlikda (sizda): {' '.join(contrib_parts)}"
                    break
            lines.append(
                f"• {egasi} <b>{r['name']}</b> ({r['region']}, {r['tier']} toifa)\n"
                f"  📦 Kunlik ulush (½): {kunlik_info}\n"
                f"  🏦 Joriy resurslar: {fmt_resources_short(r)}"
                + contrib_info
            )
            kb.add(types.InlineKeyboardButton(f"🔁 {r['name']} ni boshqasiga berish",
                                               callback_data=f"vgive_pick_{r['name']}"))
        txt = "\n".join(lines)
    kb.add(types.InlineKeyboardButton("⬅️ Bosh menyu", callback_data="m_back"))
    bot.send_message(c.message.chat.id, txt, reply_markup=kb)
    bot.answer_callback_query(c.id)


def fmt_resources_short(h):
    """Uy resurslarini qisqacha ko'rsatish."""
    parts = []
    if h["tanga"]: parts.append(f"💰{h['tanga']}")
    if h["qoshin"]: parts.append(f"⚔️{h['qoshin']}")
    if h["kamonchi"]: parts.append(f"🏹{h['kamonchi']}")
    if h["otliq"]: parts.append(f"🐎{h['otliq']}")
    if h["kema"]: parts.append(f"⛵{h['kema']}")
    if h["benuqson"]: parts.append(f"🛡️{h['benuqson']}")
    if h["kenja_ogil"]: parts.append(f"🗡️{h['kenja_ogil']}")
    return " ".join(parts) if parts else "—"


