@bot.callback_query_handler(func=lambda c: c.data == "m_musterdisperse")
def cb_musterdisperse(c):
    """Bayroqdorlarni tarqatish: aktiv safarbarlik(lar)dagi omon qolgan
    resurslarni ulush asosida asl egalariga qaytaradi."""
    uid = c.from_user.id
    lord_house = get_house_by_owner(uid)
    if not lord_house:
        bot.answer_callback_query(c.id, "Sizda uy yoʻq.", show_alert=True)
        return
    conn = db()
    campaigns = conn.execute("SELECT * FROM muster_campaigns WHERE lord_house=? AND status='active'",
                              (lord_house["name"],)).fetchall()
    if not campaigns:
        conn.close()
        bot.answer_callback_query(c.id, "Aktiv safarbarligingiz yoʻq.", show_alert=True)
        return
    report_lines = []
    for campaign in campaigns:
        contributions = conn.execute(
            "SELECT * FROM muster_contributions WHERE campaign_id=? AND status='active'",
            (campaign["id"],)).fetchall()
        if not contributions:
            conn.execute("UPDATE muster_campaigns SET status='dispersed' WHERE id=?", (campaign["id"],))
            continue
        lord_now = conn.execute("SELECT * FROM houses WHERE name=?", (lord_house["name"],)).fetchone()
        for u in WAR_MUSTER_FIELDS:
            total_pool = campaign[f"base_{u}"] + sum(row[u] for row in contributions)
            if total_pool <= 0:
                continue
            current_amount = lord_now[u]
            for row in contributions:
                if row[u] <= 0:
                    continue
                share = round(current_amount * row[u] / total_pool)
                if share <= 0:
                    continue
                conn.execute(f"UPDATE houses SET {u} = MAX({u}-?,0) WHERE name=?",
                             (share, lord_house["name"]))
                conn.execute(f"UPDATE houses SET {u} = {u} + ? WHERE name=?",
                             (share, row["vassal_house"]))
                report_lines.append(f"• {row['vassal_house']}: {RESOURCE_EMOJI.get(u,'')} "
                                     f"{RESOURCE_LABEL.get(u,u)} {share}")
                v_house = get_house(row["vassal_house"])
                if v_house and v_house["owner_id"]:
                    notify(v_house["owner_id"],
                           f"🏳️ <b>{lord_house['name']}</b> bayroqdorlarni tarqatdi — sizga "
                           f"{RESOURCE_EMOJI.get(u,'')} {RESOURCE_LABEL.get(u,u)}: {share} qaytdi.")
        conn.execute("UPDATE muster_contributions SET status='returned' WHERE campaign_id=?",
                     (campaign["id"],))
        conn.execute("UPDATE muster_campaigns SET status='dispersed' WHERE id=?", (campaign["id"],))
    conn.commit()
    conn.close()
    bot.answer_callback_query(c.id, "Tarqatildi.")
    txt = "🏳️ <b>Bayroqdorlar tarqatildi.</b>\n"
    txt += "\n".join(report_lines) if report_lines else "Qaytariladigan omon qolgan resurs topilmadi."
    bot.send_message(c.message.chat.id, txt, reply_markup=main_menu(uid))


def check_muster_response_timeouts():
    """"Istalgan paytdagi" bayroqdor safarbarligida (m_musterall) chorlovga
    javob bermagan vassallarni tekshiradi. BANNERCALL_RESPONSE_SECONDS
    muddati o'tsa — javobsizlik AVTOMATIK rad etish sifatida hisoblanadi:
    yarmi majburiy olinadi (oldin javob bermaslik hech narsaga olib
    kelmasdi — bu ENDI tuzatildi)."""
    now = time.time()
    conn = db()
    expired = conn.execute(
        "SELECT * FROM muster_pending WHERE created_at<=?",
        (now - BANNERCALL_RESPONSE_SECONDS,)).fetchall()
    for row in expired:
        campaign_id = row["campaign_id"]
        vassal_name = row["vassal_house"]
        conn.execute("DELETE FROM muster_pending WHERE campaign_id=? AND vassal_house=?",
                     (campaign_id, vassal_name))
        conn.commit()
        campaign = conn.execute("SELECT * FROM muster_campaigns WHERE id=? AND status='active'",
                                 (campaign_id,)).fetchone()
        vassal_house = conn.execute("SELECT * FROM houses WHERE name=?", (vassal_name,)).fetchone()
        if not campaign or not vassal_house:
            continue
        forced = {}
        for u in WAR_MUSTER_FIELDS:
            half = vassal_house[u] // 2
            if half > 0:
                forced[u] = half
        if forced:
            _apply_muster_contribution(campaign_id, vassal_name, forced, campaign["lord_house"])
        lines = [f"{RESOURCE_EMOJI.get(u,'')} {RESOURCE_LABEL.get(u,u)}: {n}" for u, n in forced.items()]
        if vassal_house["owner_id"]:
            try:
                bot.send_message(
                    vassal_house["owner_id"],
                    "⏰ <b>Bayroqdor safarbarligiga javob bermadingiz</b> — bu AVTOMATIK rad etish "
                    "hisoblanadi. Shunga qaramay yarmi majburiy olindi:\n"
                    + ("\n".join(lines) if lines else "— (resurs yoʻq)") +
                    "\n\n⏳ Urush tugagach, urushda yoʻqotilmagan qismi avtomatik qaytadi (eng koʻpi "
                    "bilan 5 soatdan keyin).",
                    parse_mode="HTML")
            except Exception as _e:
                _swallow(_e)
        lord_h = conn.execute("SELECT * FROM houses WHERE name=?", (campaign["lord_house"],)).fetchone()
        if lord_h and lord_h["owner_id"]:
            try:
                bot.send_message(
                    lord_h["owner_id"],
                    f"⏰ <b>{vassal_name}</b> safarbarlikka javob bermadi — avtomatik rad etish "
                    f"sifatida yarmi majburiy olindi:\n" + ("\n".join(lines) if lines else "—"),
                    parse_mode="HTML")
            except Exception as _e:
                _swallow(_e)
    conn.close()


def _muster_return_rows(conn, campaign, rows, all_active, header):
    """Bayroqdor hissalarini (rows) asl egalariga (vassallarga) qaytaradi.
    Ulush lordning HOZIRGI resursiga nisbatan hisoblanadi — shuning uchun urushda
    yoʻqotilgan qism qaytmaydi, yoʻqotilmagani qaytadi.

    MUHIM (tuzatilgan xato): lordning hozirgi resursi BIR MARTA (snapshot) olinadi.
    Oldin har bir vassal uchun qayta oʻqilar edi, shu sababli bir vaqtda bir necha
    vassal qaytarilganda keyingilariga KAM (kamaygan qoldiqdan) qaytar edi."""
    lord_house = campaign["lord_house"]
    lord_snapshot = conn.execute("SELECT * FROM houses WHERE name=?", (lord_house,)).fetchone()
    if not lord_snapshot:
        return
    for row in rows:
        lines = []
        for u in WAR_MUSTER_FIELDS:
            if row[u] <= 0:
                continue
            total_pool = campaign[f"base_{u}"] + sum(r[u] for r in all_active)
            if total_pool <= 0:
                continue
            current_amount = lord_snapshot[u] or 0
            share = round(current_amount * row[u] / total_pool)
            if share <= 0:
                continue
            conn.execute(f"UPDATE houses SET {u} = MAX({u}-?,0) WHERE name=?", (share, lord_house))
            conn.execute(f"UPDATE houses SET {u} = {u} + ? WHERE name=?", (share, row["vassal_house"]))
            lines.append(f"{RESOURCE_EMOJI.get(u,'')} {RESOURCE_LABEL.get(u,u)}: {share}")
        conn.execute("UPDATE muster_contributions SET status='returned' WHERE id=?", (row["id"],))
        _house_cache_invalidate(name=row["vassal_house"])
        v_house = conn.execute("SELECT owner_id FROM houses WHERE name=?", (row["vassal_house"],)).fetchone()
        if v_house and v_house["owner_id"]:
            try:
                bot.send_message(v_house["owner_id"],
                    header + "\n" + ("\n".join(lines) if lines
                                     else "— (omon qolgan resurs yoʻq — urushda yoʻqotilgan)"))
            except Exception as _e:
                _swallow(_e)
    _house_cache_invalidate(name=lord_house)


def check_muster_timeouts():
    """5 soatlik MUDDAT tugagan bayroqdor hissalarini AVTOMATIK egalariga qaytaradi
    (zaxira qoida: urush tugashi bilan qaytarish check_muster_war_end da bajariladi)."""
    now = time.time()
    conn = db()
    expired = conn.execute(
        "SELECT * FROM muster_contributions WHERE status='active' AND created_at<=?",
        (now - MUSTER_LOCK_SECONDS,)).fetchall()
    if not expired:
        conn.close()
        return
    by_campaign = {}
    for row in expired:
        by_campaign.setdefault(row["campaign_id"], []).append(row)
    for campaign_id, rows in by_campaign.items():
        campaign = conn.execute("SELECT * FROM muster_campaigns WHERE id=?", (campaign_id,)).fetchone()
        if not campaign or campaign["status"] != "active":
            continue
        all_active = conn.execute(
            "SELECT * FROM muster_contributions WHERE campaign_id=? AND status='active'",
            (campaign_id,)).fetchall()
        _muster_return_rows(conn, campaign, rows, all_active,
                            "⏳ 5 soat toʻldi — bayroqdor safarbarligiga bergan resurslaringiz "
                            "AVTOMATIK ravishda sizga qaytdi:")
        still_active = conn.execute(
            "SELECT COUNT(*) AS n FROM muster_contributions WHERE campaign_id=? AND status='active'",
            (campaign_id,)).fetchone()
        if still_active["n"] == 0:
            conn.execute("UPDATE muster_campaigns SET status='dispersed' WHERE id=?", (campaign_id,))
    conn.commit()
    conn.close()


def check_muster_war_end():
    """URUSH TUGAGACH (urush vaqti yopilgach — jadval boʻyicha yoki admin
    urushni toʻxtatganda) bayroqdorlar resurslarini avtomatik qaytaradi:
    urushda YOʻQOTILMAGAN qismi vassallarga qaytadi. Lordning hali hal boʻlmagan
    (kutilayotgan) urushi boʻlsa — u yakunlangach qaytariladi."""
    if is_war_time():
        return
    conn = db()
    campaigns = conn.execute("SELECT * FROM muster_campaigns WHERE status='active'").fetchall()
    for campaign in campaigns:
        lord = campaign["lord_house"]
        busy = conn.execute(
            "SELECT 1 FROM pending_attacks WHERE status IN ('pending','guard_pending') "
            "AND (attacker=? OR defender=?)", (lord, lord)).fetchone()
        if busy:
            continue
        rows = conn.execute(
            "SELECT * FROM muster_contributions WHERE campaign_id=? AND status='active'",
            (campaign["id"],)).fetchall()
        if rows:
            _muster_return_rows(conn, campaign, rows, rows,
                                "🏳️ Urush tugadi — bayroqdor safarbarligiga bergan resurslaringizning "
                                "urushda yoʻqotilmagan qismi AVTOMATIK qaytdi:")
            lord_h = conn.execute("SELECT owner_id FROM houses WHERE name=?", (lord,)).fetchone()
            if lord_h and lord_h["owner_id"]:
                notify(lord_h["owner_id"],
                       "🏳️ Urush tugadi — bayroqdorlar tarqatildi, ularning omon qolgan resurslari "
                       "egalariga qaytarildi.")
        conn.execute("UPDATE muster_campaigns SET status='dispersed' WHERE id=?", (campaign["id"],))
        conn.execute("DELETE FROM muster_pending WHERE campaign_id=?", (campaign["id"],))
        conn.commit()
    conn.close()


