@bot.callback_query_handler(func=lambda c: c.data == "ally_gift_start")
def cb_ally_gift_start(c):
    uid = c.from_user.id
    house = get_house_by_owner(uid)
    if not house:
        bot.answer_callback_query(c.id, "Sizda uy yoʻq.", show_alert=True)
        return
    if not house["alliance_with"]:
        bot.answer_callback_query(c.id, "Sizda ittifoqdoshingiz yoʻq.", show_alert=True)
        return
    ally_gift_session[uid] = {}
    kb = types.InlineKeyboardMarkup(row_width=2)
    btns = []
    for r in RESOURCE_NAMES:
        amount = house.get(r, 0) or 0
        btns.append(types.InlineKeyboardButton(
            f"{RESOURCE_EMOJI.get(r,'')} {RESOURCE_LABEL.get(r,r)} (bor: {amount})",
            callback_data=f"allygiftres_{r}"))
    kb.add(*btns)
    kb.add(types.InlineKeyboardButton("⬅️ Bosh menyu", callback_data="m_back"))
    bot.send_message(c.message.chat.id,
        f"🎁 <b>{house['alliance_with']}</b> ga qaysi resursdan berasiz?",
        reply_markup=kb, parse_mode="HTML")
    bot.answer_callback_query(c.id)


@bot.callback_query_handler(func=lambda c: c.data.startswith("allygiftres_"))
def cb_ally_giftres(c):
    uid = c.from_user.id
    resource = c.data[len("allygiftres_"):]
    house = get_house_by_owner(uid)
    if not house or not house["alliance_with"]:
        bot.answer_callback_query(c.id, "Sizda ittifoqdoshingiz yoʻq.", show_alert=True)
        return
    if resource not in RESOURCE_NAMES:
        bot.answer_callback_query(c.id, "Notoʻgʻri resurs.", show_alert=True)
        return
    have = house.get(resource, 0) or 0
    if have <= 0:
        bot.answer_callback_query(c.id, f"Sizda {RESOURCE_LABEL.get(resource,resource)} yoʻq.", show_alert=True)
        return
    ally_gift_session.setdefault(uid, {})["resource"] = resource
    msg = bot.send_message(c.message.chat.id,
        f"{RESOURCE_EMOJI.get(resource,'')} <b>{RESOURCE_LABEL.get(resource,resource)}</b> dan "
        f"ittifoqdoshingiz <b>{house['alliance_with']}</b> ga nechta berasiz? (bor: {have})\n"
        f"Sonini yozib yuboring (masalan: 10)", parse_mode="HTML")
    bot.register_next_step_handler(msg, process_ally_gift_amount)
    bot.answer_callback_query(c.id)


def process_ally_gift_amount(m):
    uid = m.from_user.id
    sess = ally_gift_session.get(uid)
    if not sess or "resource" not in sess:
        bot.reply_to(m, "Jarayon bekor qilingan. Qaytadan boshlang.", reply_markup=main_menu(uid))
        return
    try:
        amount = int((m.text or "").strip())
        if amount <= 0:
            raise ValueError
    except ValueError:
        bot.reply_to(m, "Musbat butun son kiriting.")
        return
    house = get_house_by_owner(uid)
    if not house:
        bot.reply_to(m, "Sizda uy yoʻq.")
        clear_sessions(uid)
        return
    ally_name = house["alliance_with"]
    if not ally_name:
        bot.reply_to(m, "Sizda ittifoqdoshingiz yoʻq.", reply_markup=main_menu(uid))
        clear_sessions(uid)
        return
    ally = get_house(ally_name)
    if not ally:
        bot.reply_to(m, "Ittifoqdoshingiz topilmadi.", reply_markup=main_menu(uid))
        clear_sessions(uid)
        return
    resource = sess["resource"]
    have = house.get(resource, 0) or 0
    if amount > have:
        bot.reply_to(m, f"Sizda yetarli {RESOURCE_LABEL.get(resource,resource)} yoʻq. Bor: {have}, soʻralgan: {amount}.")
        return
    conn = db()
    conn.execute(f"UPDATE houses SET {resource} = MAX({resource}-?,0) WHERE name=?", (amount, house["name"]))
    conn.execute(f"UPDATE houses SET {resource} = {resource} + ? WHERE name=?", (amount, ally_name))
    conn.commit()
    conn.close()
    clear_sessions(uid)
    res_label = RESOURCE_LABEL.get(resource, resource)
    res_emoji = RESOURCE_EMOJI.get(resource, "")
    bot.reply_to(m,
        f"✅ Ittifoqdoshingiz <b>{ally_name}</b> ga {res_emoji} <b>{amount} {res_label}</b> hadya qildingiz!",
        reply_markup=main_menu(uid), parse_mode="HTML")
    if ally["owner_id"]:
        notify(ally["owner_id"],
               f"🎁 Ittifoqdoshingiz <b>{house['name']}</b> sizga {res_emoji} <b>{amount} {res_label}</b> hadya qildi!")


