def show_houses_list(m):
    conn = db()
    rows = conn.execute("""
        SELECT h.name, h.region, h.tier, h.owner_id, h.is_essos,
               u.username, u.ism
        FROM houses h
        LEFT JOIN users u ON h.owner_id = u.user_id
        ORDER BY h.region, h.name
    """).fetchall()
    conn.close()
    text = "<b>🏰 Uylar roʻyxati:</b>\nUyni bosing — umumiy ma'lumot ko'ring.\n"
    cur = None
    kb = types.InlineKeyboardMarkup(row_width=2)
    btns = []
    for r in rows:
        if r["region"] != cur:
            cur = r["region"]
            text += f"\n<b>— {cur} —</b>\n"
        if not r["owner_id"]:
            egasi = "🔓 boʻsh"
        else:
            lord_ism = r["ism"] or ""
            lord_user = r["username"] or ""
            display = lord_ism or lord_user or "lord"
            if lord_user:
                egasi = f'👤 <a href="https://t.me/{lord_user}">{display}</a>'
            else:
                egasi = f"👤 {display}"
        toifa = "" if r["is_essos"] else f" [{r['tier']}]"
        text += f"{r['name']}{toifa} — {egasi}\n"
        btns.append(types.InlineKeyboardButton(r["name"], callback_data=f"hview_{r['name']}"))
    kb.add(*btns)
    kb.add(types.InlineKeyboardButton("⬅️ Bosh menyu", callback_data="m_back"))
    bot.send_message(m.chat.id, text, reply_markup=kb, parse_mode="HTML",
                     disable_web_page_preview=True)


@bot.callback_query_handler(func=lambda c: c.data.startswith("hview_"))
def cb_hview(c):
    uid = c.from_user.id
    name = c.data[len("hview_"):]
    house = get_house(name)
    if not house:
        bot.answer_callback_query(c.id, "Topilmadi.", show_alert=True)
        return
    bot.answer_callback_query(c.id)
    my_house = get_house_by_owner(uid)
    is_own = my_house and my_house["name"] == name

    text = f"<b>🏰 {house['name']}</b>"
    if not house["is_essos"]:
        text += f" [{house['tier']} toifa]"
    text += f"\n📍 Hudud: {house['region']}\n"

    if house["is_essos"]:
        kind_label = "Quldorlik koʻrfazi shahri" if house["name"] in ESSOS_SLAVERS_BAY else "Essos ozod shahri"
        text += f"\n🌊 Bu — {kind_label}\n"
        if house["vassal_of"]:
            text += f"⚑ Boshqa Essos shahriga vassal: {house['vassal_of']}\n"
        if get_essos_king() == house["name"]:
            text += "👑🌊 ESSOS QIROLI!\n"
        if is_own:
            text += f"\n<b>📊 Sizning resurslaringiz:</b>\n"
            text += fmt_resources(house)
            ok_mil, atk_pow, def_pow = essos_military_status(house)
            text += f"\n⚔️ Hujum kuchi: {atk_pow}  🛡️ Himoya kuchi: {def_pow}"
            text += ("\n🏰 <b>\"Harbiy shahar\"</b> maqomida — boshqa Essos shaharlariga hujum qila olasiz!"
                      if ok_mil else
                      f"\n🔒 \"Harbiy shahar\" maqomi yoʻq (kerak: ⚔️{ESSOS_MILITARY_ATK_THRESHOLD} / 🛡️{ESSOS_MILITARY_DEF_THRESHOLD})")
    else:
        # Status
        if not house["owner_id"]:
            text += "🔓 Egasiz — kimsasiz uy\n"
        else:
            _lu_conn = db()
            _lu = _lu_conn.execute(
                "SELECT username, ism FROM users WHERE user_id=?",
                (house["owner_id"],)).fetchone()
            _lu_conn.close()
            if _lu:
                _lism = _lu["ism"] or ""
                _lusr = _lu["username"] or ""
                _disp = _lism or _lusr or "lord"
                if _lusr:
                    text += f'👤 Lord: <a href="https://t.me/{_lusr}">{_disp}</a>\n'
                else:
                    text += f"👤 Lord: {_disp}\n"
            else:
                text += "👤 Ega bor (lord)\n"
        if house["name"] == get_king():
            text += "👑 QIROLLIK UYI!\n"
        elif house["name"] == get_region_lord(house["region"]):
            text += f"🏛️ {house['region']} hudud lordi\n"
        if house["alliance_with"]:
            text += f"🤝 Ittifoqdosh: {house['alliance_with']}\n"
        if house["vassal_of"]:
            text += f"⚑ Vassal: {house['vassal_of']} uyiga bo'ysunadi\n"
        text += "\n🔒 <i>Resurslar va askar soni maxfiy. Josuslik missiyasi orqali bilib olish mumkin.</i>"

        # Faqat o'z uyini ko'rsa — resurslar ko'rsatiladi
        if is_own:
            text += f"\n\n<b>📊 Sizning resurslaringiz:</b>\n"
            text += fmt_resources(house)
            text += f"\n⚔️ Hujum kuchi: {land_attack_power(row_troops(house), house['valyria_polati'])}"
            text += f"\n🛡️ Himoya kuchi: {land_defense_power(row_troops(house), house['valyria_polati'])}"
            text += f"\n⛵ {house['kema']} kema ({naval_capacity(house['kema'])} ta askar sig'adi)"

    kb = types.InlineKeyboardMarkup(row_width=1)
    if not house["owner_id"] and not house["is_essos"]:
        kb.add(types.InlineKeyboardButton("🏰 Ushbu uyni tanlash", callback_data=f"pick_{house['name']}"))
    if is_own and house["is_essos"] and get_essos_king() != house["name"]:
        kb.add(types.InlineKeyboardButton(
            "👑🌊 Essos qirolligiga davogar boʻlish", callback_data=f"essos_claim_start_{house['name']}"))
    # Isyon tugmasi: faqat o'z uyi bo'lmagan, egali Westeros uyiga
    if not is_own and not house["is_essos"] and house["owner_id"]:
        my_h = get_house_by_owner(uid)
        if my_h:
            region_lord_n = get_region_lord(my_h["region"])
            king_n = get_king()
            # Faqat o'z hudud lordiga yoki hozirgi qirolga isyon ko'tarish mumkin
            if house["name"] in (region_lord_n, king_n) and my_h["name"] != house["name"]:
                kb.add(types.InlineKeyboardButton(
                    "⚔️ Isyon ko'tarish", callback_data=f"isyon_pick_{house['name']}"))
    kb.add(types.InlineKeyboardButton("⬅️ Uylar roʻyxati", callback_data="m_uylar"))
    kb.add(types.InlineKeyboardButton("🏠 Bosh menyu", callback_data="m_back"))
    bot.send_message(c.message.chat.id, text, parse_mode="HTML", reply_markup=kb)


def _isyon_lord_cooldown_ok(house):
    """Lordga isyon: faqat urush vaqtida, kuniga 1 marta (hududda).
    Oxirgi isyon bugun bo'lmagan bo'lsin."""
    if not is_war_time():
        return False
    last = house.get("last_lord_isyon") or 0
    if not last:
        return True
    now_utc = datetime.datetime.now(datetime.timezone.utc).replace(tzinfo=None)
    now_local = now_utc + datetime.timedelta(hours=WAR_TIMEZONE_OFFSET)
    last_dt = (datetime.datetime.utcfromtimestamp(last)
               + datetime.timedelta(hours=WAR_TIMEZONE_OFFSET))
    return last_dt.date() < now_local.date()


def _isyon_king_cooldown_ok(house):
    """Qirolga isyon: faqat urush vaqtida."""
    return is_war_time()


@bot.callback_query_handler(func=lambda c: c.data == "m_isyon_menu")
def cb_isyon_menu(c):
    """Isyon ko'tarish — Janglar menyusidan to'g'ridan-to'g'ri, uy sahifasiga
    kirib o'tirmasdan. O'z hudud lordi va/yoki qiroliga qarshi isyon
    tugmalarini bittada ko'rsatadi (isyon_do_ ga tegishli parametr bilan
    yo'naltiradi — cb_isyon_pick bilan bir xil qoidalar)."""
    uid = c.from_user.id
    my_house = get_house_by_owner(uid)
    if not my_house:
        bot.answer_callback_query(c.id, "Sizda uy yoʻq.", show_alert=True)
        return
    if get_active_war_for_house(my_house["name"]):
        bot.answer_callback_query(c.id, "Sizda hali tugamagan urush bor!", show_alert=True)
        return
    region_lord_name = get_region_lord(my_house["region"])
    king_name = get_king()
    is_lord_rebel = (bool(region_lord_name) and region_lord_name != my_house["name"]
                     and _isyon_lord_cooldown_ok(my_house))
    is_king_rebel = (bool(king_name) and king_name != my_house["name"]
                     and _isyon_king_cooldown_ok(my_house))
    if not is_lord_rebel and not is_king_rebel:
        reasons = []
        if bool(region_lord_name) and region_lord_name != my_house["name"] and not _isyon_lord_cooldown_ok(my_house):
            reasons.append("Lordga isyon: faqat urush vaqtida (Chorshanba/Juma/Yakshanba 19:00–21:30), kuniga 1 marta.")
        if bool(king_name) and king_name != my_house["name"] and not _isyon_king_cooldown_ok(my_house):
            reasons.append("Qirolga isyon: faqat urush vaqtida (Chorshanba/Juma/Yakshanba 19:00–21:30).")
        if not reasons:
            reasons.append("Ustingizda hudud lordi ham, qirol ham yoʻq.")
        bot.answer_callback_query(c.id, " | ".join(reasons), show_alert=True)
        return
    kb_i = types.InlineKeyboardMarkup(row_width=1)
    if is_lord_rebel:
        kb_i.add(types.InlineKeyboardButton(
            f"🏛️ Hudud lordi {region_lord_name} ga isyon",
            callback_data=f"isyon_do_{region_lord_name}_lord"))
    if is_king_rebel:
        kb_i.add(types.InlineKeyboardButton(
            f"👑 Qirol {king_name} ga isyon",
            callback_data=f"isyon_do_{king_name}_king"))
    kb_i.add(types.InlineKeyboardButton("❌ Bekor", callback_data="m_jang_menu"))
    bot.answer_callback_query(c.id)
    lord_note = "Lordga isyon: faqat urush vaqtida, kuniga 1 marta.\n" if is_lord_rebel else ""
    king_note = "Qirolga isyon: faqat urush vaqtida.\n" if is_king_rebel else ""
    bot.send_message(c.message.chat.id,
        f"⚔️ <b>Isyon ko'tarish</b>\n\n"
        f"Kimga qarshi isyon ko'tarmoqchisiz?\n\n"
        f"ℹ️ {lord_note}{king_note}"
        f"⚠️ Isyon vaqtida <b>bayroqdorlarni chaqirish TAQIQLANGAN</b>.\n"
        f"Isyon — oddiy quruqlik urushi: qo'shinlaringizni yuboring.",
        reply_markup=kb_i, parse_mode="HTML")


@bot.callback_query_handler(func=lambda c: c.data.startswith("isyon_pick_"))
def cb_isyon_pick(c):
    """Isyon so'rovi: faqat o'z hudud lordi yoki qirolga, urush vaqtida."""
