@bot.callback_query_handler(func=lambda c: c.data.startswith("tradepick_"))
def cb_tradepick(c):
    target_name = c.data[len("tradepick_"):]
    target = get_house(target_name)
    house = get_house_by_owner(c.from_user.id)
    # Endi BARCHA Essos shaharlari bilan savdo qilish mumkin (Westeros ↔ Essos
    # va Essos ↔ Essos) — savdo taklif-asosida ishlaydi, oʻzi qabul qilsagina
    # amalga oshadi.
    if not target:
        bot.answer_callback_query(c.id, "Topilmadi.", show_alert=True)
        return
    trade_session.setdefault(c.from_user.id, {})["target"] = target_name
    kb = types.InlineKeyboardMarkup(row_width=2)
    is_essos_target = bool(target.get("is_essos"))
    btns = []
    for r in BUY_PRICES.keys():
        if is_essos_target:
            # Essos shahridan sotib olish: uning omborida bor BARCHA resurslar
            # (jumladan yuzsiz qotil, qizil jodugar, zahar, ziddizahar, benuqson va h.k.)
            stock = target.get(r, 0) or 0
            if stock <= 0:
                continue
            btns.append(types.InlineKeyboardButton(
                f"{RESOURCE_EMOJI.get(r,'')} {RESOURCE_LABEL.get(r,r)} ({BUY_PRICES[r]} tanga/dona) — {target_name}da: {stock}",
                callback_data=f"traderes_{r}"))
        else:
            # Oddiy Westeros savdosi: bank-excluded resurslar sotilmaydi
            if r not in BANK_EXCLUDED_RESOURCES:
                btns.append(types.InlineKeyboardButton(
                    f"{RESOURCE_EMOJI.get(r,'')} {RESOURCE_LABEL.get(r,r)} ({BUY_PRICES[r]} tanga/dona)",
                    callback_data=f"traderes_{r}"))
    kb.add(*btns)
    kb.add(types.InlineKeyboardButton("⬅️ Bosh menyu", callback_data="m_back"))
    if is_essos_target:
        bot.send_message(c.message.chat.id,
            f"🌊 <b>{target_name} savdosi</b>\n{target_name} dan qaysi resursni soʻraysiz? "
            f"(Taklif {target_name} egasiga yuboriladi — u qabul qilishi kerak.)",
            reply_markup=kb, parse_mode="HTML")
    else:
        bot.send_message(c.message.chat.id, f"<b>{target_name}</b> dan qaysi resursni soʻraysiz?", reply_markup=kb)
    bot.answer_callback_query(c.id)


