def _braavos_auto_sell(offer_id):
    """Braavos (Temir bank) ga yuborilgan savdo taklifini darhol, egasining
    tasdig'isiz bajaradi. Qaytaradi: (ok, sabab_matni_yoki_None)."""
    conn = db()
    offer = conn.execute("SELECT * FROM trade_offers WHERE id=?", (offer_id,)).fetchone()
    if not offer or offer["status"] != "pending" or offer["to_house"] != IRON_BANK_HOUSE:
        conn.close()
        return False, "Taklif topilmadi."
    resource, amount, cost = offer["resource"], offer["amount"], offer["tanga_cost"]
    if resource not in BUY_PRICES:
        conn.execute("UPDATE trade_offers SET status='declined' WHERE id=?", (offer_id,))
        conn.commit()
        conn.close()
        return False, "Noma'lum resurs."
    buyer = offer["from_house"]
    # 1) xaridor tangasini atomik yechamiz
    cur = conn.execute("UPDATE houses SET tanga = tanga - ? WHERE name=? AND tanga >= ?",
                       (cost, buyer, cost))
    if cur.rowcount == 0:
        conn.execute("UPDATE trade_offers SET status='declined' WHERE id=?", (offer_id,))
        conn.commit()
        conn.close()
        return False, "Yetarli tanga yo'q."
    # 2) Braavos zaxirasidan atomik yechamiz
    cur = conn.execute(f"UPDATE houses SET {resource} = {resource} - ? WHERE name=? AND {resource} >= ?",
                       (amount, IRON_BANK_HOUSE, amount))
    if cur.rowcount == 0:
        conn.execute("UPDATE houses SET tanga = tanga + ? WHERE name=?", (cost, buyer))  # qaytarish
        conn.execute("UPDATE trade_offers SET status='declined' WHERE id=?", (offer_id,))
        conn.commit()
        conn.close()
        _house_cache_invalidate(name=buyer)
        return False, "Braavosda yetarli resurs qolmadi."
    conn.execute("UPDATE houses SET tanga = tanga + ? WHERE name=?", (cost, IRON_BANK_HOUSE))
    conn.execute(f"UPDATE houses SET {resource} = {resource} + ? WHERE name=?", (amount, buyer))
    conn.execute("UPDATE trade_offers SET status='accepted' WHERE id=?", (offer_id,))
    conn.commit()
    owner_row = conn.execute("SELECT owner_id FROM houses WHERE name=?", (IRON_BANK_HOUSE,)).fetchone()
    conn.close()
    _house_cache_invalidate(name=buyer)
    _house_cache_invalidate(name=IRON_BANK_HOUSE)
    if owner_row and owner_row["owner_id"]:
        try:
            bot.send_message(
                owner_row["owner_id"],
                f"🏦 <b>{buyer}</b> ga avtomatik sotildi: {amount} "
                f"{RESOURCE_EMOJI.get(resource, '')} {RESOURCE_LABEL.get(resource, resource)} "
                f"(+{cost} tanga).", parse_mode="HTML")
        except Exception as _e:
            _swallow(_e)
    return True, None


def process_trade_amount(m):
    uid = m.from_user.id
    sess = trade_session.get(uid)
    if not sess or "target" not in sess or "resource" not in sess:
        bot.reply_to(m, "Savdo jarayoni bekor qilingan. Qaytadan boshlang.", reply_markup=main_menu(uid))
        return
    try:
        amount = int((m.text or "").strip())
        if amount <= 0:
            raise ValueError
    except ValueError:
        bot.reply_to(m, "Musbat butun son kiriting.")
        return
    house = get_house_by_owner(uid)
    if not house:
        bot.reply_to(m, "Sizda uy yoʻq.")
        return
    resource = sess["resource"]
    target_name = sess["target"]
    cost = amount * BUY_PRICES[resource]
    if house["tanga"] < cost:
        bot.reply_to(m, f"Yetarli tangangiz yoʻq. Kerak: {cost} tanga, bor: {house['tanga']} tanga.")
        clear_sessions(uid)
        return
    res_label = RESOURCE_LABEL.get(resource, resource)
    res_emoji = RESOURCE_EMOJI.get(resource, "")

    # Essos savdosi — kema talabi va kutish vaqti yo'q (ESSOS_TRADE_REQUIRES_SHIP=False)
    _is_essos_target = target_name in ESSOS_CITIES
    _buyer_is_essos = bool(house.get("is_essos"))
    _needs_ship = False  # kema talabi olib tashlandi

    # Nishonning hozirgi zaxirasini tekshiramiz (yakuniy tekshiruv qabul
    # qilinganda яна amalga oshiriladi, chunki zaxira shu orada oʻzgarishi mumkin)
    target_house = get_house(target_name)
    target_stock = (target_house.get(resource, 0) or 0) if target_house else 0
    if target_stock < amount:
        bot.reply_to(m,
            f"❌ <b>{target_name}</b>da yetarli {res_label} yoʻq.\n"
            f"Mavjud: {target_stock} ta, Soʻralgan: {amount} ta.",
            parse_mode="HTML")
        clear_sessions(uid)
        return

    # ── SAVDO TAKLIFI: taklif yuboriladi, nishon oila (yoki Essos shahri)
    #    egasi qabul qilsagina amalga oshadi. Rad etsa yoki eʼtiborsiz
    #    qoldirsa — hech narsa sotilmaydi. ─────────────────────────────────
    conn = db()
    conn.execute("""INSERT INTO trade_offers
        (from_house, to_house, resource, amount, tanga_cost, status, created_at, needs_ship)
        VALUES (?,?,?,?,?,'pending',?,?)""",
        (house["name"], target_name, resource, amount, cost, time.time(), 1 if _needs_ship else 0))
    offer_id = conn.execute("SELECT last_insert_rowid() AS id").fetchone()["id"]
    conn.commit()
    target_row = conn.execute("SELECT owner_id FROM houses WHERE name=?", (target_name,)).fetchone()
    conn.close()
    clear_sessions(uid)
    # Braavos (Temir bank) takliflarni avtomatik qabul qiladi
    if target_name == IRON_BANK_HOUSE:
        ok, why = _braavos_auto_sell(offer_id)
        if ok:
            bot.reply_to(m, f"✅ <b>{target_name}</b> savdoni avtomatik qabul qildi: "
                             f"{amount} {res_emoji} {res_label} xazinangizga tushdi, "
                             f"{cost} tanga to'landi.",
                         reply_markup=main_menu(uid), parse_mode="HTML")
        else:
            bot.reply_to(m, f"❌ Savdo amalga oshmadi: {why}", reply_markup=main_menu(uid))
        return
    bot.reply_to(m, f"✅ Taklif yuborildi: <b>{target_name}</b> dan {amount} {res_label} "
                     f"({cost} tanga evaziga). Javobni kuting.", reply_markup=main_menu(uid),
                 parse_mode="HTML")
    if target_row and target_row["owner_id"]:
        kb = types.InlineKeyboardMarkup(row_width=2)
        kb.add(types.InlineKeyboardButton("✅ Qabul qilish", callback_data=f"trade_accept_{offer_id}"),
               types.InlineKeyboardButton("❌ Rad etish", callback_data=f"trade_decline_{offer_id}"))
        notif_text = (f"📦 <b>{house['name']}</b> sizdan {amount} {res_emoji} {res_label} soʻramoqda "
                      f"({cost} tanga toʻlaydi). Sotasizmi?")
        try:
            bot.send_message(target_row["owner_id"], notif_text, reply_markup=kb, parse_mode="HTML")
        except Exception as _e:
            _swallow(_e)


def _fmt_offer(row):
    return (f"#{row['id']}: <b>{row['from_house']}</b> → <b>{row['to_house']}</b> — "
            f"{row['amount']} {RESOURCE_LABEL.get(row['resource'], row['resource'])} "
            f"({row['tanga_cost']} tanga) [{row['status']}]")


