@bot.callback_query_handler(func=lambda c: c.data.startswith("allyaccept_"))
def cb_allyaccept(c):
    from_name = c.data[len("allyaccept_"):]
    house = get_house_by_owner(c.from_user.id)
    if not house:
        bot.answer_callback_query(c.id, "Sizda uy yoʻq.", show_alert=True)
        return
    # --- HAR BIR OILA FAQAT BITTA OILA BILAN ITTIFOQDA BO'LADI ---
    if house["alliance_with"]:
        bot.answer_callback_query(c.id,
            f"Sizda allaqachon ittifoq bor ({house['alliance_with']}). Avval uni bekor qiling.",
            show_alert=True)
        return
    wait_days = get_divorce_wait_days(house)
    if wait_days > 0:
        bot.answer_callback_query(c.id,
            f"Kechirasiz, oldingi ittifoqingizni buzganingiz uchun yana {wait_days} kun yangi ittifoq tuza olmaysiz.",
            show_alert=True)
        return
    from_house = get_house(from_name)
    if not from_house:
        bot.answer_callback_query(c.id, "Bunday uy topilmadi.", show_alert=True)
        return
    from_wait_days = get_divorce_wait_days(from_house)
    if from_wait_days > 0:
        bot.answer_callback_query(c.id,
            f"{from_name} yaqinda ittifoqni buzgan va yana {from_wait_days} kun yangi ittifoq tuza olmaydi.",
            show_alert=True)
        return
    if from_house["alliance_with"]:
        bot.answer_callback_query(c.id,
            f"{from_name} allaqachon boshqa oila ({from_house['alliance_with']}) bilan ittifoqda — taklif eskirgan.",
            show_alert=True)
        conn = db()
        conn.execute("DELETE FROM pending_alliance WHERE from_house=? AND to_house=?", (from_name, house["name"]))
        conn.commit()
        conn.close()
        return
    conn = db()
    row = conn.execute("SELECT * FROM pending_alliance WHERE from_house=? AND to_house=?",
                        (from_name, house["name"])).fetchone()
    if not row:
        conn.close()
        bot.answer_callback_query(c.id, "Bunday taklif topilmadi (eskirgan boʻlishi mumkin).", show_alert=True)
        return
    until = time.time() + 30 * 24 * 3600
    conn.execute("UPDATE houses SET alliance_with=?, alliance_until=? WHERE name=?", (from_name, until, house["name"]))
    conn.execute("UPDATE houses SET alliance_with=?, alliance_until=? WHERE name=?", (house["name"], until, from_name))
    # Har ikkala tomonning boshqa BARCHA kutayotgan ittifoq takliflari (yuborgan
    # ham, kelgan ham) endi eskirgan hisoblanadi — bitta oila faqat bitta
    # ittifoqda boʻlishi mumkin.
    conn.execute("DELETE FROM pending_alliance WHERE from_house IN (?,?) OR to_house IN (?,?)",
                 (from_name, house["name"], from_name, house["name"]))
    conn.commit()
    conn.close()
    bot.answer_callback_query(c.id, "Ittifoq tuzildi!")
    bot.send_message(c.message.chat.id,
        f"🤝 Ittifoq tuzildi: <b>{from_name}</b> ↔ <b>{house['name']}</b> (30 kun).",
        reply_markup=main_menu(c.from_user.id))
    if from_house["owner_id"]:
        notify(from_house["owner_id"],
               f"🤝 <b>{house['name']}</b> ittifoq taklifingizni qabul qildi! Ittifoq 30 kun davom etadi.")
    # Syujet kanaliga QISQA ittifoq eloni — katta va'zsiz, faqat lo'nda xabar.
    try:
        post_to_channel(ittifoq_announcement(from_name, house["name"]))
    except Exception as e:
        print("ittifoq elonida xatolik:", e)


