# ---------------------------------------------------------------------------
# QIZIL TOʻY — himoya chorasi yoʻq xiyonat hodisasi. Faqat ittifoqdoshga
# qarshi, va faqat ittifoq rasman tuzilgandan keyingi 24 SOAT ICHIDA
# amalga oshirilishi mumkin (keyin bu imkoniyat yopiladi).
# ---------------------------------------------------------------------------

def _rw_deadline(house_row):
    """Qizil toʻy uchun ruxsat etilgan oxirgi vaqt (unix timestamp) ni
    qaytaradi, yoki ittifoq muddati saqlanmagan boʻlsa None. Ittifoq 30
    kunlik boʻlib (alliance_until = boshlanish + 30 kun) qayd etilgani
    uchun, 24 soatlik oyna oxiri = alliance_until - 29 kun."""
    until = (house_row["alliance_until"] or 0) if house_row else 0
    if not until:
        return None
    return until - 29 * 24 * 3600


@bot.callback_query_handler(func=lambda c: c.data == "rw_confirm")
def cb_rw_confirm(c):
    house = get_house_by_owner(c.from_user.id)
    if not house or not house["alliance_with"]:
        bot.answer_callback_query(c.id, "Sizda ittifoqdoshingiz yoʻq.", show_alert=True)
        return
    if house["tanga"] < 1000:
        bot.answer_callback_query(c.id, "Qizil toʻy uchun 1000 tanga kerak.", show_alert=True)
        return
    deadline = _rw_deadline(house)
    if deadline is not None and time.time() > deadline:
        bot.answer_callback_query(c.id,
            "Qizil toʻy faqat ittifoq tuzilgandan keyingi 24 soat ichida amalga oshirilishi mumkin. "
            "Bu muddat allaqachon oʻtib ketgan.", show_alert=True)
        return
    kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton(f"🩸 Ha, {house['alliance_with']} ga qizil toʻy!", callback_data=f"rw_go_{house['alliance_with']}"))
    kb.add(types.InlineKeyboardButton("⬅️ Bekor qilish", callback_data="m_back"))
    bot.send_message(c.message.chat.id,
        "1000 tanga evaziga ittifoqdoshingizga qizil toʻy uyushtirasizmi?\n\n"
        "⚠️ Bundan himoya chorasi yoʻq — qaror qabul qilinsa, ortga qaytarib boʻlmaydi.",
        reply_markup=kb)
    bot.answer_callback_query(c.id)


@bot.callback_query_handler(func=lambda c: c.data.startswith("rw_go_"))
def cb_rw_go(c):
    target_name = c.data[len("rw_go_"):]
    house = get_house_by_owner(c.from_user.id)
    if not house or house["alliance_with"] != target_name:
        bot.answer_callback_query(c.id, "Qizil toʻy faqat ittifoqdoshingizga qarshi.", show_alert=True)
        return
    if house["tanga"] < 1000:
        bot.answer_callback_query(c.id, "1000 tanga kerak.", show_alert=True)
        return
    deadline = _rw_deadline(house)
    if deadline is not None and time.time() > deadline:
        bot.answer_callback_query(c.id,
            "Qizil toʻy faqat ittifoq tuzilgandan keyingi 24 soat ichida amalga oshirilishi mumkin. "
            "Bu muddat allaqachon oʻtib ketgan.", show_alert=True)
        return
    target = get_house(target_name)
    if not target:
        bot.answer_callback_query(c.id, "Topilmadi.", show_alert=True)
        return

    conn = db()
    # Xoin oila 1000 tangasidan voz kechadi (bu tanga hech kimga oʻtmaydi —
    # shunchaki sarflanadi).
    conn.execute("UPDATE houses SET tanga = tanga - 1000 WHERE name=?", (house["name"],))

    is_royal = (get_king() == target_name)
    left_game = False
    new_tier = target["tier"]

    if is_royal:
        # QIROLLIK OILASI QIZIL TOʻYGA UCHRASA: taxtdan darhol ag'daraladi,
        # daraja (tier)idan qat'iy nazar B TOIFAGA tushadi, va TEMIR TAXT
        # BOʻSHAB QOLADI — yangi qirol uchun kurash/saylov boshlanadi.
        new_tier = "B"
        conn.execute("UPDATE world SET value='' WHERE key='king'")
    else:
        if target["tier"] == "A":
            new_tier = "B"
        elif target["tier"] == "B":
            new_tier = "C"
        else:
            left_game = True

    # Zahar/ziddizahar zaxiralari qo'riqchisiz qoladi va XOINGA o'tadi
    # (avval hujumchining qo'liga, keyin qurbonnikini nolga tushiramiz).
    t_zahar = target["zahar"] or 0
    t_ziddizahar = target["ziddizahar"] or 0
    if t_zahar or t_ziddizahar:
        conn.execute("UPDATE houses SET zahar = zahar + ?, ziddizahar = ziddizahar + ? WHERE name=?",
                     (t_zahar, t_ziddizahar, house["name"]))
    # Eslatma: bu build'da devor buzuvchi qamal inshootlari (mamont va h.k.)
    # alohida resurs sifatida mavjud emas, shuning uchun ular bo'yicha
    # o'tkazma qo'llanilmaydi. Xuddi shunday, yuzsiz qotil yollash uchun
    # oldindan to'lovli navbat/ariza tizimi ham mavjud emas (Bravos savdosi
    # darhol amalga oshadi) — bekor qilinadigan kutilayotgan ariza yo'q.

    if is_royal:
        conn.execute("""UPDATE houses SET tier=?, tanga=0, qoshin=0, kamonchi=0, otliq=0, kema=0,
                        benuqson=0, kenja_ogil=0, valyria_polati=0, ritsarlik=0, siyosat=0,
                        qizil_jodugar=0, zahar=0, ziddizahar=0, alliance_with='' WHERE name=?""",
                     (new_tier, target_name))
    elif left_game:
        conn.execute("""UPDATE houses SET owner_id=NULL, tanga=0, qoshin=0, kamonchi=0, otliq=0,
                        kema=0, benuqson=0, kenja_ogil=0, valyria_polati=0, ritsarlik=0, siyosat=0,
                        qizil_jodugar=0, zahar=0, ziddizahar=0,
                        alliance_with='', vassal_of='' WHERE name=?""", (target_name,))
    else:
        conn.execute("""UPDATE houses SET tier=?, tanga=MAX(tanga-500,0), ritsarlik=0, siyosat=0,
                        qizil_jodugar=0, zahar=0, ziddizahar=0,
                        alliance_with='' WHERE name=?""", (new_tier, target_name))
    conn.execute("UPDATE houses SET alliance_with='' WHERE name=?", (house["name"],))
    conn.commit()
    conn.close()

    if is_royal:
        result = "taxtdan agʻdarildi va B toifaga tushirildi"
    elif left_game:
        result = "va oʻyindan chiqarildi 💀"
    else:
        result = f"va {new_tier} toifaga tushirildi"

    bot.answer_callback_query(c.id, "Qizil toʻy amalga oshirildi.")
    bot.send_message(c.message.chat.id, f"🩸 Qizil toʻy! <b>{target_name}</b> {result}.",
                      reply_markup=main_menu(c.from_user.id))
    if target["owner_id"]:
        try:
            bot.send_message(target["owner_id"],
                f"🩸 Sizga <b>{house['name']}</b> QIZIL TOʻY uyushtirdi! Ritsarlik va siyosat "
                f"ballaringiz nolga tushdi, qizil jodugarlaringiz halok boʻldi, zahar/ziddizahar "
                f"zaxiralaringiz <b>{house['name']}</b> qoʻliga oʻtdi.")
        except Exception as _e:
            _swallow(_e)
    try:
        post_to_channel(
            f"🩸 <b>QIZIL TOʻY!</b> {lord_full_name(house['name'])} oʻz ittifoqdoshi "
            f"<b>{target_name}</b> ga xiyonat qildi — {target_name} {result}."
        )
    except Exception as e:
        print("qizil to'y elonida xatolik:", e)
    if is_royal:
        try:
            post_to_channel(
                "👑 <b>TEMIR TAXT BOʻSH QOLDI!</b> Qirollik sulolasi qizil toʻyga uchradi. "
                "Yangi qirol uchun kurash boshlandi."
            )
        except Exception as e:
            print("taxt bo'shashi elonida xatolik:", e)


