@bot.callback_query_handler(func=lambda c: c.data.startswith("cancelatk_yes_"))
def cb_cancelatk_yes(c):
    uid = c.from_user.id
    attack_id = int(c.data[len("cancelatk_yes_"):])
    attack = get_pending_attack(attack_id)
    house = get_house_by_owner(uid)
    if not attack or attack["status"] != "pending" or not house:
        bot.answer_callback_query(c.id, "Bu hujum allaqachon tugagan.", show_alert=True)
        return
    if house["name"] != attack["attacker"]:
        bot.answer_callback_query(c.id, "Faqat hujumni e'lon qilgan tomon uni bekor qila oladi.", show_alert=True)
        return
    with _lock:
        conn = db()
        atk_row = conn.execute("SELECT * FROM pending_attacks WHERE id=?", (attack_id,)).fetchone()
        if not atk_row or atk_row["status"] != "pending":
            conn.close()
            bot.answer_callback_query(c.id, "Bu hujum allaqachon tugagan.", show_alert=True)
            return
        refunded_houses = _refund_cancelled_attack(conn, atk_row)
        conn.execute("UPDATE pending_attacks SET status='cancelled', resolved_at=? WHERE id=?",
                     (time.time(), attack_id))
        conn.commit()
        conn.close()
    bot.answer_callback_query(c.id, "Hujum bekor qilindi.")
    bot.send_message(c.message.chat.id,
        f"❌ <b>#{attack_id}: {attack['defender']} ga hujum bekor qilindi.</b> "
        f"Qo'shinlaringiz joyida qoldi.", reply_markup=main_menu(uid))
