def process_warship_manual(m):
    uid = m.from_user.id
    sess = war_session.get(uid)
    if not sess:
        bot.reply_to(m, "Jang jarayoni topilmadi, qaytadan boshlang.", reply_markup=main_menu(uid))
        return
    attacker = get_house_by_owner(uid)
    try:
        amount = int((m.text or "").strip())
    except ValueError:
        bot.reply_to(m, "Butun son kiriting.")
        return
    if amount < 0 or amount > attacker["kema"]:
        bot.reply_to(m, f"0 dan {attacker['kema']} gacha son kiriting.")
        return
    start_naval_troop_selection(m.chat.id, uid, amount)


def start_naval_troop_selection(chat_id, uid, ship_count):
    sess = war_session.get(uid)
    if not sess:
        return
    attacker = get_house_by_owner(uid)
    sess["kema_count"] = ship_count
    sess["capacity_left"] = naval_capacity(ship_count)
    if ship_count == 0 or sess["capacity_left"] <= 0:
        bot.send_message(chat_id, "0 ta kema bilan hujum qilib boʻlmaydi. Hujum bekor qilindi.",
                          reply_markup=main_menu(uid))
        war_session.pop(uid, None)
        return
    queue = [u for u in COMBAT_UNITS if attacker[u] > 0]
    if not queue:
        bot.send_message(chat_id, "Sizda kemalarga chiqaradigan askar yoʻq — askar boʻlmasa kema hujum "
                                   "qila olmaydi. Hujum bekor qilindi.", reply_markup=main_menu(uid))
        war_session.pop(uid, None)
        return
    sess["queue"] = queue
    send_pct_prompt(chat_id, "warpct_", "warmanual_", queue[0], attacker[queue[0]], cap=sess["capacity_left"])


def send_pct_prompt(chat_id, pct_prefix, manual_prefix, unit, max_amount, cap=None):
    """cap berilsa (dengizda qoldiq kema sigʻimi), tanlov shu bilan ham cheklanadi."""
    effective_max = max_amount if cap is None else max(0, min(max_amount, cap))
    kb = types.InlineKeyboardMarkup(row_width=3)
    row = [types.InlineKeyboardButton(f"{pct}% ({round(effective_max*pct/100)})",
                                       callback_data=f"{pct_prefix}{unit}_{pct}") for pct in WAR_PCT_OPTIONS]
    kb.add(*row)
    kb.add(types.InlineKeyboardButton("✍️ Qoʻlda son kiritish", callback_data=f"{manual_prefix}{unit}"))
    extra = f" (kema sigʻimidan qoldi: {cap})" if cap is not None else ""
    bot.send_message(chat_id, f"{RESOURCE_EMOJI.get(unit,'')} Nechta <b>{RESOURCE_LABEL.get(unit,unit)}</b> "
                               f"yuborasiz? (jamingizda: {max_amount}{extra})", reply_markup=kb)


def war_advance(chat_id, uid):
    """Navbatdagi keyingi qoʻshin turini soʻraydi yoki yakunlab tasdiqlash oynasini chiqaradi."""
    sess = war_session.get(uid)
    if not sess:
        return
    attacker = get_house_by_owner(uid)
    if sess["type"] == "dengiz":
        if sess.get("capacity_left", 0) <= 0 or not sess["queue"]:
            show_war_confirm(chat_id, uid)
            return
        nxt = sess["queue"][0]
        send_pct_prompt(chat_id, "warpct_", "warmanual_", nxt, attacker[nxt], cap=sess["capacity_left"])
        return
    if sess["queue"]:
        nxt = sess["queue"][0]
        send_pct_prompt(chat_id, "warpct_", "warmanual_", nxt, attacker[nxt])
    else:
        show_war_confirm(chat_id, uid)


def _valyria_remaining(house, session_dict):
    """Shu urush sessiyasida hozirgacha turli qoʻshin turlariga taqsimlangan
    valyria po'latini hisobga olib, qancha valyria qoldi (hali ishlatilmagan)."""
    used = sum(session_dict.get("valyria_map", {}).values())
    owned = house["valyria_polati"] if house else 0
    return max(owned - used, 0)


def maybe_ask_unit_valyria(chat_id, uid, session_dict, unit, amount, advance_fn, ask_prefix):
    """Har bir qoʻshin turi tanlangandan soʻng (masalan "210 ta otliq"), agar
    lordda ishlatilmagan valyria po'lati qolgan bo'lsa — aynan shu turga
    valyria berasizmi deb soʻraydi. Yo'q bo'lsa yoki valyria qolmagan bo'lsa,
    navbatdagi qadamga o'tadi."""
    sess = session_dict.get(uid)
    if not sess:
        return
    house = get_house_by_owner(uid)
    if sess["type"] != "quruqlik" or amount <= 0 or not house:
        advance_fn(chat_id, uid)
        return
    remaining = _valyria_remaining(house, sess)
    if remaining <= 0:
        advance_fn(chat_id, uid)
        return
    kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton(f"🔱 Ha, {RESOURCE_LABEL.get(unit,unit)}ga valeriya beraman",
                                       callback_data=f"{ask_prefix}yes_{unit}"))
    kb.add(types.InlineKeyboardButton("🚫 Yoʻq", callback_data=f"{ask_prefix}no_{unit}"))
    bot.send_message(chat_id,
        f"🔱 <b>{RESOURCE_LABEL.get(unit,unit)}</b> ({amount} ta) uchun Valyria poʻlati berasizmi? "
        f"(sizda {remaining} dona ishlatilmagan qoldi)", reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data.startswith("warvalyask_no_"))
def cb_warvalyask_no(c):
    uid = c.from_user.id
    bot.answer_callback_query(c.id, "Valeriya berilmadi.")
    war_advance(c.message.chat.id, uid)


@bot.callback_query_handler(func=lambda c: c.data.startswith("warvalyask_yes_"))
def cb_warvalyask_yes(c):
    uid = c.from_user.id
    unit = c.data[len("warvalyask_yes_"):]
    sess = war_session.get(uid)
    if not sess:
        bot.answer_callback_query(c.id, "Jang jarayoni topilmadi.", show_alert=True)
        return
    attacker = get_house_by_owner(uid)
    remaining = _valyria_remaining(attacker, sess)
    unit_count = sess["units"].get(unit, 0)
    useful_max = max(1, -(-unit_count // VALYRIA_BLOCK))
    bot.answer_callback_query(c.id)
    msg = bot.send_message(c.message.chat.id,
        f"🔱 <b>{RESOURCE_LABEL.get(unit,unit)}</b> ga nechta Valyria poʻlati berasiz? "
        f"(qoldiq: {remaining} dona; har biri {VALYRIA_BLOCK} tagacha askarni 2x kuchaytiradi — "
        f"{unit_count} ta {RESOURCE_LABEL.get(unit,unit)} uchun {useful_max} dona yetarli). Sonini yozing:")
    bot.register_next_step_handler(msg, process_warvalyask_count, unit)


def process_warvalyask_count(m, unit):
    uid = m.from_user.id
    sess = war_session.get(uid)
    if not sess:
        bot.reply_to(m, "Jang jarayoni topilmadi, qaytadan boshlang.", reply_markup=main_menu(uid))
        return
    attacker = get_house_by_owner(uid)
    remaining = _valyria_remaining(attacker, sess)
    try:
        n = int(m.text.strip())
    except ValueError:
        msg = bot.reply_to(m, "Butun son kiriting.")
        bot.register_next_step_handler(msg, process_warvalyask_count, unit)
        return
    if n < 1 or n > remaining:
        msg = bot.reply_to(m, f"1 dan {remaining} gacha son kiriting.")
        bot.register_next_step_handler(msg, process_warvalyask_count, unit)
        return
    vmap = sess.setdefault("valyria_map", {})
    vmap[unit] = vmap.get(unit, 0) + n
    bot.reply_to(m, f"✅ {RESOURCE_LABEL.get(unit,unit)} uchun {n} dona Valyria poʻlati beriladi.")
    war_advance(m.chat.id, uid)


def show_war_confirm(chat_id, uid):
    sess = war_session.get(uid)
    if not sess:
        return
    kb = types.InlineKeyboardMarkup(row_width=1)
    if sess["type"] == "dengiz":
        kema = sess.get("kema_count", 0)
        troops = {u: sess["units"].get(u, 0) for u in COMBAT_UNITS if sess["units"].get(u, 0) > 0}
        total_troops = sum(troops.values())
        if kema == 0 or total_troops == 0:
            bot.send_message(chat_id, "🚫 Askar boʻlmasa kema hujum qila olmaydi. Hujum bekor qilindi.",
                              reply_markup=main_menu(uid))
            war_session.pop(uid, None)
            return
        required = kema * SHIP_CAPACITY
        if SHIPS_REQUIRE_FULL and total_troops != required:
            bot.send_message(chat_id,
                f"🚫 {kema} ta kema toʻliq hujumga oʻtishi uchun aynan {required} ta askar kerak "
                f"(hozir {total_troops} ta tanladingiz). Kema toʻlmaguncha hujum qila olmaydi. Hujum bekor qilindi.",
                reply_markup=main_menu(uid))
            war_session.pop(uid, None)
            return
        lines = "\n".join(f"{RESOURCE_EMOJI.get(u,'')} {RESOURCE_LABEL.get(u,u)}: {n}" for u, n in troops.items())
        text = (f"🌊 <b>{sess['target']}</b> ga {kema} ta kema va quyidagi askarlar bilan hujum qilasizmi?\n{lines}")
    else:
        lines = [f"{RESOURCE_EMOJI.get(u,'')} {RESOURCE_LABEL.get(u,u)}: {sess['units'].get(u,0)}"
                 for u in COMBAT_UNITS if sess["units"].get(u, 0) > 0]
        valyria_map = sess.get("valyria_map", {})
        atk = land_power_with_valyria_map(sess["units"], "atk", valyria_map)
        if atk == 0:
            kb.add(types.InlineKeyboardButton("❌ Bekor qilish", callback_data="m_back"))
            bot.send_message(chat_id, "Hech qanday qoʻshin tanlamadingiz, hujum bekor qilindi.", reply_markup=kb)
            war_session.pop(uid, None)
            return
        if valyria_map:
            valy_parts = [f"{n} dona → {RESOURCE_LABEL.get(u,u)}" for u, n in valyria_map.items() if n]
            valy_note = f" (🔱 " + ", ".join(valy_parts) + " 2x kuchaytirilgan)"
        else:
            valy_note = ""
        text = ("🗡️ <b>" + sess["target"] + "</b> ga quyidagi kuch bilan hujum qilasizmi?\n" +
                "\n".join(lines) + f"\n\nJami hujum kuchi: {atk}{valy_note}")
    kb.add(types.InlineKeyboardButton("⚔️ Hujumni boshlash", callback_data="war_confirm"))
    kb.add(types.InlineKeyboardButton("❌ Bekor qilish", callback_data="m_back"))
    bot.send_message(chat_id, text, reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data.startswith("warpct_"))
def cb_warpct(c):
    uid = c.from_user.id
    sess = war_session.get(uid)
    if not sess:
        bot.answer_callback_query(c.id, "Jang jarayoni topilmadi, qaytadan boshlang.", show_alert=True)
        return
    _, unit, pct = c.data.split("_")
    pct = int(pct)
    attacker = get_house_by_owner(uid)
    max_amount = attacker[unit]
    if sess["type"] == "dengiz":
        max_amount = max(0, min(max_amount, sess.get("capacity_left", 0)))
    amount = round(max_amount * pct / 100)
    sess["units"][unit] = amount
    if sess["type"] == "dengiz":
        sess["capacity_left"] = sess.get("capacity_left", 0) - amount
    if sess["queue"]:
        sess["queue"].pop(0)
    bot.answer_callback_query(c.id, f"{amount} ta {RESOURCE_LABEL.get(unit,unit)} tanlandi.")
    maybe_ask_unit_valyria(c.message.chat.id, uid, war_session, unit, amount, war_advance, "warvalyask_")


