@bot.callback_query_handler(func=lambda c: c.data == "war_confirm")
def cb_war_confirm(c):
    uid = c.from_user.id
    # Pop before creating the attack so a double-click/retried callback cannot
    # create two pending attacks from one selection.
    sess = war_session.pop(uid, None)
    if not sess:
        bot.answer_callback_query(c.id, "Jang jarayoni topilmadi.", show_alert=True)
        return
    attacker = get_house_by_owner(uid)
    target = get_house(sess["target"])
    if not attacker or not target:
        bot.answer_callback_query(c.id, "Xatolik yuz berdi.", show_alert=True)
        return
    _ownerless = ownerless_attack_block_text(target)
    if _ownerless:
        bot.answer_callback_query(c.id, "Bu uyning egasi yoʻq — hujum qilib boʻlmaydi.", show_alert=True)
        bot.send_message(c.message.chat.id, _ownerless, parse_mode="HTML", reply_markup=main_menu(uid))
        return
    bot.answer_callback_query(c.id)
    units = {u: n for u, n in sess["units"].items() if n > 0}
    if sess.get("valyria_map"):
        units["_valyria_map"] = sess["valyria_map"]
    kema_count = sess.get("kema_count", 0) if sess["type"] == "dengiz" else 0
    if sess["type"] == "dengiz":
        # V4: kema/askar nisbati (1:10) QAT'IY tekshiriladi + hozirgi zaxira bilan solishtiriladi
        _fresh_ok = (attacker["kema"] >= kema_count
                     and all(attacker[u] >= units.get(u, 0) for u in COMBAT_UNITS))
        if not (SHIPS_REQUIRE_FULL and naval_ratio_ok(kema_count, units)) or not _fresh_ok:
            bot.send_message(c.message.chat.id,
                f"🚫 Dengiz hujumiga ruxsat berilmadi: {kema_count} ta kemaga aynan "
                f"{kema_count * SHIP_CAPACITY} ta askar kerak va zaxirangiz yetarli bo'lishi shart.",
                reply_markup=main_menu(uid))
            return
    if not click_guard(uid, "war_confirm", 5.0):
        return
    attack_id = create_pending_attack(sess["type"], attacker["name"], target["name"], units, kema_count,
                                       isyon=1 if sess.get("isyon") else 0,
                                       isyon_type=sess.get("isyon_type", ""))
    announce_war_declared(attacker["name"], target["name"], units)

    # --- NPC (EGASIZ) UY: sinov davrida egasi yoʻq lordliklarni NPC boshqaradi.
    # Bunday uyga hujum qilinsa, javob beradigan real odam yoʻqligi uchun
    # 15 daqiqa kutib oʻtirmay, DARHOL avtomatik (mavjud butun armiya bilan)
    # himoyalanadi va jang natijasi shu zahoti chiqadi. ---
    if not target["owner_id"]:
        if sess["type"] == "dengiz":
            _npc_ships, npc_def_units = auto_fill_naval_defense(target)
            npc_def_units = dict(npc_def_units)
            npc_def_units["kema"] = _npc_ships
        else:
            npc_def_units = auto_fill_land_defense(target)
        bot.send_message(c.message.chat.id,
            f"🤖 <b>{target['name']}</b> hozircha egasiz — NPC tomonidan boshqarilmoqda va "
            f"darhol avtomatik himoyalandi. Jang natijasi:", reply_markup=main_menu(uid))

        # --- NPC UYGA HUJUMDA HAM: vassal lord va hudud lordiga xabar boradi ---
        kind_npc = "🌊 Dengiz" if sess["type"] == "dengiz" else "🗡️ Quruqlik"
        already_notified_npc = set()
        if target["vassal_of"] and sess["type"] != "dengiz":
            npc_vassal_lord = get_house(target["vassal_of"])
            if npc_vassal_lord and npc_vassal_lord["owner_id"] and npc_vassal_lord["owner_id"] != attacker["owner_id"]:
                try:
                    bot.send_message(npc_vassal_lord["owner_id"],
                        f"🏴 <b>{attacker['name']}</b> sizning vassalingiz <b>{target['name']}</b> ga "
                        f"hujum qildi! (Uy hozircha NPC boshqaruvida, jang avtomatik hal qilindi)")
                    already_notified_npc.add(npc_vassal_lord["owner_id"])
                except Exception as _e:
                    _swallow(_e)
        if sess["type"] != "dengiz":
            npc_region_lord_name = get_region_lord(target["region"])
            if npc_region_lord_name and npc_region_lord_name != target["name"]:
                npc_region_lord = get_house(npc_region_lord_name)
                if (npc_region_lord and npc_region_lord["owner_id"]
                        and npc_region_lord["owner_id"] != attacker["owner_id"]
                        and npc_region_lord["owner_id"] not in already_notified_npc):
                    try:
                        bot.send_message(npc_region_lord["owner_id"],
                            f"🏴 <b>{attacker['name']}</b> sizning hududingizda <b>{target['name']}</b> ga "
                            f"hujum qildi! (Uy hozircha NPC boshqaruvida, jang avtomatik hal qilindi)")
                    except Exception as _e:
                        _swallow(_e)

        resolve_pending_attack(attack_id, npc_def_units)
        return

    minutes = DEFENSE_WINDOW_SECONDS // 60
    bot.send_message(c.message.chat.id,
        f"⚔️ Hujum <b>{target['name']}</b> ga yuborildi! Himoyachiga javob berish uchun {minutes} daqiqa "
        f"vaqt berildi. Javob bermasa, avtomatik himoya ishga tushadi.", reply_markup=main_menu(uid))

    kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton("🛡️ Himoyalanish", callback_data=f"def_start_{attack_id}"))
    kind = "🌊 Dengiz" if sess["type"] == "dengiz" else "🗡️ Quruqlik"
    if target["owner_id"]:
        try:
            bot.send_message(target["owner_id"],
                f"🚨 <b>{attacker['name']}</b> sizga {kind.lower()} hujumi bilan hujum qildi!\n"
                f"{minutes} daqiqa ichida himoyangizni tanlang, aks holda avtomatik himoya ishga tushadi.",
                reply_markup=kb)
        except Exception as _e:
            _swallow(_e)

    # --- ITTIFOQCHIGA XABAR: hujum boshlanganda hujumchining ittifoqchisi
    #     darhol xabardor qilinadi va hujumga yordam berish-bermasligini
    #     soʻraydi ---
    if attacker["alliance_with"]:
        ally = get_house(attacker["alliance_with"])
        if ally and ally["owner_id"]:
            kb2 = types.InlineKeyboardMarkup()
            kb2.add(types.InlineKeyboardButton("🤝 Ha, yordam beraman", callback_data=f"ally_help_yes_{attack_id}"))
            kb2.add(types.InlineKeyboardButton("🚫 Yoʻq", callback_data=f"ally_help_no_{attack_id}"))
            try:
                bot.send_message(ally["owner_id"],
                    f"📯 Ittifoqchingiz <b>{attacker['name']}</b> <b>{target['name']}</b> ga {kind.lower()} "
                    f"hujumi bilan hujum qildi. Hujumga yordam berasizmi?", reply_markup=kb2)
            except Exception as _e:
                _swallow(_e)

    # --- ITTIFOQCHIGA XABAR: himoyachining ittifoqdoshi ham darhol xabardor
    #     qilinadi va himoyaga yordam berish-bermasligini soʻraydi (masalan
    #     Frey Starkka hujum qilsa, Starkning ittifoqdoshi Tully Starkka
    #     himoyada yordam bera oladi) — faqat quruqlik jangida ---
    if target["alliance_with"] and sess["type"] != "dengiz":
        def_ally = get_house(target["alliance_with"])
        if def_ally and def_ally["owner_id"]:
            kb3 = types.InlineKeyboardMarkup()
            kb3.add(types.InlineKeyboardButton("🛡️ Ha, himoyaga yordam beraman", callback_data=f"defhelp_yes_{attack_id}"))
            kb3.add(types.InlineKeyboardButton("🚫 Yoʻq", callback_data=f"defhelp_no_{attack_id}"))
            try:
                bot.send_message(def_ally["owner_id"],
                    f"📯 Ittifoqchingiz <b>{target['name']}</b> ga <b>{attacker['name']}</b> tomonidan "
                    f"{kind.lower()} hujumi bilan hujum qilindi. Himoyasiga yordam berasizmi?", reply_markup=kb3)
            except Exception as _e:
                _swallow(_e)

    # --- HUDUD LORDI XABARDOR QILISH: agar hujumga uchragan uy kimningdir vassali
    #     bo'lsa, o'sha lord xabardor qilinadi va bayroqdor (bannerlord) sifatida
    #     himoyaga quruqlik qo'shini yuborishi mumkin (faqat quruqlik jangida).
    #     TUZATISH: oldin "elif" ishlatilgani uchun vassal bo'lmagan uylar uchun
    #     hudud lordi HECH QACHON xabardor bo'lmas edi. Endi ikkalasi ham
    #     alohida-alohida tekshiriladi — vassal lord VA hudud lordi har biri
    #     o'z holatida xabardor bo'ladi. ---
    already_notified_lords = set()  # bir lordga ikki marta xabar bormasligi uchun
    if target["vassal_of"] and sess["type"] != "dengiz":
        region_lord_house = get_house(target["vassal_of"])
        if region_lord_house and region_lord_house["owner_id"] and region_lord_house["owner_id"] != attacker["owner_id"]:
            kb_lord = types.InlineKeyboardMarkup()
            kb_lord.add(types.InlineKeyboardButton("🏴 Ha, bayroqdor chaqiraman (qoʻshin yuboring)",
                                                    callback_data=f"bannerlord_yes_{attack_id}"))
            kb_lord.add(types.InlineKeyboardButton("🚫 Yoʻq, yordam bermayman",
                                                    callback_data=f"bannerlord_no_{attack_id}"))
            try:
                bot.send_message(region_lord_house["owner_id"],
                    f"🏴 <b>{attacker['name']}</b> sizning vassalingiz <b>{target['name']}</b> ga "
                    f"hujum qildi! Bayroqdor chaqirib himoyaga qoʻshin yuborasizmi?\n"
                    f"(Quruqlik qoʻshinlaringizdan xohlagan miqdorini yuborishingiz mumkin)",
                    reply_markup=kb_lord)
                already_notified_lords.add(region_lord_house["owner_id"])
            except Exception as _e:
                _swallow(_e)
    # --- HUDUD LORDI XABARDOR QILISH: hududdagi har qanday uyga hujum bo'lsa,
    #     shu hududning lordi (vassal lord bilan bir xil bo'lmasa) ham xabardor
    #     qilinadi. Masalan Reedga hujum bo'lsa — Stark (Shimol lordi) ham xabar oladi. ---
    if sess["type"] != "dengiz":
        region_lord_name = get_region_lord(target["region"])
        if region_lord_name and region_lord_name != target["name"]:
            region_lord_house = get_house(region_lord_name)
            if (region_lord_house and region_lord_house["owner_id"]
                    and region_lord_house["owner_id"] != attacker["owner_id"]
                    and region_lord_house["owner_id"] not in already_notified_lords):
                kb_lord = types.InlineKeyboardMarkup()
                kb_lord.add(types.InlineKeyboardButton("🏴 Ha, bayroqdor chaqiraman (qoʻshin yuboring)",
                                                        callback_data=f"bannerlord_yes_{attack_id}"))
                kb_lord.add(types.InlineKeyboardButton("🚫 Yoʻq, yordam bermayman",
                                                        callback_data=f"bannerlord_no_{attack_id}"))
                try:
                    bot.send_message(region_lord_house["owner_id"],
                        f"🏴 <b>{attacker['name']}</b> sizning hududingizda <b>{target['name']}</b> ga "
                        f"hujum qildi! Bayroqdor chaqirib himoyaga qoʻshin yuborasizmi?\n"
                        f"(Quruqlik qoʻshinlaringizdan xohlagan miqdorini yuborishingiz mumkin)",
                        reply_markup=kb_lord)
                except Exception as _e:
                    _swallow(_e)

    # --- TAXTGA QARSHI URUSH: agar hujumga uchragan uy HOZIRGI QIROL boʻlsa,
    #     BUTUN DUNYODAGI barcha oilalarga xabar boradi ("... Targaryenga hujum
    #     qildi" yoki, agar hujumchi qirolning vassali boʻlsa yoki bu ISYON
    #     tugmasi orqali boshlangan boʻlsa, "... Targaryenga isyon qildi") va
    #     "yordam berasizmi?" deb soʻraladi (tugmalarda ikkala tomonning
    #     haqiqiy uy nomi koʻrsatiladi). Bu yagona holat — ittifoqchi boʻlmasa
    #     ham hujumchi tomonga qoʻshin yuborish mumkin, chunki bu shaxsiy
    #     urush emas, taxt uchun umumiy kurash. ---
    current_king = get_king()
    is_isyon_war = bool(sess.get("isyon"))
    if current_king and target["name"] == current_king and sess["type"] != "dengiz":
        is_rebellion = is_isyon_war or (bool(attacker["vassal_of"]) and attacker["vassal_of"] == target["name"])
        if is_rebellion:
            crown_text = (f"👑 <b>{attacker['name']}</b> oʻz qiroli <b>{target['name']}</b> ga qarshi "
                          f"ISYON KOʻTARDI! Yordam berasizmi?")
        else:
            crown_text = (f"👑 <b>{attacker['name']}</b> qirol <b>{target['name']}</b> ga hujum qildi! "
                          f"Yordam berasizmi?")
        conn_ck = db()
        all_houses = conn_ck.execute(
            "SELECT name, owner_id FROM houses WHERE is_essos=0").fetchall()
        conn_ck.close()
        for hh in all_houses:
            if hh["name"] in (attacker["name"], target["name"]) or not hh["owner_id"]:
                continue
            kb_crown = types.InlineKeyboardMarkup(row_width=1)
            kb_crown.add(types.InlineKeyboardButton(f"🗡️ {attacker['name']} ga yordam beraman",
                                                      callback_data=f"crownhelp_yes_{attack_id}"))
            kb_crown.add(types.InlineKeyboardButton(f"👑 {target['name']} ga yordam beraman",
                                                      callback_data=f"crownhelp_king_{attack_id}"))
            kb_crown.add(types.InlineKeyboardButton("🚫 Yoʻq", callback_data=f"crownhelp_no_{attack_id}"))
            try:
                bot.send_message(hh["owner_id"], crown_text, reply_markup=kb_crown)
            except Exception as _e:
                _swallow(_e)

    # --- HUDUD LORDIGA ISYON: agar bu ISYON tugmasi orqali boshlangan urush
    #     boʻlsa va nishon QIROL emas, balki oʻz HUDUD LORDI boʻlsa — xuddi
    #     taxtga qarshi urushdagi kabi, lekin faqat shu HUDUDDAGI barcha
    #     oilalarga "kimga yordam berasiz?" deb soʻraladi (nomlangan tugmalar
    #     bilan, masalan "Karstark" va "Stark"). Qirol holatidagi broadcast
    #     bilan bir xil crownhelp_ callbacklaridan foydalaniladi. ---
    if (is_isyon_war and sess["type"] != "dengiz"
            and not (current_king and target["name"] == current_king)
            and target["name"] == get_region_lord(target["region"])):
        region_text = (f"⚔️ <b>{attacker['name']}</b> hudud lordi <b>{target['name']}</b> ga qarshi "
                        f"ISYON KOʻTARDI! Kimga yordam berasiz?")
        conn_rh = db()
        region_houses = conn_rh.execute(
            "SELECT name, owner_id FROM houses WHERE region=? AND is_essos=0",
            (target["region"],)).fetchall()
        conn_rh.close()
        for hh in region_houses:
            if hh["name"] in (attacker["name"], target["name"]) or not hh["owner_id"]:
                continue
            kb_region = types.InlineKeyboardMarkup(row_width=1)
            kb_region.add(types.InlineKeyboardButton(f"🗡️ {attacker['name']} ga yordam beraman",
                                                       callback_data=f"crownhelp_yes_{attack_id}"))
            kb_region.add(types.InlineKeyboardButton(f"🏛️ {target['name']} ga yordam beraman",
                                                       callback_data=f"crownhelp_king_{attack_id}"))
            kb_region.add(types.InlineKeyboardButton("🚫 Yoʻq", callback_data=f"crownhelp_no_{attack_id}"))
            try:
                bot.send_message(hh["owner_id"], region_text, reply_markup=kb_region)
            except Exception as _e:
                _swallow(_e)


# ---------------------------------------------------------------------------
# BAYROQDOR CHAQIRUVI — hudud lordi o'z hududidagi oilalarni urushga chorlay oladi
# ---------------------------------------------------------------------------

bannerlord_session = {}  # uid -> {"attack_id": int, "units": {}, "queue": [...]}

# ---------------------------------------------------------------------------
# XONADON LORDINI OLIB TASHLASH — admin biror uyning lordini olib tashlasa
# (uyning o'zi, resurslari, armiyasi, toifasi hech narsa o'zgarmaydi, faqat
# egasi yo'q qoladi), shu hududdagi mustaqil ritserlarga "lord bo'lasizmi?"
# taklifi yuboriladi. Hech kim rozi bo'lmasa (yoki hududda ritser bo'lmasa),
# taklif QOLGAN BARCHA mustaqil ritserlarga kengaytiriladi.
# ---------------------------------------------------------------------------
vacant_house_state = {}  # house_name -> {"regional_uids": set, "responded_no": set, "widened": bool}



@bot.callback_query_handler(func=lambda c: c.data.startswith("bannerlord_no_"))
def cb_bannerlord_no(c):
    bot.answer_callback_query(c.id, "Yordam berilmadi.")
    bot.send_message(c.message.chat.id, "🚫 Bayroqdor chaqirilmadi.", reply_markup=main_menu(c.from_user.id))


@bot.callback_query_handler(func=lambda c: c.data.startswith("bannerlord_yes_"))
def cb_bannerlord_yes(c):
    uid = c.from_user.id
    attack_id = int(c.data[len("bannerlord_yes_"):])
    attack = get_pending_attack(attack_id)
    lord_house = get_house_by_owner(uid)
    if not attack or attack["status"] != "pending" or not lord_house:
        bot.answer_callback_query(c.id, "Bu hujum endi yordamga ochiq emas.", show_alert=True)
        return
    if attack["war_type"] != "quruqlik":
        bot.answer_callback_query(c.id, "Dengiz jangiga bayroqdor yordami ishlamaydi.", show_alert=True)
        return
    queue = [u for u in COMBAT_UNITS if lord_house[u] > 0]
    if not queue:
        bot.answer_callback_query(c.id, "Sizda yuboradigan qoʻshin yoʻq.", show_alert=True)
        return
    bannerlord_session[uid] = {"attack_id": attack_id, "units": {}, "queue": list(queue)}
    bot.answer_callback_query(c.id)
    send_pct_prompt(c.message.chat.id, "blpct_", "blmanual_", queue[0], lord_house[queue[0]])


@bot.callback_query_handler(func=lambda c: c.data.startswith("blpct_"))
def cb_blpct(c):
    uid = c.from_user.id
    sess = bannerlord_session.get(uid)
    if not sess:
        bot.answer_callback_query(c.id, "Bayroqdor jarayoni topilmadi.", show_alert=True)
        return
    _, unit, pct = c.data.split("_")
    pct = int(pct)
    lord_house = get_house_by_owner(uid)
    amount = round(lord_house[unit] * pct / 100)
    sess["units"][unit] = amount
    if sess["queue"]:
        sess["queue"].pop(0)
    bot.answer_callback_query(c.id, f"{amount} ta {RESOURCE_LABEL.get(unit,unit)} tanlandi.")
    bannerlord_advance(c.message.chat.id, uid)


@bot.callback_query_handler(func=lambda c: c.data.startswith("blmanual_"))
def cb_blmanual(c):
    uid = c.from_user.id
    unit = c.data[len("blmanual_"):]
    sess = bannerlord_session.get(uid)
    if not sess:
        bot.answer_callback_query(c.id, "Bayroqdor jarayoni topilmadi.", show_alert=True)
        return
    lord_house = get_house_by_owner(uid)
    msg = bot.send_message(c.message.chat.id,
        f"{RESOURCE_LABEL.get(unit,unit)} sonini kiriting (0 dan {lord_house[unit]} gacha):")
    bot.register_next_step_handler(msg, process_bl_manual, unit)
    bot.answer_callback_query(c.id)


def process_bl_manual(m, unit):
    uid = m.from_user.id
    sess = bannerlord_session.get(uid)
    if not sess:
        bot.reply_to(m, "Bayroqdor jarayoni topilmadi.", reply_markup=main_menu(uid))
        return
    lord_house = get_house_by_owner(uid)
    try:
        amount = int(m.text.strip())
    except ValueError:
        bot.reply_to(m, "Butun son kiriting.")
        return
    if amount < 0 or amount > lord_house[unit]:
        bot.reply_to(m, f"0 dan {lord_house[unit]} gacha son kiriting.")
        return
    sess["units"][unit] = amount
    if sess["queue"]:
        sess["queue"].pop(0)
    bannerlord_advance(m.chat.id, uid)


def bannerlord_advance(chat_id, uid):
    sess = bannerlord_session.get(uid)
    if not sess:
        return
    lord_house = get_house_by_owner(uid)
    if sess["queue"]:
        nxt = sess["queue"][0]
        send_pct_prompt(chat_id, "blpct_", "blmanual_", nxt, lord_house[nxt])
        return
    attack = get_pending_attack(sess["attack_id"])
    if not attack or attack["status"] != "pending":
        bot.send_message(chat_id, "🚫 Hujum endi bayroqdor yordamiga ochiq emas.", reply_markup=main_menu(uid))
        bannerlord_session.pop(uid, None)
        return
    conn = db()
    added_lines = []
    current_bl = json.loads(attack["bannerlord_units"]) if attack["bannerlord_units"] else {}
    current_bl["_lord_house"] = lord_house["name"]
    for u, n in sess["units"].items():
        if n > 0:
            current_bl[u] = current_bl.get(u, 0) + n
            conn.execute(f"UPDATE houses SET {u} = MAX({u}-?,0) WHERE name=?", (n, lord_house["name"]))
            added_lines.append(f"{RESOURCE_EMOJI.get(u,'')} {RESOURCE_LABEL.get(u,u)}: {n}")
    conn.execute("UPDATE pending_attacks SET bannerlord_units=? WHERE id=?",
                 (json.dumps(current_bl), attack["id"]))
    conn.commit()
    conn.close()
    bannerlord_session.pop(uid, None)
    bot.send_message(chat_id,
        "🏴 Bayroqdor qoʻshini himoyaga qoʻshildi:\n" + ("\n".join(added_lines) if added_lines else "—"),
        reply_markup=main_menu(uid))
    # Himoyachiga xabar
    defender = get_house(attack["defender"])
    if defender and defender["owner_id"]:
        notify(defender["owner_id"],
               f"🏴 Hudud lordi <b>{lord_house['name']}</b> sizga bayroqdor qoʻshini yubordi:\n"
               + ("\n".join(added_lines) if added_lines else "—"))


# ---------------------------------------------------------------------------
# HUDUD LORDI — BAYROQDOR CHAQIRUV TUGMASI (urush paytida vassallarga)
# ---------------------------------------------------------------------------

lord_bannercall_session = {}  # uid -> {"attack_id": int, "target_vassals": [...]}


@bot.callback_query_handler(func=lambda c: c.data == "m_bannercall")
def cb_bannercall_menu(c):
    """Hudud lordi urush paytida o'z vassallarini bayroqdorga chaqiradi."""
    uid = c.from_user.id
    lord_house = get_house_by_owner(uid)
    if not lord_house:
        bot.answer_callback_query(c.id, "Sizda uy yoʻq.", show_alert=True)
        return
    # Faqat urush vaqtida (yoki admin urushni ochgan boʻlsa) chaqirish mumkin.
    if not war_call_allowed(c):
        return
    # Aktiv hujumlar (lord hujumchi yoki himoyachi sifatida)
    conn = db()
    active_attacks = conn.execute(
        "SELECT * FROM pending_attacks WHERE status='pending' AND (attacker=? OR defender=?)",
        (lord_house["name"], lord_house["name"])).fetchall()
    conn.close()
    # Bayroqdorlar — shu lordning HUDUDIDAGI barcha boshqa uylar
    region_lord_name = get_region_lord(lord_house["region"])
    if region_lord_name != lord_house["name"]:
        bot.answer_callback_query(c.id, "Faqat hudud lordi bayroqdor chaqira oladi.", show_alert=True)
        return
    # Isyon vaqtida bayroqdor chaqirish TAQIQLANGAN:
    # agar aktiv urushda hujumchi (isyon ko'targan) hududda bo'lsa — taqiq
    for _atk in active_attacks:
        _rln = get_region_lord(lord_house["region"])
        _king = get_king()
        # Agar lord HIMOYACHI, hujumchi esa shu hududdan (isyon)
        if _atk["defender"] == lord_house["name"]:
            _atk_h = get_house(_atk["attacker"])
            if _atk_h and _atk_h.get("region") == lord_house["region"]:
                bot.answer_callback_query(c.id,
                    "⛔ Hududingizda isyon bo'layabdi — avval uni bartaraf eting!\n"
                    "Isyon davomida bayroqdor chaqirish TAQIQLANGAN.", show_alert=True)
                bot.send_message(c.message.chat.id,
                    "⛔ <b>Bayroqdor chaqirib bo'lmaydi!</b>\n"
                    "Hududingizda isyon bo'layabdi. Avval isyonni bartaraf eting.",
                    parse_mode="HTML", reply_markup=main_menu(uid))
                return
    # Urush vaqtida bayroqdorlarni chaqirish — o'ziga hujum boʻlsa ham, boʻlmasa ham
    # mumkin. Yagona mexanizm: bayroqdorlar resursi lordga qoʻshiladi (u lordning
    # BARCHA urushlarida ishtirok etadi) va urush tugagach yoʻqotilmagan qismi
    # avtomatik egalariga qaytadi (check_muster_war_end).
    cb_musterall(c)


_STALE_BC_MSG = ("Bu chaqiruv shakli eskirgan — bayroqdor chaqiruvi yangilandi. "
                 "Lord yangi chaqiruv yuborsa, javob bera olasiz.")


@bot.callback_query_handler(func=lambda c: c.data.startswith("vassal_bc_yes_")
                                            or c.data.startswith("vassal_bc_no_"))
def cb_vassal_bc_stale(c):
    """Eski (urushga bogʻlangan) chorlov tugmalari — endi ishlatilmaydi:
    barcha chaqiruvlar yagona safarbarlik mexanizmi (muster_*) orqali ketadi."""
    conn = db()
    try:
        vh = get_house_by_owner(c.from_user.id)
        if vh:
            conn.execute("DELETE FROM vassal_bc_pending WHERE vassal_house=?", (vh["name"],))
            conn.commit()
    finally:
        conn.close()
    bot.answer_callback_query(c.id, _STALE_BC_MSG, show_alert=True)


def check_vassal_bc_timeouts():
    """Eski (urushga bogʻlangan) chorlovlarning kutilayotgan yozuvlarini tozalaydi.
    Ular endi majburiy 'yarmini olish'ga olib kelmaydi."""
    conn = db()
    conn.execute("DELETE FROM vassal_bc_pending WHERE created_at<=?",
                 (time.time() - BANNERCALL_RESPONSE_SECONDS,))
    conn.commit()
    conn.close()


