@bot.callback_query_handler(func=lambda c: c.data.startswith("def_start_"))
def cb_def_start(c):
    uid = c.from_user.id
    attack_id = int(c.data[len("def_start_"):])
    attack = get_pending_attack(attack_id)
    if not attack or attack["status"] != "pending":
        bot.answer_callback_query(c.id, "Bu hujum endi amal qilmaydi (vaqt tugagan yoki hal qilingan).", show_alert=True)
        return
    defender = get_house_by_owner(uid)
    if not defender or defender["name"] != attack["defender"]:
        bot.answer_callback_query(c.id, "Bu hujum sizga tegishli emas.", show_alert=True)
        return
    bot.answer_callback_query(c.id)
    def_session[uid] = {"attack_id": attack_id, "type": attack["war_type"], "units": {}, "queue": [],
                         "kema_count": 0, "capacity_left": 0}
    if attack["war_type"] == "dengiz":
        if defender["kema"] == 0:
            bot.send_message(c.message.chat.id,
                "Sizda kema yoʻq — dengizda himoyalana olmaysiz, flot bemalol qirg'oqqa chiqadi.")
            def_session.pop(uid, None)
            resolve_pending_attack(attack_id, {})
            return
        send_def_ship_pct_prompt(c.message.chat.id, defender["kema"])
    else:
        queue = [u for u in COMBAT_UNITS if defender[u] > 0]
        if not queue:
            bot.send_message(c.message.chat.id, "Sizda himoyalanadigan qoʻshin yoʻq.")
            def_session.pop(uid, None)
            resolve_pending_attack(attack_id, {})
            return
        def_session[uid]["queue"] = queue
        send_pct_prompt(c.message.chat.id, "defpct_", "defmanual_", queue[0], defender[queue[0]])


def send_def_ship_pct_prompt(chat_id, max_ships):
    kb = types.InlineKeyboardMarkup(row_width=3)
    row = [types.InlineKeyboardButton(f"{pct}% ({round(max_ships*pct/100)})", callback_data=f"defship_{pct}")
           for pct in WAR_PCT_OPTIONS]
    kb.add(*row)
    kb.add(types.InlineKeyboardButton("✍️ Qoʻlda son kiritish", callback_data="defshipmanual"))
    bot.send_message(chat_id, f"⛵ Nechta kema bilan himoyalanasiz? (jamingizda: {max_ships})", reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data.startswith("defship_"))
def cb_defship(c):
    uid = c.from_user.id
    sess = def_session.get(uid)
    if not sess:
        bot.answer_callback_query(c.id, "Himoya jarayoni topilmadi.", show_alert=True)
        return
    pct = int(c.data[len("defship_"):])
    defender = get_house_by_owner(uid)
    amount = round(defender["kema"] * pct / 100)
    bot.answer_callback_query(c.id, f"{amount} ta kema tanlandi.")
    start_naval_defense_selection(c.message.chat.id, uid, amount)


@bot.callback_query_handler(func=lambda c: c.data == "defshipmanual")
def cb_defshipmanual(c):
    msg = bot.send_message(c.message.chat.id, "Nechta kema bilan himoyalanasiz? Sonini yozing:")
    bot.register_next_step_handler(msg, process_defship_manual)
    bot.answer_callback_query(c.id)


def process_defship_manual(m):
    uid = m.from_user.id
    sess = def_session.get(uid)
    if not sess:
        bot.reply_to(m, "Himoya jarayoni topilmadi.", reply_markup=main_menu(uid))
        return
    defender = get_house_by_owner(uid)
    try:
        amount = int((m.text or "").strip())
    except ValueError:
        bot.reply_to(m, "Butun son kiriting.")
        return
    if amount < 0 or amount > defender["kema"]:
        bot.reply_to(m, f"0 dan {defender['kema']} gacha son kiriting.")
        return
    start_naval_defense_selection(m.chat.id, uid, amount)


def start_naval_defense_selection(chat_id, uid, ship_count):
    sess = def_session.get(uid)
    if not sess:
        return
    defender = get_house_by_owner(uid)
    sess["kema_count"] = ship_count
    sess["capacity_left"] = naval_capacity(ship_count)
    queue = [u for u in COMBAT_UNITS if defender[u] > 0]
    if ship_count == 0 or sess["capacity_left"] <= 0 or not queue:
        bot.send_message(chat_id, "Kema/askar tanlanmadi — himoyasiz qoldingiz.", reply_markup=main_menu(uid))
        attack_id = sess["attack_id"]
        def_session.pop(uid, None)
        resolve_pending_attack(attack_id, {})
        return
    sess["queue"] = queue
    send_pct_prompt(chat_id, "defpct_", "defmanual_", queue[0], defender[queue[0]], cap=sess["capacity_left"])


@bot.callback_query_handler(func=lambda c: c.data.startswith("defvalyask_no_"))
def cb_defvalyask_no(c):
    uid = c.from_user.id
    bot.answer_callback_query(c.id, "Valeriya berilmadi.")
    def_advance(c.message.chat.id, uid)


@bot.callback_query_handler(func=lambda c: c.data.startswith("defvalyask_yes_"))
def cb_defvalyask_yes(c):
    uid = c.from_user.id
    unit = c.data[len("defvalyask_yes_"):]
    sess = def_session.get(uid)
    if not sess:
        bot.answer_callback_query(c.id, "Himoya jarayoni topilmadi.", show_alert=True)
        return
    defender = get_house_by_owner(uid)
    remaining = _valyria_remaining(defender, sess)
    unit_count = sess["units"].get(unit, 0)
    useful_max = max(1, -(-unit_count // VALYRIA_BLOCK))
    bot.answer_callback_query(c.id)
    msg = bot.send_message(c.message.chat.id,
        f"🔱 <b>{RESOURCE_LABEL.get(unit,unit)}</b> ga nechta Valyria poʻlati berasiz? "
        f"(qoldiq: {remaining} dona; har biri {VALYRIA_BLOCK} tagacha askarni 2x kuchaytiradi — "
        f"{unit_count} ta {RESOURCE_LABEL.get(unit,unit)} uchun {useful_max} dona yetarli). Sonini yozing:")
    bot.register_next_step_handler(msg, process_defvalyask_count, unit)


def process_defvalyask_count(m, unit):
    uid = m.from_user.id
    sess = def_session.get(uid)
    if not sess:
        bot.reply_to(m, "Himoya jarayoni topilmadi.", reply_markup=main_menu(uid))
        return
    defender = get_house_by_owner(uid)
    remaining = _valyria_remaining(defender, sess)
    try:
        n = int(m.text.strip())
    except ValueError:
        msg = bot.reply_to(m, "Butun son kiriting.")
        bot.register_next_step_handler(msg, process_defvalyask_count, unit)
        return
    if n < 1 or n > remaining:
        msg = bot.reply_to(m, f"1 dan {remaining} gacha son kiriting.")
        bot.register_next_step_handler(msg, process_defvalyask_count, unit)
        return
    vmap = sess.setdefault("valyria_map", {})
    vmap[unit] = vmap.get(unit, 0) + n
    bot.reply_to(m, f"✅ {RESOURCE_LABEL.get(unit,unit)} uchun {n} dona Valyria poʻlati beriladi.")
    def_advance(m.chat.id, uid)


def def_advance(chat_id, uid):
    sess = def_session.get(uid)
    if not sess:
        return
    defender = get_house_by_owner(uid)
    if sess["type"] == "dengiz":
        if sess.get("capacity_left", 0) <= 0 or not sess["queue"]:
            show_def_confirm(chat_id, uid)
            return
        nxt = sess["queue"][0]
        send_pct_prompt(chat_id, "defpct_", "defmanual_", nxt, defender[nxt], cap=sess["capacity_left"])
        return
    if sess["queue"]:
        nxt = sess["queue"][0]
        send_pct_prompt(chat_id, "defpct_", "defmanual_", nxt, defender[nxt])
    else:
        show_def_confirm(chat_id, uid)


def show_def_confirm(chat_id, uid):
    sess = def_session.get(uid)
    if not sess:
        return
    units = {u: n for u, n in sess["units"].items() if n > 0}
    if sess["type"] == "dengiz":
        kema = sess.get("kema_count", 0)
        total_troops = sum(units.values())
        required = kema * SHIP_CAPACITY
        if SHIPS_REQUIRE_FULL and kema > 0 and total_troops != required:
            bot.send_message(chat_id,
                f"🚫 {kema} ta kema toʻliq himoyalanishi uchun aynan {required} ta askar kerak "
                f"(hozir {total_troops} ta). Kema toʻlmaguncha himoyaga chiqolmaydi — himoyasiz qolasiz.")
            attack_id = sess["attack_id"]
            def_session.pop(uid, None)
            resolve_pending_attack(attack_id, {})
            return
        lines = "\n".join(f"{RESOURCE_EMOJI.get(u,'')} {RESOURCE_LABEL.get(u,u)}: {n}" for u, n in units.items()) or "—"
        text = f"🛡️ {kema} ta kema va quyidagi askarlar bilan himoyalanasizmi?\n{lines}"
    else:
        lines = "\n".join(f"{RESOURCE_EMOJI.get(u,'')} {RESOURCE_LABEL.get(u,u)}: {n}" for u, n in units.items()) or "—"
        valyria_map = sess.get("valyria_map", {})
        dp = land_power_with_valyria_map(sess["units"], "def", valyria_map)
        if valyria_map:
            valy_parts = [f"{n} dona → {RESOURCE_LABEL.get(u,u)}" for u, n in valyria_map.items() if n]
            valy_note = f" (🔱 " + ", ".join(valy_parts) + " 2x kuchaytirilgan)"
        else:
            valy_note = ""
        text = f"🛡️ Quyidagi kuch bilan himoyalanasizmi?\n{lines}\n\nJami himoya kuchi: {dp}{valy_note}"
    kb = types.InlineKeyboardMarkup(row_width=1)
    kb.add(types.InlineKeyboardButton("🛡️ Himoyani tasdiqlash", callback_data="def_confirm"))
    kb.add(types.InlineKeyboardButton("🚫 Himoyasiz qoldirish", callback_data="def_none"))
    bot.send_message(chat_id, text, reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data.startswith("defpct_"))
def cb_defpct(c):
    uid = c.from_user.id
    sess = def_session.get(uid)
    if not sess:
        bot.answer_callback_query(c.id, "Himoya jarayoni topilmadi.", show_alert=True)
        return
    _, unit, pct = c.data.split("_")
    pct = int(pct)
    defender = get_house_by_owner(uid)
    max_amount = defender[unit]
    if sess["type"] == "dengiz":
        max_amount = max(0, min(max_amount, sess.get("capacity_left", 0)))
    amount = round(max_amount * pct / 100)
    sess["units"][unit] = amount
    if sess["type"] == "dengiz":
        sess["capacity_left"] = sess.get("capacity_left", 0) - amount
    if sess["queue"]:
        sess["queue"].pop(0)
    bot.answer_callback_query(c.id, f"{amount} ta {RESOURCE_LABEL.get(unit,unit)} tanlandi.")
    maybe_ask_unit_valyria(c.message.chat.id, uid, def_session, unit, amount, def_advance, "defvalyask_")


