def send_admin_house_list(chat_id):
    conn = db()
    rows = conn.execute("SELECT * FROM houses ORDER BY region, name").fetchall()
    conn.close()
    text = ""
    for r in rows:
        text += (f"\n<b>{r['name']}</b> [{r['tier']}] owner={r['owner_id']}\n"
                 f"  tanga={r['tanga']} qoshin={r['qoshin']} kamonchi={r['kamonchi']} "
                 f"otliq={r['otliq']} kema={r['kema']} benuqson={r['benuqson']} kenja_ogil={r['kenja_ogil']} "
                 f"valyria_polati={r['valyria_polati']}")
    for i in range(0, len(text), 3500):
        bot.send_message(chat_id, text[i:i + 3500] or "—")


def show_admin_player_list(chat_id):
    """O'yinchilar (uy egalari) ro'yxati — bosilsa har birining to'liq
    ma'lumoti (admin uchun, resurslar yashirilmasdan) ochiladi."""
    conn = db()
    rows = conn.execute(
        "SELECT h.name, h.region, h.tier, h.owner_id, h.is_essos, u.username, u.ism "
        "FROM houses h LEFT JOIN users u ON u.user_id = h.owner_id "
        "ORDER BY h.is_essos, h.region, h.name").fetchall()
    conn.close()
    text = "<b>👥 O'yinchilar roʻyxati</b>\nBirini bosing — toʻliq maʼlumotini koʻring.\n"
    cur = None
    kb = types.InlineKeyboardMarkup(row_width=2)
    btns = []
    for r in rows:
        if r["region"] != cur:
            cur = r["region"]
            text += f"\n<b>— {cur} —</b>\n"
        toifa = "" if r["is_essos"] else f" [{r['tier']}]"
        if r["owner_id"]:
            who = r["ism"] or (f"@{r['username']}" if r["username"] else str(r["owner_id"]))
            text += f"{r['name']}{toifa} — 👤 {who}\n"
        else:
            text += f"{r['name']}{toifa} — 🔓 boʻsh\n"
        btns.append(types.InlineKeyboardButton(r["name"], callback_data=f"aview_{r['name']}"))
    kb.add(*btns)
    kb.add(types.InlineKeyboardButton("⬅️ Admin panel", callback_data="m_admin"))
    for i in range(0, len(text), 3500):
        bot.send_message(chat_id, text[i:i + 3500])
    bot.send_message(chat_id, "Batafsil ko'rish uchun uyni tanlang 👇", reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data == "a_players")
def cb_a_players(c):
    if not is_admin(c.from_user.id):
        bot.answer_callback_query(c.id, "Ruxsat yo'q.", show_alert=True)
        return
    bot.answer_callback_query(c.id)
