@bot.callback_query_handler(func=lambda c: c.data.startswith("aview_"))
def cb_aview(c):
    if not is_admin(c.from_user.id):
        bot.answer_callback_query(c.id, "Ruxsat yo'q.", show_alert=True)
        return
    name = c.data[len("aview_"):]
    house = get_house(name)
    if not house:
        bot.answer_callback_query(c.id, "Topilmadi.", show_alert=True)
        return
    bot.answer_callback_query(c.id)
    conn = db()
    user_row = conn.execute("SELECT username, ism FROM users WHERE user_id=?",
                             (house["owner_id"],)).fetchone() if house["owner_id"] else None
    conn.close()

    if house["is_essos"]:
        text = f"<b>🏰 {house['name']}</b> [🌊 Essos]\n\n"
    else:
        text = f"<b>🏰 {house['name']}</b> [{house['tier']} toifa]\n📍 Hudud: {house['region']}\n\n"
    if house["owner_id"]:
        text += "<b>👤 Ega:</b>\n"
        text += f"  Ism: {user_row['ism'] if user_row and user_row['ism'] else '—'}\n"
        text += f"  Username: @{user_row['username']}\n" if user_row and user_row["username"] else "  Username: —\n"
        text += f"  Telegram ID: <code>{house['owner_id']}</code>\n\n"
    else:
        text += "🔓 <b>Egasiz uy</b>\n\n"
    if house["is_essos"]:
        if get_essos_king() == house["name"]:
            text += "👑🌊 ESSOS QIROLI!\n"
    elif house["name"] == get_king():
        text += "👑 QIROLLIK UYI!\n"
    elif house["name"] == get_region_lord(house["region"]):
        text += f"🏛️ {house['region']} hudud lordi\n"
    if house["alliance_with"]:
        text += f"🤝 Ittifoqdosh: {house['alliance_with']}\n"
    if house["vassal_of"]:
        text += f"⚑ Vassal: {house['vassal_of']} uyiga bo'ysunadi\n"
    if house["tax_exempt"]:
        text += "🛡️ Soliqdan ozod\n"
    text += f"⚔️ Urushlar: {house['wars_won']}W / {house['wars_lost']}L\n\n"
    text += "<b>📊 Resurslar (admin ko'rinishi — hech narsa yashirilmagan):</b>\n"
    text += fmt_resources(house)
    text += f"\n⛵ Kema: {house['kema']} ({naval_capacity(house['kema'])} ta askar sig'adi)"
    if house["yuzsiz_qotil"]:
        text += f"\n🗝️ Yuzsiz qotil: {house['yuzsiz_qotil']}"
    if house["qizil_jodugar"]:
        text += f"\n🔮 Qizil jodugar: {house['qizil_jodugar']}"

    kb = types.InlineKeyboardMarkup(row_width=1)
    if house["owner_id"] and not is_admin(house["owner_id"]):
        if is_blocked(house["owner_id"]):
            kb.add(types.InlineKeyboardButton("✅ Blokdan chiqarish", callback_data=f"ablocktoggle_{house['owner_id']}"))
        else:
            kb.add(types.InlineKeyboardButton("🚫 Ushbu foydalanuvchini bloklash", callback_data=f"ablocktoggle_{house['owner_id']}"))
    kb.add(
        types.InlineKeyboardButton("✏️ Ushbu uyning resursini o'zgartirish", callback_data="a_resurs"),
        types.InlineKeyboardButton("⬅️ O'yinchilar roʻyxati", callback_data="a_players"),
        types.InlineKeyboardButton("👑 Admin panel", callback_data="m_admin"),
    )
    bot.send_message(chat_id=c.message.chat.id, text=text, parse_mode="HTML", reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data.startswith("ablocktoggle_"))
def cb_ablocktoggle(c):
    if not is_admin(c.from_user.id):
        return
    target_uid = int(c.data[len("ablocktoggle_"):])
    if is_admin(target_uid):
        bot.answer_callback_query(c.id, "Adminni bloklab boʻlmaydi.", show_alert=True)
        return
    new_state = not is_blocked(target_uid)
    set_blocked(target_uid, new_state)
    bot.answer_callback_query(c.id, "🚫 Bloklandi." if new_state else "✅ Blokdan chiqarildi.", show_alert=True)
    bot.send_message(c.message.chat.id,
        f"user_id=<code>{target_uid}</code> {'🚫 bloklandi' if new_state else '✅ blokdan chiqarildi'}.",
        parse_mode="HTML", reply_markup=back_button())


