@bot.callback_query_handler(func=lambda c: c.data == "a_war_toggle")
def cb_a_war_toggle(c):
    global war_open_override, war_force_closed
    if not is_admin(c.from_user.id):
        bot.answer_callback_query(c.id, "Ruxsat yo'q.", show_alert=True)
        return
    war_open_override = not war_open_override
    if war_open_override:
        war_force_closed = False
        status = "OCHIQ ✅ (istalgan vaqt urush mumkin)"
    else:
        status = "AVTOMATIK 🕐 (Chorshanba/Juma/Yakshanba 19:00-21:30)"
    bot.answer_callback_query(c.id, f"Urush rejimi: {status}", show_alert=True)
    bot.send_message(c.message.chat.id,
        f"⚔️ <b>Urush rejimi o'zgartirildi:</b>\n\n{status}",
        parse_mode="HTML", reply_markup=back_button())


