@bot.callback_query_handler(func=lambda c: c.data.startswith("aincome_"))
def cb_aincome(c):
    if not is_admin(c.from_user.id):
        return
    name = c.data[len("aincome_"):]
    conn = db()
    h = conn.execute("SELECT * FROM houses WHERE name=?", (name,)).fetchone()
    if not h:
        conn.close()
        bot.answer_callback_query(c.id, "Uy topilmadi.", show_alert=True)
        return
    # Essos shahri (hozir faqat Bravos) uchun kunlik ishlab chiqarishni
    # qoʻlda berish — ESSOS_CITIES lugʻati orqali ishlaydi.
    if name in ESSOS_CITIES:
        _apply_essos_city_daily_production(conn, name, time.localtime(), force=True)
        conn.commit()
        conn.close()
        given = ", ".join(
            f"{RESOURCE_EMOJI.get(r,'')} +{amt} {RESOURCE_LABEL.get(r,r)}"
            for r, amt in ESSOS_CITIES[name].items())
        bot.answer_callback_query(c.id, "Bajarildi.")
        bot.send_message(c.message.chat.id,
            f"🌊 <b>{name}</b> shahriga kunlik ishlab chiqarish qoʻlda berildi:\n{given}",
            reply_markup=back_button(), parse_mode="HTML")
        essos_h = get_house(name)
        if essos_h and essos_h["owner_id"]:
            notify(essos_h["owner_id"], f"🌊 Admin {name} shahriga kunlik ishlab chiqarish qoʻlda berdi.")
        return
    # Barcha qolgan uylar — jumladan mustaqil ritser qurgan vassal qal'alar
    # (PRODUCTION lug'atida yo'q, lekin castle_daily_income ustunida oʻz
    # kunlik daromadi bor) — apply_daily_income_for_house ichida ikkalasi
    # ham qo'llab-quvvatlanadi, shuning uchun bu yerda alohida tekshirish
    # SHART EMAS (avval PRODUCTION'da yo'qligi sababli bloklanardi — bu xato edi).
    king = get_king()
    applied = apply_daily_income_for_house(conn, h, king)
    conn.commit()
    conn.close()
    if not applied:
        bot.answer_callback_query(c.id, "Bu uy uchun ishlab chiqarish jadvali yoʻq.", show_alert=True)
        return
    bot.answer_callback_query(c.id, "Bajarildi.")
    bot.send_message(c.message.chat.id, f"🎁 <b>{name}</b> ga kunlik daromad qoʻlda berildi.", reply_markup=back_button())
    if h["owner_id"]:
        notify(h["owner_id"], "🎁 Admin sizga qoʻlda kunlik daromad berdi.")


