@bot.callback_query_handler(func=lambda c: c.data.startswith("avmake_pick_"))
def cb_a_vmake_pick(c):
    if not is_admin(c.from_user.id):
        bot.answer_callback_query(c.id, "Ruxsat yo'q.", show_alert=True)
        return
    name = c.data[len("avmake_pick_"):]
    target = get_house(name)
    if not target or target["vassal_of"]:
        bot.answer_callback_query(c.id, "Bu uy ozod emas yoki topilmadi.", show_alert=True)
        return
    _admin_vassal_target[c.from_user.id] = name
    conn = db()
    rows = conn.execute(
        "SELECT name FROM houses WHERE is_essos=? AND is_free_knight=0 AND name!=? AND name!=? "
        "ORDER BY name", (1 if target["is_essos"] else 0, name, WALL_HOUSE)).fetchall()
    conn.close()
    if not rows:
        bot.answer_callback_query(c.id, "Mos lord topilmadi.", show_alert=True)
        return
    kb = types.InlineKeyboardMarkup(row_width=2)
    kb.add(*[types.InlineKeyboardButton(r["name"], callback_data=f"avmake_lord_{r['name']}") for r in rows])
    kb.add(types.InlineKeyboardButton("⬅️ Bosh menyu", callback_data="m_back"))
    bot.send_message(c.message.chat.id,
        f"🏰 2-qadam: <b>{name}</b> qaysi uyning vassali boʻladi?\n"
        f"(faqat bir qit'adagi uylar koʻrsatilgan)",
        reply_markup=kb, parse_mode="HTML")
    bot.answer_callback_query(c.id)


@bot.callback_query_handler(func=lambda c: c.data.startswith("avmake_lord_"))
def cb_a_vmake_go(c):
    if not is_admin(c.from_user.id):
        bot.answer_callback_query(c.id, "Ruxsat yo'q.", show_alert=True)
        return
    lord_name = c.data[len("avmake_lord_"):]
    target_name = _admin_vassal_target.get(c.from_user.id)
    if not target_name:
        bot.answer_callback_query(c.id, "Seans tugagan — qaytadan boshlang.", show_alert=True)
        return
    target = get_house(target_name)
    lord = get_house(lord_name)
    if not target or not lord or target_name == lord_name:
        bot.answer_callback_query(c.id, "Uy topilmadi.", show_alert=True)
        return
    if target["vassal_of"]:
        bot.answer_callback_query(c.id, "Bu uy allaqachon vassal.", show_alert=True)
        return
    if not _same_continent(target, lord):
        bot.answer_callback_query(c.id, "Boshqa qit'adagi uyga vassal qilib boʻlmaydi.", show_alert=True)
        return
    _admin_vassal_target.pop(c.from_user.id, None)
    conn = db()
    conn.execute("UPDATE houses SET vassal_of=? WHERE name=?", (lord_name, target_name))
    # Kaskad ozodlik: vassal qilingan uyning o'z vassallari ozod bo'ladi
    # (mustaqil ritserlar tegilmaydi).
    freed = conn.execute(
        "SELECT name, owner_id FROM houses WHERE vassal_of=? AND is_free_knight=0",
        (target_name,)).fetchall()
    if freed:
        conn.execute("UPDATE houses SET vassal_of='' WHERE vassal_of=? AND is_free_knight=0",
                     (target_name,))
    # Vassal qilingan uy hozirgi qirol bo'lsa — qirollik lordga o'tadi.
    became_king = False
    king_row = conn.execute("SELECT value FROM world WHERE key='king'").fetchone()
    if king_row and king_row["value"] == target_name:
        conn.execute("UPDATE world SET value=? WHERE key='king'", (lord_name,))
        became_king = True
    conn.commit()
    conn.close()
    log_history("vassal_make", target_name, f"Admin {target_name} ni {lord_name} ga vassal qildi")
    bot.answer_callback_query(c.id, "Bajarildi.")
    bot.send_message(c.message.chat.id,
        f"🏰 <b>{target_name}</b> endi <b>{lord_name}</b> ning vassali."
        + (f"\n👑 Temir taxt qirolligi <b>{lord_name}</b> ga oʻtdi." if became_king else ""),
        reply_markup=back_button(), parse_mode="HTML")
    if target["owner_id"]:
        notify(target["owner_id"],
               f"🏰 Admin qaroriga koʻra siz endi <b>{lord_name}</b> ning vassalisiz. "
               f"Kunlik resursingizning yarmi ularga oʻtadi.")
    if lord["owner_id"]:
        notify(lord["owner_id"],
               f"🏰 Admin qaroriga koʻra <b>{target_name}</b> endi sizning vassalingiz.")
    if became_king and lord["owner_id"]:
        notify(lord["owner_id"], "👑 Siz endi TEMIR TAXT QIROLISIZ!")
    _transfer_region_lordship_if_vassal(target_name)
    for f in freed:
        if f["owner_id"]:
            notify(f["owner_id"],
                   f"🏰 Sobiq hukmdoringiz <b>{target_name}</b> endi <b>{lord_name}</b> ning vassaliga "
                   f"aylandi, shu sabab siz ENDI OZODSIZ.")


