# V19: ADMIN — Oq piyodalar (White Walkers) holatini koʻrish: joriy hujum
# kutilmoqda boʻlsa uning kuchi/qolgan vaqti/hozirgacha yigʻilgan mudofaa,
# hujum jadvali (qachon avtomatik boshlanishi) va jami boʻlib oʻtgan
# hujumlar soni.
# ---------------------------------------------------------------------------
@bot.callback_query_handler(func=lambda c: c.data == "a_ww_status")
def cb_a_ww_status(c):
    if not is_admin(c.from_user.id):
        return
    conn = db()
    destroyed = conn.execute("SELECT value FROM world WHERE key='wall_destroyed'").fetchone()
    total = conn.execute("SELECT COUNT(*) AS n FROM white_walker_events").fetchone()["n"]
    wall_wins = conn.execute(
        "SELECT COUNT(*) AS n FROM white_walker_events WHERE result='wall'").fetchone()["n"]
    ww_wins = conn.execute(
        "SELECT COUNT(*) AS n FROM white_walker_events WHERE result='white_walkers'").fetchone()["n"]
    conn.close()

    weekday_names = ["Dushanba", "Seshanba", "Chorshanba", "Payshanba",
                      "Juma", "Shanba", "Yakshanba"]
    lines = [
        "☠️ <b>Oq piyodalar — holat</b>\n",
        f"🌑 Tun qiroli: <b>{_nk_label()}</b>",
        f"📅 Avtomatik hujum jadvali: har hafta <b>{weekday_names[WHITE_WALKER_EVENT_DAY]}</b> kuni, "
        f"soat <b>{WHITE_WALKER_EVENT_HOUR}:00</b> dan keyin (server vaqti bo'yicha), "
        f"haftasiga bittadan koʻp emas.",
        f"⏳ Yordam berish oynasi: <b>{WHITE_WALKER_WINDOW_SECONDS // 60}</b> daqiqa.",
        f"⚔️ Hujum kuchi diapazoni: <b>{WHITE_WALKER_BASE_POWER}</b>–<b>{WHITE_WALKER_MAX_POWER}</b> "
        f"(tasodifiy, har safar).",
        f"📊 Jami boʻlib oʻtgan hujumlar: <b>{total}</b> (Devor gʻalabasi: {wall_wins}, "
        f"Oq piyodalar gʻalabasi: {ww_wins}).",
    ]
    if destroyed and destroyed["value"] == "1":
        lines.append("\n💀 Devor allaqachon YIQILGAN — yangi hujum boshlanmaydi.")
    else:
        event = _ww_event()
        if event:
            wall_units = json.loads(event["defense_units"] or "{}")
            helpers = json.loads(event["helper_units"] or "{}")
            all_defense = dict(wall_units)
            for _hn, units in helpers.items():
                for unit, amount in units.items():
                    all_defense[unit] = all_defense.get(unit, 0) + amount
            defense_power = _ww_power(all_defense)
            remaining = max(0, int(event["deadline"] - time.time()))
            lines.append(
                f"\n🔴 <b>HOZIR faol hujum bor!</b>\n"
                f"Bazaviy hujum kuchi: <b>{int(event['attack_power'])}</b>\n"
                f"Tun qiroli yuborgan qoʻshin kuchi: <b>{_ww_atk_power(json.loads(event['nk_units'] or '{}'))}</b>\n"
                f"Hozirgacha yigʻilgan mudofaa kuchi: <b>{defense_power}</b>\n"
                f"Yordam beruvchi oilalar soni: <b>{len(helpers)}</b>\n"
                f"Qolgan vaqt: <b>{remaining // 60}</b> daq {remaining % 60} soniya")
        else:
            lines.append("\n🟢 Hozircha faol hujum yoʻq — navbatdagi hujum jadval boʻyicha boshlanadi.")
    bot.send_message(c.message.chat.id, "\n".join(lines), reply_markup=back_button())
    bot.answer_callback_query(c.id)


