turnir_session = {}  # admin_uid -> {"kind": "regional"/"kingdom", "region": str, "resource": str, "amount": int}

TURNIR_REGIONS = list(REGION_LORDS_INIT.keys())

TURNIR_MIN_PRIZE = 150
TURNIR_MAX_ENTRY_FEE = 10
