def can_manage_tournament(uid, t):
    if is_admin(uid):
        return True
    if not t or not t["organizer_house"]:
        return False
    house = get_house_by_owner(uid)
    return bool(house) and house["name"] == t["organizer_house"]

# ---------------------------------------------------------------------------
# CHAT TIZIMI: har bir o'yinchi o'z hududining chatiga (faqat o'sha hudud
# o'yinchilari yoza/o'qiy oladi) va butun Westeros chatiga kira oladi.
# Admin barcha hududiy chatlarga kira oladi, boshqa o'yinchilar faqat o'z
# hududiga. Admin alohida "Admin xabari" yubora oladi — bu chatga yozilmaydi,
# har bir o'yinchiga to'g'ridan-to'g'ri, alohida xabar sifatida boradi.
# ---------------------------------------------------------------------------
chat_session = {}   # uid -> {"scope": "region"/"kingdom", "region": str}
CHAT_HISTORY_LIMIT = 15


@bot.callback_query_handler(func=lambda c: c.data == "m_chat")
def cb_m_chat(c):
    uid = c.from_user.id
    admin = is_admin(uid)
    house = get_house_by_owner(uid)
    if not house and not admin:
        bot.answer_callback_query(c.id, "Sizda uy yoʻq.", show_alert=True)
        return
    kb = types.InlineKeyboardMarkup(row_width=1)
    kb.add(types.InlineKeyboardButton("👑 Butun Westeros chati", callback_data="chat_kingdom"))
    kb.add(types.InlineKeyboardButton("🌊 Butun Essos chati", callback_data="chat_essos"))
    if admin:
        for idx, reg in enumerate(TURNIR_REGIONS):
            kb.add(types.InlineKeyboardButton(f"🏘️ {reg}", callback_data=f"chat_region_{idx}"))
        kb.add(types.InlineKeyboardButton("📢 Admin xabari yuborish (barchaga)", callback_data="chat_broadcast"))
    else:
        idx = TURNIR_REGIONS.index(house["region"]) if house["region"] in TURNIR_REGIONS else None
        if idx is not None:
            kb.add(types.InlineKeyboardButton(f"🏘️ {house['region']} (mening hududim)",
                                               callback_data=f"chat_region_{idx}"))
    kb.add(types.InlineKeyboardButton("⬅️ Bosh menyu", callback_data="m_back"))
    bot.send_message(c.message.chat.id, "💬 <b>Chat</b>\nQaysi boʻlimga kirasiz?", reply_markup=kb)
    bot.answer_callback_query(c.id)


def _chat_can_access(uid, scope, region):
    if is_admin(uid):
        return True
    house = get_house_by_owner(uid)
    if not house:
        return False
    if scope == "kingdom":
        return not house["is_essos"]
    if scope == "essos":
        return bool(house["is_essos"])
    return house["region"] == region


def open_chat(chat_id, uid, scope, region):
    if not _chat_can_access(uid, scope, region):
        bot.send_message(chat_id, "🚫 Sizga bu chat yopiq.", reply_markup=main_menu(uid))
        return
    chat_session[uid] = {"scope": scope, "region": region}
    conn = db()
    if scope == "kingdom":
        rows = conn.execute(
            "SELECT * FROM chat_messages WHERE scope='kingdom' ORDER BY id DESC LIMIT ?",
            (CHAT_HISTORY_LIMIT,)).fetchall()
        title = "👑 Butun Westeros chati"
    elif scope == "essos":
        rows = conn.execute(
            "SELECT * FROM chat_messages WHERE scope='essos' ORDER BY id DESC LIMIT ?",
            (CHAT_HISTORY_LIMIT,)).fetchall()
        title = "🌊 Butun Essos chati"
    else:
        rows = conn.execute(
            "SELECT * FROM chat_messages WHERE scope='region' AND region=? ORDER BY id DESC LIMIT ?",
            (region, CHAT_HISTORY_LIMIT)).fetchall()
        title = f"🏘️ {region} hududiy chati"
    conn.close()
    rows = list(reversed(rows))
    if rows:
        lines = []
        for r in rows:
            t = time.strftime("%d.%m %H:%M", time.localtime(r["created_at"]))
            lines.append(f"🕐 {t} <b>{r['house']}</b>: {r['text']}")
        body = "\n".join(lines)
    else:
        body = "<i>Hali xabarlar yoʻq. Birinchi boʻlib yozing!</i>"
    kb = types.InlineKeyboardMarkup(row_width=1)
    kb.add(types.InlineKeyboardButton("✍️ Xabar yozish", callback_data="chat_write"))
    kb.add(types.InlineKeyboardButton("🔄 Yangilash", callback_data=f"chat_refresh"))
    kb.add(types.InlineKeyboardButton("⬅️ Chat menyusi", callback_data="m_chat"))
    bot.send_message(chat_id, f"{title}\n\n{body}", reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data.startswith("chat_region_"))
def cb_chat_region(c):
    uid = c.from_user.id
    idx = int(c.data[len("chat_region_"):])
    if idx < 0 or idx >= len(TURNIR_REGIONS):
        bot.answer_callback_query(c.id, "Hudud topilmadi.", show_alert=True)
        return
    region = TURNIR_REGIONS[idx]
    bot.answer_callback_query(c.id)
    open_chat(c.message.chat.id, uid, "region", region)


