def process_admin_broadcast(m):
    uid = m.from_user.id
    if not is_admin(uid):
        return
    text = (m.text or "").strip()
    if not text:
        msg = bot.reply_to(m, "Boʻsh xabar yuborib boʻlmaydi. Qayta yozing:")
        bot.register_next_step_handler(msg, process_admin_broadcast)
        return
    conn = db()
    rows = conn.execute(
        "SELECT DISTINCT owner_id FROM houses WHERE is_essos=0 AND owner_id IS NOT NULL").fetchall()
