@bot.callback_query_handler(func=lambda c: c.data.startswith("turnir_manage_"))
def cb_turnir_manage(c):
    t_id = int(c.data[len("turnir_manage_"):])
    conn = db()
    t = conn.execute("SELECT * FROM tournaments WHERE id=?", (t_id,)).fetchone()
    if not t or not can_manage_tournament(c.from_user.id, t):
        conn.close()
        bot.answer_callback_query(c.id, "Topilmadi yoki bu turnir sizga tegishli emas.", show_alert=True)
        return
    parts = conn.execute(
        "SELECT house, status FROM tournament_participants WHERE tournament_id=? ORDER BY joined_at",
        (t_id,)).fetchall()
    conn.close()
    back_target = "a_turnir" if is_admin(c.from_user.id) else "m_ritserlik"
    kind_label = "Hududiy" if t["kind"] == "regional" else "Qirollik"
    if t["organizer_house"]:
        kind_label = f"{t['organizer_house']} oilasi tashkil qilgan"
    region_info = f" ({t['region']})" if t["region"] else ""
    active_parts = [p for p in parts if p["status"] == "active"]
    elim_parts = [p for p in parts if p["status"] == "eliminated"]
    fee_info = f"\nQatnashish badali: {t['entry_fee']} 💰tanga" if t["entry_fee"] else ""
    txt = (f"🏇 <b>Turnir #{t_id}</b> — {kind_label}{region_info}\n"
           f"Holat: <b>{t['status']}</b>\n"
           f"Mukofot: {t['prize_amount']} {RESOURCE_LABEL.get(t['prize_resource'], t['prize_resource'])}{fee_info}\n\n"
           f"✅ Aktiv ishtirokchilar ({len(active_parts)}):\n"
           + "\n".join(f"• {p['house']}" for p in active_parts) +
           (f"\n\n❌ Chiqarilganlar ({len(elim_parts)}):\n" +
            "\n".join(f"• {p['house']}" for p in elim_parts) if elim_parts else ""))
    kb = types.InlineKeyboardMarkup(row_width=1)
    if t["status"] == "signup":
        if len(active_parts) >= 2:
            kb.add(types.InlineKeyboardButton(
                f"▶️ Turnirni boshlash ({len(active_parts)} ishtirokchi)",
                callback_data=f"turnir_start_{t_id}"))
        else:
            txt += "\n\n⚠️ Turnirni boshlash uchun kamida 2 ta ishtirokchi kerak."
    elif t["status"] == "active":
        conn2 = db()
        pending_matches = conn2.execute(
            "SELECT * FROM tournament_matches WHERE tournament_id=? AND status='pending' ORDER BY id",
            (t_id,)).fetchall()
        conn2.close()
        if pending_matches:
            txt += "\n\n⚔️ <b>Davom etayotgan janglar (duel):</b>"
            for pm in pending_matches:
                txt += f"\n• {pm['house1']} vs {pm['house2']}"
                # Majburiy natija faqat admin uchun
                if is_admin(c.from_user.id):
                    kb.add(types.InlineKeyboardButton(
                        f"🔧 {pm['house1']} vs {pm['house2']} — majburiy natija",
                        callback_data=f"turnir_match_{pm['id']}"))
        elif len(active_parts) == 1:
            kb.add(types.InlineKeyboardButton(
                f"🏆 G'olibni e'lon qilish: {active_parts[0]['house']}",
                callback_data=f"turnir_finish_{t_id}_{active_parts[0]['house']}"))
        elif len(active_parts) >= 2:
            kb.add(types.InlineKeyboardButton("⚙️ Keyingi raundni yaratish",
                                               callback_data=f"turnir_nextround_{t_id}"))
    elif t["status"] == "finished":
        winner = t["winner_house"] or "Noma'lum"
        txt += f"\n\n🏆 <b>G'olib:</b> {winner}"
    kb.add(types.InlineKeyboardButton("⬅️ Orqaga", callback_data=back_target))
    bot.send_message(c.message.chat.id, txt, reply_markup=kb)
    bot.answer_callback_query(c.id)


@bot.callback_query_handler(func=lambda c: c.data.startswith("turnir_start_"))
def cb_turnir_start(c):
    t_id = int(c.data[len("turnir_start_"):])
    conn = db()
    t = conn.execute("SELECT * FROM tournaments WHERE id=?", (t_id,)).fetchone()
    if not t or not can_manage_tournament(c.from_user.id, t):
        conn.close()
        bot.answer_callback_query(c.id, "Topilmadi yoki bu turnir sizga tegishli emas.", show_alert=True)
        return
    back_target = "a_turnir" if is_admin(c.from_user.id) else "m_ritserlik"
    try:
        parts = conn.execute(
            "SELECT house FROM tournament_participants WHERE tournament_id=? AND status='active'",
            (t_id,)).fetchall()
        if t["status"] != "signup":
            conn.close()
            bot.answer_callback_query(c.id, "Turnir allaqachon boshlangan yoki topilmadi.", show_alert=True)
            return
        houses = [p["house"] for p in parts]
        if len(houses) < 2:
            conn.close()
            bot.answer_callback_query(c.id, "Kamida 2 ta ishtirokchi kerak.", show_alert=True)
            return
        random.shuffle(houses)
        now = time.time()
        conn.execute("UPDATE tournaments SET status='active', started_at=? WHERE id=?", (now, t_id))
        # 1-raund juftliklarini yaratish
        new_match_ids = []
        for i in range(0, len(houses) - 1, 2):
            conn.execute(
                "INSERT INTO tournament_matches (tournament_id, house1, house2, round, status, created_at) VALUES (?,?,?,1,'pending',?)",
                (t_id, houses[i], houses[i + 1], now))
            new_match_ids.append(conn.execute("SELECT last_insert_rowid() AS id").fetchone()["id"])
        if len(houses) % 2 == 1:
            # Toq son — oxirgi o'yinchi avtomatik keyingi raundga
            bye_house = houses[-1]
            conn.execute(
                "UPDATE tournament_participants SET status='bye' WHERE tournament_id=? AND house=?",
                (t_id, bye_house))
        conn.commit()
        conn.close()
    except Exception as e:
        try:
            conn.close()
        except Exception as _e:
            _swallow(_e)
        print("turnir_start xatosi:", e)
        bot.answer_callback_query(c.id, "Turnirni boshlashda xatolik yuz berdi. Qaytadan urinib ko'ring.", show_alert=True)
        return
    bot.answer_callback_query(c.id, "Turnir boshlandi!")
    bot.send_message(c.message.chat.id,
        f"✅ Turnir #{t_id} boshlandi! 1-raund janglari avtomatik boshlanmoqda (ritserlik duel tizimi).",
        reply_markup=back_button(back_target))
    # Ishtirokchilarga xabar
    _turnir_notify_all_participants(t_id, "🏇 <b>Turnir boshlandi!</b> Janglaringiz boshlanmoqda. Natijalarni kuting.")
    houses_list = "\n".join(f"🐺 {lord_full_name(h)}" for h in houses)
    prize_text = f"{t['prize_amount']} {RESOURCE_EMOJI.get(t['prize_resource'],'')} {RESOURCE_LABEL.get(t['prize_resource'], t['prize_resource'])}"
    post_to_channel(tournament_open_text(t, houses_list, prize_text))
    for mid in new_match_ids:
        try:
            start_tournament_duel(mid)
        except Exception as e:
            print("start_tournament_duel xatosi:", e)


def _turnir_notify_all_participants(t_id, text):
    conn = db()
    parts = conn.execute(
        "SELECT house FROM tournament_participants WHERE tournament_id=?", (t_id,)).fetchall()
    houses_data = [conn.execute("SELECT owner_id FROM houses WHERE name=?", (p["house"],)).fetchone()
                   for p in parts]
    conn.close()
    for h in houses_data:
        if h and h["owner_id"]:
            notify(h["owner_id"], text)


