@bot.callback_query_handler(func=lambda c: c.data.startswith("turnir_win_"))
def cb_turnir_win(c):
    payload = c.data[len("turnir_win_"):]
    match_id_str, winner = payload.split("_", 1)
    match_id = int(match_id_str)
    conn = db()
    match = conn.execute("SELECT * FROM tournament_matches WHERE id=?", (match_id,)).fetchone()
    t = conn.execute("SELECT * FROM tournaments WHERE id=?", (match["tournament_id"],)).fetchone() if match else None
    if not match or not is_admin(c.from_user.id):
        conn.close()
        bot.answer_callback_query(c.id, "Majburiy natija faqat admin tomonidan kiritilishi mumkin.", show_alert=True)
        return
    if match["status"] != "pending":
        conn.close()
        bot.answer_callback_query(c.id, "Bu jang allaqachon tugagan.", show_alert=True)
        return
    try:
        loser = match["house2"] if winner == match["house1"] else match["house1"]
        conn.execute("UPDATE tournament_matches SET winner=?, status='finished' WHERE id=?", (winner, match_id))
        conn.execute("UPDATE tournament_participants SET status='eliminated' WHERE tournament_id=? AND house=?",
                     (match["tournament_id"], loser))
        # Agar shu jangga bog'langan avtomatik duel hali faol bo'lsa, uni bekor qilamiz
        # (natija endi qo'lda kiritildi — ikki marta hal qilinmasligi uchun).
        if match["duel_id"]:
            conn.execute("UPDATE duels SET status='cancelled' WHERE id=? AND status='active'", (match["duel_id"],))
        conn.commit()
        t_id = match["tournament_id"]
        # Natijani ishtirokchilarga yuborish
        winner_h = conn.execute("SELECT owner_id FROM houses WHERE name=?", (winner,)).fetchone()
        loser_h = conn.execute("SELECT owner_id FROM houses WHERE name=?", (loser,)).fetchone()
        if winner_h and winner_h["owner_id"]:
            notify(winner_h["owner_id"], f"🏆 Turnir jangida <b>{loser}</b> ni yengdingiz! Keyingi raundga o'tdingiz.")
        if loser_h and loser_h["owner_id"]:
            notify(loser_h["owner_id"], f"💀 Turnir jangida <b>{winner}</b> ga yutqazdingiz. Turnirdan chiqdingiz.")
        # Qolgan aktiv + bye ishtirokchilarni tekshirish
        remaining = conn.execute(
            "SELECT house FROM tournament_participants WHERE tournament_id=? AND status IN ('active','bye')",
            (t_id,)).fetchall()
        conn.close()
    except Exception as e:
        try:
            conn.close()
        except Exception as _e:
            _swallow(_e)
        print("turnir_win xatosi:", e)
        bot.answer_callback_query(c.id, "Natijani saqlashda xatolik yuz berdi.", show_alert=True)
        return
    back_target = f"turnir_manage_{t_id}"
    bot.answer_callback_query(c.id, f"{winner} g'alaba qildi!")
    bot.send_message(c.message.chat.id,
        f"✅ Natija kiritildi: <b>{winner}</b> g'alaba.\nQolganlar: {len(remaining)} ta",
        reply_markup=back_button(back_target))
    post_to_channel(random.choice(TOURNAMENT_MATCH_TEMPLATES).format(
        round=match["round"], h1=lord_full_name(match["house1"]), h2=lord_full_name(match["house2"]),
        winner=lord_full_name(winner), loser=lord_full_name(loser)))
    # Shu raunddagi barcha janglar tugagan bo'lsa, keyingi bosqichga avtomatik o'tamiz
    _maybe_advance_tournament_round(t_id)


@bot.callback_query_handler(func=lambda c: c.data.startswith("turnir_nextround_"))
def cb_turnir_nextround(c):
    t_id = int(c.data[len("turnir_nextround_"):])
    conn = db()
    t = conn.execute("SELECT * FROM tournaments WHERE id=?", (t_id,)).fetchone()
    if not t or not can_manage_tournament(c.from_user.id, t):
        conn.close()
        bot.answer_callback_query(c.id, "Topilmadi yoki sizga tegishli emas.", show_alert=True)
        return
    back_target = f"turnir_manage_{t_id}"
    # Tugallanmagan matchlar bormi?
    pending = conn.execute(
        "SELECT COUNT(*) AS n FROM tournament_matches WHERE tournament_id=? AND status='pending'",
        (t_id,)).fetchone()
    if pending["n"] > 0:
        conn.close()
        bot.answer_callback_query(c.id, "Avval joriy raundni tugatng.", show_alert=True)
        return
    try:
        # Raund raqamini aniqlash
        last_round = conn.execute(
            "SELECT MAX(round) AS r FROM tournament_matches WHERE tournament_id=?", (t_id,)).fetchone()
        next_round = (last_round["r"] or 0) + 1
        # Aktiv + bye ishtirokchilar
        active = conn.execute(
            "SELECT house, status FROM tournament_participants WHERE tournament_id=? AND status IN ('active','bye')",
            (t_id,)).fetchall()
        houses = [p["house"] for p in active]
        # Bye statusni active ga qaytaramiz
        conn.execute("UPDATE tournament_participants SET status='active' WHERE tournament_id=? AND status='bye'",
                     (t_id,))
        if len(houses) == 1:
            conn.close()
            bot.answer_callback_query(c.id, "G'olib aniqlandi! Turnirni yakunlang.")
            bot.send_message(c.message.chat.id,
                f"🏆 Turnirda yagona o'yinchi qoldi: <b>{houses[0]}</b>. G'olib sifatida e'lon qiling.",
                reply_markup=back_button(back_target))
            return
        random.shuffle(houses)
        now = time.time()
        new_match_ids = []
        for i in range(0, len(houses) - 1, 2):
            conn.execute(
                "INSERT INTO tournament_matches (tournament_id, house1, house2, round, status, created_at) VALUES (?,?,?,?,'pending',?)",
                (t_id, houses[i], houses[i + 1], next_round, now))
            new_match_ids.append(conn.execute("SELECT last_insert_rowid() AS id").fetchone()["id"])
        if len(houses) % 2 == 1:
            bye_house = houses[-1]
            conn.execute("UPDATE tournament_participants SET status='bye' WHERE tournament_id=? AND house=?",
                         (t_id, bye_house))
        conn.commit()
        conn.close()
    except Exception as e:
        try:
            conn.close()
        except Exception as _e:
            _swallow(_e)
        print("turnir_nextround xatosi:", e)
        bot.answer_callback_query(c.id, "Keyingi raundni yaratishda xatolik yuz berdi.", show_alert=True)
        return
    for mid in new_match_ids:
        try:
            start_tournament_duel(mid)
        except Exception as e:
            print("start_tournament_duel xatosi:", e)
    bot.answer_callback_query(c.id, f"{next_round}-raund yaratildi.")
    bot.send_message(c.message.chat.id, f"✅ {next_round}-raund juftliklari yaratildi va janglar avtomatik boshlandi.",
        reply_markup=back_button(back_target))
    _turnir_notify_all_participants(t_id, f"🏇 Turnirda <b>{next_round}-raund</b> boshlandi! Janglaringizni kuting.")


@bot.callback_query_handler(func=lambda c: c.data.startswith("turnir_finish_"))
def cb_turnir_finish(c):
    payload = c.data[len("turnir_finish_"):]
    t_id_str, winner = payload.split("_", 1)
    t_id = int(t_id_str)
    conn = db()
    t = conn.execute("SELECT * FROM tournaments WHERE id=?", (t_id,)).fetchone()
    if not t or not can_manage_tournament(c.from_user.id, t):
        conn.close()
        bot.answer_callback_query(c.id, "Topilmadi yoki sizga tegishli emas.", show_alert=True)
        return
    if t["status"] != "active":
        conn.close()
        bot.answer_callback_query(c.id, "Bu turnir allaqachon yakunlangan.", show_alert=True)
        return
    back_target = "a_turnir" if is_admin(c.from_user.id) else "m_ritserlik"
    try:
        now = time.time()
        conn.execute("UPDATE tournaments SET status='finished', winner_house=?, finished_at=? WHERE id=?",
                     (winner, now, t_id))
        # Mukofotni g'olibga berish (uy tashkil qilgan turnirlarda mukofot
        # allaqachon yaratilishda tashkilotchidan yechib olingan edi — bu yerda
        # faqat g'olibga o'tkaziladi)
        prize_res = t["prize_resource"]
        prize_amt = t["prize_amount"]
        if prize_res == "tanga":
            conn.execute("UPDATE houses SET tanga=tanga+? WHERE name=?", (prize_amt, winner))
        else:
            conn.execute(f"UPDATE houses SET {prize_res}={prize_res}+? WHERE name=?", (prize_amt, winner))
        conn.commit()
        winner_h = conn.execute("SELECT owner_id FROM houses WHERE name=?", (winner,)).fetchone()
        conn.close()
    except Exception as e:
        try:
            conn.close()
        except Exception as _e:
            _swallow(_e)
        print("turnir_finish xatosi:", e)
        bot.answer_callback_query(c.id, "Turnirni yakunlashda xatolik yuz berdi.", show_alert=True)
        return
    bot.answer_callback_query(c.id, "Turnir yakunlandi!")
    if t["organizer_house"]:
        kind_label = f"{t['organizer_house']} oilasi tashkil qilgan"
    else:
        kind_label = "Hududiy" if t["kind"] == "regional" else "Qirollik"
    region_info = f" ({t['region']})" if t["region"] else ""
    finish_text = (f"🏆 <b>{kind_label} Ritserlik Turniri{region_info} yakunlandi!</b>\n\n"
                   f"👑 G'olib: <b>{winner}</b>\n"
                   f"🎁 Mukofot: {prize_amt} {RESOURCE_EMOJI.get(prize_res,'')} "
                   f"{RESOURCE_LABEL.get(prize_res, prize_res)} berildi!")
    bot.send_message(c.message.chat.id, finish_text, reply_markup=back_button(back_target))
    if winner_h and winner_h["owner_id"]:
        notify(winner_h["owner_id"],
               f"🏆 Tabriklaymiz! <b>{winner}</b> turnirda G'OLIB bo'ldi va "
               f"{prize_amt} {RESOURCE_EMOJI.get(prize_res,'')} {RESOURCE_LABEL.get(prize_res, prize_res)} "
               f"mukofot oldi!")
    # Barcha ishtirokchilarga xabar
    _turnir_notify_all_participants(t_id, finish_text)
    post_to_channel(random.choice(TOURNAMENT_FINISH_TEMPLATES).format(winner=lord_full_name(winner)))


