@bot.callback_query_handler(func=lambda c: c.data == "turnir_house_create")
def cb_turnir_house_create(c):
    uid = c.from_user.id
    house = get_house_by_owner(uid)
    if not house:
        bot.answer_callback_query(c.id, "Sizda uy yoʻq.", show_alert=True)
        return
    turnir_house_session[uid] = {"prize": 0, "fee": 0}
    bot.answer_callback_query(c.id)
    msg = bot.send_message(c.message.chat.id,
        f"🏇 <b>O'z turniringizni tashkil qilish</b>\n\n"
        f"Bu turnir butun Westeros bo'ylab (barcha oilalar uchun) e'lon qilinadi.\n"
        f"Mukofot sizning shaxsiy 💰tanga hisobingizdan olinadi va turnir "
        f"tashkil qilinishi bilan darhol yechib qo'yiladi (g'olib chiqqach unga beriladi).\n\n"
        f"Sizda hozir: <b>{house['tanga']}</b> 💰tanga.\n"
        f"🎁 G'olibga qancha tanga mukofot belgilaysiz? (eng kami — {TURNIR_MIN_PRIZE} tanga)")
    bot.register_next_step_handler(msg, process_turnir_house_prize)


def process_turnir_house_prize(m):
    uid = m.from_user.id
    sess = turnir_house_session.get(uid)
    if not sess:
        bot.reply_to(m, "Sessiya topilmadi. Qaytadan boshlang.", reply_markup=main_menu(uid))
        return
    house = get_house_by_owner(uid)
    if not house:
        bot.reply_to(m, "Sizda uy yoʻq.", reply_markup=main_menu(uid))
        return
    try:
        amount = int((m.text or "").strip())
    except ValueError:
        msg = bot.reply_to(m, f"Musbat butun son kiriting (kamida {TURNIR_MIN_PRIZE}):")
        bot.register_next_step_handler(msg, process_turnir_house_prize)
        return
    if amount < TURNIR_MIN_PRIZE:
        msg = bot.reply_to(m, f"Mukofot kamida {TURNIR_MIN_PRIZE} tanga bo'lishi kerak. Qaytadan kiriting:")
        bot.register_next_step_handler(msg, process_turnir_house_prize)
        return
    if amount > house["tanga"]:
        msg = bot.reply_to(m,
            f"Sizda faqat {house['tanga']} 💰tanga bor, {amount} tanga ajrata olmaysiz. Qaytadan kiriting:")
        bot.register_next_step_handler(msg, process_turnir_house_prize)
        return
    sess["prize"] = amount
    kb = types.InlineKeyboardMarkup(row_width=3)
    kb.add(*[types.InlineKeyboardButton(f"{fee} tanga" if fee else "Bepul (0)",
                                        callback_data=f"turnir_house_fee_{fee}")
             for fee in (0, 3, 5, 8, TURNIR_MAX_ENTRY_FEE)])
    bot.reply_to(m,
        f"🎁 Mukofot: <b>{amount}</b> 💰tanga.\n\n"
        f"💰 Qatnashuvchi oilalardan qatnashish badali olasizmi? "
        f"(eng ko'pi — {TURNIR_MAX_ENTRY_FEE} tanga, ixtiyoriy)",
        reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data.startswith("turnir_house_fee_"))
def cb_turnir_house_fee(c):
    uid = c.from_user.id
    sess = turnir_house_session.get(uid)
    if not sess:
        bot.answer_callback_query(c.id, "Sessiya topilmadi.", show_alert=True)
        return
    try:
        fee = int(c.data[len("turnir_house_fee_"):])
    except ValueError:
        fee = 0
    fee = max(0, min(fee, TURNIR_MAX_ENTRY_FEE))
    sess["fee"] = fee
    bot.answer_callback_query(c.id)
    kb = types.InlineKeyboardMarkup(row_width=1)
    kb.add(types.InlineKeyboardButton("✅ Ha, turnirni tashkil qilaman", callback_data="turnir_house_go"))
    kb.add(types.InlineKeyboardButton("❌ Bekor qilish", callback_data="m_ritserlik"))
    fee_text = f"{fee} tanga" if fee else "Bepul"
    bot.send_message(c.message.chat.id,
        f"🏇 <b>Turnir ma'lumotlari:</b>\n"
        f"Turi: Butun Westeros (uy tashkil qilgan)\n"
        f"🎁 Mukofot: {sess['prize']} 💰tanga (hisobingizdan darhol yechiladi)\n"
        f"💰 Qatnashish badali: {fee_text}\n\n"
        f"Tasdiqlaysizmi?", reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data == "turnir_house_go")
def cb_turnir_house_go(c):
    uid = c.from_user.id
    sess = turnir_house_session.pop(uid, None)
    if not sess:
        bot.answer_callback_query(c.id, "Sessiya topilmadi.", show_alert=True)
        return
    house = get_house_by_owner(uid)
    if not house:
        bot.answer_callback_query(c.id, "Sizda uy yoʻq.", show_alert=True)
        return
    prize = sess["prize"]
    fee = sess["fee"]
    try:
        with _lock:
            conn = db()
            fresh = conn.execute("SELECT tanga FROM houses WHERE name=?", (house["name"],)).fetchone()
            if not fresh or fresh["tanga"] < prize:
                conn.close()
                bot.answer_callback_query(c.id, "Tanga yetarli emas.", show_alert=True)
                return
            conn.execute("UPDATE houses SET tanga=tanga-? WHERE name=?", (prize, house["name"]))
            now = time.time()
            conn.execute("""INSERT INTO tournaments (kind, region, prize_resource, prize_amount, status,
                            organizer_house, entry_fee, created_at)
                            VALUES (?,'','tanga',?,'signup',?,?,?)""",
                         ("essos" if house["is_essos"] else "kingdom", prize, house["name"], fee, now))
            t_id = conn.execute("SELECT last_insert_rowid() AS id").fetchone()["id"]
            all_houses = conn.execute(
                "SELECT name, owner_id FROM houses WHERE is_essos=? AND owner_id IS NOT NULL "
                "AND name!=?", (1 if house["is_essos"] else 0, house["name"])).fetchall()
            npc_houses = conn.execute(
                "SELECT name FROM houses WHERE is_essos=? AND owner_id IS NULL",
                (1 if house["is_essos"] else 0,)).fetchall()
            npc_added = 0
            for nh in npc_houses:
                conn.execute(
                    "INSERT INTO tournament_participants (tournament_id, house, status, joined_at) "
                    "VALUES (?,?,'active',?)", (t_id, nh["name"], now))
                npc_added += 1
            # Tashkilotchi avtomatik qo'shiladi (badal to'lamaydi — u tashkilotchi)
            conn.execute(
                "INSERT INTO tournament_participants (tournament_id, house, status, joined_at) "
                "VALUES (?,?,'active',?)", (t_id, house["name"], now))
            conn.commit()
            conn.close()
    except Exception as e:
        print("turnir_house_go xatosi:", e)
        bot.answer_callback_query(c.id, "Turnir tashkil qilishda xatolik yuz berdi.", show_alert=True)
        return
    fee_text = f"{fee} 💰tanga" if fee else "Bepul"
    if house["is_essos"]:
        announce_text = (f"🏇🌊 <b>{house['name']}</b> shahri Buyuk Turnir e'lon qildi!\n"
                         f"Butun Essosdagi barcha shaharlar uchun!\n"
                         f"G'olibga mukofot: <b>{prize} 💰tanga</b>\n"
                         f"Qatnashish badali: <b>{fee_text}</b>\n\n"
                         f"Turnirga qoʻshilasizmi?")
    else:
        announce_text = (f"🏇 <b>{house['name']}</b> oilasi Buyuk Turnir e'lon qildi!\n"
                         f"Butun Westerosdagi barcha oilalar uchun!\n"
                         f"G'olibga mukofot: <b>{prize} 💰tanga</b>\n"
                         f"Qatnashish badali: <b>{fee_text}</b>\n\n"
                         f"Turnirga qoʻshilasizmi?")
    kb_join = types.InlineKeyboardMarkup()
    kb_join.add(
        types.InlineKeyboardButton("⚔️ Ha, qoʻshilaman", callback_data=f"turnir_join_{t_id}"),
        types.InlineKeyboardButton("🚫 Yoʻq", callback_data=f"turnir_skip_{t_id}"),
    )
    sent_count = 0
    for h in all_houses:
        try:
            bot.send_message(h["owner_id"], announce_text, reply_markup=kb_join)
            sent_count += 1
        except Exception as _e:
            _swallow(_e)
    bot.answer_callback_query(c.id, "Turnir tashkil qilindi!")
    bot.send_message(c.message.chat.id,
        f"✅ <b>Turnir #{t_id}</b> tashkil qilindi va {prize} tanga hisobingizdan ajratildi.\n"
        f"{sent_count} ta o'yinchiga taklif yuborildi.\n"
        f"🤖 {npc_added} ta NPC (egasiz) uy avtomatik qoʻshildi.\n\n"
        f"Yetarli o'yinchi qo'shilgach, turniringizni '🛡️ Ritserlik' menyusidan boshqarishingiz mumkin.",
        reply_markup=back_button("m_ritserlik"))
    post_to_channel(f"📯 <b>{lord_full_name(house['name'])}</b> {house_seat(house['name'])}da "
                    f"Buyuk Turnir e'lon qildi! Barcha ritserlar {house_seat(house['name'])}ga yig'ilmoqda. "
                    f"G'olibga {prize} 💰tanga va'da qilindi.")


