@bot.callback_query_handler(func=lambda c: c.data == "a_fullreset_go")
def cb_a_fullreset_go(c):
    if not is_admin(c.from_user.id):
        return
    conn = db()
    # --- TO'LIQ TOZALASH: o'yin bilan bog'liq BARCHA jadvallar tozalanadi,
    #     aks holda ba'zi jadvallarda (masalan "knights") eski yozuvlar
    #     qolib ketib, o'yinchilar reset keyin ham eski uy/holatiga bog'liq
    #     bo'lib qolishi mumkin edi (masalan sobiq mustaqil ritser yozuvi
    #     saqlanib qolgani uchun ba'zan eski uyga qaytarilardi). Shu bilan
    #     birga daraja (tier), urush va boshqa hamma narsa 100% boshlang'ich
    #     holatga qaytishi kafolatlanadi. ---
    _tables = conn.execute(
        "SELECT name FROM sqlite_master "
        "WHERE type='table' AND name NOT LIKE 'sqlite_%'").fetchall()
    for _table_row in _tables:
        _tbl = _table_row["name"]
        if _tbl == "blocked_users":
            continue   # bloklanganlar o'yin reset bo'lsa ham saqlanadi
        try:
            conn.execute(f'DELETE FROM "{_tbl}"')
        except Exception as e:
            print(f"fullreset: {_tbl} tozalashda xatolik: {e}")
    conn.commit()
    conn.close()
    init_db()

    # Yangi o'yin barcha oilalar uchun mutlaqo bo'sh boshlanadi. init_db()
    # oddiy ishga tushishda PRODUCTION qiymatlarini urug'laydi, shuning uchun
    # full resetdan keyin resurslarni alohida nolga tushiramiz.
    conn2 = db()
    house_columns = {
        row["name"] for row in conn2.execute("PRAGMA table_info(houses)").fetchall()
    }
    zero_columns = (
        "owner_id", "tanga", "qoshin", "kamonchi", "otliq", "kema", "benuqson",
        "kenja_ogil", "valyria_polati", "ritsarlik", "siyosat", "special",
        "alliance_with", "alliance_until", "vassal_of", "last_income",
        "tax_exempt", "income_bonus", "castle_daily_income", "is_free_knight",
        "wars_won", "wars_lost", "divorce_until", "last_lord_isyon",
        "last_king_isyon",
    )
    reset_values = {
        "owner_id": None,
        "tanga": 0,
        "qoshin": 0,
        "kamonchi": 0,
        "otliq": 0,
        "kema": 0,
        "benuqson": 0,
        "kenja_ogil": 0,
        "valyria_polati": 0,
        "ritsarlik": 0,
        "siyosat": 0,
        "special": "{}",
        "alliance_with": "",
        "alliance_until": 0,
        "vassal_of": "",
        "last_income": 0,
        "tax_exempt": 0,
        "income_bonus": 0,
        "castle_daily_income": 0,
        "is_free_knight": 0,
        "wars_won": 0,
        "wars_lost": 0,
        "divorce_until": 0,
        "last_lord_isyon": 0,
        "last_king_isyon": 0,
    }
    assignments = [f"{column}=?" for column in zero_columns if column in house_columns]
    values = [reset_values[column] for column in zero_columns if column in house_columns]
    conn2.execute(f"UPDATE houses SET {', '.join(assignments)}", values)

    # Har bir foydalanuvchi yangi o'yinda ism/jins/uy tanlovini ham boshidan
    # boshlaydi. Admin esa uy egasi sifatida avtomatik qayta biriktirilmaydi.
    conn2.execute("DELETE FROM users")
    conn2.execute("DELETE FROM regions")
    for region, lord in REGION_LORDS_INIT.items():
        conn2.execute(
            "INSERT INTO regions (region, lord_house) VALUES (?, ?)",
            (region, lord))
    for _tbl in ("nk_attacks", "sea_claims", "sea_claim_responses"):
        try:
            conn2.execute(f"DELETE FROM {_tbl}")
        except Exception as _e:
            _swallow(_e)
    conn2.execute("DELETE FROM world")
    conn2.execute("INSERT INTO world (key, value) VALUES ('king', 'Targaryen')")
    conn2.execute("INSERT INTO world (key, value) VALUES ('game_frozen', '0')")
    conn2.commit()
    conn2.close()
    _set_game_frozen(False)
    war_session.clear()
    def_session.clear()
    help_session.clear()
    turnir_session.clear()
    trade_session.clear()
    admin_session.clear()
    try:
        bannerlord_session.clear()
    except Exception as _e:
        _swallow(_e)
    try:
        white_walker_session.clear()
    except Exception as _e:
        _swallow(_e)
    try:
        vacant_house_state.clear()
    except Exception as _e:
        _swallow(_e)
    bot.answer_callback_query(c.id, "Oʻyin qayta boshlandi.")
    bot.send_message(c.message.chat.id,
        "💣 Butun oʻyin boshlangʻich holatiga qaytarildi! Barcha uylar boʻsh, Targaryen qirol, "
        "hamma hudud lordlari, darajalar (toifalar) va urushlar asl holatida. Foydalanuvchilar "
        "/start orqali qaytadan uy tanlashlari kerak.",
        reply_markup=back_button())


