@bot.callback_query_handler(func=lambda c: c.data == "a_endgame_go")
def cb_a_endgame_go(c):
    if not is_admin(c.from_user.id):
        return
    king_name = get_king()
    if not king_name:
        bot.answer_callback_query(c.id, "Qirol tayinlanmagan.", show_alert=True)
        return
    conn = db()
    best_knight = conn.execute(
        "SELECT name, ritsarlik FROM houses WHERE is_essos=0 ORDER BY ritsarlik DESC, name ASC LIMIT 1").fetchone()
    best_politician = conn.execute(
        "SELECT name, siyosat FROM houses WHERE is_essos=0 ORDER BY siyosat DESC, name ASC LIMIT 1").fetchone()
    conn.close()

    lines = [
        "🏆 <b>OʻYIN TUGADI!</b>",
        "",
        "Uzoq davom etgan kurashlar, ittifoqlar va xiyonatlardan soʻng Vesteros nihoyat "
        "yangi tartibga keldi.",
        "",
        f"👑 Temir taxtda oʻtirgan <b>{lord_full_name(king_name)}</b> uyi — oʻyinning yakuniy gʻolibi boʻldi!",
    ]
    if best_knight and best_knight["ritsarlik"] > 0:
        lines.append(f"🛡️ Eng yaxshi ritser — <b>{lord_full_name(best_knight['name'])}</b> "
                      f"({best_knight['ritsarlik']} ball).")
    if best_politician and best_politician["siyosat"] > 0:
        lines.append(f"🏛️ Eng yaxshi siyosatchi — <b>{lord_full_name(best_politician['name'])}</b> "
                      f"({best_politician['siyosat']} ball).")
    lines.append("")
    lines.append("Barchaga rahmat — ushbu taxtlar oʻyini shu bilan yakunlandi! 🐺🦁🐉")

    post_to_channel("\n".join(lines))
    _set_game_frozen(True)
    bot.answer_callback_query(c.id, "Oʻyin tugatildi.")
    bot.send_message(c.message.chat.id, "🏁 Oʻyin tugatildi va kanalga eʼlon qilindi. Oʻyin muzlatildi.",
                      reply_markup=back_button())


