@bot.callback_query_handler(func=lambda c: c.data.startswith("areset_go_"))
def cb_areset_go(c):
    if not is_admin(c.from_user.id):
        return
    name = c.data[len("areset_go_"):]
    conn = db()
    old = conn.execute("SELECT * FROM houses WHERE name=?", (name,)).fetchone()
    if not old:
        conn.close()
        bot.answer_callback_query(c.id, "Bu uy topilmadi.", show_alert=True)
        return
    old_owner_id = old["owner_id"] if old else None
    old_ally = old["alliance_with"] if old else ""

    prod = PRODUCTION.get(name)
    essos_res = ESSOS_CITIES.get(name)
    if prod:
        region, tier, tanga, qoshin, kamonchi, otliq, kema, benuqson, kenja_ogil = prod
        valyria_polati = 0
        extra_res = {}
    elif essos_res is not None:
        # Essos shahri — ESSOS_CITIES lug'atidagi boshlang'ich resurslarga qaytariladi.
        region, tier = "Essos", "-"
        tanga = essos_res.get("tanga", 0)
        qoshin = essos_res.get("qoshin", 0)
        kamonchi = essos_res.get("kamonchi", 0)
        otliq = essos_res.get("otliq", 0)
        kema = essos_res.get("kema", 0)
        benuqson = essos_res.get("benuqson", 0)
        kenja_ogil = essos_res.get("kenja_ogil", 0)
        valyria_polati = essos_res.get("valyria_polati", 0)
        # Essosga xos maxsus resurslar (yuzsiz_qotil, zahar, ziddizahar, qizil_jodugar)
        extra_res = {k: v for k, v in essos_res.items() if k not in
                     ("tanga", "qoshin", "kamonchi", "otliq", "kema", "benuqson", "kenja_ogil", "valyria_polati")}
    else:
        # V18: ritser qurgan vassal qal'a kabi asl PRODUCTION lug'atida
        # yo'q uylar uchun — hozirgi hudud/darajasi saqlanadi (o'zgarmaydi),
        # resurslari esa 0 ga tushiriladi (haqiqiy "boshlang'ich" qiymati yo'q).
        region, tier = old["region"], old["tier"]
        tanga = qoshin = kamonchi = otliq = kema = benuqson = kenja_ogil = valyria_polati = 0
        extra_res = {}

    # --- Uyning o'zini to'liq boshlang'ich holatga qaytarish ---
    conn.execute("""UPDATE houses SET region=?, tier=?, owner_id=NULL, tanga=?, qoshin=?, kamonchi=?,
                    otliq=?, kema=?, benuqson=?, kenja_ogil=?, valyria_polati=?, ritsarlik=0, siyosat=0,
                    alliance_with='', alliance_until=0, vassal_of='', last_income=? WHERE name=?""",
                 (region, tier, tanga, qoshin, kamonchi, otliq, kema, benuqson, kenja_ogil, valyria_polati,
                  time.time(), name))
    for res_name, res_amount in extra_res.items():
        try:
            conn.execute(f"UPDATE houses SET {res_name}=? WHERE name=?", (res_amount, name))
        except Exception as _e:
            _swallow(_e)

    # --- BOG'LIQ MA'LUMOTLARNI TOZALASH (avvalgi versiyada bular unutilgan edi) ---
    # 1) Ittifoqdoshi bo'lgan uyning ham ittifoq maydonini tozalash.
    if old_ally:
        conn.execute("UPDATE houses SET alliance_with='', alliance_until=0 WHERE name=? AND alliance_with=?",
                     (old_ally, name))
    # 2) Ushbu uyga yoki undan yuborilgan barcha kutilayotgan ittifoq takliflari.
    conn.execute("DELETE FROM pending_alliance WHERE from_house=? OR to_house=?", (name, name))
    # 3) Agar boshqa uylar shu uyning vassali bo'lsa, ular endi ozod bo'ladi.
    conn.execute("UPDATE houses SET vassal_of='' WHERE vassal_of=?", (name,))
    # 4) Ushbu uy ishtirok etgan kutilayotgan (hali hal bo'lmagan) hujumlarni bekor qilish.
    conn.execute("UPDATE pending_attacks SET status='cancelled' WHERE status='pending' AND (attacker=? OR defender=?)",
                 (name, name))
    # 6) V9: ushbu uyga tegishli bir martalik ruxsatlar, port ijaralari va
    #    safarbarlik yozuvlarini ham tozalash.
    conn.execute("DELETE FROM land_permits WHERE house=? OR target_house=? OR gate=?", (name, name, name))
    conn.execute("DELETE FROM port_leases WHERE house=? OR gate=?", (name, name))
    conn.execute("UPDATE muster_campaigns SET status='dispersed' WHERE lord_house=? AND status='active'", (name,))
    conn.execute("UPDATE muster_contributions SET status='returned' WHERE vassal_house=? AND status='active'", (name,))
    # 5) Ushbu uy ishtirok etgan kutilayotgan savdo takliflarini bekor qilish.
    conn.execute("UPDATE trade_offers SET status='cancelled' WHERE status='pending' AND (from_house=? OR to_house=?)",
                 (name, name))
    conn.commit()
    conn.close()
    bot.answer_callback_query(c.id, "Bajarildi.")
    bot.send_message(c.message.chat.id,
        f"♻️ <b>{name}</b> boshlang'ich holatga qaytarildi (ittifoq, vassallik, kutilayotgan hujum/savdolar ham tozalandi).",
        reply_markup=back_button())
    if old_owner_id:
        notify(old_owner_id, f"♻️ Admin <b>{name}</b> uyini boshlang'ich holatga qaytardi. Siz endi bu uyning lordi emassiz.")


