@bot.callback_query_handler(func=lambda c: c.data.startswith("vh_yes_"))
def cb_vh_yes(c):
    uid = c.from_user.id
    house_name = c.data[len("vh_yes_"):]
    house = get_house(house_name)
    if not house:
        bot.answer_callback_query(c.id, "Bu xonadon topilmadi.", show_alert=True)
        return
    knight = get_knight(uid)
    if not knight:
        bot.answer_callback_query(c.id, "Siz mustaqil ritser emassiz.", show_alert=True)
        return
    conn = db()
    cur = conn.execute("UPDATE houses SET owner_id=? WHERE name=? AND owner_id IS NULL", (uid, house_name))
    conn.commit()
    if cur.rowcount == 0:
        conn.close()
        bot.answer_callback_query(c.id, "Uzr, bu xonadonga boshqa lord tayinlandi.", show_alert=True)
        bot.send_message(c.message.chat.id,
            f"🚫 Uzr, <b>{house_name}</b> xonadoniga sizdan oldin boshqa lord tayinlandi.",
            parse_mode="HTML")
        return
    conn.execute("DELETE FROM knights WHERE user_id=?", (uid,))
    conn.execute("DELETE FROM houses WHERE owner_id=? AND is_free_knight=1", (uid,))
    conn.commit()
    conn.close()
    vacant_house_state.pop(house_name, None)
    bot.answer_callback_query(c.id, "🎉 Siz endi lordsiz!", show_alert=True)
    bot.send_message(c.message.chat.id,
        f"🎉 Tabriklaymiz! Endi siz <b>{house_name}</b> xonadonining yangi lordisiz!",
        reply_markup=main_menu(uid), parse_mode="HTML")
    post_to_channel(f"👑 Mustaqil ritser <b>{get_user_name(uid) or 'Ritser'}</b> "
                    f"<b>{house_name}</b> xonadonining yangi lordi boʻldi!")


@bot.callback_query_handler(func=lambda c: c.data.startswith("vh_no_"))
def cb_vh_no(c):
    uid = c.from_user.id
    house_name = c.data[len("vh_no_"):]
    bot.answer_callback_query(c.id, "Taklif rad etildi.")
    bot.send_message(c.message.chat.id, f"🚫 <b>{house_name}</b> lordligini rad etdingiz.", parse_mode="HTML")
    state = vacant_house_state.get(house_name)
    if not state:
        return
    state["responded_no"].add(uid)
    house = get_house(house_name)
    if not house or house["owner_id"]:
        # Bu orada allaqachon lord tayinlangan — endi hech narsa qilish shart emas.
        vacant_house_state.pop(house_name, None)
        return
    # Agar shu bosqichda taklif yuborilgan barcha ritserlar rad etgan boʻlsa
    # va hali kengaytirilmagan boʻlsa — taklifni QOLGAN barcha mustaqil
    # ritserlarga kengaytiramiz.
    if not state["widened"] and state["regional_uids"] and state["regional_uids"] <= state["responded_no"]:
        _offer_vacant_house_to_knights(house_name, widen=True)


def process_admin_text(m):
    uid = m.from_user.id
    if not is_admin(uid):
        return
    sess = admin_session.get(uid)
    if not sess:
        bot.reply_to(m, "Amaliyot topilmadi, qaytadan boshlang.", reply_markup=main_menu(uid))
        return
    action = sess["action"]
    name = sess["house"]
    if not get_house(name):
        bot.reply_to(m, "Uy topilmadi.")
        admin_session.pop(uid, None)
        return
    if action == "make_knight":
        try:
            target_uid = int((m.text or "").strip())
        except ValueError:
            bot.reply_to(m, "user_id son boʻlishi kerak. Qaytadan yuboring.")
            return
        if is_night_king(target_uid):
            bot.reply_to(m, "❌ Bu foydalanuvchi Tun qiroli — uy lordi bo'la olmaydi. "
                             "Avval Tun qirolini olib tashlang.")
            return
        ok, text = make_independent_knight(target_uid, name)
        bot.reply_to(m, text, reply_markup=back_button(), parse_mode="HTML")
        if ok:
            try:
                notify(target_uid,
                    f"⚔️ Admin sizni <b>{name}</b> lordligining mustaqil ritseri qilib "
                    f"tayinladi!\n\nEndi boshqa o'yinchilar kabi asosiy menyudan foydalanib "
                    f"savdo, hayvon, hudud topshirig'i va temir bank bo'limlaridan "
                    f"foydalanishingiz mumkin. \"🏗 Qasrni yuksaltirish\" bo'limidan "
                    f"{KNIGHT_CASTLE_COST} tangaga o'zingizga qal'a qurib to'liq lord "
                    f"bo'lishingiz ham mumkin!")
            except Exception as _e:
                _swallow(_e)
        admin_session.pop(uid, None)
        return
    if action == "biriktir":
        try:
            target_uid = int((m.text or "").strip())
        except ValueError:
            bot.reply_to(m, "user_id son boʻlishi kerak. Qaytadan yuboring.")
            return
        if is_night_king(target_uid):
            bot.reply_to(m, "❌ Bu foydalanuvchi Tun qiroli — uy lordi bo'la olmaydi. "
                             "Avval Tun qirolini olib tashlang.")
            return
        conn = db()
        # --- MUHIM TUZATISH: agar bu foydalanuvchida allaqachon BOSHQA uy
        # biriktirilgan boʻlsa, avval o'sha eski uydan owner_id ni tozalash
        # kerak — aks holda foydalanuvchi bir vaqtning o'zida IKKITA uyga
        # egalik qilib qoladi va ikkalasi uchun ham soliq/daromad olib,
        # 2 MARTA soliq toʻlab qoladi (masalan avval Greyjoy, keyin Stark). ---
        old_house = conn.execute(
            "SELECT name, is_free_knight FROM houses WHERE owner_id=? AND name!=?", (target_uid, name)).fetchone()
        if old_house:
            if old_house.get("is_free_knight"):
                # Yersiz ritser "qobig'i" — endi haqiqiy uyga ega bo'lgani
                # uchun bu qator butunlay o'chiriladi (bo'sh holda qolsa
                # keyinchalik boshqa o'yinchiga xato biriktirilib qolishi mumkin).
                conn.execute("DELETE FROM houses WHERE name=?", (old_house["name"],))
            else:
                conn.execute("UPDATE houses SET owner_id=NULL WHERE name=?", (old_house["name"],))
        conn.execute("UPDATE houses SET owner_id=? WHERE name=?", (target_uid, name))
        conn.execute("DELETE FROM knights WHERE user_id=?", (target_uid,))
        conn.commit()
        conn.close()
        if old_house:
            bot.reply_to(m, f"✅ {name} endi user_id={target_uid} ga biriktirildi "
                             f"(oldingi uyi <b>{old_house['name']}</b> dan avtomatik olib qoʻyildi, "
                             f"u endi NPC boshqaruviga qaytdi).", reply_markup=back_button())
            notify(target_uid, f"ℹ️ Admin sizni <b>{old_house['name']}</b> uyidan <b>{name}</b> uyiga oʻtkazdi.")
        else:
            bot.reply_to(m, f"✅ {name} endi user_id={target_uid} ga biriktirildi.", reply_markup=back_button())
    elif action == "resurs":
        resource = sess["field"]
        try:
            amount = int((m.text or "").strip())
        except ValueError:
            bot.reply_to(m, "Butun son kiriting (masalan +50 yoki -20).")
            return
        conn = db()
        conn.execute(f"UPDATE houses SET {resource} = MAX({resource}+?,0) WHERE name=?", (amount, name))
        conn.commit()
        conn.close()
        bot.reply_to(m, f"✅ {name} {resource} {amount:+} oʻzgartirildi.", reply_markup=back_button())
    elif action == "ball":
        field = sess["field"]
        try:
            amount = int((m.text or "").strip())
        except ValueError:
            bot.reply_to(m, "Butun son kiriting.")
            return
        conn = db()
        conn.execute(f"UPDATE houses SET {field} = MAX({field}+?,0) WHERE name=?", (amount, name))
        conn.commit()
        conn.close()
        bot.reply_to(m, f"✅ {name} {field} {amount:+}.", reply_markup=back_button())
    admin_session.pop(uid, None)


# ---------------------------------------------------------------------------
# RITSERLIK — PVP / PVE DUEL O'YINI
# ---------------------------------------------------------------------------
# Qoidalar:
#  - Har ikkala tomonda 3 jondan boshlanadi (DUEL_LIVES).
#  - Har raundda o'yinchi (1) qayerga zarba berishni va (2) qayerini
#    himoya qilishni tanlaydi (tana/bosh/qo'l/oyoq). 60 soniya berilib,
#    tanlanmasa avtomatik (tasodifiy) tanlanadi.
#  - Agar hujumchining zarbasi raqib TOʻSMAGAN joyga tegsa — raqib 1 jon
#    yoʻqotadi. Toʻsilgan boʻlsa — jon ketmaydi.
#  - Ritsar qilichi / Valyria poʻlati / Qalqon / Tong qilichi kabi buyumlar
#    natijaga OZGINA (kichik foizli) bonus beradi, lekin hal qiluvchi emas.
#  - Har bir g'alaba/mag'lubiyat "ritsarlik" (umumiy) va "ritsarlik_week"
#    (haftalik) ballariga ta'sir qiladi. Hafta oxirida eng koʻp haftalik
#    ball toʻplagan uyga 7 kunga "Tong qilichi" beriladi.

duel_lock = _GameLock("duel_lock")   # qayta kiruvchi, egasi kuzatiladi


def get_active_duel_for_uid(uid):
    conn = db()
    row = conn.execute(
        "SELECT * FROM duels WHERE status='active' AND (p1_uid=? OR p2_uid=?) ORDER BY id DESC LIMIT 1",
        (uid, uid)).fetchone()
    conn.close()
    return row


def get_duel(duel_id):
    conn = db()
    row = conn.execute("SELECT * FROM duels WHERE id=?", (duel_id,)).fetchone()
    conn.close()
    return row


def duel_item_bonus(house_row):
    """house_row bo'lishi shart emas (PVE bot uchun None -> bonus yo'q)."""
    if house_row is None:
        return 0.0, 0.0
    atk = 0.0
    defn = 0.0
    for item, eff in DUEL_ITEM_BONUS.items():
        try:
            has = house_row[item] and house_row[item] > 0
        except (IndexError, KeyError):
            has = False
        if has:
            atk += eff.get("atk", 0.0)
            defn += eff.get("def", 0.0)
    if house_row["tong_qilichi_until"] and house_row["tong_qilichi_until"] > time.time():
        atk += DUEL_TONG_QILICHI_ATK_BONUS
    return min(atk, DUEL_MAX_ATK_BONUS), min(defn, DUEL_MAX_DEF_BONUS)


def _ritserlik_pvp_today():
    return time.strftime("%Y-%m-%d")


def _ritserlik_pvp_count_today(house_name):
    conn = db()
    row = conn.execute("SELECT count FROM ritserlik_pvp_log WHERE house=? AND day=?",
                        (house_name, _ritserlik_pvp_today())).fetchone()
    conn.close()
    return row["count"] if row else 0


def _ritserlik_pvp_increment(house_name):
    conn = db()
    conn.execute(
        "INSERT INTO ritserlik_pvp_log (house, day, count) VALUES (?,?,1) "
        "ON CONFLICT(house, day) DO UPDATE SET count = count + 1",
        (house_name, _ritserlik_pvp_today()))
    conn.commit()
    conn.close()


