def log_history(event_type, house, detail):
    """Tarix jurnalga voqea yozadi."""
    try:
        conn = db()
        conn.execute(
            "INSERT INTO history_log (event_type, house, detail, logged_at) VALUES (?,?,?,?)",
            (event_type, house, detail, time.time()))
        conn.commit()
        conn.close()
    except Exception as _e:
        _swallow(_e)


def _count_unread_mail(house_name):
    """O'qilmagan xatlar sonini qaytaradi."""
    if not house_name:
        return 0
    conn = db()
    row = conn.execute(
        "SELECT COUNT(*) AS n FROM mailbox WHERE to_house=? AND is_read=0",
        (house_name,)).fetchone()
    conn.close()
    return row["n"] if row else 0


def get_council():
    """Kengash a'zolarini {position: house} ko'rinishida qaytaradi."""
    conn = db()
    rows = conn.execute("SELECT position, house FROM council").fetchall()
    conn.close()
    return {r["position"]: r["house"] for r in rows}


def get_council_position(house_name):
    """Uy kengashda qaysi lavozimda ekanini qaytaradi yoki None."""
    conn = db()
    row = conn.execute("SELECT position FROM council WHERE house=?", (house_name,)).fetchone()
    conn.close()
    return row["position"] if row else None


def is_council_member(house_name, position):
    conn = db()
    row = conn.execute(
        "SELECT 1 FROM council WHERE position=? AND house=?", (position, house_name)).fetchone()
    conn.close()
    return bool(row)


