# 2. JOSUSLIK TIZIMI
# ---------------------------------------------------------------------------

SPY_MISSION_DURATION = {
    "razvedka": 30 * 60,   # 30 daqiqa
    "sabotaj":  60 * 60,   # 60 daqiqa
}
SPY_CATCH_CHANCE = {
    "razvedka": 0.50,   # 50% tutilish
    "sabotaj":  0.65,   # 65% tutilish
}
SPY_COST = {
    "razvedka": 100,    # tanga
    "sabotaj":  150,    # tanga
}

_josus_session = {}   # uid -> {"target": str, "type": str}


def check_spy_missions():
    """Vaqti tugagan josuslik missiyalarini hal qiladi."""
    now = time.time()
    conn = db()
    for mtype, dur in SPY_MISSION_DURATION.items():
        done = conn.execute(
            "SELECT * FROM spy_missions WHERE status='active' AND mission_type=? AND started_at<=?",
            (mtype, now - dur)).fetchall()
        for m in done:
            try:
                _resolve_spy_mission(m["id"])
            except Exception as e:
                print(f"josus missiya xatosi (id={m['id']}):", e)
    conn.close()


def _resolve_spy_mission(mission_id):
    conn = db()
    m = conn.execute("SELECT * FROM spy_missions WHERE id=?", (mission_id,)).fetchone()
    if not m or m["status"] != "active":
        conn.close()
        return

    spy_name = m["spy_house"]
    target_name = m["target_house"]
    mtype = m["mission_type"]
    spy = conn.execute("SELECT * FROM houses WHERE name=?", (spy_name,)).fetchone()
    target = conn.execute("SELECT * FROM houses WHERE name=?", (target_name,)).fetchone()

    catch_chance = SPY_CATCH_CHANCE.get(mtype, 0.2)
    if is_council_member(spy_name, "josuslar_boshi"):
        catch_chance = max(catch_chance - 0.20, 0.05)

    caught = random.random() < catch_chance

    if caught:
        result = "tutildi"
        conn.execute("UPDATE spy_missions SET status='caught', result=? WHERE id=?",
                     (result, mission_id))
        conn.commit()
        conn.close()
        spy_h = get_house(spy_name)
        target_h = get_house(target_name)
        if spy_h and spy_h["owner_id"]:
            notify(spy_h["owner_id"],
                   f"🚨 Josuslaringiz <b>{target_name}</b> da tutildi! Missiya muvaffaqiyatsiz.")
        if target_h and target_h["owner_id"]:
            notify(target_h["owner_id"],
                   f"🚨 <b>{spy_name}</b> dan josus tutdingiz! Ular sizni razvedka qilmoqchi edi.")
        return

    # Muvaffaqiyatli missiya
    result_text = ""
    if mtype == "razvedka":
        if target:
            lines = [f"💰 Tanga: {target['tanga']}", f"⚔️ Qo'shin: {target['qoshin']}",
                     f"🏹 Kamonchi: {target['kamonchi']}", f"🐎 Otliq: {target['otliq']}",
                     f"🗡️ Benuqson: {target['benuqson']}", f"⛵ Kema: {target['kema']}",
                     f"🔱 Valyria po'lati: {target['valyria_polati']}"]
            result_text = "\n".join(lines)
    elif mtype == "sabotaj":
        res_list = ["tanga", "qoshin", "kamonchi", "otliq", "benuqson"]
        target_res = random.choice(res_list)
        cur = target[target_res] if target else 0
        destroyed = max(1, int(cur * 0.15))
        # BUG FIX: conn2 o'rniga asosiy conn ishlatiladi — ikki xil connection
        # bir vaqtda yozsa ma'lumot yo'qolishi (race condition) oldini oladi.
        conn.execute(f"UPDATE houses SET {target_res}=MAX({target_res}-?,0) WHERE name=?",
                     (destroyed, target_name))
        label = RESOURCE_LABEL.get(target_res, target_res)
        result_text = f"Sabotaj: {target_name} dan {destroyed} {label} yo'q qilindi."

    conn.execute("UPDATE spy_missions SET status='success', result=? WHERE id=?",
                 (result_text, mission_id))
    conn.commit()
    conn.close()

    spy_h = get_house(spy_name)
    if spy_h and spy_h["owner_id"]:
        if mtype == "razvedka":
            notify(spy_h["owner_id"],
                   f"🕵️ <b>Razvedka muvaffaqiyatli!</b>\n\n<b>{target_name}</b> resurslari:\n{result_text}")
        else:
            notify(spy_h["owner_id"],
                   f"🕵️ <b>Sabotaj muvaffaqiyatli!</b>\n\n{result_text}")


@bot.callback_query_handler(func=lambda c: c.data == "m_josus")
def cb_m_josus(c):
    uid = c.from_user.id
    house = get_house_by_owner(uid)
    bot.answer_callback_query(c.id)
    if not house:
        bot.send_message(c.message.chat.id, "Sizda uy yo'q.", reply_markup=main_menu(uid))
        return
    conn = db()
    active = conn.execute(
        "SELECT * FROM spy_missions WHERE spy_house=? AND status='active'",
        (house["name"],)).fetchone()
    conn.close()
    if active:
        rem = SPY_MISSION_DURATION.get(active["mission_type"], 1800) - (time.time() - active["started_at"])
        rem_min = max(0, int(rem / 60))
        bot.send_message(c.message.chat.id,
            f"🕵️ Josuslaringiz hali missiyada! ~{rem_min} daqiqada qaytadi.",
            reply_markup=back_button())
