    pos = get_council_position(house["name"])
    is_jboshi = (pos == "josuslar_boshi")
    r_catch = int((SPY_CATCH_CHANCE["razvedka"] - (0.15 if is_jboshi else 0)) * 100)
    s_catch = int((SPY_CATCH_CHANCE["sabotaj"]  - (0.15 if is_jboshi else 0)) * 100)
    bonus_note = "\n🏅 Josuslar boshi: tutilish ehtimoli -15%!" if is_jboshi else ""
    kb = types.InlineKeyboardMarkup(row_width=1)
    kb.add(
        types.InlineKeyboardButton(f"🔍 Razvedka (30 daq, {r_catch}% tutilish) — {SPY_COST['razvedka']} tanga",
                                   callback_data="josus_type_razvedka"),
        types.InlineKeyboardButton(f"💣 Sabotaj (60 daq, {s_catch}% tutilish) — {SPY_COST['sabotaj']} tanga",
                                   callback_data="josus_type_sabotaj"),
    )
    kb.add(types.InlineKeyboardButton("⬅️ Bosh menyu", callback_data="m_back"))
    bot.send_message(c.message.chat.id,
        f"🕵️ <b>Josuslik</b>\n\nSizda: <b>{house['tanga']} tanga</b>{bonus_note}\n\n"
        f"• <b>Razvedka</b> ({SPY_COST['razvedka']} tanga) — nishon resurslarini ko'rish\n"
        f"• <b>Sabotaj</b> ({SPY_COST['sabotaj']} tanga) — nishon resurslarini 15% yo'q qilish",
        parse_mode="HTML", reply_markup=kb)


