@bot.callback_query_handler(func=lambda c: c.data.startswith("josus_target_"))
def cb_josus_target(c):
    uid = c.from_user.id
    sess = _josus_session.pop(uid, None)
    bot.answer_callback_query(c.id)
    if not sess:
        return
    target_name = c.data[len("josus_target_"):]
    house = get_house_by_owner(uid)
    if not house:
        return
    mtype = sess["type"]
    cost = SPY_COST.get(mtype, 100)
    conn = db()
    fresh = conn.execute("SELECT tanga FROM houses WHERE name=?", (house["name"],)).fetchone()
    if not fresh or fresh["tanga"] < cost:
        conn.close()
        bot.send_message(c.message.chat.id,
            f"⛔ Tanga yetmadi. Kerak: {cost} tanga.", reply_markup=main_menu(uid))
        return
