# 4. REYTING VA HAFTALIK STATISTIKA
# ---------------------------------------------------------------------------

def check_weekly_stats_post():
    """Har Dushanba DAILY_TICK_HOUR da haftalik statistikani kanalga e'lon qiladi."""
    now = time.time()
    now_s = time.localtime(now)
    if now_s.tm_wday != 0 or now_s.tm_hour < DAILY_TICK_HOUR:
        return
    week_key = time.strftime("%Y-W%W", now_s)
    conn = db()
    row = conn.execute("SELECT value FROM world WHERE key='last_stats_week'").fetchone()
    if row and row["value"] == week_key:
        conn.close()
        return
    conn.execute("INSERT INTO world (key,value) VALUES ('last_stats_week',?) "
                 "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (week_key,))
    conn.commit()

    top_wars = conn.execute(
        "SELECT name, wars_won, wars_lost FROM houses WHERE is_essos=0 "
        "ORDER BY wars_won DESC LIMIT 5").fetchall()
    top_tanga = conn.execute(
        "SELECT name, tanga FROM houses WHERE is_essos=0 ORDER BY tanga DESC LIMIT 3").fetchall()
    king = conn.execute("SELECT value FROM world WHERE key='king'").fetchone()
    conn.close()

    lines = [f"📊 <b>Haftalik Reyting — {week_key}</b>\n"]
    lines.append("⚔️ <b>Eng ko'p urush yutganlar:</b>")
    for i, r in enumerate(top_wars, 1):
        lines.append(f"{i}. <b>{r['name']}</b> — {r['wars_won']}W / {r['wars_lost']}L")
    lines.append("\n💰 <b>Eng boy oilalar:</b>")
    for i, r in enumerate(top_tanga, 1):
        lines.append(f"{i}. <b>{r['name']}</b> — {r['tanga']} tanga")
    if king:
        lines.append(f"\n👑 <b>Qirol:</b> {king['value']}")
    post_to_channel("\n".join(lines))


