DUEL_STAKE = 5        # Ritsarlik ball — g'olib oladi, mag'lub beradi
DUEL_TIMEOUT = PASSAGE_REQUEST_TIMEOUT  # 15 daqiqa ichida qabul qilinmasa bekor


def check_personal_duel_timeouts():
    """Qabul qilinmagan duellarni bekor qiladi."""
    now = time.time()
    conn = db()
    expired = conn.execute(
        "SELECT * FROM personal_duels WHERE status='pending' AND created_at<=?",
        (now - DUEL_TIMEOUT,)).fetchall()
    conn.close()
    for d in expired:
        conn2 = db()
        conn2.execute("UPDATE personal_duels SET status='expired' WHERE id=?", (d["id"],))
        conn2.commit()
        conn2.close()
        challenger = get_house(d["challenger"])
        if challenger and challenger["owner_id"]:
            notify(challenger["owner_id"],
                   f"⚔️ <b>{d['defender']}</b> duel taklifiga 15 daqiqa ichida javob bermadi — "
                   f"taklif bekor qilindi. Xohlasangiz, yana duel taklif qilishingiz mumkin.")


