MAIL_COOLDOWN = 3600    # 1 soatda 1 ta xabar
MAIL_MAX_LEN  = 300     # Maksimal belgi soni

_mail_session = {}   # uid -> {"to": str}


@bot.callback_query_handler(func=lambda c: c.data == "m_pochta")
def cb_m_pochta(c):
    uid = c.from_user.id
    house = get_house_by_owner(uid)
    bot.answer_callback_query(c.id)
    if not house:
        bot.send_message(c.message.chat.id, "Sizda uy yo'q.", reply_markup=main_menu(uid))
        return
    conn = db()
    mails = conn.execute(
        "SELECT * FROM mailbox WHERE to_house=? ORDER BY sent_at DESC LIMIT 10",
        (house["name"],)).fetchall()
    conn.execute("UPDATE mailbox SET is_read=1 WHERE to_house=?", (house["name"],))
    conn.commit()
    conn.close()

    kb = types.InlineKeyboardMarkup(row_width=1)
    kb.add(types.InlineKeyboardButton("✉️ Xabar yuborish", callback_data="mail_send"))
    kb.add(types.InlineKeyboardButton("⬅️ Bosh menyu", callback_data="m_back"))

    if not mails:
        bot.send_message(c.message.chat.id,
            "📭 <b>Pochta qutisi bo'sh</b>\n\nHali xabar kelmagan.",
            parse_mode="HTML", reply_markup=kb)
        return

    lines = [f"📬 <b>Pochta qutisi</b> ({len(mails)} ta xabar)\n"]
    for m in mails:
        t = time.strftime("%d.%m %H:%M", time.localtime(m["sent_at"]))
        status = "🆕" if not m["is_read"] else "📩"
        lines.append(f"{status} <b>{m['from_house']}</b> [{t}]:\n<i>{m['message']}</i>\n")

    bot.send_message(c.message.chat.id, "\n".join(lines), parse_mode="HTML", reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data == "mail_send")
def cb_mail_send(c):
    uid = c.from_user.id
    house = get_house_by_owner(uid)
    bot.answer_callback_query(c.id)
    if not house:
        return
    # Cooldown tekshirish
    conn = db()
    last = conn.execute(
        "SELECT sent_at FROM mailbox WHERE from_house=? ORDER BY sent_at DESC LIMIT 1",
        (house["name"],)).fetchone()
    conn.close()
    if last and (time.time() - last["sent_at"]) < MAIL_COOLDOWN:
        mins = int((MAIL_COOLDOWN - (time.time() - last["sent_at"])) / 60)
        bot.send_message(c.message.chat.id,
            f"⏳ Keyingi xabar yuborishgacha {mins} daqiqa kutish kerak.",
            reply_markup=back_button())
        return
    bot.send_message(c.message.chat.id,
        "✉️ Kimga xabar yuborasiz?",
        reply_markup=houses_keyboard(exclude=house["name"], prefix="mail_to_"))


@bot.callback_query_handler(func=lambda c: c.data.startswith("mail_to_"))
def cb_mail_to(c):
    uid = c.from_user.id
    target_name = c.data[len("mail_to_"):]
    bot.answer_callback_query(c.id)
    house = get_house_by_owner(uid)
    if not house:
        return
    _mail_session[uid] = {"to": target_name}
    msg = bot.send_message(c.message.chat.id,
        f"✉️ <b>{target_name}</b> ga xabar yozing (max {MAIL_MAX_LEN} belgi):",
        parse_mode="HTML",
        reply_markup=types.ForceReply(selective=True))
    bot.register_next_step_handler(msg, _process_mail_text)


def _process_mail_text(message):
    uid = message.from_user.id
    sess = _mail_session.pop(uid, None)
    if not sess:
        return
    house = get_house_by_owner(uid)
    if not house:
        return
    text = (message.text or "").strip()[:MAIL_MAX_LEN]
    if not text:
        bot.send_message(message.chat.id, "⛔ Bo'sh xabar yuborib bo'lmaydi.",
                         reply_markup=main_menu(uid))
        return
    target_name = sess["to"]
    target = get_house(target_name)
    conn = db()
    conn.execute(
        "INSERT INTO mailbox (from_house, to_house, message, sent_at) VALUES (?,?,?,?)",
        (house["name"], target_name, text, time.time()))
    conn.commit()
    conn.close()

    bot.send_message(message.chat.id,
        f"✅ Xabar <b>{target_name}</b> ga yuborildi!", parse_mode="HTML",
        reply_markup=main_menu(uid))
    if target and target["owner_id"]:
        notify(target["owner_id"],
               f"✉️ <b>{house['name']}</b> dan yangi xabar:\n\n<i>{text}</i>")


