_loan_admin_session = {}   # admin_uid -> {"step": str, "loan_id": int, ...}
_loan_user_session  = {}   # user_uid  -> {"loan_id": int}


def _get_iron_bank_balance():
    conn = db()
    row = conn.execute("SELECT value FROM world WHERE key='iron_bank_balance'").fetchone()
    conn.close()
    return int(row["value"]) if row else IRON_BANK_INITIAL_BALANCE


def _set_iron_bank_balance(amount):
    conn = db()
    conn.execute("INSERT INTO world (key,value) VALUES ('iron_bank_balance',?) "
                 "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (str(amount),))
    conn.commit()
    conn.close()


def _get_game_frozen():
    """DB dan muzlatish holatini o'qiydi."""
    global game_frozen
    conn = db()
    row = conn.execute("SELECT value FROM world WHERE key='game_frozen'").fetchone()
    conn.close()
    game_frozen = (row["value"] == "1") if row else False
    return game_frozen


def _set_game_frozen(frozen: bool):
    """O'yinni muzlatadi yoki ochadi (DB + global flag)."""
    global game_frozen
    game_frozen = frozen
    conn = db()
    conn.execute("INSERT INTO world (key,value) VALUES ('game_frozen',?) "
                 "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                 ("1" if frozen else "0",))
    conn.commit()
    conn.close()


def _freeze_guard(uid, chat_id):
    """
    Agar o'yin muzlatilgan bo'lsa va foydalanuvchi admin bo'lmasa — xabar yuboradi.
    Returns True (muzlatilgan, bloklanadi), False (davom etish mumkin).
    """
    if not game_frozen:
        return False
    if is_admin(uid):
        return False
    bot.send_message(chat_id,
        "❄️ <b>O'yin hozircha muzlatilgan</b>\n\n"
        "Admin yangi bosqich boshlanishidan oldin o'yinni tayyorlamoqda.\n"
        "Tez orada o'yin qayta ochiladi — sabr qiling! 🙏",
        parse_mode="HTML")
    return True


# ---- Foydalanuvchi: qarz olish (endi TO'LIQ AVTOMATIK — admin tasdig'i shart emas) ----

@bot.callback_query_handler(func=lambda c: c.data == "tb_loan_request")
def cb_tb_loan_request(c):
    uid = c.from_user.id
    house = get_house_by_owner(uid)
    bot.answer_callback_query(c.id)
    if not house:
        return
    if house["tier"] not in LOAN_TIER_AMOUNTS:
        bot.send_message(c.message.chat.id,
            "⛔ Sizning uyingiz turi uchun qarz mo'ljallanmagan (faqat A/B/C toifadagi Westeros uylari).",
            reply_markup=back_button())
        return
    conn = db()
    existing = conn.execute(
        "SELECT 1 FROM loans WHERE house=? AND status='active'", (house["name"],)).fetchone()
    conn.close()
    if existing:
        bot.send_message(c.message.chat.id,
            "⛔ Sizda hali toʻlanmagan faol qarz bor. 1-qarzni yopmasdan 2-chisini ololmaysiz.",
            reply_markup=back_button())
        return

    max_amount = LOAN_TIER_AMOUNTS[house["tier"]]
    msg = bot.send_message(c.message.chat.id,
        f"🏦 <b>Temir bankdan qarz</b>\n\n"
        f"Toifa: <b>{house['tier']}</b>\n"
        f"Maksimal miqdor: <b>{max_amount} tanga</b>\n\n"
        f"Qancha tanga qarz olmoqchisiz? (1 dan {max_amount} gacha, xohlagan miqdorni yozing):",
        parse_mode="HTML")
    bot.register_next_step_handler(msg, _process_loan_amount_input, max_amount)


def _process_loan_amount_input(message, max_amount):
    uid = message.from_user.id
    house = get_house_by_owner(uid)
    if not house:
        return
    try:
        amount = int(message.text.strip())
        if amount <= 0 or amount > max_amount:
            raise ValueError
    except ValueError:
        msg = bot.send_message(message.chat.id,
            f"⚠️ 1 dan {max_amount} gacha butun son kiriting (bu — {house['tier']} toifa uchun "
            f"limit, {max_amount} tangadan oshib bo'lmaydi):")
        bot.register_next_step_handler(msg, _process_loan_amount_input, max_amount)
        return

    conn = db()
    existing = conn.execute(
        "SELECT 1 FROM loans WHERE house=? AND status='active'", (house["name"],)).fetchone()
    if existing:
        conn.close()
        bot.send_message(message.chat.id,
            "⛔ Sizda hali toʻlanmagan faol qarz bor. 1-qarzni yopmasdan 2-chisini ololmaysiz.",
            reply_markup=main_menu(uid))
        return

    now = time.time()
    due_at = now + LOAN_TERM_DAYS * 86400
    # Temir bankning byudjeti yoʻq — puli cheklanmagan, shuning uchun bank
    # balansini tekshirmasdan/qisqartirmasdan har qanday miqdordagi qarzni
    # avtomatik beraveradi.
    conn.execute("""INSERT INTO loans (house, max_amount, given_amount, interest_rate,
        days_to_repay, given_at, due_at, status) VALUES (?,?,?,?,?,?,?,'active')""",
        (house["name"], amount, amount, LOAN_INTEREST_RATE, LOAN_TERM_DAYS, now, due_at))
    conn.execute("UPDATE houses SET tanga=tanga+? WHERE name=?", (amount, house["name"]))
    conn.commit()
    conn.close()

    due_str = time.strftime("%d.%m.%Y %H:%M", time.localtime(due_at))
    log_history("loan_given", house["name"],
                f"Temir bankdan (avtomatik, {house['tier']} toifa) {amount} tanga qarz oldi "
                f"(muddat: {due_str})")
    bot.send_message(message.chat.id,
        f"✅ <b>{amount} tanga</b> hisobingizga avtomatik oʻtkazildi!\n\n"
        f"Toifa: <b>{house['tier']}</b>\n"
        f"Qaytarish muddati: <b>{LOAN_TERM_DAYS} kun</b> (<b>{due_str}</b>)\n\n"
        f"⚠️ Muddat tugaguncha qaytarmasangiz, Temir bank AVTOMATIK ravishda "
        f"tangangizdan (yetmasa — resurslaringizdan) undirib oladi.\n"
        f"⚠️ Yangi qarz olish uchun avval shu qarzni yoping.",
        parse_mode="HTML", reply_markup=main_menu(uid))
    for admin_id in ADMIN_IDS:
        try:
            bot.send_message(admin_id,
                f"🏦 <b>{house['name']}</b> ({house['tier']} toifa) Temir bankdan avtomatik "
                f"<b>{amount} tanga</b> qarz oldi.\nMuddat: {due_str}", parse_mode="HTML")
        except Exception as _e:
            _swallow(_e)


