def _admin_loan_step_amount(message):
    uid = message.from_user.id
    sess = _loan_admin_session.get(uid)
    if not sess or sess["step"] != "max_amount":
        return
    try:
        max_amt = int((message.text or "").strip())
        if max_amt <= 0:
            raise ValueError
    except ValueError:
        msg = bot.send_message(message.chat.id, "Musbat butun son kiriting (tanga):")
        bot.register_next_step_handler(msg, _admin_loan_step_amount)
        return
    # Temir bankning byudjeti yoʻq — puli cheklanmagan, shuning uchun bank
    # balansi admin tomonidan belgilangan qarz limitini cheklamaydi.
    # Foiz toifaga qarab avtomatik hisoblanadi: A=20%, B=15%, C=10%
    TIER_INTEREST = {"A": 20, "B": 15, "C": 10}
    target_house = get_house(sess["house"])
    tier = target_house["tier"] if target_house else "C"
    rate = TIER_INTEREST.get(tier, 10)

    sess["max_amount"] = max_amt
    _loan_admin_session.pop(uid, None)

    house_name = sess["house"]
    conn = db()
    conn.execute(
        "UPDATE loans SET max_amount=?, interest_rate=?, days_to_repay=?, status='approved' "
        "WHERE house=? AND status='pending'",
        (max_amt, rate, sess["days"], house_name))
    conn.commit()
    conn.close()

    target = get_house(house_name)
    if target and target["owner_id"]:
        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton("💵 Qarz olish (miqdor tanlash)", callback_data="tb_take_loan"))
        notify(target["owner_id"],
            f"🏦 <b>Temir bank: Qarz tasdiqlandi!</b>\n\n"
            f"Maksimal limit: <b>{max_amt} tanga</b>\n"
            f"Foiz: <b>{rate}%</b> ({tier} toifa uchun belgilangan)\n"
            f"Muddat: <b>{sess['days']} kun</b>\n\n"
            f"Temir bank menyusiga kiring va qarz oling.",
            reply_markup=kb)
    bot.send_message(message.chat.id,
        f"✅ <b>{house_name}</b> ga qarz tasdiqlandi!\n"
        f"Limit: {max_amt} tanga | Foiz: {rate}% ({tier} toifa) | Muddat: {sess['days']} kun.",
        parse_mode="HTML", reply_markup=back_button())


