@bot.callback_query_handler(func=lambda c: c.data == "tb_repay_loan")
def cb_tb_repay_loan(c):
    uid = c.from_user.id
    house = get_house_by_owner(uid)
    bot.answer_callback_query(c.id)
    if not house:
        return
    conn = db()
    loan = conn.execute(
        "SELECT * FROM loans WHERE house=? AND status='active'", (house["name"],)).fetchone()
    conn.close()
    if not loan:
        bot.send_message(c.message.chat.id, "Faol qarz topilmadi.", reply_markup=main_menu(uid))
        return
    owed = int(loan["given_amount"] * (1 + loan["interest_rate"] / 100))
    if house["tanga"] < owed:
        bot.send_message(c.message.chat.id,
            f"⛔ Qarz qaytarish uchun {owed} tanga kerak, sizda faqat {house['tanga']} tanga bor.",
            reply_markup=main_menu(uid))
        return

    # ATOMIK TRANZAKSIYA: uy balansi, qarz holati va bank balansi bir vaqtda o'zgaradi
    conn = db()
    tb_bal_row = conn.execute("SELECT value FROM world WHERE key='iron_bank_balance'").fetchone()
    tb_bal = int(tb_bal_row["value"]) if tb_bal_row else IRON_BANK_INITIAL_BALANCE
    conn.execute("UPDATE houses SET tanga=tanga-? WHERE name=?", (owed, house["name"]))
    conn.execute("UPDATE loans SET status='repaid', note=? WHERE id=?",
                 (f"Qaytarildi: {owed} tanga", loan["id"]))
    conn.execute("INSERT INTO world (key,value) VALUES ('iron_bank_balance',?) "
                 "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (str(tb_bal + owed),))
    conn.commit()
    conn.close()
    log_history("loan_repaid", house["name"], f"Temir bankga {owed} tanga qarz qaytardi")
    bot.send_message(c.message.chat.id,
        f"✅ <b>{owed} tanga</b> Temir bankka qaytarildi. Qarzingiz yopildi!",
        parse_mode="HTML", reply_markup=main_menu(uid))
    for admin_id in ADMIN_IDS:
        try:
            bot.send_message(admin_id,
                f"🏦 <b>{house['name']}</b> {owed} tanga qarzini qaytardi.", parse_mode="HTML")
        except Exception as _e:
            _swallow(_e)


