@bot.callback_query_handler(func=lambda c: c.data == "a_loan_manage")
def cb_a_loan_manage(c):
    uid = c.from_user.id
    if not is_admin(uid):
        return
    bot.answer_callback_query(c.id)
    conn = db()
    tb_bal = _get_iron_bank_balance()
    active_loans = conn.execute(
        "SELECT * FROM loans WHERE status='active' ORDER BY due_at").fetchall()
    pending_loans = conn.execute(
        "SELECT * FROM loans WHERE status='pending'").fetchall()
    conn.close()

    lines = [f"🏦 <b>Temir bank boshqaruvi</b>\nBank balansi: <b>{tb_bal} tanga</b>\n"]
    kb = types.InlineKeyboardMarkup(row_width=1)

    if pending_loans:
        lines.append(f"\n⏳ <b>Kutayotgan so'rovlar ({len(pending_loans)} ta):</b>")
        for l in pending_loans:
            lines.append(f"• <b>{l['house']}</b>")
            kb.add(
                types.InlineKeyboardButton(f"✅ {l['house']} ni tasdiqlash",
                                           callback_data=f"a_loan_approve_{l['house']}"),
                types.InlineKeyboardButton(f"❌ {l['house']} ni rad etish",
                                           callback_data=f"a_loan_reject_{l['house']}"),
            )

    if active_loans:
        lines.append(f"\n⚡ <b>Faol qarzlar ({len(active_loans)} ta):</b>")
        for l in active_loans:
            due = time.strftime("%d.%m.%Y", time.localtime(l["due_at"]))
            owed = int(l["given_amount"] * (1 + l["interest_rate"] / 100))
            overdue = "⚠️MUDDATI O'TDI" if time.time() > l["due_at"] else ""
            lines.append(f"• <b>{l['house']}</b>: {l['given_amount']} tanga qarz → {owed} tanga qaytarish | Muddat: {due} {overdue}")
            kb.add(types.InlineKeyboardButton(
                f"🕊️ {l['house']} qarzini kechirish", callback_data=f"a_loan_forgive_{l['id']}"))

    if not pending_loans and not active_loans:
        lines.append("Hozirda qarzlar yo'q.")

    kb.add(types.InlineKeyboardButton("⬅️ Admin panel", callback_data="m_admin"))
    bot.send_message(c.message.chat.id, "\n".join(lines), parse_mode="HTML", reply_markup=kb)


