def _display_chat(chat_id_tg, uid, chat_id, gc):
    messages = _get_chat_messages(chat_id, 10)
    members = _get_chat_members(chat_id)
    house = get_house_by_owner(uid)
    is_creator = gc["created_by"] == (house["name"] if house else "")

    lines = [f"💬 <b>{gc['name']}</b>", f"👥 A'zolar: {', '.join(members)}\n"]
    if messages:
        lines.append("<b>📨 So'nggi xabarlar:</b>")
        for m in messages:
            t = time.strftime("%H:%M", time.localtime(m["sent_at"]))
            lines.append(f"[{t}] <b>{m['house_name']}</b>: {m['message']}")
    else:
        lines.append("<i>Hali xabar yo'q. Birinchi bo'ling!</i>")

    kb = types.InlineKeyboardMarkup(row_width=1)
    kb.add(types.InlineKeyboardButton("✍️ Xabar yozish", callback_data=f"chat_write_{chat_id}"))
    if is_creator:
        kb.add(types.InlineKeyboardButton("👤 A'zo qo'shish", callback_data=f"chat_addinvite_{chat_id}"))
    kb.add(types.InlineKeyboardButton("🚪 Chatdan chiqish", callback_data=f"chat_leave_{chat_id}"))
    kb.add(types.InlineKeyboardButton("⬅️ Guruh chatlar", callback_data="m_guruh_chat"))
    bot.send_message(chat_id_tg, "\n".join(lines), parse_mode="HTML", reply_markup=kb)


