def cb_group_chat_write(c):
    uid = c.from_user.id
    house = get_house_by_owner(uid)
    bot.answer_callback_query(c.id)
    if not house:
        return
    try:
        chat_id = int(c.data[len("chat_write_"):])
    except ValueError:
        return
    conn = db()
    gc = conn.execute("SELECT name FROM group_chats WHERE id=?", (chat_id,)).fetchone()
    conn.close()
    if not gc:
        return
    msg = bot.send_message(c.message.chat.id,
        f"💬 <b>{gc['name']}</b> chatiga xabar yozing:\n<i>(Bekor qilish uchun /cancel yozing)</i>",
        parse_mode="HTML")
    bot.register_next_step_handler(msg, _process_chat_message, chat_id)


def _process_chat_message(message, chat_id):
    uid = message.from_user.id
    house = get_house_by_owner(uid)
    if not house:
        return
    text = message.text.strip() if message.text else ""
    if text.lower() in ("/cancel", "bekor"):
        bot.send_message(message.chat.id, "❌ Bekor qilindi.", reply_markup=main_menu(uid))
        return
    if not text or len(text) > 500:
        bot.send_message(message.chat.id, "Xabar 1-500 belgi bo'lishi kerak.",
                         reply_markup=main_menu(uid))
        return
    members = _get_chat_members(chat_id)
    if house["name"] not in members:
        bot.send_message(message.chat.id, "⛔ Siz bu chatda a'zo emassiz.",
                         reply_markup=main_menu(uid))
        return
    conn = db()
    gc = conn.execute("SELECT * FROM group_chats WHERE id=?", (chat_id,)).fetchone()
    conn.execute(
        "INSERT INTO group_chat_messages (chat_id, house_name, message, sent_at) VALUES (?,?,?,?)",
        (chat_id, house["name"], text, time.time()))
    conn.commit()
    conn.close()
    # Barcha a'zolarga xabar yuborish
    t = time.strftime("%H:%M")
    relay_text = (f"💬 <b>{gc['name']}</b>\n"
                  f"[{t}] <b>{house['name']}</b>:\n{text}")
    kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton("💬 Chatga javob berish", callback_data=f"chat_write_{chat_id}"))
    for member_name in members:
        if member_name == house["name"]:
            continue
        member_house = get_house(member_name)
        if member_house and member_house["owner_id"]:
            try:
                bot.send_message(member_house["owner_id"], relay_text,
                                 parse_mode="HTML", reply_markup=kb)
            except Exception as _e:
                _swallow(_e)
    bot.send_message(message.chat.id,
        f"✅ Xabar yuborildi ({len(members)-1} ta a'zoga).",
        reply_markup=types.InlineKeyboardMarkup().add(
            types.InlineKeyboardButton("💬 Chatga qaytish", callback_data=f"chat_open_{chat_id}")))


