def _process_braavos_director(m):
    uid = m.from_user.id
    if not _braavos_director_session.get(uid):
        return
    _braavos_director_session.pop(uid, None)
    text = (m.text or "").strip()
    if text.lower() == "/cancel":
        bot.send_message(m.chat.id, "❌ Bekor qilindi.", reply_markup=main_menu(uid))
        return
    try:
        target_uid = int(text)
    except ValueError:
        bot.send_message(m.chat.id, "❌ Noto'g'ri ID. Butun son kiriting.", reply_markup=main_menu(uid))
        return
    if is_night_king(target_uid):
        bot.send_message(m.chat.id, "❌ Bu foydalanuvchi Tun qiroli — uy lordi bo'la olmaydi.",
                         reply_markup=main_menu(uid))
        return
    conn = db()
    user_row = conn.execute("SELECT * FROM users WHERE user_id=?", (target_uid,)).fetchone()
    if not user_row:
        conn.close()
        bot.send_message(m.chat.id, f"❌ ID={target_uid} foydalanuvchi topilmadi (u /start bosishi kerak).",
                         reply_markup=main_menu(uid))
        return
    # Eski egani olib, yangi egani belgilash
    conn.execute("UPDATE houses SET owner_id=? WHERE name=?", (target_uid, IRON_BANK_HOUSE))
    conn.commit()
    conn.close()
    bot.send_message(m.chat.id,
        f"✅ <b>Bravos rahbari yangilandi!</b>\n\nID={target_uid} endi Bravos shahri va Temir bank rahbaridir.",
        parse_mode="HTML", reply_markup=main_menu(uid))
    try:
        bot.send_message(target_uid,
            "🌊 <b>Tabriklaymiz!</b> Siz Bravos shahri va Temir bank rahbari etib tayinlandingiz!\n\n"
            "/start bosib Bravos paneliga kiring.",
            parse_mode="HTML")
    except Exception as _e:
        _swallow(_e)


