    if not wall_row:
        conn.close()
        bot.send_message(m.chat.id, "❌ Devor uyi bazada topilmadi.", reply_markup=main_menu(uid))
        return
    prev_commander = wall_row["owner_id"]
    if prev_commander == target_uid:
        conn.close()
        bot.send_message(m.chat.id, "ℹ️ Bu foydalanuvchi allaqachon Devor Lord Qo'mondoni.",
                         reply_markup=main_menu(uid))
        return
    # Foydalanuvchida boshqa uy bo'lsa — undan chiqariladi (bir vaqtda ikki uyga
    # ega bo'lib, ikki marta soliq to'lab qolmasligi uchun; "Uyni biriktirish"
    # funksiyasi bilan bir xil qoida).
    old_house = conn.execute(
        "SELECT name, is_free_knight FROM houses WHERE owner_id=? AND name!=?",
        (target_uid, WALL_HOUSE)).fetchone()
    released = None
    if old_house:
        released = old_house["name"]
        if old_house["is_free_knight"]:
            conn.execute("DELETE FROM houses WHERE name=?", (old_house["name"],))
        else:
            conn.execute("UPDATE houses SET owner_id=NULL WHERE name=?", (old_house["name"],))
    conn.execute("UPDATE houses SET owner_id=? WHERE name=?", (target_uid, WALL_HOUSE))
    conn.execute("DELETE FROM knights WHERE user_id=?", (target_uid,))
    conn.commit()
    conn.close()
    _house_cache_invalidate(name=WALL_HOUSE, uid=target_uid)
    if prev_commander:
        _house_cache_invalidate(uid=prev_commander)
    if released:
        _house_cache_invalidate(name=released)

    report = (f"✅ <b>Devor Lord Qo'mondoni tayinlandi!</b>\n\n"
              f"ID={target_uid} endi <b>{WALL_HOUSE}</b> Lord Qo'mondoni.")
    if released:
        report += f"\n\nℹ️ Uning oldingi uyi <b>{released}</b> egasiz (NPC) holatiga qaytdi."
    if prev_commander:
        report += f"\n\n♻️ Oldingi Lord Qo'mondon (ID={prev_commander}) lavozimdan bo'shatildi."
    bot.send_message(m.chat.id, report, parse_mode="HTML", reply_markup=main_menu(uid))

    notify(target_uid,
           "🛡️ <b>Tabriklaymiz!</b> Siz Devorning Lord Qo'mondoni etib tayinlandingiz!\n\n"
           "Devor faqat Oq piyodalarga qarshi jang qiladi va kuniga "
           f"<b>{PRODUCTION[WALL_HOUSE][2]} 💰 tanga</b> oladi.\n"
           "/start bosib Devor paneliga kiring.")
    if prev_commander:
        notify(prev_commander,
               "⚰️ Siz Devorning Lord Qo'mondoni lavozimidan bo'shatildingiz.")
    post_to_channel(f"🛡️ <b>{get_user_name(target_uid) or 'Yangi qo‘mondon'}</b> "
                    f"<b>{WALL_HOUSE}</b>ning yangi Lord Qo'mondoni etib tayinlandi!")


