def cb_jodugar_pick(c):
    uid = c.from_user.id
    ability = c.data[len("jodugar_pick_"):]
    house = get_house_by_owner(uid)
    if not house:
        bot.answer_callback_query(c.id, "Sizda uy yo'q.", show_alert=True)
        return
    if ability not in JODUGAR_ABILITIES:
        bot.answer_callback_query(c.id, "Noto'g'ri qobiliyat.", show_alert=True)
        return
    qj = house.get("qizil_jodugar", 0)
    if qj <= 0:
        bot.answer_callback_query(c.id, "Sizda qizil jodugar yo'q.", show_alert=True)
        return
    if not click_guard(uid, "jodugar_pick", 3.0):
        bot.answer_callback_query(c.id, "Biroz kuting...")
        return
    # Tekshiruv + INSERT bitta lock ostida (spam-click bitta jodugarga 2 ta qobiliyat bermasin)
    now = time.time()
    week_end = now + 7 * 24 * 3600
    err = None
    with _lock:
        conn = db()
        try:
            fresh = conn.execute("SELECT qizil_jodugar FROM houses WHERE name=?", (house["name"],)).fetchone()
            qj = (fresh["qizil_jodugar"] if fresh else 0) or 0
            active_list = conn.execute(
                "SELECT ability FROM jodugar_abilities WHERE house=? AND status='active' AND week_end>?",
                (house["name"], now)).fetchall()
            if qj <= 0:
                err = "Sizda qizil jodugar yo'q."
            elif len(active_list) >= qj:
                err = (f"Sizdagi barcha {qj} ta qizil jodugar band. Yangi qobiliyat tanlash uchun "
                       f"ko'proq jodugar sotib oling yoki mavjud qobiliyat hafta muddati tugashini kuting.")
            elif any(r["ability"] == ability for r in active_list):
                err = "Bu qobiliyat allaqachon faol."
            else:
                conn.execute("""INSERT INTO jodugar_abilities (house, ability, week_start, week_end, status, used, created_at)
                    VALUES (?,?,?,?,'active',0,?)""", (house["name"], ability, now, week_end, now))
                conn.commit()
        except Exception as e:
            try:
                conn.rollback()
            except Exception as _e:
                _swallow(_e)
            logging.warning("jodugar_pick xatosi: %r", e)
            err = "Xatolik yuz berdi, qayta urinib ko'ring."
        finally:
            conn.close()
    if err:
        bot.answer_callback_query(c.id, err, show_alert=True)
        return
    bot.answer_callback_query(c.id)
    ability_label = JODUGAR_ABILITIES[ability]
    week_end_str = time.strftime("%d.%m.%Y %H:%M", time.localtime(week_end))
    bot.send_message(c.message.chat.id,
        f"✅ <b>Qobiliyat tanlandi!</b>\n\n"
        f"{ability_label}\n\n"
        f"Bu qobiliyat <b>{week_end_str}</b> gacha ishlaydi.\n"
        f"Hafta o'rtasida qobiliyat almashtirilmaydi (lekin bo'sh jodugaringiz bo'lsa, "
        f"boshqa qobiliyatni PARALLEL tanlashingiz mumkin).",
        parse_mode="HTML", reply_markup=main_menu(uid))


