@bot.callback_query_handler(func=lambda c: c.data.startswith("jodugar_revive_pick_"))
def cb_jodugar_revive_pick(c):
    uid = c.from_user.id
    unit = c.data[len("jodugar_revive_pick_"):]
    house = get_house_by_owner(uid)
    if not house:
        bot.answer_callback_query(c.id, "Sizda uy yo'q.", show_alert=True)
        return
    if unit not in REVIVE_UNIT_CHOICES:
        bot.answer_callback_query(c.id, "Noto'g'ri qo'shin turi.", show_alert=True)
        return
    active = _get_active_jodugar_by_ability(house["name"], "tiriltirish")
    if not active or active.get("used"):
        bot.answer_callback_query(c.id, "Bu qobiliyat faol emas yoki allaqachon ishlatilgan.", show_alert=True)
        return
    # Qobiliyatni ATOMIK sarflash: faqat used=0 bo'lsa o'tadi — spam-click 100 ta
    # qo'shinni bir necha marta bermaydi.
    ok = False
    with _lock:
        conn = db()
        try:
            cur = conn.execute(
                "UPDATE jodugar_abilities SET used=1, status='finished' "
                "WHERE id=? AND used=0 AND status='active'", (active["id"],))
            if cur.rowcount == 1:
                conn.execute(f"UPDATE houses SET {unit} = {unit} + ? WHERE name=?",
                             (REVIVE_UNIT_AMOUNT, house["name"]))
                conn.execute("UPDATE houses SET qizil_jodugar = MAX(qizil_jodugar-1, 0) WHERE name=?",
                             (house["name"],))
                ok = True
            conn.commit()
        except Exception as e:
            try:
                conn.rollback()
            except Exception as _e:
                _swallow(_e)
            logging.warning("tiriltirish xatosi: %r", e)
        finally:
            conn.close()
    if not ok:
        bot.answer_callback_query(c.id, "Bu qobiliyat allaqachon ishlatilgan.", show_alert=True)
        return
    bot.answer_callback_query(c.id)
    bot.send_message(c.message.chat.id,
        f"✨ <b>Tiriltirish yakunlandi!</b>\n\n"
        f"{RESOURCE_EMOJI.get(unit,'')} {RESOURCE_LABEL.get(unit,unit)}: +{REVIVE_UNIT_AMOUNT}\n\n"
        f"🔮 Qizil jodugar bu jarayonda halok bo'ldi.",
        parse_mode="HTML", reply_markup=main_menu(uid))


def check_jodugar_daily_reset():
    """Josuslik qobiliyati kuniga bir marta — used=1 bo'lsa, har kuni sifirlanadi."""
    conn = db()
    today = time.strftime("%Y-%m-%d")
    row = conn.execute("SELECT value FROM world WHERE key='jodugar_reset_date'").fetchone()
    last_date = row["value"] if row else ""
    if last_date == today:
        conn.close()
        return
    # Josuslik qobiliyati uchun used ni sifirla (lekin tiriltirish/himoya uchun emas)
    conn.execute("""UPDATE jodugar_abilities SET used=0
        WHERE ability='josuslik' AND status='active' AND week_end>?""", (time.time(),))
    conn.execute("INSERT INTO world (key,value) VALUES ('jodugar_reset_date',?) "
                 "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (today,))
    conn.commit()
    conn.close()


