# ===========================================================================
# AVTOMATIK QARZ UNDIRISH: muddati o'tgan faol qarzlarni Temir bank
# o'zi avtomatik undiradi — avval tangadan, keyin BUY_PRICES bo'yicha eng
# arzon resurslardan (_collect_tax bilan bir xil mexanizm). Bravos direktori
# endi qo'lda urush e'lon qilishi shart emas.
# ===========================================================================

def check_loan_due_collections():
    conn = db()
    now = time.time()
    due_loans = conn.execute(
        "SELECT * FROM loans WHERE status='active' AND due_at<=?", (now,)).fetchall()
    for loan in due_loans:
        house_name = loan["house"]
        owed = int(loan["given_amount"] * (1 + loan["interest_rate"] / 100))
        paid, desc = _collect_tax(conn, house_name, owed, IRON_BANK_HOUSE)
        conn.commit()
        remaining_debt = owed - paid
        if remaining_debt <= 0:
            conn.execute("UPDATE loans SET status='collected', note=? WHERE id=?",
                         (f"Avtomatik undirildi: {desc}", loan["id"]))
            conn.commit()
            log_history("loan_auto_collected", house_name,
                        f"Temir bank qarzni avtomatik undirdi: {desc} ({paid}/{owed} tanga)")
            house_row = conn.execute("SELECT owner_id FROM houses WHERE name=?", (house_name,)).fetchone()
            if house_row and house_row["owner_id"]:
                notify(house_row["owner_id"],
                       f"🏦 <b>Temir bank qarzingizni avtomatik undirdi!</b>\n\n"
                       f"Muddat tugagani sababli {desc} olib qo'yildi ({paid} tanga ekvivalenti).")
            for admin_id in ADMIN_IDS:
                try:
                    bot.send_message(admin_id,
                        f"🏦 <b>{house_name}</b> ning muddati o'tgan qarzi avtomatik undirildi: "
                        f"{desc} ({paid}/{owed} tanga).", parse_mode="HTML")
                except Exception as _e:
                    _swallow(_e)
        else:
            # Resurs yetmasa — qarzni "overdue" deb belgilaymiz, mavjud narsani undiramiz,
            # qolgan qismini keyingi tekshiruvda (masalan resurs kelganda) yana urinib ko'ramiz.
            conn.execute("UPDATE loans SET given_amount=?, note=? WHERE id=?",
                         (remaining_debt, f"Qisman undirildi: {desc} (qoldi: {remaining_debt} tanga)", loan["id"]))
            conn.commit()
            house_row = conn.execute("SELECT owner_id FROM houses WHERE name=?", (house_name,)).fetchone()
            if house_row and house_row["owner_id"]:
                notify(house_row["owner_id"],
                       f"🏦 <b>Temir bank qarzingizni qisman undirdi!</b>\n\n"
                       f"{desc} olib qo'yildi, lekin resurs yetmagani uchun "
                       f"<b>{remaining_debt} tanga</b> qarzingiz hali qoldi — resurs to'planishi bilan "
                       f"bank yana undirishga urinadi.")
    conn.close()


