def _animal_get(house, akey):
    conn = db()
    row = conn.execute("SELECT * FROM animals WHERE house=? AND akey=?", (house, akey)).fetchone()
    conn.close()
    return row


def _animal_get_house_animals(house_name):
    conn = db()
    rows = conn.execute("SELECT * FROM animals WHERE house=?", (house_name,)).fetchall()
    conn.close()
    return rows


def _animal_is_fed(row):
    if not row:
        return False
    return (time.time() - (row["last_fed"] or 0)) < ANIMAL_FEED_VALID_SECONDS


def _animal_today():
    return time.strftime("%Y-%m-%d")


def _animal_battle_count_today(house_name):
    conn = db()
    row = conn.execute("SELECT count FROM animal_battle_log WHERE house=? AND day=?",
                        (house_name, _animal_today())).fetchone()
    conn.close()
    return row["count"] if row else 0


def _animal_battle_increment(house_name):
    conn = db()
    conn.execute(
        "INSERT INTO animal_battle_log (house, day, count) VALUES (?,?,1) "
        "ON CONFLICT(house, day) DO UPDATE SET count = count + 1",
        (house_name, _animal_today()))
    conn.commit()
    conn.close()


def _animal_win_probability(power_a, power_b):
    """A hayvonining g'alaba ehtimoli. Kuch farqi katta boʻlsa ustunlik ham
    katta boʻladi, lekin ehtimol HECH QACHON 8%-92% oraligʻidan chiqmaydi —
    yaʼni eng kuchli Balerion ham har doim tasodifan yutqazishi mumkin."""
    diff = power_a - power_b
    p = 0.5 + diff * 0.08
    return max(0.08, min(0.92, p))


def animal_menu_text_and_kb(house_name):
    owned = _animal_get_house_animals(house_name)
    text = "🐉🐺 <b>Hayvonlarim</b>\n\n"
    if not owned:
        text += "Sizda hozircha hech qanday hayvon yoʻq.\n"
    else:
        for r in owned:
            info = ANIMAL_ALL.get(r["akey"])
            if not info:
                continue
            fed = "🍖 toʻq" if _animal_is_fed(r) else "⚠️ och (jangga chiqolmaydi)"
            text += f"{info['name']} — {fed} | G': {r['wins']} / M: {r['losses']}\n"
        text += f"\nBugungi janglar: {_animal_battle_count_today(house_name)}/{ANIMAL_DAILY_LIMIT}\n"
    text += (
        f"\n💰 Narxlar: ajdar {ANIMAL_BUY_COST['dragon']} tanga, "
        f"boʻri {ANIMAL_BUY_COST['wolf']} tanga (tur TASODIFIY beriladi)\n"
        f"🍖 Ovqat: ajdar {ANIMAL_FEED_COST['dragon']} tanga, "
        f"boʻri {ANIMAL_FEED_COST['wolf']} tanga (24 soatga)\n"
        f"🏆 G'alaba mukofoti: ajdar {ANIMAL_WIN_MIN['dragon']}-{ANIMAL_WIN_MAX['dragon']} tanga, "
        f"boʻri {ANIMAL_WIN_MIN['wolf']}-{ANIMAL_WIN_MAX['wolf']} tanga\n"
        "\n⚠️ Hayvonlar urushlarga aralashmaydi va boshqa hech qanday bonus bermaydi."
    )
    kb = types.InlineKeyboardMarkup(row_width=2)
    kb.add(
        types.InlineKeyboardButton("🐉 Ajdar sotib olish", callback_data="an_buy_dragon"),
        types.InlineKeyboardButton("🐺 Boʻri sotib olish", callback_data="an_buy_wolf"),
    )
    kb.add(types.InlineKeyboardButton("🍖 Ovqatlantirish", callback_data="an_feed_menu"))
    kb.add(types.InlineKeyboardButton("⚔️ Jang qilish", callback_data="an_battle_menu"))
    kb.add(types.InlineKeyboardButton("📜 Barcha hayvonlar (dunyo)", callback_data="an_world_list"))
    kb.add(types.InlineKeyboardButton("⬅️ Bosh menyu", callback_data="m_back"))
    return text, kb


@bot.callback_query_handler(func=lambda c: c.data == "m_hayvonlarim")
def cb_hayvonlarim(c):
    if _freeze_guard(c.from_user.id, c.message.chat.id):
        bot.answer_callback_query(c.id)
        return
    house = get_house_by_owner(c.from_user.id)
    if not house:
        bot.send_message(c.message.chat.id, "Sizda uy yo'q — avval uy tanlang.", reply_markup=main_menu(c.from_user.id))
        bot.answer_callback_query(c.id)
        return
    text, kb = animal_menu_text_and_kb(house["name"])
    bot.send_message(c.message.chat.id, text, reply_markup=kb, parse_mode="HTML")
    bot.answer_callback_query(c.id)


@bot.callback_query_handler(func=lambda c: c.data == "an_world_list")
def cb_an_world_list(c):
    conn = db()
    rows = conn.execute("SELECT * FROM animals").fetchall()
    conn.close()
    owners_map = {}
    for r in rows:
        owners_map.setdefault(r["akey"], []).append(r["house"])
    text = "📜 <b>Dunyodagi hayvon turlari va egalari:</b>\n\n<b>🐉 Ajdarlar:</b>\n"
    for ak, (name, power) in sorted(ANIMAL_DRAGONS.items(), key=lambda kv: -kv[1][1]):
        owners = owners_map.get(ak, [])
        egasi = ", ".join(owners) if owners else "🔓 hali hech kimda yoʻq"
        text += f"{name} (kuch {power}) — {egasi}\n"
    text += "\n<b>🐺 Boʻrilar:</b>\n"
    for ak, (name, power) in sorted(ANIMAL_WOLVES.items(), key=lambda kv: -kv[1][1]):
        owners = owners_map.get(ak, [])
        egasi = ", ".join(owners) if owners else "🔓 hali hech kimda yoʻq"
        text += f"{name} (kuch {power}) — {egasi}\n"
    text += "\n<i>Eslatma: bir xil hayvon turini bir nechta uy egallashi mumkin.</i>"
    kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton("⬅️ Orqaga", callback_data="m_hayvonlarim"))
    bot.send_message(c.message.chat.id, text, reply_markup=kb, parse_mode="HTML")
    bot.answer_callback_query(c.id)


@bot.callback_query_handler(func=lambda c: c.data in ("an_buy_dragon", "an_buy_wolf"))
def cb_an_buy(c):
    kind = "dragon" if c.data == "an_buy_dragon" else "wolf"
    house = get_house_by_owner(c.from_user.id)
    if not house:
        bot.answer_callback_query(c.id)
        return
    pool = ANIMAL_DRAGONS if kind == "dragon" else ANIMAL_WOLVES
    cost = ANIMAL_BUY_COST[kind]
    with _lock:
        conn = db()
        hrow = conn.execute("SELECT tanga FROM houses WHERE name=?", (house["name"],)).fetchone()
        if not hrow or hrow["tanga"] < cost:
            conn.close()
            bot.answer_callback_query(c.id, f"Yetarli tanga yoʻq! Kerak: {cost}", show_alert=True)
            return
        already_owned = {r["akey"] for r in conn.execute(
            "SELECT akey FROM animals WHERE house=?", (house["name"],)).fetchall()}
        available = [ak for ak in pool if ak not in already_owned]
        if not available:
            conn.close()
            label = "ajdar" if kind == "dragon" else "boʻri"
            bot.answer_callback_query(c.id, f"Sizda allaqachon barcha {label} turlari bor!", show_alert=True)
            return
        chosen_akey = random.choice(available)
        conn.execute("UPDATE houses SET tanga = tanga - ? WHERE name=?", (cost, house["name"]))
        conn.execute(
            "INSERT INTO animals (house, akey, last_fed, acquired_at) VALUES (?,?,0,?)",
            (house["name"], chosen_akey, time.time()))
        conn.commit()
        conn.close()
    info = ANIMAL_ALL[chosen_akey]
    bot.answer_callback_query(c.id, "✅ Sotib olindi!")
    bot.send_message(c.message.chat.id,
                      f"🎲 Tizim sizga tasodifiy tanladi: <b>{info['name']}</b> endi sizning uyingizga tegishli!\n"
                      "Jangga chiqarishdan oldin uni ovqatlantirishni unutmang.",
                      parse_mode="HTML")
    text, kb = animal_menu_text_and_kb(house["name"])
    bot.send_message(c.message.chat.id, text, reply_markup=kb, parse_mode="HTML")


